begin;
insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C3-L1-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'عدد التأكسد لذرة في المركب الأيوني هو:', null, '["عدد الإلكترونات التي فقدتها الذرة أو اكتسبتها عند تكوين الأيون","عدد البروتونات الموجودة في نواة الذرة","عدد إلكترونات المستوى الخارجي للذرة قبل التفاعل","عدد الأيونات التي تكونها الذرة في البلورة"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 106 — التغير في عدد التأكسد'),
('mcq', 2, 'ما الرمز الذي يُستعمل للدلالة على عدد تأكسد ذرة (مثل عدد تأكسد Cl في KClO₃ وهو +5)؟', null, '["Z","e⁻","n","M"]'::jsonb, 'تذكر', 'تذكر رمز', 'متوسط', 'الكتاب ص 110 — تحديد أعداد التأكسد (الجدول 2-3)'),
('mcq', 3, 'أيّ مما يأتي يمثل الطريقة الصحيحة لكتابة عدد تأكسد الألومنيوم في الأيون Al³⁺؟', null, '["3+","+3","3","−3"]'::jsonb, 'فهم', 'تمييز', 'صعب', 'الكتاب ص 106 — التغير في عدد التأكسد'),
('mcq', 4, 'يستعمل الكيميائيون أعداد التأكسد أداةً تساعدهم على:', null, '["حساب الكتلة المولية للمركبات","تحديد عدد النيوترونات في نوى الذرات","قياس سرعة تفاعلات الأكسدة والاختزال","تتبّع مسار حركة الإلكترونات في تفاعلات الأكسدة والاختزال"]'::jsonb, 'تذكر', 'تذكر وظيفة', 'سهل', 'الكتاب ص 106 — التغير في عدد التأكسد'),
('mcq', 5, 'لماذا يساوي عدد تأكسد البوتاسيوم +1 في كلوريد البوتاسيوم KCl؟', null, '["لأن ذرة البوتاسيوم فقدت إلكترونًا واحدًا عند تكوين الأيون K⁺","لأن ذرة البوتاسيوم اكتسبت إلكترونًا واحدًا عند تكوين الأيون K⁺","لأن ذرة البوتاسيوم تحتوي على بروتون واحد زائد في نواتها","لأن البوتاسيوم يرتبط بذرة كلور واحدة برابطة تساهمية"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 106 — التغير في عدد التأكسد'),
('mcq', 6, 'عند تكوين أكسيد المغنيسيوم MgO يكون عدد تأكسد الأكسجين −2؛ لأن كل ذرة أكسجين:', null, '["فقدت إلكترونين لذرة مغنيسيوم","اكتسبت إلكترونين من ذرة مغنيسيوم","اكتسبت إلكترونًا واحدًا من ذرة مغنيسيوم","شاركت ذرة المغنيسيوم بزوجين من الإلكترونات"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 104 — الشكل 1-3'),
('mcq', 7, 'وفق قواعد تحديد أعداد التأكسد، عدد تأكسد الذرة الأكثر كهروسالبية في الجزيء التساهمي يساوي:', null, '["عدد الروابط التساهمية التي تكوّنها الذرة","صفرًا دائمًا لأنه لا تتكون أيونات","عدد إلكترونات التكافؤ في الذرة","الشحنة التي تكون عليها لو كانت أيونًا"]'::jsonb, 'فهم', 'تعميم تعريف', 'صعب', 'الكتاب ص 110 — تحديد أعداد التأكسد (الجدول 2-3)'),
('essay', 1, 'عرّف عدد التأكسد لذرة في مركب أيوني، ثم بيّن الفرق بين كتابة عدد التأكسد وكتابة الشحنة الأيونية مستعملًا أيون Fe³⁺ مثالًا.', null, null, 'تذكر', 'تعريف مع مثال', 'سهل', 'الكتاب ص 106 — التغير في عدد التأكسد'),
('essay', 2, 'يتفاعل البوتاسيوم مع الكلور وفق المعادلة: 2K(s) + Cl₂(g) → 2K⁺(s) + 2Cl⁻(s).
(أ) اكتب عدد تأكسد كلٍّ من K وCl قبل التفاعل وبعده.
(ب) فسّر كل قيمة بعد التفاعل بدلالة الإلكترونات.', null, null, 'فهم', 'تفسير قيم', 'متوسط', 'الكتاب ص 106 — التغير في عدد التأكسد'),
('essay', 3, 'في جزيء الأمونيا NH₃ لا تتكون أيونات، ومع ذلك يُعطى النيتروجين عدد تأكسد −3 والهيدروجين +1. فسّر ذلك في ضوء تعريف عدد التأكسد وقواعد تحديده، علمًا بأن كهروسالبية N = 3.04 وH = 2.20.', null, null, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 108، 110 — الكهروسالبية والجدول 2-3')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C3-L1-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'عدد التأكسد لذرة في المركب الأيوني هو عدد الإلكترونات التي فقدتها الذرة أو اكتسبتها عندما كوّنت الأيون.', '["","هذا هو العدد الذري، ولا يتغير في التفاعلات الكيميائية.","هذه إلكترونات التكافؤ، وهي لا تساوي عدد التأكسد دائمًا ولا تحدد إشارته.","عدد الأيونات في البلورة لا علاقة له بتعريف عدد التأكسد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.586Z"}'::jsonb),
('mcq', 2, 2, 'يُرمز لعدد التأكسد بالرمز n، مثل n(Cl) = +5 في KClO₃.', '["Z رمز العدد الذري.","e⁻ رمز الإلكترون.","","M رمز المولارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.586Z"}'::jsonb),
('mcq', 3, 1, 'يُكتب عدد التأكسد بوضع الإشارة قبل العدد (+3)، في حين تُكتب إشارة الشحنة الأيونية بعد العدد (3+).', '["هذه طريقة كتابة الشحنة الأيونية، إذ تُكتب إشارتها بعد العدد.","","عدد التأكسد يُكتب مع إشارته؛ فإغفال الإشارة غير صحيح.","الألومنيوم فقد ثلاثة إلكترونات، فعدد تأكسده موجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.586Z"}'::jsonb),
('mcq', 4, 3, 'عدد التأكسد أداة يستعملها العلماء لمساعدتهم على الاحتفاظ بمسار حركة الإلكترونات في تفاعلات الأكسدة والاختزال.', '["الكتلة المولية تُحسب من الكتل الذرية لا من أعداد التأكسد.","النيوترونات في النواة ولا علاقة لها بعدد التأكسد.","عدد التأكسد لا يقيس سرعة التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.586Z"}'::jsonb),
('mcq', 5, 0, 'البوتاسيوم من المجموعة 1 ويفقد إلكترونًا واحدًا عند تكوين K⁺، وعدد التأكسد في المركب الأيوني يساوي عدد الإلكترونات المفقودة (بإشارة موجبة)؛ لذا n(K) = +1.', '["","اكتساب الإلكترون يعطي عدد تأكسد سالبًا، والبوتاسيوم يفقد الإلكترون.","عدد البروتونات لا يتغير في التفاعل الكيميائي.","KCl مركب أيوني، وعدد التأكسد يعبّر عن الإلكترونات المفقودة لا عن عدد الروابط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.586Z"}'::jsonb),
('mcq', 6, 1, 'تعطي كل ذرة Mg إلكترونين إلى كل ذرة أكسجين فتتحول إلى O²⁻، وعدد التأكسد في المركب الأيوني يساوي عدد الإلكترونات المكتسبة بإشارة سالبة؛ أي −2.', '["فقد الإلكترونات يعطي عدد تأكسد موجبًا؛ والأكسجين هو الذي يكتسب.","","اكتساب إلكترون واحد يعطي −1 لا −2.","MgO مركب أيوني تنتقل فيه الإلكترونات انتقالًا كاملًا ولا تُشارَك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.587Z"}'::jsonb),
('mcq', 7, 3, 'تنص القاعدة على أن عدد تأكسد الذرة الأكثر كهروسالبية في الجزيء أو الأيون المعقد هو الشحنة نفسها التي سيكون عليها لو كان أيونًا، مثل N في NH₃ (−3).', '["عدد الروابط ليس هو عدد التأكسد، فقد يختلف عنه في الإشارة والقيمة.","الصفر للذرات غير المتحدة؛ أما الذرة المرتبطة بذرة مختلفة فلها عدد تأكسد غير صفري.","عدد إلكترونات التكافؤ موجب دائمًا، والذرة الأكثر كهروسالبية تأخذ عدد تأكسد سالبًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.587Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عدد التأكسد لذرة في مركب أيوني هو عدد الإلكترونات التي فقدتها الذرة أو اكتسبتها عند تكوين الأيون. ويُكتب بوضع الإشارة قبل العدد، فعدد تأكسد الحديد في Fe³⁺ هو +3، أما الشحنة الأيونية فتُكتب إشارتها بعد العدد: 3+.', '["التعريف: الإلكترونات المفقودة أو المكتسبة عند تكوين الأيون","عدد التأكسد +3 (الإشارة قبل العدد)","الشحنة الأيونية 3+ (الإشارة بعد العدد)"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"كتابة عدد التأكسد للحديد","marks":1},{"element":"كتابة الشحنة الأيونية وبيان الفرق","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف صحيح وبيان صحيح للفرق في الكتابة بالمثال."},{"level":"1–2 درجة","description":"تعريف صحيح فقط أو بيان الفرق دون تعريف."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["كتابة عدد التأكسد 3+ والشحنة +3 (عكس الصواب).","تعريف عدد التأكسد بعدد البروتونات."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.587Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) قبل التفاعل: K صفر وCl صفر (عنصران غير متحدين). بعد التفاعل: K في K⁺ يساوي +1، وCl في Cl⁻ يساوي −1. (ب) +1 لأن كل ذرة بوتاسيوم فقدت إلكترونًا واحدًا، و−1 لأن كل ذرة كلور اكتسبت إلكترونًا واحدًا.', '["K وCl صفر قبل التفاعل","K: +1 بعده","Cl: −1 بعده","تفسير القيمتين بالفقد والاكتساب"]'::jsonb, '[]'::jsonb, '[{"element":"أعداد التأكسد قبل التفاعل","marks":1},{"element":"أعداد التأكسد بعد التفاعل","marks":1},{"element":"تفسير +1 للبوتاسيوم","marks":1},{"element":"تفسير −1 للكلور","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أعداد صحيحة قبل التفاعل وبعده مع تفسير صحيح لكلتا القيمتين."},{"level":"2–3 درجات","description":"أعداد صحيحة مع تفسير ناقص."},{"level":"1 درجة","description":"قيمة أو قيمتان صحيحتان فقط."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ عدد تأكسد الكلور في Cl₂ يساوي −1.","عدّ عدد تأكسد Cl⁻ يساوي −2 لأن الجزيء ثنائي الذرة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.587Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في المركبات الجزيئية يُعامل الجزيء كأنه أيوني: تُنسب الإلكترونات المشتركة في كل رابطة إلى الذرة الأكثر كهروسالبية. النيتروجين (3.04) أكثر كهروسالبية من الهيدروجين (2.20)، فيُعدّ كأنه اكتسب إلكترونًا من كل ذرة من ذرات الهيدروجين الثلاث، فيكون عدد تأكسده −3 (الشحنة التي سيكون عليها لو كان أيونًا)، وتُعدّ كل ذرة هيدروجين كأنها فقدت إلكترونًا فعدد تأكسدها +1. ومجموع أعداد التأكسد: −3 + 3(+1) = 0 كما يجب في مركب متعادل.', '["تُنسب الإلكترونات المشتركة إلى الذرة الأعلى كهروسالبية","N أعلى كهروسالبية فيأخذ −3","H يأخذ +1","التحقق: المجموع صفر"]'::jsonb, '["N > H في الكهروسالبية (3.04 > 2.20)","ثلاث روابط N–H ⇒ يُعدّ N كأنه اكتسب 3e⁻ ⇒ −3","n(N) + 3(+1) = 0 ⇒ n(N) = −3"]'::jsonb, '[{"element":"فكرة نسب الإلكترونات للأعلى كهروسالبية","marks":1},{"element":"تعليل −3 للنيتروجين","marks":1},{"element":"تعليل +1 للهيدروجين","marks":1},{"element":"التحقق بمجموع أعداد التأكسد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط الكهروسالبية بتعريف عدد التأكسد مع التحقق من المجموع."},{"level":"2–3 درجات","description":"يربط بالكهروسالبية لكن دون تحقق أو بتفسير ناقص لأحد العنصرين."},{"level":"1 درجة","description":"يذكر القيم دون تفسير مقبول."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["القول إن عدد التأكسد صفر لعدم وجود أيونات.","إعطاء الهيدروجين −1 لأنه في جزيء.","الخلط بين عدد الروابط وعدد التأكسد."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.587Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C3-L1-O04') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C3-L1-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما عدد تأكسد الكبريت في حمض الكبريتيك H₂SO₄؟', null, '["+8","+2","+6","−2"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 110 — قواعد تحديد أعداد التأكسد (الجدول 2-3)'),
('mcq', 2, 'ما عدد تأكسد المنجنيز في أيون البيرمنجنات MnO₄⁻؟', null, '["+8","+6","−1","+7"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 112 — التقويم (13b)'),
('mcq', 3, 'ما عدد تأكسد الكروم في ثنائي كرومات البوتاسيوم K₂Cr₂O₇؟', null, '["+12","+6","+7","+5"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 110 — قواعد تحديد أعداد التأكسد (الجدول 2-3)'),
('mcq', 4, 'ما عدد تأكسد الأكسجين في فوق أكسيد الهيدروجين H₂O₂؟', null, '["−1","−2","+1","صفر"]'::jsonb, 'تطبيق', 'تطبيق قاعدة', 'سهل', 'الكتاب ص 110 — قواعد تحديد أعداد التأكسد (الجدول 2-3)'),
('mcq', 5, 'ما عدد تأكسد الهيدروجين في هيدريد الكالسيوم CaH₂؟', null, '["+1","+2","−2","−1"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 110 — قواعد تحديد أعداد التأكسد (الجدول 2-3)'),
('mcq', 6, 'في أيّ الأيونات الآتية يكون عدد تأكسد الكلور +5؟', null, '["ClO₃⁻","ClO₄⁻","ClO⁻","ClO₂⁻"]'::jsonb, 'تطبيق', 'مقارنة حسابية', 'سهل', 'الكتاب ص 110 — قواعد تحديد أعداد التأكسد (الجدول 2-3)'),
('mcq', 7, 'ما عدد تأكسد الكبريت في ثيوكبريتات الصوديوم Na₂S₂O₃؟', null, '["+4","+2","+3","−2"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 110 — قواعد تحديد أعداد التأكسد (الجدول 2-3)'),
('essay', 1, 'حدد عدد تأكسد العنصر المطلوب في كلٍّ مما يأتي، واذكر القاعدة التي استعملتها:
(أ) الأكسجين في O₂
(ب) الحديد في الأيون Fe³⁺
(ج) الأكسجين في OF₂
(د) الفوسفور في الأيون PO₄³⁻', null, null, 'تطبيق', 'حساب مع تعليل', 'متوسط', 'الكتاب ص 110 — قواعد تحديد أعداد التأكسد (الجدول 2-3)'),
('essay', 2, 'احسب عدد تأكسد الكبريت في كبريتات الألومنيوم Al₂(SO₄)₃، موضحًا خطوات الحل.', null, null, 'تطبيق', 'حساب بخطوات', 'صعب', 'الكتاب ص 110 — قواعد تحديد أعداد التأكسد (الجدول 2-3)'),
('essay', 3, 'رتّب المواد الآتية تصاعديًا حسب عدد تأكسد النيتروجين فيها، مبيّنًا حساب كل قيمة:
HNO₃ ، NH₃ ، N₂ ، NO₂ ، N₂H₄', null, null, 'تحليل', 'حساب وترتيب', 'متوسط', 'الكتاب ص 111 — مثال 2-3 ومسائل تدريبية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C3-L1-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'مجموع أعداد التأكسد في المركب المتعادل صفر: 2(+1) + n(S) + 4(−2) = 0 ⇒ n(S) = +6.', '["ناتج إهمال ذرتي الهيدروجين (+1 لكل منهما) عند جمع أعداد التأكسد.","ناتج عدّ عدد تأكسد الأكسجين −1 كما في فوق الأكاسيد، وH₂SO₄ ليس فوق أكسيد.","","هذا عدد تأكسد الكبريت في الكبريتيدات، لا حين يرتبط بالأكسجين الأعلى كهروسالبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.588Z"}'::jsonb),
('mcq', 2, 3, 'مجموع أعداد التأكسد في الأيون متعدد الذرات يساوي شحنته: n(Mn) + 4(−2) = −1 ⇒ n(Mn) = +7.', '["ناتج جعل مجموع أعداد التأكسد صفرًا، مع أن مجموعها في الأيون يساوي شحنته (−1).","ناتج استعمال شحنة −2 بدل −1، وهي شحنة أيون آخر (MnO₄²⁻).","هذه شحنة الأيون كله، لا عدد تأكسد المنجنيز وحده.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.588Z"}'::jsonb),
('mcq', 3, 1, '2(+1) + 2n(Cr) + 7(−2) = 0 ⇒ 2n(Cr) = +12 ⇒ n(Cr) = +6.', '["ناتج عدم القسمة على 2؛ فالقيمة +12 مجموع أعداد تأكسد ذرتي الكروم معًا.","","ناتج إهمال ذرتي البوتاسيوم (+1 لكل منهما) في المجموع.","ناتج عدّ البوتاسيوم +2، مع أن فلزات المجموعة 1 عدد تأكسدها +1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.588Z"}'::jsonb),
('mcq', 4, 0, 'وفق القاعدة 5، عدد تأكسد الأكسجين في فوق الأكاسيد مثل H₂O₂ يساوي −1، ويتحقق ذلك من المجموع: 2(+1) + 2(−1) = 0.', '["","−2 هو عدد تأكسد الأكسجين في معظم مركباته، لكن فوق الأكاسيد استثناء.","الأكسجين أكثر كهروسالبية من الهيدروجين فيأخذ عددًا سالبًا.","الصفر لذرة الأكسجين غير المتحدة (O₂) فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.588Z"}'::jsonb),
('mcq', 5, 3, 'الكالسيوم من المجموعة 2 فعدد تأكسده +2، ومجموع أعداد التأكسد صفر: +2 + 2n(H) = 0 ⇒ n(H) = −1، وهذا يتفق مع قاعدة الهيدريدات.', '["+1 عدد تأكسد الهيدروجين في معظم مركباته، أما في الهيدريدات فيساوي −1.","+2 هو عدد تأكسد الكالسيوم (المجموعة 2) لا الهيدروجين.","ناتج عدم القسمة على عدد ذرات الهيدروجين؛ −2 مجموع ذرتي الهيدروجين معًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.588Z"}'::jsonb),
('mcq', 6, 0, 'في ClO₃⁻: n(Cl) + 3(−2) = −1 ⇒ n(Cl) = +5، فهو الأيون الوحيد بين البدائل الذي يكون فيه الكلور +5.', '["","n(Cl) + 4(−2) = −1 ⇒ +7.","n(Cl) + (−2) = −1 ⇒ +1.","n(Cl) + 2(−2) = −1 ⇒ +3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.588Z"}'::jsonb),
('mcq', 7, 1, '2(+1) + 2n(S) + 3(−2) = 0 ⇒ 2n(S) = +4 ⇒ n(S) = +2.', '["ناتج عدم القسمة على 2؛ فالقيمة +4 مجموع ذرتي الكبريت.","","ناتج إهمال ذرتي الصوديوم (+1 لكل منهما).","هذا عدد تأكسد الكبريت في الكبريتيدات، وهنا يرتبط الكبريت بالأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.588Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) صفر؛ لأن عدد تأكسد الذرة غير المتحدة يساوي صفرًا. (ب) +3؛ لأن عدد تأكسد الأيون أحادي الذرة يساوي شحنته. (ج) +2؛ لأن الفلور (الأكثر كهروسالبية) عدد تأكسده −1 دائمًا، فالأكسجين المرتبط بالفلور عدد تأكسده موجب: n(O) + 2(−1) = 0 ⇒ +2. (د) +5؛ لأن مجموع أعداد التأكسد في الأيون متعدد الذرات يساوي شحنته: n(P) + 4(−2) = −3 ⇒ +5.', '["(أ) صفر — الذرة غير المتحدة","(ب) +3 — الأيون أحادي الذرة","(ج) +2 — الفلور −1 دائمًا","(د) +5 — مجموع الأيون = شحنته"]'::jsonb, '["(ج) n(O) + 2(−1) = 0 ⇒ n(O) = +2","(د) n(P) + 4(−2) = −3 ⇒ n(P) = +5"]'::jsonb, '[{"element":"(أ) مع القاعدة","marks":1},{"element":"(ب) مع القاعدة","marks":1},{"element":"(ج) مع القاعدة","marks":1},{"element":"(د) مع القاعدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"القيم الأربع صحيحة مع القواعد."},{"level":"2–3 درجات","description":"قيمتان أو ثلاث صحيحة."},{"level":"1 درجة","description":"قيمة واحدة صحيحة."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["إعطاء الأكسجين −2 في OF₂.","عدّ عدد تأكسد O في O₂ يساوي −2.","جعل مجموع PO₄³⁻ صفرًا فيخرج +8."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.588Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الألومنيوم +3 (القاعدة 7) والأكسجين −2. مجموع أعداد التأكسد في المركب المتعادل صفر: 2(+3) + 3n(S) + 12(−2) = 0 ⇒ 6 + 3n(S) − 24 = 0 ⇒ 3n(S) = 18 ⇒ n(S) = +6. (ويمكن الحل بأيون الكبريتات SO₄²⁻: n(S) + 4(−2) = −2 ⇒ +6.)', '["n(Al) = +3 وn(O) = −2","عدد الذرات: 2 Al و3 S و12 O","معادلة المجموع = صفر","n(S) = +6"]'::jsonb, '["n(Al) = +3 ، n(O) = −2","2(+3) + 3n(S) + 12(−2) = 0","6 + 3n(S) − 24 = 0 ⇒ 3n(S) = 18","n(S) = +6"]'::jsonb, '[{"element":"أعداد تأكسد Al وO","marks":1},{"element":"عدّ الذرات وكتابة معادلة المجموع","marks":2},{"element":"الحل والوصول إلى +6","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات كاملة وصحيحة تصل إلى +6."},{"level":"2–3 درجات","description":"معادلة صحيحة مع خطأ حسابي، أو جواب صحيح بخطوات ناقصة."},{"level":"1 درجة","description":"يحدد أعداد تأكسد Al وO فقط."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ ذرات الأكسجين 4 بدل 12.","نسيان القسمة على 3 ذرات كبريت (n = +18).","إعطاء الألومنيوم +2."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.589Z"}'::jsonb),
('essay', 3, null::int, null, null, 'NH₃: n + 3(+1) = 0 ⇒ −3. N₂H₄: 2n + 4(+1) = 0 ⇒ −2. N₂: صفر (عنصر غير متحد). NO₂: n + 2(−2) = 0 ⇒ +4. HNO₃: +1 + n + 3(−2) = 0 ⇒ +5. الترتيب تصاعديًا: NH₃ (−3) < N₂H₄ (−2) < N₂ (0) < NO₂ (+4) < HNO₃ (+5).', '["NH₃: −3","N₂H₄: −2","N₂: 0","NO₂: +4","HNO₃: +5","الترتيب الصحيح"]'::jsonb, '["NH₃: n + 3 = 0 ⇒ −3","N₂H₄: 2n + 4 = 0 ⇒ −2","N₂: صفر","NO₂: n − 4 = 0 ⇒ +4","HNO₃: 1 + n − 6 = 0 ⇒ +5","ترتيب القيم تصاعديًا"]'::jsonb, '[{"element":"حساب القيم الخمس","marks":5},{"element":"الترتيب","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"القيم الخمس صحيحة والترتيب صحيح."},{"level":"3–5 درجات","description":"ثلاث قيم أو أكثر صحيحة مع ترتيب متسق معها."},{"level":"1–2 درجة","description":"قيمة أو قيمتان صحيحتان."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدم القسمة على 2 في N₂H₄ (−4).","إعطاء N في NH₃ القيمة +3.","الترتيب تنازليًا بدل تصاعديًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.589Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
