insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C3-L1-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في تفاعل صناعة الأمونيا N₂ + 3H₂ → 2NH₃ (كهروسالبية N = 3.04، H = 2.20)، أيّ العبارات الآتية صحيحة؟', null, '["تأكسد النيتروجين لأنه يجذب الإلكترونات المشتركة بقوة أكبر","اختُزل النيتروجين لأنه يجذب الإلكترونات المشتركة بقوة أكبر","اختُزل الهيدروجين لأن كهروسالبيته أقل من النيتروجين","لا أكسدة ولا اختزال لأن التفاعل لا يكوّن أيونات"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 108 — تفاعلات الأكسدة والاختزال والكهروسالبية'),
('mcq', 2, 'في تفاعلات الأكسدة والاختزال التي تتضمن مركبات جزيئية، تُعامل الذرة الأعلى كهروسالبية كأنها:', null, '["اختُزلت باكتسابها الإلكترونات","تأكسدت بفقدها الإلكترونات","تأكسدت باكتسابها الإلكترونات","لم تتغير لأنها تشارك الإلكترونات"]'::jsonb, 'تذكر', 'تذكر تعميم', 'سهل', 'الكتاب ص 112 — الخلاصة'),
('mcq', 3, 'كيف تتدرج الكهروسالبية في الجدول الدوري بصورة عامة؟', null, '["تقل من اليسار إلى اليمين عبر الدورة، وتزداد نحو أسفل المجموعة","تزداد من اليسار إلى اليمين عبر الدورة، وتزداد نحو أسفل المجموعة","تزداد من اليسار إلى اليمين عبر الدورة، وتقل نحو أسفل المجموعة","تقل من اليسار إلى اليمين عبر الدورة، وتقل نحو أسفل المجموعة"]'::jsonb, 'تذكر', 'تذكر نمط', 'سهل', 'الكتاب ص 108 — الشكل 4-3 تدرج الكهروسالبية'),
('mcq', 4, 'أيّ العناصر الآتية يُتوقع أن يكون أقوى عامل مختزل؟', null, '["Li","Be","F","Cs"]'::jsonb, 'تطبيق', 'توقع', 'متوسط', 'الكتاب ص 108 — الشكل 4-3 تدرج الكهروسالبية'),
('mcq', 5, 'أيّ عناصر المجموعة 17 الآتية يُتوقع أن يكون أقوى عامل مؤكسد؟', null, '["Cl","F","Br","I"]'::jsonb, 'تطبيق', 'توقع', 'سهل', 'الكتاب ص 108 — الشكل 4-3 تدرج الكهروسالبية'),
('mcq', 6, 'في التفاعل H₂ + Cl₂ → 2HCl (كهروسالبية H = 2.20، Cl = 3.16)، أيّ العبارات الآتية صحيحة؟', null, '["تأكسد الكلور، والهيدروجين هو العامل المؤكسد","اختُزل الهيدروجين، والكلور هو العامل المختزل","تأكسد الهيدروجين، والكلور هو العامل المؤكسد","تأكسد الهيدروجين، والكلور هو العامل المختزل"]'::jsonb, 'تطبيق', 'تحليل حالة', 'متوسط', 'الكتاب ص 108 — تفاعلات الأكسدة والاختزال والكهروسالبية'),
('mcq', 7, 'يتفاعل الكربون مع الأكسجين: C + O₂ → CO₂ (كهروسالبية C = 2.55، O = 3.44). أيّ العبارات الآتية صحيحة؟', null, '["تفاعل أكسدة واختزال يُختزل فيه الأكسجين لأنه أعلى كهروسالبية","ليس أكسدة واختزالًا لأن CO₂ مركب جزيئي لا تتكون فيه أيونات","تفاعل أكسدة واختزال يُختزل فيه الكربون لأنه أقل كهروسالبية","تفاعل أكسدة فقط؛ إذ يتأكسد الكربون ولا يُختزل أي عنصر"]'::jsonb, 'تحليل', 'تقويم عبارات', 'صعب', 'الكتاب ص 108، 111 — الكهروسالبية ومسائل تدريبية (8a)'),
('essay', 1, 'يُستعمل التفاعل N₂ + 3H₂ → 2NH₃ في صناعة الأمونيا، والمتفاعلات والنواتج كلها مركبات جزيئية. فسّر كيف يُعدّ هذا التفاعل تفاعل أكسدة واختزال مع أنه لا تتكون فيه أيونات، وحدد العامل المؤكسد والعامل المختزل (كهروسالبية N = 3.04، H = 2.20).', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 108 — تفاعلات الأكسدة والاختزال والكهروسالبية'),
('essay', 2, 'اعتمادًا على تدرج الكهروسالبية في الجدول الدوري:
(أ) صنّف العناصر الآتية إلى عوامل مختزلة قوية وعوامل مؤكسدة قوية: Na ، Ba ، F ، O ، Br.
(ب) أيّهما أقوى عاملًا مختزلًا: Na أم Cs؟ علّل.
(ج) أيّهما أقوى عاملًا مؤكسدًا: Cl أم I؟ علّل.', null, null, 'تطبيق', 'تصنيف وتوقع', 'صعب', 'الكتاب ص 108 — الشكل 4-3 تدرج الكهروسالبية'),
('essay', 3, 'يتفاعل الهيدروجين مع الفلور مكوّنًا فلوريد الهيدروجين: H₂ + F₂ → 2HF (كهروسالبية H = 2.20، F = 3.98).
(أ) حدد العنصر الذي تأكسد والعنصر الذي اختُزل، معلّلًا بالكهروسالبية.
(ب) اكتب عدد تأكسد كلٍّ من H وF قبل التفاعل وبعده، وبيّن اتساق ذلك مع إجابتك في (أ).', null, null, 'تحليل', 'تحليل وتعليل', 'صعب', 'الكتاب ص 108، 110 — الكهروسالبية والجدول 2-3')
