from (values
('mcq', 1, 1, 'النيتروجين أعلى كهروسالبية (3.04) من الهيدروجين (2.20)، فيجذب الإلكترونات المشتركة نحوه ويُعامل كأنه اكتسبها فيُختزل، ويتأكسد الهيدروجين.', '["الذرة التي تجذب الإلكترونات نحوها تُعامل كأنها اكتسبتها، أي اختُزلت لا تأكسدت.","","الذرة الأقل كهروسالبية تُعامل كأنها فقدت الإلكترونات فتتأكسد.","يُعدّ هذا التفاعل أكسدة واختزالًا رغم عدم تكوّن أيونات، اعتمادًا على الكهروسالبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T11:36:22.589Z"}'::jsonb),
('mcq', 2, 0, 'في تفاعلات المركبات الجزيئية تُختزل الذرات الأعلى كهروسالبية، وتتأكسد الذرات ذات الكهروسالبية الأقل.', '["","هذا ما يُنسب إلى الذرة الأقل كهروسالبية.","اكتساب الإلكترونات اختزال لا أكسدة.","رغم المشاركة، تُنسب الإلكترونات إلى الذرة الأعلى كهروسالبية فتُعدّ مختزلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.590Z"}'::jsonb),
('mcq', 3, 2, 'تزداد الكهروسالبية من اليسار إلى اليمين عبر الدورة، وتقل في الاتجاه نحو أسفل المجموعة الواحدة.', '["عكس التدرج الصحيح في الاتجاهين.","الكهروسالبية تقل لا تزداد بالاتجاه نحو أسفل المجموعة.","","الكهروسالبية تزداد لا تقل عبر الدورة من اليسار إلى اليمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.590Z"}'::jsonb),
('mcq', 4, 3, 'العوامل المختزلة القوية هي العناصر منخفضة الكهروسالبية في المجموعتين 1 و2، والكهروسالبية تقل نحو أسفل المجموعة؛ فالسيزيوم Cs (أسفل المجموعة 1) أقلها كهروسالبية وأقواها عاملًا مختزلًا.', '["الليثيوم في المجموعة 1 أيضًا لكنه أعلى المجموعة فكهروسالبيته أكبر من السيزيوم.","البريليوم في المجموعة 2 وأعلاها، وكهروسالبيته أكبر من فلزات المجموعة 1 في الأسفل.","الفلور أعلى العناصر كهروسالبية، فهو عامل مؤكسد قوي لا مختزل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-17T11:36:22.590Z"}'::jsonb),
('mcq', 5, 1, 'العوامل المؤكسدة القوية هي العناصر ذات الكهروسالبية المرتفعة، والكهروسالبية تقل نحو أسفل المجموعة؛ فالفلور أعلاها كهروسالبية وأقواها عاملًا مؤكسدًا.', '["الكلور عامل مؤكسد قوي، لكن كهروسالبيته أقل من الفلور الذي يعلوه في المجموعة.","","البروم أدنى من الفلور والكلور في المجموعة، فكهروسالبيته أقل.","اليود أسفل هذه العناصر وأقلها كهروسالبية، فهو أضعفها عاملًا مؤكسدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-17T11:36:22.591Z"}'::jsonb),
('mcq', 6, 2, 'الكلور (3.16) أعلى كهروسالبية من الهيدروجين (2.20)، فتنزاح نحوه الإلكترونات المشتركة فيُختزل ويكون عاملًا مؤكسدًا، ويتأكسد الهيدروجين فيكون عاملًا مختزلًا.', '["الكلور أعلى كهروسالبية فيُعامل كأنه اكتسب الإلكترونات أي اختُزل.","الهيدروجين أقل كهروسالبية فيُعامل كأنه فقد الإلكترونات أي تأكسد.","","الكلور اختُزل، والمادة المختزلة هي العامل المؤكسد لا المختزل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T11:36:22.591Z"}'::jsonb),
('mcq', 7, 0, 'الأكسجين (3.44) أعلى كهروسالبية من الكربون (2.55)، فتنزاح نحوه الإلكترونات المشتركة فيُعدّ مختزلًا (من صفر إلى −2)، ويتأكسد الكربون (من صفر إلى +4)؛ فهو تفاعل أكسدة واختزال رغم أن CO₂ مركب جزيئي.', '["","تكوّن الأيونات ليس شرطًا؛ ففي المركبات الجزيئية تُحدد الأكسدة والاختزال بالكهروسالبية.","الذرة الأقل كهروسالبية (الكربون) تُعامل كأنها فقدت الإلكترونات فتتأكسد.","الأكسدة والاختزال يحدثان معًا؛ فالأكسجين يُختزل في أثناء تأكسد الكربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.591Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في الروابط التساهمية تتشارك الذرتان الإلكترونات، لكن الذرة الأعلى كهروسالبية تجذب الإلكترونات المشتركة بقوة أكبر، فتُعامل كأنها اكتسبتها (اختُزلت)، وتُعامل الذرة الأقل كهروسالبية كأنها فقدتها (تأكسدت). النيتروجين (3.04) أعلى كهروسالبية من الهيدروجين (2.20)، لذا اختُزل النيتروجين فهو العامل المؤكسد (N₂)، وتأكسد الهيدروجين فهو العامل المختزل (H₂).', '["الذرة الأعلى كهروسالبية تجذب الإلكترونات المشتركة","تُعامل كأنها اختُزلت والأخرى تأكسدت","N اختُزل ⇒ N₂ عامل مؤكسد","H تأكسد ⇒ H₂ عامل مختزل"]'::jsonb, '[]'::jsonb, '[{"element":"فكرة جذب الإلكترونات المشتركة","marks":1},{"element":"ربطها بالأكسدة والاختزال","marks":1},{"element":"العامل المؤكسد","marks":1},{"element":"العامل المختزل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح كامل وتحديد صحيح للعاملين."},{"level":"2–3 درجات","description":"تفسير صحيح مع خطأ في أحد العاملين، أو تحديد صحيح بتفسير ناقص."},{"level":"1 درجة","description":"يحدد عاملًا واحدًا دون تفسير."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["القول إن التفاعل ليس أكسدة واختزال لعدم تكوّن أيونات.","عدّ الهيدروجين عاملًا مؤكسدًا.","عكس العلاقة بين الكهروسالبية والاختزال."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.591Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) عوامل مختزلة قوية: Na وBa (المجموعتان 1 و2، كهروسالبية منخفضة). عوامل مؤكسدة قوية: F وO وBr (المجموعة 17 والأكسجين، كهروسالبية مرتفعة). (ب) Cs؛ لأنه أسفل Na في المجموعة 1، والكهروسالبية تقل نحو أسفل المجموعة، فيفقد الإلكترونات بسهولة أكبر. (ج) Cl؛ لأنه أعلى من I في المجموعة 17، فكهروسالبيته أكبر ويجذب الإلكترونات بقوة أكبر.', '["Na وBa مختزلة قوية","F وO وBr مؤكسدة قوية","Cs أقوى مختزلًا مع التعليل","Cl أقوى مؤكسدًا مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التصنيف","marks":2},{"element":"(ب) مع التعليل","marks":1.5},{"element":"(ج) مع التعليل","marks":1.5}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح كامل ومقارنتان صحيحتان معللتان بتدرج الكهروسالبية."},{"level":"3–4 درجات","description":"تصنيف صحيح مع خطأ في إحدى المقارنتين أو تعليل ناقص."},{"level":"1–2 درجة","description":"تصنيف جزئي صحيح فقط."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ الأكسجين عاملًا مختزلًا.","القول إن الكهروسالبية تزداد نحو أسفل المجموعة.","عدّ اليود أقوى مؤكسدًا لأن ذرته أكبر."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.592Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الفلور أعلى كهروسالبية (3.98) من الهيدروجين (2.20)، فتنزاح الإلكترونات المشتركة نحوه فيُختزل الفلور ويتأكسد الهيدروجين. (ب) قبل التفاعل: H صفر، F صفر (عنصران غير متحدين). بعده في HF: F يساوي −1 (الفلور −1 دائمًا) وH يساوي +1. زاد عدد تأكسد H (أكسدة) وقلّ عدد تأكسد F (اختزال)، وهذا يتفق مع (أ).', '["F اختُزل لأنه أعلى كهروسالبية","H تأكسد","أعداد التأكسد قبل التفاعل صفر","في HF: H = +1 وF = −1","الاتساق: الزيادة أكسدة والنقصان اختزال"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تحديد المتأكسد والمختزل مع التعليل","marks":2},{"element":"(ب) أعداد التأكسد قبل التفاعل وبعده","marks":2},{"element":"(ب) بيان الاتساق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد وتعليل صحيحان وأعداد تأكسد صحيحة مع بيان الاتساق."},{"level":"3–4 درجات","description":"تحديد صحيح مع خطأ في عدد تأكسد أو غياب بيان الاتساق."},{"level":"1–2 درجة","description":"تحديد صحيح دون تعليل أو أعداد تأكسد فقط."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ الهيدروجين مختزلًا لأنه يكتسب الفلور.","إعطاء الفلور في F₂ العدد −1.","عدّ التفاعل غير أكسدة واختزال لأن HF جزيئي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.592Z"}'::jsonb)
