('mcq', 4, 1, 'الكربون غير المتحد عدد تأكسده صفر، وفي CO₂: n(C) + 2(−2) = 0 ⇒ +4؛ فعدد تأكسده زاد من صفر إلى +4، والزيادة تعني الأكسدة.', '["الكربون أقل كهروسالبية من الأكسجين، فعدد تأكسده في CO₂ موجب: n + 2(−2) = 0 ⇒ +4.","","ناتج عدّ ذرة أكسجين واحدة؛ في CO₂ ذرتا أكسجين فيصبح +4.","عكس اتجاه التغير؛ الكربون عنصر غير متحد في المتفاعلات (صفر)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.593Z"}'::jsonb),
('mcq', 5, 0, 'Cl: صفر في Cl₂ ⇒ −1 في ZnCl₂ (نقصان = اختزال)؛ I: −1 في ZnI₂ ⇒ صفر في I₂ (زيادة = أكسدة)؛ أما Zn فبقي +2.', '["","التغيرات صحيحة لكن التسمية معكوسة: النقصان اختزال والزيادة أكسدة.","الخارصين +2 في ZnI₂ وفي ZnCl₂، فلم يتغير عدد تأكسده.","الكلور يصبح −1 في ZnCl₂ لا +1، واليود يصبح صفرًا في I₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.593Z"}'::jsonb),
('mcq', 6, 3, 'عدد تأكسد الحديد في Fe₂O₃: 2n + 3(−2) = 0 ⇒ +3، ويصبح صفرًا في Fe؛ فقد نقص عدد تأكسده، أي اختُزلت المادة Fe₂O₃. والأكسجين بقي −2، والألومنيوم تأكسد من صفر إلى +3.', '["عدد تأكسد الألومنيوم زاد من صفر إلى +3، فقد تأكسد.","Al₂O₃ ناتج تأكسد الألومنيوم، وليس المادة المتفاعلة التي اختُزلت.","Fe ناتج الاختزال، والسؤال عن المادة المتفاعلة التي اختُزلت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.593Z"}'::jsonb),
('mcq', 7, 2, 'Mn: n + 2(−2) = 0 ⇒ +4 في MnO₂، وn + 2(−1) = 0 ⇒ +2 في MnCl₂ (نقصان = اختزال). Cl: −1 في HCl ⇒ صفر في Cl₂ لبعض الذرات (زيادة = أكسدة). H بقي +1 وO بقي −2.', '["اتجاه التغيرات معكوس: المنجنيز +4 في MnO₂ و+2 في MnCl₂، والكلور −1 في HCl.","الهيدروجين بقي +1 في HCl وH₂O، فلم يُختزل.","","الأكسجين بقي −2، والنقصان من +4 إلى +2 اختزال لا أكسدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.594Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) CdO: Cd = +2، O = −2. CO: C = +2، O = −2. Cd: صفر. CO₂: C = +4، O = −2. (ب) Cd: من +2 إلى صفر (نقص 2) ⇒ اختُزل الكادميوم، أي اختُزلت المادة CdO. C: من +2 إلى +4 (زاد 2) ⇒ تأكسد الكربون، أي تأكسدت المادة CO. O: لا تغير.', '["أعداد التأكسد في المتفاعلات","أعداد التأكسد في النواتج","Cd: −2 اختزال","C: +2 أكسدة","O: لا تغير"]'::jsonb, '["CdO: n(Cd) − 2 = 0 ⇒ +2","CO: n(C) − 2 = 0 ⇒ +2","CO₂: n(C) − 4 = 0 ⇒ +4","Cd عنصر غير متحد ⇒ صفر","التغير: Cd (+2 → 0) = −2 اختزال، C (+2 → +4) = +2 أكسدة، O (−2 → −2) لا تغير"]'::jsonb, '[{"element":"أعداد التأكسد","marks":2},{"element":"تغير الكادميوم واختزاله","marks":1},{"element":"تغير الكربون وتأكسده","marks":1},{"element":"الأكسجين لم يتغير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"أعداد تأكسد صحيحة وتغيرات صحيحة مع تحديد المتأكسد والمختزل والأكسجين."},{"level":"3–4 درجات","description":"أعداد صحيحة مع خطأ في تحديد أحد التغيرات."},{"level":"1–2 درجة","description":"بعض أعداد التأكسد صحيحة فقط."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ عدد تأكسد الكربون في CO صفرًا.","عدّ الأكسجين متغيرًا لانتقاله من CdO إلى CO₂.","الحكم بأن النقصان أكسدة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.594Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) 2Fe + 6HBr → 2FeBr₃ + 3H₂. (ب) الحديد: من صفر إلى +3 لكل ذرة، وللذرتين زيادة كلية +6 ⇒ تأكسد. الهيدروجين: من +1 إلى صفر لكل ذرة، ولست ذرات نقصان كلي −6 ⇒ اختُزل. البروم بقي −1. (ج) الزيادة الكلية (+6) تساوي النقصان الكلي (6)؛ لأن الإلكترونات التي فقدها الحديد اكتسبها الهيدروجين.', '["المعادلة الموزونة","Fe: 0 → +3، الكلي +6، أكسدة","H: +1 → 0، الكلي −6، اختزال","Br لا يتغير","تساوي الزيادة والنقصان"]'::jsonb, '["كتابة الصيغ: Fe، HBr، FeBr₃، H₂","الوزن: 2Fe + 6HBr → 2FeBr₃ + 3H₂","Fe: صفر ⇒ +3 ؛ 2 × (+3) = +6","H: +1 ⇒ صفر ؛ 6 × (−1) = −6","Br: −1 ⇒ −1 (لا تغير)"]'::jsonb, '[{"element":"المعادلة الموزونة","marks":1},{"element":"التغير الكلي للحديد","marks":1.5},{"element":"التغير الكلي للهيدروجين","marks":1.5},{"element":"ملاحظة التساوي وتفسيرها","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلة موزونة وتغيرات كلية صحيحة وملاحظة التساوي مفسرة."},{"level":"3–4 درجات","description":"معادلة موزونة مع خطأ في أحد التغيرات الكلية أو في التفسير."},{"level":"1–2 درجة","description":"معادلة صحيحة فقط أو تغيرات لكل ذرة دون الكلي."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["كتابة FeBr₂ بدل FeBr₃.","حساب التغير لذرة واحدة دون ضربه في عدد الذرات.","عدّ البروم متأكسدًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.594Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في (1): K من صفر إلى +1 (فقد إلكترونًا، تأكسد)، Cl من صفر إلى −1 (اكتسب إلكترونًا، اختُزل). في (2): Br من −1 إلى صفر (فقد إلكترونًا، تأكسد)، Cl من صفر إلى −1 (اختُزل)، وK بقي +1. القاعدة: عندما تتأكسد الذرة يزيد عدد تأكسدها، وعندما تُختزل يقل عدد تأكسدها. التفسير: فقد الإلكترونات السالبة يجعل الذرة أكثر موجبية فيزيد عددها، واكتسابها يجعلها أكثر سالبية فيقل عددها.', '["تغيرات التفاعل (1)","تغيرات التفاعل (2) وبقاء K","القاعدة: الأكسدة زيادة والاختزال نقصان","التفسير بالإلكترونات السالبة"]'::jsonb, '[]'::jsonb, '[{"element":"تغيرات التفاعل (1)","marks":1},{"element":"تغيرات التفاعل (2)","marks":1},{"element":"استنتاج القاعدة","marks":1},{"element":"التفسير بالإلكترونات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تتبع صحيح للتفاعلين واستنتاج القاعدة مع تفسير صحيح."},{"level":"2–3 درجات","description":"تتبع صحيح مع قاعدة صحيحة دون تفسير، أو تفسير مع خطأ في التتبع."},{"level":"1 درجة","description":"تتبع جزئي فقط."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["ربط اكتساب الإلكترونات بزيادة عدد التأكسد.","عدّ K في التفاعل (2) متأكسدًا.","القاعدة دون أمثلة مستخرجة من التفاعلين."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.594Z"}'::jsonb)
