('mcq', 3, 'في التفاعل 2Mg + O₂ → 2MgO، كم إلكترونًا يكتسبه جزيء O₂ الواحد؟', null, '["2","1","8","4"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 104 — الشكل 1-3'),
('mcq', 4, 'تتأكسد أيونات Fe²⁺ إلى Fe³⁺ عند تفاعلها مع الكلور (Cl₂ + 2e⁻ → 2Cl⁻). كم أيون Fe²⁺ يلزم لاختزال جزيء Cl₂ واحد؟', null, '["1","3","2","4"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 105، 109 — مسائل تدريبية (1)'),
('mcq', 5, 'قال طالب: «صدأ الحديد تفاعل أكسدة فقط». أيّ مما يأتي يصحح قوله؟', null, '["يُختزل الحديد لأنه يكتسب الأكسجين","قوله صحيح لأن الأكسجين لا يتغير في الصدأ","يتأكسد الأكسجين أيضًا لأنه يتحد بالحديد","يُختزل الأكسجين لأنه يكتسب الإلكترونات التي يفقدها الحديد"]'::jsonb, 'فهم', 'تصحيح مفهوم', 'متوسط', 'الكتاب ص 105، 109 — واقع الكيمياء في الحياة'),
('mcq', 6, 'نصفا التفاعل: Al → Al³⁺ + 3e⁻ و Zn²⁺ + 2e⁻ → Zn. ما أصغر عدد من ذرات Al وأيونات Zn²⁺ يجعل الإلكترونات المفقودة تساوي المكتسبة؟', null, '["3 Al و 2 Zn²⁺","2 Al و 3 Zn²⁺","1 Al و 1 Zn²⁺","2 Al و 2 Zn²⁺"]'::jsonb, 'تحليل', 'حساب واستنتاج', 'صعب', 'الكتاب ص 105 — الأكسدة والاختزال عمليتان مترافقتان'),
('mcq', 7, 'في التفاعل 2Br⁻ + Cl₂ → Br₂ + 2Cl⁻ يفقد أيونا البروميد إلكترونين. ماذا يحدث في الوقت نفسه؟', null, '["يكتسب جزيء Cl₂ الإلكترونين فيُختزل إلى أيوني Cl⁻","يفقد جزيء Cl₂ إلكترونين أيضًا فيتأكسد","يبقى الإلكترونان حرّين في المحلول","يكتسب أيونا K⁺ الإلكترونين فيُختزلان"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 105 — الشكل 2-3'),
('essay', 1, 'فسّر لماذا يجب أن يحدث تفاعلا الأكسدة والاختزال معًا دائمًا، مستعينًا بنصفي التفاعل لتكوين كلوريد الصوديوم من الصوديوم والكلور.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 105، 112 — التقويم (9)'),
('essay', 2, 'لديك نصفا التفاعل:
