from (values
('mcq', 1, 0, 'حتى يحدث تفاعل الأكسدة يجب أن تُكتسب الإلكترونات التي تفقدها المادة المتأكسدة من قبل ذرات أو أيونات مادة أخرى؛ فالأكسدة والاختزال عمليتان مترافقتان متكاملتان.', '["","الأكسدة لا تشترط الأكسجين، كتأكسد Na في تفاعله مع Cl₂.","المادة المتأكسدة تفقد الإلكترونات ولا تكتسبها.","العمليتان تحدثان معًا في الوقت نفسه، لا متتابعتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.595Z"}'::jsonb),
('mcq', 2, 1, 'الإلكترونات لا تُفنى ولا تبقى حرة؛ فكل إلكترون تفقده المادة المتأكسدة تكتسبه المادة المختزلة، لذا يتساوى العددان.', '["لو كان المفقود أكبر لبقيت إلكترونات حرة دون أن تكتسبها مادة، وهذا لا يحدث.","","لا يمكن اكتساب إلكترونات أكثر مما فُقد؛ فمصدرها المادة المتأكسدة.","بينهما علاقة تساوٍ؛ لأن الإلكترونات تنتقل من مادة إلى أخرى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.595Z"}'::jsonb),
('mcq', 3, 3, 'تفقد كل ذرة Mg إلكترونين، فتفقد الذرتان 4 إلكترونات، يكتسبها جزيء O₂ الواحد (كل ذرة أكسجين إلكترونان) ليتكون أيونا O²⁻.', '["2 هو ما تكتسبه ذرة أكسجين واحدة؛ والجزيء O₂ فيه ذرتان.","كل ذرة أكسجين تصبح O²⁻ فتكتسب إلكترونين لا إلكترونًا واحدًا.","ناتج مضاعفة الحساب؛ ذرتا Mg تفقدان معًا 4 إلكترونات فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.595Z"}'::jsonb),
('mcq', 4, 2, 'كل أيون Fe²⁺ يفقد إلكترونًا واحدًا (Fe²⁺ → Fe³⁺ + e⁻)، وجزيء Cl₂ يكتسب إلكترونين؛ ولتساوي المفقود والمكتسب يلزم أيونان من Fe²⁺.', '["أيون Fe²⁺ الواحد يفقد إلكترونًا واحدًا فقط، وجزيء Cl₂ يحتاج إلى إلكترونين.","ناتج الخلط بين الشحنة الناتجة (3+) وعدد الإلكترونات المفقودة.","","ناتج مضاعفة عدد الإلكترونات بالخطأ؛ فالجزيء يحتاج إلى إلكترونين فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.595Z"}'::jsonb),
('mcq', 5, 3, 'عند تكوّن الصدأ Fe₂O₃ يفقد الحديد الإلكترونات فيتأكسد، ويكتسبها الأكسجين فيُختزل؛ فلا أكسدة دون اختزال مرافق.', '["الحديد يفقد الإلكترونات فيتأكسد، ولا يُختزل.","عدد تأكسد الأكسجين يتغير من صفر إلى −2، فهو يُختزل.","الأكسجين يكتسب الإلكترونات فيُختزل لا يتأكسد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.596Z"}'::jsonb),
('mcq', 6, 1, 'المضاعف المشترك الأصغر لـ 3 و2 هو 6: ذرتا Al تفقدان 2 × 3 = 6 إلكترونات، وثلاثة أيونات Zn²⁺ تكتسب 3 × 2 = 6 إلكترونات.', '["تبديل للمعاملين: 3 Al تفقد 9 إلكترونات و2 Zn²⁺ تكتسب 4 فقط.","","ذرة Al تفقد 3 إلكترونات وأيون Zn²⁺ يكتسب 2، فلا يتساويان.","ذرتا Al تفقدان 6 إلكترونات، وأيونا Zn²⁺ يكتسبان 4 فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.596Z"}'::jsonb),
('mcq', 7, 0, 'الأكسدة والاختزال يحدثان معًا: الإلكترونان اللذان يفقدهما أيونا Br⁻ يكتسبهما جزيء Cl₂ فيُختزل إلى 2Cl⁻.', '["","لو فقد الكلور إلكترونات أيضًا لما وُجدت مادة تكتسب إلكترونات البروميد.","الإلكترونات لا تبقى حرة؛ بل تكتسبها مادة أخرى في التفاعل نفسه.","لا يوجد K⁺ في المعادلة، وهو في التفاعل الكامل أيون متفرج لا يتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.596Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لأن الأكسدة فقد للإلكترونات، والإلكترونات المفقودة لا يمكن أن تبقى حرة، بل يجب أن تكتسبها ذرات أو أيونات مادة أخرى فتُختزل؛ فلا تحدث أكسدة إلا إذا حدث اختزال مرافق، وعدد الإلكترونات المفقودة يساوي عدد المكتسبة. ففي تكوين NaCl: الأكسدة 2Na → 2Na⁺ + 2e⁻، والاختزال Cl₂ + 2e⁻ → 2Cl⁻؛ فالإلكترونان اللذان تفقدهما ذرتا الصوديوم يكتسبهما جزيء الكلور.', '["الإلكترونات المفقودة لا تبقى حرة","لا بد من مادة تكتسبها فتُختزل","نصف تفاعل أكسدة Na","نصف تفاعل اختزال Cl₂","تساوي الإلكترونات (2 = 2)"]'::jsonb, '[]'::jsonb, '[{"element":"التفسير بانتقال الإلكترونات","marks":2},{"element":"نصف تفاعل الأكسدة","marks":1},{"element":"نصف تفاعل الاختزال","marks":1},{"element":"بيان تساوي الإلكترونات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير صحيح مع نصفي التفاعل وبيان التساوي."},{"level":"3–4 درجات","description":"تفسير صحيح مع نصف تفاعل واحد أو دون بيان التساوي."},{"level":"1–2 درجة","description":"يذكر أن العمليتين متلازمتان دون تفسير مقبول."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["الاكتفاء بقول «لأنهما متكاملتان» دون ذكر الإلكترونات.","كتابة الإلكترونات في الطرف الخطأ.","القول إن الصوديوم يكتسب الإلكترونات."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.596Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الإلكترونان اللذان تفقدهما ذرة Zn يجب أن تكتسبهما مادة أخرى، وأيون Ag⁺ لا يكتسب إلكترونًا إلا إذا فقدته مادة أخرى؛ فالعمليتان متلازمتان. (ب) ذرة Zn تفقد إلكترونين وكل أيون Ag⁺ يكتسب إلكترونًا واحدًا، فيلزم أيونان: Zn + 2Ag⁺ → Zn²⁺ + 2Ag. (ج) المفقود: 1 × 2 = 2 إلكترون، والمكتسب: 2 × 1 = 2 إلكترون؛ متساويان.', '["تلازم العمليتين بانتقال الإلكترونات","يلزم 2Ag⁺ لكل Zn","Zn + 2Ag⁺ → Zn²⁺ + 2Ag","التحقق: 2 = 2"]'::jsonb, '["الإلكترونات المفقودة لكل Zn = 2","الإلكترونات المكتسبة لكل Ag⁺ = 1","عدد Ag⁺ = 2 ÷ 1 = 2","جمع نصفي التفاعل بعد ضرب نصف تفاعل الفضة في 2 وحذف الإلكترونات"]'::jsonb, '[{"element":"(أ) التفسير","marks":1},{"element":"(ب) عدد أيونات Ag⁺","marks":1},{"element":"(ب) المعادلة الكلية","marks":1},{"element":"(ج) التحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة صحيحة كاملة للأجزاء الثلاثة."},{"level":"2–3 درجات","description":"معادلة صحيحة مع تفسير أو تحقق ناقص."},{"level":"1 درجة","description":"جزء واحد صحيح."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["كتابة Zn + Ag⁺ → Zn²⁺ + Ag دون موازنة الإلكترونات.","إبقاء الإلكترونات في المعادلة الكلية.","ضرب نصف تفاعل الخارصين بدل الفضة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.596Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المعادلة غير صحيحة؛ فذرة Al تفقد 3 إلكترونات (Al → Al³⁺ + 3e⁻) بينما أيون Cu²⁺ يكتسب إلكترونين فقط (Cu²⁺ + 2e⁻ → Cu)، فالمفقود (3) لا يساوي المكتسب (2)، والشحنة غير موزونة (+2 في المتفاعلات و+3 في النواتج). لتساوي الإلكترونات نضرب نصف تفاعل الألومنيوم في 2 ونصف تفاعل النحاس في 3: 2Al + 3Cu²⁺ → 2Al³⁺ + 3Cu؛ فالمفقود 6 = المكتسب 6، والشحنة +6 في الطرفين.', '["Al يفقد 3e⁻ وCu²⁺ يكتسب 2e⁻","عدم التساوي (3 ≠ 2) وعدم توازن الشحنة","المعادلة الصحيحة 2Al + 3Cu²⁺ → 2Al³⁺ + 3Cu","التحقق 6 = 6"]'::jsonb, '["Al → Al³⁺ + 3e⁻ (×2) ⇒ 6e⁻","Cu²⁺ + 2e⁻ → Cu (×3) ⇒ 6e⁻","الجمع: 2Al + 3Cu²⁺ → 2Al³⁺ + 3Cu"]'::jsonb, '[{"element":"تحديد الإلكترونات لكل نصف تفاعل","marks":1},{"element":"الحكم بعدم الصحة مع التعليل","marks":1},{"element":"المعادلة الصحيحة","marks":1},{"element":"التحقق من التساوي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم معلل وكتابة المعادلة الصحيحة مع التحقق."},{"level":"2–3 درجات","description":"يكتب المعادلة الصحيحة دون تعليل كافٍ، أو يعلل دون تصحيح كامل."},{"level":"1 درجة","description":"يحكم بالخطأ دون تعليل أو تصحيح."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["الاكتفاء بموازنة الذرات وعدّ المعادلة صحيحة.","استعمال المعاملين 3 و2 بترتيب معكوس.","إهمال توازن الشحنة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.597Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
