from (values
('mcq', 1, 'ما الصيغة الكيميائية للصدأ الذي يتكون عند تأكسد الحديد في الهواء الرطب؟', null, '["FeO","FeCl₃","Fe₂O₃","FeS"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 109 — واقع الكيمياء في الحياة: الأكسدة (الصدأ)'),
('mcq', 2, 'متى يتأكسد الحديد مكوّنًا الصدأ؟', null, '["عندما يلامسه الهواء الرطب","عندما يُحفظ في فراغ تام","عندما يُغطّى بطبقة من الدهان","عندما يُحفظ في هواء جاف تمامًا"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 109 — واقع الكيمياء في الحياة: الأكسدة (الصدأ)'),
('mcq', 3, 'أيّ مما يأتي من طرائق حماية منتجات الحديد من الأكسدة؟', null, '["غمرها في ماء مالح","تغطيتها بالطلاء أو الدهان","تعريضها للهواء الرطب","تسخينها في جو من الأكسجين"]'::jsonb, 'فهم', 'تذكر تطبيق', 'متوسط', 'الكتاب ص 109 — واقع الكيمياء في الحياة: الأكسدة (الصدأ)'),
('mcq', 4, 'يُستعمل مبيض الغسيل الذي يحتوي على هيبوكلوريت الصوديوم NaClO لتبييض الملابس؛ لأنه:', null, '["عامل مختزل يختزل البقع والأصباغ","حمض قوي يذيب البقع والأصباغ","مادة تمتص البقع دون تفاعل كيميائي","عامل مؤكسد يؤكسد البقع والأصباغ"]'::jsonb, 'تذكر', 'تذكر تطبيق', 'متوسط', 'الكتاب ص 107 — تطبيقات العوامل المؤكسدة والمختزلة'),
('mcq', 5, 'في تجربة إزالة الشوائب (كبريتيد الفضة) عن قطعة فضة بلفّها برقائق الألومنيوم وتسخينها في الماء مع صودا الخبز والملح، ما المادة التي تتأكسد؟', null, '["الفضة في كبريتيد الفضة","ملح الطعام المضاف للماء","فلز الألومنيوم في الرقائق","الماء المستعمل في الكأس"]'::jsonb, 'تطبيق', 'تحليل تجربة', 'متوسط', 'الكتاب ص 107 — تجربة: ملاحظة تفاعل الأكسدة والاختزال'),
('mcq', 6, 'ينتج ضوء العصا الضوئية عند كسر الكبسولة الزجاجية داخلها عن:', null, '["احتراق الغلاف البلاستيكي","تفاعل كيميائي تنتقل فيه الإلكترونات","تيار كهربائي من بطارية داخلها","تسخين المواد حتى التوهج"]'::jsonb, 'تذكر', 'تذكر تطبيق', 'سهل', 'الكتاب ص 104 — الربط مع الحياة'),
('mcq', 7, 'في تفاعل تكوّن الصدأ 4Fe + 3O₂ → 2Fe₂O₃، أيّ العبارات الآتية صحيحة؟', null, '["Fe عامل مؤكسد، ويتغير عدد تأكسده من صفر إلى +3","O₂ عامل مختزل، ويتغير عدد تأكسد الحديد من صفر إلى +2","O₂ عامل مؤكسد، ويتغير عدد تأكسد الحديد من صفر إلى +6","O₂ عامل مؤكسد، ويتغير عدد تأكسد الحديد من صفر إلى +3"]'::jsonb, 'تطبيق', 'تحليل تطبيق حياتي', 'صعب', 'الكتاب ص 109، 110 — الصدأ وقواعد أعداد التأكسد'),
('essay', 1, 'اذكر ثلاثة تطبيقات لتفاعلات الأكسدة والاختزال في الحياة اليومية، مبيّنًا في كل منها المادة التي تتأكسد أو العامل المؤكسد.', null, null, 'تذكر', 'تعداد أمثلة', 'متوسط', 'الكتاب ص 104، 107، 109 — تطبيقات الأكسدة والاختزال'),
('essay', 2, 'الصدأ مشكلة شائعة في المنشآت الحديدية.
(أ) اكتب معادلة موزونة لتكوّن الصدأ Fe₂O₃ من الحديد والأكسجين.
(ب) حدد المادة التي تأكسدت والمادة التي اختُزلت مع التغير في عدد تأكسد كل منهما.
(ج) فسّر كيف يحمي طلاء الحديد بالدهان من الصدأ.', null, null, 'فهم', 'تفسير تطبيق', 'صعب', 'الكتاب ص 109 — واقع الكيمياء في الحياة: الأكسدة (الصدأ)'),
('essay', 3, 'في إحدى طرائق إزالة الشوائب عن الفضة، تُلف قطعة فضة عليها طبقة من كبريتيد الفضة Ag₂S برقائق الألومنيوم وتُسخن في ماء مع صودا الخبز وملح الطعام.
(أ) اكتب معادلة تفاعل كبريتيد الفضة مع الألومنيوم الذي ينتج كبريتيد الألومنيوم والفضة، وزنها.
(ب) حدد المادة التي تأكسدت والمادة التي اختُزلت، وأيّ الفلزين أكثر نشاطًا.
(ج) فسّر لماذا يُنصح بعدم استعمال أواني الألومنيوم عند تنظيف مواد مصنوعة من الفضة.', null, null, 'تحليل', 'تحليل تجربة', 'صعب', 'الكتاب ص 107 — تجربة: ملاحظة تفاعل الأكسدة والاختزال')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
