from (values
('mcq', 1, 2, 'يتأكسد الحديد عندما يلامسه الهواء الرطب مكوّنًا أكسيد الحديد(III) Fe₂O₃ ويسمى الصدأ.', '["FeO أكسيد الحديد(II)، والصدأ أكسيد الحديد(III).","FeCl₃ كلوريد الحديد(III) وليس أكسيدًا؛ والصدأ ناتج عن الأكسجين.","","FeS كبريتيد الحديد(II)، ولا يتكون من تفاعل الحديد مع الهواء الرطب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.597Z"}'::jsonb),
('mcq', 2, 0, 'الحديد يتأكسد عندما يلامسه الهواء الرطب، مكوّنًا Fe₂O₃ (الصدأ).', '["","في الفراغ لا يوجد أكسجين ولا رطوبة يتفاعل معهما الحديد.","الدهان طريقة لحماية الحديد من الأكسدة لا سبب لها.","الصدأ يرتبط بالهواء الرطب لا الجاف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.597Z"}'::jsonb),
('mcq', 3, 1, 'من طرائق حماية الحديد من الأكسدة الطلاء والدهان وإضافة المواد البلاستيكية؛ إذ تمنع وصول الهواء الرطب إلى سطحه.', '["الماء المالح يسرّع تأكسد الحديد ولا يحميه.","","الهواء الرطب هو سبب الصدأ.","التسخين في الأكسجين يزيد أكسدة الحديد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.597Z"}'::jsonb),
('mcq', 4, 3, 'هيبوكلوريت الصوديوم NaClO في مبيض الغسيل عامل مؤكسد يؤدي إلى أكسدة البقع والأصباغ ومواد أخرى.', '["NaClO عامل مؤكسد لا مختزل.","عمل المبيض قائم على الأكسدة لا على الحمضية.","المبيض يغيّر البقع كيميائيًا بأكسدتها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.598Z"}'::jsonb),
('mcq', 5, 2, 'الألومنيوم أكثر نشاطًا من الفضة، فيفقد الإلكترونات ويتأكسد إلى Al³⁺، وتكتسبها أيونات الفضة في الشوائب فتُختزل إلى فضة، فيعود لمعان القطعة.', '["أيونات الفضة في الشوائب تكتسب الإلكترونات فتُختزل إلى فضة.","ملح الطعام يساعد على التوصيل ولا يتأكسد في هذا التفاعل.","","الماء وسط للتفاعل، والمادة التي تفقد الإلكترونات هي الألومنيوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.598Z"}'::jsonb),
('mcq', 6, 1, 'عند كسر الكبسولة يحدث تفاعل بين مادتين تنتقل فيه الإلكترونات، فتتحول الطاقة الكيميائية إلى طاقة ضوئية.', '["لا يحدث احتراق؛ بل تفاعل بين مادتين داخل العصا.","","العصا الضوئية لا تحتوي بطارية؛ فالطاقة كيميائية.","الضوء ناتج عن تحول الطاقة الكيميائية لا عن التسخين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.598Z"}'::jsonb),
('mcq', 7, 3, 'في Fe₂O₃: 2n(Fe) + 3(−2) = 0 ⇒ n(Fe) = +3؛ فالحديد تأكسد من صفر إلى +3 (عامل مختزل)، والأكسجين اختُزل من صفر إلى −2 فهو العامل المؤكسد.', '["الحديد يتأكسد (يزيد عدد تأكسده)، والمادة المتأكسدة عامل مختزل.","الأكسجين يُختزل فهو عامل مؤكسد، والحديد في Fe₂O₃ عدد تأكسده +3.","+6 مجموع ذرتي الحديد في Fe₂O₃؛ أما عدد تأكسد كل ذرة فهو +3.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.598Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) صدأ الحديد: يتأكسد الحديد عند ملامسته الهواء الرطب مكوّنًا Fe₂O₃، والأكسجين هو العامل المؤكسد. 2) مبيض الغسيل: هيبوكلوريت الصوديوم NaClO عامل مؤكسد يؤكسد البقع والأصباغ. 3) إزالة الشوائب من الفلزات: كإزالة كبريتيد الفضة عن الفضة برقائق الألومنيوم، فيتأكسد الألومنيوم وتُختزل أيونات الفضة. (ويقبل أيضًا: ضوء العصا الضوئية الناتج عن تفاعل تنتقل فيه الإلكترونات.) ويقبل أي تطبيق صحيح آخر.', '["صدأ الحديد مع المادة المتأكسدة أو العامل المؤكسد","المبيض NaClO عامل مؤكسد","إزالة الشوائب من الفلزات (الألومنيوم يتأكسد)"]'::jsonb, '[]'::jsonb, '[{"element":"التطبيق الأول مع البيان","marks":1},{"element":"التطبيق الثاني مع البيان","marks":1},{"element":"التطبيق الثالث مع البيان","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة تطبيقات صحيحة مع بيان صحيح في كل منها."},{"level":"1–2 درجة","description":"تطبيق أو تطبيقان صحيحان، أو ثلاثة دون بيان."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ المبيض عاملًا مختزلًا.","ذكر تطبيقات لا تتضمن أكسدة واختزالًا كالذوبان.","عدّ الأكسجين في الصدأ مادة متأكسدة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.598Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) 4Fe + 3O₂ → 2Fe₂O₃. (ب) الحديد تأكسد: من صفر إلى +3 (فقدت كل ذرة 3 إلكترونات)، والأكسجين اختُزل: من صفر إلى −2 (اكتسبت كل ذرة إلكترونين). (ج) الدهان يكوّن طبقة عازلة تمنع ملامسة الهواء الرطب (الأكسجين والرطوبة) لسطح الحديد، فلا يحدث التفاعل الذي يتأكسد فيه الحديد.', '["4Fe + 3O₂ → 2Fe₂O₃","Fe: 0 → +3 أكسدة","O: 0 → −2 اختزال","الدهان يمنع ملامسة الهواء الرطب"]'::jsonb, '["في Fe₂O₃: 2n(Fe) + 3(−2) = 0 ⇒ n(Fe) = +3","الوزن: 4 ذرات Fe و6 ذرات O في الطرفين"]'::jsonb, '[{"element":"المعادلة الموزونة","marks":1},{"element":"تأكسد الحديد مع التغير","marks":1},{"element":"اختزال الأكسجين مع التغير","marks":1},{"element":"تفسير الحماية بالدهان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة موزونة وتحديد صحيح للتغيرين وتفسير صحيح للحماية."},{"level":"2–3 درجات","description":"عنصران أو ثلاثة صحيحة."},{"level":"1 درجة","description":"عنصر واحد صحيح."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["كتابة FeO بدل Fe₂O₃.","عدّ الحديد مختزلًا لأنه اتحد بالأكسجين.","القول إن الدهان يتفاعل مع الصدأ ويزيله."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.598Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) 3Ag₂S + 2Al → Al₂S₃ + 6Ag. (ب) الألومنيوم تأكسد (من صفر إلى +3)، وأيونات الفضة في Ag₂S اختُزلت (من +1 إلى صفر)؛ والألومنيوم أكثر نشاطًا من الفضة لأنه هو الذي يفقد الإلكترونات. (ج) لأن الألومنيوم سيتفاعل ويتأكسد مع الشوائب، فيتآكل سطح الإناء ويتلف؛ لذا تُستعمل رقائق ألومنيوم رخيصة تُستهلك بدلًا من الإناء.', '["3Ag₂S + 2Al → Al₂S₃ + 6Ag","Al تأكسد (0 → +3)","Ag⁺ اختُزل (+1 → 0)","الألومنيوم أنشط","الإناء يتأكسد ويتآكل"]'::jsonb, '["Ag₂S: 2n(Ag) + (−2) = 0 ⇒ n(Ag) = +1","Al₂S₃: 2n(Al) + 3(−2) = 0 ⇒ n(Al) = +3","الإلكترونات: 2Al تفقد 6e⁻، و6Ag⁺ تكتسب 6e⁻","الوزن: 3Ag₂S + 2Al → Al₂S₃ + 6Ag"]'::jsonb, '[{"element":"المعادلة الموزونة","marks":1},{"element":"تحديد المتأكسد والمختزل","marks":1},{"element":"الفلز الأنشط","marks":1},{"element":"تفسير عدم استعمال أواني الألومنيوم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة موزونة وتحديد صحيح وتفسير منطقي."},{"level":"2–3 درجات","description":"تحديد صحيح مع خطأ في الموازنة أو تفسير ناقص."},{"level":"1 درجة","description":"عنصر واحد صحيح."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ الفضة متأكسدة لأنها «تُنظَّف».","عدم موازنة المعادلة (Ag₂S + Al → ...).","القول إن الفضة أنشط من الألومنيوم."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.599Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
