('mcq', 3, 'في أثناء وزن المعادلة الأيونية الآتية في وسط حمضي، وصلت إلى: Cr₂O₇²⁻ + 6Fe²⁺ → 2Cr³⁺ + 6Fe³⁺
ما الذي يجب إضافته لإكمال الوزن؟', null, '["7H⁺ إلى المتفاعلات و7H₂O إلى النواتج","14H⁺ إلى النواتج و7H₂O إلى المتفاعلات","14H⁺ إلى المتفاعلات و14H₂O إلى النواتج","14H⁺ إلى المتفاعلات و7H₂O إلى النواتج"]'::jsonb, 'تطبيق', 'إكمال وزن في وسط حمضي', 'متوسط', 'الكتاب ص 116 — المثال 4-3: وزن المعادلة الأيونية الكلية في وسط حمضي'),
('mcq', 4, 'أيُّ المعادلات الآتية تمثل الوزن الصحيح لتفاعل أيون السيانيد مع أيون البيرمنجنات في وسط قاعدي؟
CN⁻(aq) + MnO₄⁻(aq) → CNO⁻(aq) + MnO₂(s)', null, '["3CN⁻ + 2MnO₄⁻ + 2H⁺ → 3CNO⁻ + 2MnO₂ + H₂O","3CN⁻ + 2MnO₄⁻ + H₂O → 3CNO⁻ + 2MnO₂ + 2OH⁻","2CN⁻ + 3MnO₄⁻ + H₂O → 2CNO⁻ + 3MnO₂ + 2OH⁻","CN⁻ + MnO₄⁻ + H₂O → CNO⁻ + MnO₂ + 2OH⁻"]'::jsonb, 'تطبيق', 'وزن معادلة أيونية في وسط قاعدي', 'صعب', 'الكتاب ص 115 — وزن معادلات الأكسدة والاختزال الأيونية الكلية'),
('mcq', 5, 'عند وزن تفاعل MnO₄⁻ مع Fe²⁺ في وسط حمضي بطريقة نصف التفاعل، يكتسب أيون MnO₄⁻ خمسة إلكترونات بينما يفقد أيون Fe²⁺ إلكترونًا واحدًا. لماذا يُضرب نصف تفاعل الحديد في 5؟', null, '["ليصبح عدد الإلكترونات المفقودة مساويًا لعدد الإلكترونات المكتسبة","ليصبح عدد ذرات الأكسجين متساويًا في طرفي المعادلة","ليصبح عدد أيونات H⁺ مساويًا لعدد جزيئات الماء","لأن شحنة أيون الحديد الناتج Fe³⁺ أكبر من شحنة Fe²⁺"]'::jsonb, 'فهم', 'تفسير خطوة إجرائية', 'سهل', 'الكتاب ص 118–119 — طريقة نصف التفاعل (الجدول 6-3 والمثال 5-3)'),
('mcq', 6, 'وزن طالب معادلة تفاعل يحدث في وسط قاعدي بطريقة نصف التفاعل، فحصل على معادلة موزونة ذريًّا وكهربائيًّا لكنها تحتوي 4H⁺ في طرف النواتج. ما الإجراء الصحيح لإكمال الحل؟', null, '["يحذف أيونات 4H⁺ من النواتج لأنها لا توجد في الوسط القاعدي","يضيف 4OH⁻ إلى طرفي المعادلة، فتتحد مع H⁺ مكونة 4H₂O، ثم يحذف جزيئات الماء المتكررة","يستبدل بأيونات 4H⁺ في النواتج 4OH⁻ في الموضع نفسه دون أي تغيير آخر","يضيف 4OH⁻ إلى طرف النواتج فقط لمعادلة أيونات H⁺"]'::jsonb, 'تحليل', 'تحليل خطأ وتصحيحه', 'صعب', 'الكتاب ص 115 — وزن معادلات الأكسدة والاختزال الأيونية الكلية'),
('mcq', 7, 'وُزنت معادلة تفاعل فوق أكسيد الهيدروجين مع أيون البيرمنجنات في وسط حمضي بطريقة نصف التفاعل:
MnO₄⁻ + H₂O₂ → Mn²⁺ + O₂
ما معامل H⁺ في المعادلة النهائية الموزونة بأصغر أعداد صحيحة؟', null, '["16","10","8","6"]'::jsonb, 'تطبيق', 'حساب معامل في معادلة موزونة', 'متوسط', 'الكتاب ص 118–119 — طريقة نصف التفاعل (الجدول 6-3 والمثال 5-3)'),
('essay', 1, 'زن معادلة التفاعل الآتي باستعمال طريقة عدد التأكسد، موضحًا أعداد التأكسد للذرات التي تغيرت، ومقدار التغير، وكيف ضبطت المعاملات:
H₂S(aq) + HNO₃(aq) → S(s) + NO(g) + H₂O(l)', null, null, 'تطبيق', 'وزن معادلة بطريقة عدد التأكسد', 'سهل', 'الكتاب ص 113–114 — طريقة عدد التأكسد'),
('essay', 2, 'زن معادلة التفاعل الآتي الذي يحدث في وسط حمضي باستعمال طريقة نصف التفاعل، مبينًا نصفي التفاعل الموزونين وكيفية جمعهما:
MnO₄⁻(aq) + Cl⁻(aq) → Mn²⁺(aq) + Cl₂(g)', null, null, 'تطبيق', 'وزن معادلة بطريقة نصف التفاعل في وسط حمضي', 'متوسط', 'الكتاب ص 118–119 — طريقة نصف التفاعل (الجدول 6-3 والمثال 5-3)'),
('essay', 3, 'يتفاعل أيون البيرمنجنات مع أيون الكبريتيت في وسط قاعدي وفق المعادلة غير الموزونة:
MnO₄⁻(aq) + SO₃²⁻(aq) → MnO₂(s) + SO₄²⁻(aq)
زن المعادلة باستعمال طريقة عدد التأكسد، ثم أكمل الوزن بما يناسب الوسط القاعدي، وتحقق من تساوي الشحنة.', null, null, 'تحليل', 'وزن معادلة أيونية في وسط قاعدي', 'صعب', 'الكتاب ص 115 — وزن معادلات الأكسدة والاختزال الأيونية الكلية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
