insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'بعض التفاعلات تحدث فقط في المحاليل القاعدية، وعند وزنها يمكن إضافة أيونات الهيدروكسيد OH⁻ وجزيئات الماء H₂O إلى طرفي المعادلة؛ لذا فالإجابة: أيونات OH⁻ وجزيئات H₂O.', '["هذا ما يُضاف في الوسط الحمضي، أما في الوسط القاعدي فلا تُترك أيونات H⁺ في المعادلة النهائية.","أيونات OH⁻ وحدها لا تكفي عادة لوزن الأكسجين والهيدروجين معًا، والمطلوب إضافة OH⁻ وجزيئات الماء.","","لا تُكتب H⁺ وOH⁻ معًا في معادلة نهائية؛ فهما يتحدان ماءً، والمطلوب في القاعدي OH⁻ وH₂O."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.599Z"}'::jsonb),
('mcq', 2, 0, 'أعداد التأكسد: Cu من 0 إلى 2+ (زيادة 2)، وN من 5+ في HNO₃ إلى 2+ في NO (نقصان 3). المضاعف المشترك 6: نضع 3 أمام Cu و2 أمام NO. ثم بالطريقة التقليدية: 3Cu(NO₃)₂ تحتاج 6 ذرات N إضافة إلى 2 في NO، فيصبح معامل HNO₃ = 8، وذرات H الثماني تعطي 4H₂O. التحقق من O: 24 = 18 + 2 + 4. فالمعادلة: 3Cu + 8HNO₃ → 3Cu(NO₃)₂ + 2NO + 4H₂O.', '["","توقف عند مساواة التغير في أعداد التأكسد (3Cu و2NO) ولم يكمل بالطريقة التقليدية؛ فعدد ذرات N في الطرف الأيسر 2 وفي الأيمن 8.","نقل معاملات تفاعل النحاس مع الحمض المركز (الناتج NO₂)؛ هنا تغير N هو 3−، فلا تتساوى الإلكترونات، وذرات O غير متساوية (12 مقابل 10).","وزن النيتروجين صحيح لكن معامل الماء خطأ؛ فذرات H في اليسار 8 وفي اليمين 16."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.600Z"}'::jsonb),
('mcq', 3, 3, 'في المتفاعلات 7 ذرات O في Cr₂O₇²⁻ ولا أكسجين في النواتج، فنضيف 7H₂O إلى النواتج، فتظهر 14 ذرة H نوازنها بإضافة 14H⁺ إلى المتفاعلات. التحقق من الشحنة: يسار (2−) + 12 + 14 = 24+، ويمين 6 + 18 = 24+. لذا نضيف 14H⁺ إلى المتفاعلات و7H₂O إلى النواتج.', '["وزن الأكسجين بإضافة 7H₂O صحيح، لكن 7H₂O تحتوي 14 ذرة H، فلا تكفي 7H⁺.","عكس الطرفين: ذرات الأكسجين السبع موجودة في المتفاعلات (Cr₂O₇²⁻) فيجب أن يظهر الماء في النواتج.","14H₂O تحتوي 14 ذرة O و28 ذرة H، بينما يحتاج الوزن إلى 7 ذرات O فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.600Z"}'::jsonb),
('mcq', 4, 1, 'عدد تأكسد C يزداد من 2+ في CN⁻ إلى 4+ في CNO⁻ (فقد 2e⁻)، وعدد تأكسد Mn ينقص من 7+ إلى 4+ (كسب 3e⁻)؛ فالنسبة 3CN⁻ : 2MnO₄⁻. وزن O يتطلب في الوسط القاعدي إضافة H₂O وOH⁻ فنحصل على: 3CN⁻ + 2MnO₄⁻ + H₂O → 3CNO⁻ + 2MnO₂ + 2OH⁻. التحقق: O: 8+1 = 3+4+2، H: 2 = 2، الشحنة: 5− = 5−.', '["هذه صورة الوزن في الوسط الحمضي؛ متوازنة ذريًّا وكهربائيًّا لكنها تحتوي H⁺، فلا تصلح لتفاعل في وسط قاعدي.","","عكس النسبة: 2CN⁻ تفقد 4 إلكترونات و3MnO₄⁻ تكتسب 9، كما أن ذرات O غير متساوية (13 مقابل 10).","لم يساوِ بين الإلكترونات المفقودة (2) والمكتسبة (3)؛ فالشحنة الكلية 2− في اليسار و3− في اليمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.600Z"}'::jsonb),
('mcq', 5, 0, 'تنص الخطوة الرابعة في طريقة نصف التفاعل على ضبط المعاملات بحيث يكون عدد الإلكترونات المفقودة في التأكسد مساويًا لعدد الإلكترونات المكتسبة في الاختزال؛ فخمسة أيونات Fe²⁺ تفقد 5e⁻ يكتسبها أيون MnO₄⁻ واحد.', '["","الحديد لا يحتوي على أكسجين، ووزن الأكسجين يتم بإضافة جزيئات الماء لا بضرب نصف تفاعل الحديد.","أيونات H⁺ وجزيئات الماء لا يُشترط تساويها، وهي توزن داخل نصف تفاعل الاختزال.","تغير الشحنة من 2+ إلى 3+ يعني فقد إلكترون واحد فقط، وهذا لا يفسر الضرب في 5."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.600Z"}'::jsonb),
('mcq', 6, 1, 'لتحويل معادلة موزونة بأيونات H⁺ إلى صورة الوسط القاعدي نضيف إلى الطرفين عددًا من أيونات OH⁻ يساوي عدد H⁺ (4OH⁻)، فيتحد كل H⁺ مع OH⁻ مكونًا H₂O، ثم نختصر جزيئات الماء الموجودة في الطرفين؛ فتبقى المعادلة موزونة ولا تحتوي H⁺.', '["حذف H⁺ وحدها يُخل بوزن ذرات الهيدروجين والشحنة؛ لا بد من إضافة OH⁻ إلى الطرفين.","","الاستبدال المباشر يغير عدد ذرات O وH والشحنة، فتفقد المعادلة وزنها.","إضافة OH⁻ إلى طرف واحد تُخل بوزن الذرات والشحنة؛ يجب إضافتها إلى الطرفين بالعدد نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.601Z"}'::jsonb),
('mcq', 7, 3, 'نصف الاختزال: MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O (×2)، ونصف التأكسد: H₂O₂ → O₂ + 2H⁺ + 2e⁻ (×5). بالجمع: 2MnO₄⁻ + 16H⁺ + 5H₂O₂ → 2Mn²⁺ + 8H₂O + 5O₂ + 10H⁺، وبحذف 10H⁺ من الطرفين: 2MnO₄⁻ + 5H₂O₂ + 6H⁺ → 2Mn²⁺ + 5O₂ + 8H₂O. فمعامل H⁺ هو 6.', '["هذا عدد H⁺ في نصف تفاعل الاختزال بعد ضربه في 2، دون طرح أيونات 10H⁺ الناتجة في نصف التأكسد عند الجمع والتبسيط.","هذا عدد H⁺ الناتجة من نصف تفاعل التأكسد (5H₂O₂ → 5O₂ + 10H⁺ + 10e⁻) فقط.","هذا عدد H⁺ في نصف تفاعل اختزال MnO₄⁻ الواحد قبل الضرب في 2 وقبل التبسيط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.601Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عدد تأكسد S يزداد من 2− في H₂S إلى صفر في S (زيادة 2؛ تأكسد)، وعدد تأكسد N ينقص من 5+ في HNO₃ إلى 2+ في NO (نقصان 3؛ اختزال). لمساواة الزيادة بالنقصان نضرب الكبريت في 3 والنيتروجين في 2: 3H₂S + 2HNO₃ → 3S + 2NO + H₂O. ثم بالطريقة التقليدية: ذرات H في اليسار 6 + 2 = 8 فيلزم 4H₂O. المعادلة الموزونة: 3H₂S + 2HNO₃ → 3S + 2NO + 4H₂O، والتحقق من O: 6 = 2 + 4.', '["أعداد التأكسد: S من 2− إلى 0، وN من 5+ إلى 2+","التغير: زيادة 2 للكبريت ونقصان 3 للنيتروجين","المعاملات 3 للكبريت و2 للنيتروجين لتساوي التغير الكلي (6)","إكمال الوزن: 4H₂O والتحقق من الذرات"]'::jsonb, '["تحديد أعداد التأكسد: S: 2− → 0 ، N: 5+ → 2+","التغير: S = 2+ ، N = 3−","مساواة التغير: 3 × 2 = 2 × 3 = 6 → 3H₂S و3S و2HNO₃ و2NO","الطريقة التقليدية: H يسار = 8 → 4H₂O","التحقق: O يسار 6 = يمين 2 + 4"]'::jsonb, '[{"element":"تحديد أعداد التأكسد للذرات المتغيرة","marks":1},{"element":"تحديد مقدار التغير في كل منها","marks":1},{"element":"ضبط المعاملات لمساواة الزيادة بالنقصان","marks":1},{"element":"إكمال الوزن بالطريقة التقليدية والتحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أعداد تأكسد صحيحة، وتغير صحيح، ومعاملات صحيحة، ومعادلة نهائية متحقق منها."},{"level":"2–3 درجات","description":"خطوات صحيحة جزئيًّا مع خطأ في إكمال الوزن (معامل الماء) أو في التحقق."},{"level":"1 درجة","description":"تحديد أعداد التأكسد أو التغير فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["اعتبار تغير النيتروجين 1− بالقياس على تفاعل النحاس مع الحمض المركز","نسيان إكمال وزن الهيدروجين بالماء بعد ضبط المعاملات","وضع معامل 2 أمام الكبريت ومعامل 3 أمام النيتروجين (عكس النسبة)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.601Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نصف التأكسد: 2Cl⁻ → Cl₂ + 2e⁻. نصف الاختزال: Mn ينقص من 7+ إلى 2+، فنكتب MnO₄⁻ + 5e⁻ → Mn²⁺، ونوزن الأكسجين بإضافة 4H₂O إلى النواتج والهيدروجين بإضافة 8H⁺ إلى المتفاعلات: MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O. المضاعف المشترك الأصغر لـ 2 و5 هو 10: نضرب نصف التأكسد في 5 ونصف الاختزال في 2: 10Cl⁻ → 5Cl₂ + 10e⁻ ، 2MnO₄⁻ + 16H⁺ + 10e⁻ → 2Mn²⁺ + 8H₂O. بالجمع وحذف الإلكترونات: 2MnO₄⁻ + 10Cl⁻ + 16H⁺ → 2Mn²⁺ + 5Cl₂ + 8H₂O. التحقق من الشحنة: يسار 2− 10− 16+ = 4+، ويمين 4+.', '["نصف التأكسد الموزون 2Cl⁻ → Cl₂ + 2e⁻","نصف الاختزال الموزون مع H⁺ وH₂O","الضرب في 5 و2 (المضاعف المشترك 10)","الجمع والمعادلة النهائية","التحقق من الشحنة"]'::jsonb, '["2Cl⁻ → Cl₂ + 2e⁻","MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O","المضاعف المشترك الأصغر لـ 2 و5 = 10","×5 للتأكسد، ×2 للاختزال","2MnO₄⁻ + 10Cl⁻ + 16H⁺ → 2Mn²⁺ + 5Cl₂ + 8H₂O","الشحنة: 4+ = 4+"]'::jsonb, '[{"element":"كتابة نصف التأكسد موزونًا","marks":1},{"element":"كتابة نصف الاختزال موزونًا ذريًّا وكهربائيًّا","marks":1},{"element":"مساواة الإلكترونات بالمضاعف المشترك الأصغر","marks":1},{"element":"الجمع وكتابة المعادلة النهائية","marks":1},{"element":"التحقق من تساوي الشحنة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"نصفا تفاعل صحيحان، ومساواة صحيحة، ومعادلة نهائية صحيحة متحقق من شحنتها."},{"level":"3–4 درجات","description":"نصفا تفاعل صحيحان مع خطأ في الجمع أو غياب التحقق."},{"level":"1–2 درجة","description":"كتابة نصف تفاعل واحد صحيح أو نصفين دون موازنة الإلكترونات."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["كتابة Cl⁻ → Cl₂ + e⁻ دون وزن ذرات الكلور","نسيان إضافة H⁺ لوزن الهيدروجين بعد إضافة الماء","بقاء الإلكترونات في المعادلة النهائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.601Z"}'::jsonb),
('essay', 3, null::int, null, null, 'Mn ينقص من 7+ إلى 4+ (نقصان 3)، وS يزداد من 4+ إلى 6+ (زيادة 2). المضاعف المشترك 6: 2MnO₄⁻ + 3SO₃²⁻ → 2MnO₂ + 3SO₄²⁻. ذرات O: يسار 8 + 9 = 17، يمين 4 + 12 = 16؛ فنضيف H₂O إلى النواتج ثم 2H⁺ إلى المتفاعلات: 2MnO₄⁻ + 3SO₃²⁻ + 2H⁺ → 2MnO₂ + 3SO₄²⁻ + H₂O. ولأن الوسط قاعدي نضيف 2OH⁻ إلى الطرفين، فتتحد 2H⁺ + 2OH⁻ مكونة 2H₂O، ونحذف جزيء ماء من الطرفين: 2MnO₄⁻ + 3SO₃²⁻ + H₂O → 2MnO₂ + 3SO₄²⁻ + 2OH⁻. التحقق من الشحنة: يسار 2− + 6− = 8−، يمين 6− + 2− = 8−.', '["تحديد التغير في عددي تأكسد Mn وS","المعاملات 2 و3","وزن الأكسجين والهيدروجين","التحويل إلى صورة الوسط القاعدي بإضافة OH⁻ للطرفين","التحقق من الشحنة"]'::jsonb, '["Mn: 7+ → 4+ (3−) ، S: 4+ → 6+ (2+)","2 × 3 = 3 × 2 = 6 → 2MnO₄⁻ و3SO₃²⁻","O: 17 مقابل 16 → إضافة H₂O للنواتج و2H⁺ للمتفاعلات","إضافة 2OH⁻ للطرفين وتكوين 2H₂O ثم الاختصار","2MnO₄⁻ + 3SO₃²⁻ + H₂O → 2MnO₂ + 3SO₄²⁻ + 2OH⁻","الشحنة: 8− = 8−"]'::jsonb, '[{"element":"تحديد التغير في أعداد التأكسد","marks":1},{"element":"ضبط معاملات المواد المتأكسدة والمختزلة","marks":1},{"element":"وزن الأكسجين والهيدروجين","marks":1},{"element":"التحويل الصحيح إلى الوسط القاعدي","marks":1},{"element":"التحقق من تساوي الشحنة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح ينتهي بمعادلة لا تحتوي H⁺ مع التحقق من الشحنة."},{"level":"3–4 درجات","description":"معاملات صحيحة مع خطأ في التحويل إلى الوسط القاعدي أو غياب التحقق."},{"level":"1–2 درجة","description":"تحديد التغير في أعداد التأكسد أو المعاملات فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["ترك H⁺ في المعادلة النهائية رغم أن الوسط قاعدي","إضافة OH⁻ إلى طرف واحد فقط","حساب تغير S من 4+ إلى 6+ على أنه 4"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.602Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
