from (values
('mcq', 1, 'على أي أساس تقوم طريقة عدد التأكسد في وزن معادلات الأكسدة والاختزال؟', null, '["مجموع أعداد التأكسد لذرات المتفاعلات يساوي مجموع أعداد التأكسد لذرات النواتج دائمًا","مجموع الزيادة في أعداد التأكسد يساوي مجموع النقصان فيها للذرات المشتركة في التفاعل","عدد الذرات المتأكسدة يساوي دائمًا عدد الذرات المختزلة في التفاعل","عدد جزيئات المتفاعلات يساوي عدد جزيئات النواتج في المعادلة الموزونة"]'::jsonb, 'تذكر', 'تذكر مبدأ', 'سهل', 'الكتاب ص 113 — طريقة عدد التأكسد (الجدول 4-3)'),
('mcq', 2, 'في طريقة عدد التأكسد، ما الخطوة التي تأتي مباشرة بعد تحديد التغير في عدد التأكسد للذرات التي تأكسدت والذرات التي اختزلت؟', null, '["تحديد أعداد التأكسد لجميع الذرات في المعادلة","استعمال الطريقة التقليدية في وزن بقية المعادلة","جعل التغير في أعداد التأكسد متساويًا في القيمة بضبط المعاملات","تحديد الذرات التي تأكسدت والذرات التي اختزلت"]'::jsonb, 'فهم', 'ترتيب خطوات', 'سهل', 'الكتاب ص 113 — طريقة عدد التأكسد (الجدول 4-3)'),
('mcq', 3, 'يبين الجدول خطوات طريقة عدد التأكسد بترتيب عشوائي. ما الترتيب الصحيح لهذه الخطوات؟', '{"headers":["الرمز","الخطوة"],"rows":[["س","استعمل الطريقة التقليدية في وزن بقية المعادلة"],["ص","حدد أعداد التأكسد لجميع الذرات في المعادلة"],["ع","اجعل التغير في أعداد التأكسد متساويًا في القيمة بضبط المعاملات"],["ل","حدد الذرات التي تأكسدت والذرات التي اختزلت"],["م","حدد التغير في عدد التأكسد للذرات التي تأكسدت والتي اختزلت"]]}'::jsonb, '["ص ← ل ← م ← ع ← س","ص ← م ← ل ← ع ← س","ل ← ص ← م ← ع ← س","ص ← ل ← ع ← م ← س"]'::jsonb, 'فهم', 'ترتيب خطوات إجراء', 'متوسط', 'الكتاب ص 113 — طريقة عدد التأكسد (الجدول 4-3)'),
('mcq', 4, 'في المعادلة غير الموزونة: SnCl₄(aq) + Fe(s) → SnCl₂(aq) + FeCl₃(aq)
ما التغير في عدد تأكسد كل من القصدير Sn والحديد Fe؟', null, '["Sn: ‎+2 ، Fe: ‎−3","Sn: ‎−4 ، Fe: ‎+3","Sn: ‎−2 ، Fe: ‎+2","Sn: ‎−2 ، Fe: ‎+3"]'::jsonb, 'تطبيق', 'حساب التغير في أعداد التأكسد', 'متوسط', 'الكتاب ص 113 — طريقة عدد التأكسد (الجدول 4-3)'),
('mcq', 5, 'وُزنت المعادلة الآتية بطريقة عدد التأكسد: MnO₂(s) + HCl(aq) → MnCl₂(aq) + Cl₂(g) + H₂O(l)
ما معامل HCl في المعادلة الموزونة بأصغر أعداد صحيحة؟', null, '["1","2","4","8"]'::jsonb, 'تطبيق', 'حساب معامل', 'متوسط', 'الكتاب ص 114 — المثال 3-3: طريقة عدد التأكسد'),
('mcq', 6, 'في المثال المحلول لوزن المعادلة Cu + HNO₃ → Cu(NO₃)₂ + NO₂ + H₂O، وُضع المعامل 2 أمام HNO₃ لمساواة التغير في أعداد التأكسد، ثم زيد إلى 4 في الخطوة الأخيرة. ما سبب هذه الزيادة؟', null, '["لأن التغير في عدد تأكسد النيتروجين يساوي 2− وليس 1−","لأن بعض ذرات النيتروجين لا يتغير عدد تأكسدها وتبقى في أيونات النترات في Cu(NO₃)₂ فتلزم موازنتها بالطريقة التقليدية","لأن التغير في عدد تأكسد النحاس يساوي 4+ فيحتاج إلى أربعة جزيئات HNO₃","لأن عدد ذرات الأكسجين في الماء الناتج يجب أن يساوي عدد ذرات النحاس"]'::jsonb, 'تحليل', 'تفسير خطوة في حل', 'صعب', 'الكتاب ص 114 — المثال 3-3: طريقة عدد التأكسد'),
('mcq', 7, 'يبين الجدول أعداد التأكسد في تفاعل الكربون مع حمض النيتريك المركز: C + HNO₃ → CO₂ + NO₂ + H₂O
استعمل طريقة عدد التأكسد، ثم اختر المعادلة الموزونة.', '{"headers":["الذرة","في المتفاعلات","في النواتج"],"rows":[["C","0 (في C)","4+ (في CO₂)"],["N","5+ (في HNO₃)","4+ (في NO₂)"],["H","1+","1+"],["O","2−","2−"]]}'::jsonb, '["C + 4HNO₃ → CO₂ + 4NO₂ + 2H₂O","C + 2HNO₃ → CO₂ + 2NO₂ + H₂O","C + 4HNO₃ → CO₂ + 4NO₂ + 4H₂O","4C + HNO₃ → 4CO₂ + NO₂ + H₂O"]'::jsonb, 'تطبيق', 'وزن معادلة جزيئية', 'صعب', 'الكتاب ص 114 — المثال 3-3: طريقة عدد التأكسد'),
('essay', 1, 'فسّر الأساس الذي تقوم عليه طريقة عدد التأكسد في وزن معادلات الأكسدة والاختزال، ثم اكتب خطواتها الخمس مرتبة.', null, null, 'فهم', 'تفسير وترتيب', 'سهل', 'الكتاب ص 120 — الخلاصة وسؤال التقويم 28'),
