from (values
('mcq', 1, 1, 'لأن عدد الإلكترونات التي تفقدها الذرات المتأكسدة يجب أن يساوي عدد الإلكترونات التي تكتسبها الذرات المختزلة، فإن مجموع الزيادة في أعداد التأكسد يجب أن يساوي مجموع النقصان فيها للذرات المشتركة في التفاعل، وهذا أساس طريقة عدد التأكسد.', '["هذه العبارة لا تمثل أساس الطريقة؛ فالمطلوب مساواة مقدار الزيادة بمقدار النقصان للذرات المتغيرة فقط.","","ليس بالضرورة؛ ففي تفاعل Cu مع HNO₃ تتأكسد ذرة Cu واحدة مقابل اختزال ذرتي N، المهم تساوي الإلكترونات.","الوزن يحفظ عدد الذرات والشحنة لا عدد الجزيئات، ولا علاقة لذلك بأساس الطريقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T11:36:22.602Z"}'::jsonb),
('mcq', 2, 2, 'خطوات طريقة عدد التأكسد بالترتيب: تحديد أعداد التأكسد، ثم تحديد الذرات المتأكسدة والمختزلة، ثم تحديد التغير، ثم جعل التغير متساويًا بضبط المعاملات، ثم الطريقة التقليدية. فالخطوة التالية لتحديد التغير هي مساواة التغير بضبط المعاملات.', '["هذه هي الخطوة الأولى في الطريقة، وتسبق تحديد التغير.","هذه الخطوة الأخيرة (الخامسة)، وتأتي بعد مساواة التغير بضبط المعاملات.","","هذه الخطوة الثانية، وتسبق تحديد مقدار التغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.602Z"}'::jsonb),
('mcq', 3, 0, 'الترتيب الصحيح: (ص) تحديد أعداد التأكسد لجميع الذرات، ثم (ل) تحديد الذرات المتأكسدة والمختزلة، ثم (م) تحديد التغير في أعداد تأكسدها، ثم (ع) مساواة التغير بضبط المعاملات، ثم (س) وزن بقية المعادلة بالطريقة التقليدية؛ أي: ص ← ل ← م ← ع ← س.', '["","لا يمكن تحديد مقدار التغير قبل معرفة أي الذرات تأكسدت وأيها اختزلت.","تحديد الذرات المتأكسدة والمختزلة يعتمد على معرفة أعداد التأكسد أولًا.","لا يمكن مساواة التغير بضبط المعاملات قبل حساب مقدار التغير لكل ذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.603Z"}'::jsonb),
('mcq', 4, 3, 'عدد تأكسد Sn في SnCl₄ هو 4+ وفي SnCl₂ هو 2+، فالتغير 2− (اختزال). عدد تأكسد Fe صفر في العنصر و3+ في FeCl₃، فالتغير 3+ (تأكسد). لذا: Sn: ‎−2 ، Fe: ‎+3.', '["عكس الإشارتين: القصدير ينتقل من 4+ إلى 2+ فعدد تأكسده يقل، والحديد من 0 إلى 3+ فيزداد.","اعتبر القصدير يُختزل إلى عنصر حر (صفر)، بينما هو في SnCl₂ عدد تأكسده 2+.","اعتبر الحديد يتحول إلى Fe²⁺، بينما عدد تأكسده في FeCl₃ هو 3+.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.603Z"}'::jsonb),
('mcq', 5, 2, 'Mn ينقص من 4+ إلى 2+ (2−)، وكل ذرة Cl تزداد من 1− إلى صفر (1+)، وCl₂ تحتاج ذرتين فالزيادة 2؛ فالتغير متساوٍ بمعامل 1 لكل من MnO₂ وCl₂ (أي 2HCl تتأكسد). ثم بالطريقة التقليدية: MnCl₂ تحتاج ذرتي Cl أخريين فيصبح المجموع 4HCl، والهيدروجين الأربع يعطي 2H₂O: MnO₂ + 4HCl → MnCl₂ + Cl₂ + 2H₂O. فالمعامل 4.', '["هذا معامل HCl في المعادلة غير الموزونة؛ لم تُطبق أي خطوة من خطوات الوزن.","هذا عدد جزيئات HCl التي تتأكسد إلى Cl₂ فقط، ولم يُكمل الوزن التقليدي لذرتي الكلور في MnCl₂ اللتين لم يتغير عدد تأكسدهما.","","خلط بتفاعل KMnO₄ مع HCl (16HCl لكل 2KMnO₄)؛ أما MnO₂ فينقص عدد تأكسد المنجنيز فيه بمقدار 2 فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.603Z"}'::jsonb),
('mcq', 6, 1, 'ذرتا N في 2NO₂ هما فقط اللتان اختزلتا، أما ذرتا N في Cu(NO₃)₂ فبقي عدد تأكسدهما 5+. لذلك بعد مساواة التغير (2HNO₃) نستعمل الطريقة التقليدية لوزن ذرات النيتروجين الكلية (2 + 2 = 4)، فيصبح معامل HNO₃ = 4.', '["التغير في عدد تأكسد N من 5+ إلى 4+ يساوي 1− فعلًا، وهو سبب المعامل 2 الأول لا سبب زيادته.","","التغير في عدد تأكسد النحاس 2+ فقط (من صفر إلى 2+)، ولا يساوي 4+.","لا توجد قاعدة كهذه؛ وزن الأكسجين والهيدروجين يتم بعد وزن النيتروجين وليس سبب الزيادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.603Z"}'::jsonb),
('mcq', 7, 0, 'C يزداد من 0 إلى 4+ (4+)، وN ينقص من 5+ إلى 4+ (1−)؛ لمساواة التغير نضع 4 أمام HNO₃ وNO₂. ثم ذرات H الأربع تعطي 2H₂O. التحقق من O: 12 = 2 + 8 + 2. فالمعادلة: C + 4HNO₃ → CO₂ + 4NO₂ + 2H₂O.', '["","التغير غير متساوٍ: الكربون يفقد 4 والنيتروجين يكتسب 2 فقط، وذرات O غير متساوية (6 مقابل 7).","المعاملات الناتجة من مساواة التغير صحيحة، لكن ذرات H في اليسار 4 وفي اليمين 8.","عكس النسبة: وضع المعامل 4 أمام الكربون بدل النيتروجين، فلا تتساوى الزيادة والنقصان ولا الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.603Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تقوم الطريقة على أن عدد الإلكترونات التي تفقدها الذرات المتأكسدة يساوي عدد الإلكترونات التي تكتسبها الذرات المختزلة؛ لذا يجب أن يكون مجموع الزيادة في أعداد التأكسد مساويًا لمجموع النقصان فيها للذرات المشتركة في التفاعل. خطواتها: (1) حدد أعداد التأكسد لجميع الذرات في المعادلة. (2) حدد الذرات التي تأكسدت والذرات التي اختزلت. (3) حدد التغير في عدد التأكسد للذرات المتأكسدة والمختزلة. (4) اجعل التغير متساويًا في القيمة بضبط المعاملات. (5) استعمل الطريقة التقليدية في وزن بقية المعادلة.', '["تساوي الإلكترونات المفقودة والمكتسبة","تساوي مجموع الزيادة ومجموع النقصان في أعداد التأكسد","الخطوات الخمس بالترتيب الصحيح"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الأساس (الإلكترونات المفقودة = المكتسبة)","marks":1},{"element":"الربط بتساوي الزيادة والنقصان في أعداد التأكسد","marks":1},{"element":"ذكر الخطوات الخمس","marks":1},{"element":"ترتيب الخطوات ترتيبًا صحيحًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للأساس وخمس خطوات صحيحة مرتبة."},{"level":"2–3 درجات","description":"تفسير صحيح مع نقص خطوة أو خلل في الترتيب."},{"level":"1 درجة","description":"ذكر بعض الخطوات دون تفسير الأساس أو العكس."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["القول إن مجموع أعداد التأكسد في المتفاعلات يساوي مجموعها في النواتج","تقديم ضبط المعاملات على حساب مقدار التغير","إغفال خطوة الطريقة التقليدية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T11:36:22.604Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) أعداد التأكسد: Pb = 2+ في الطرفين، S = 2− في PbS و6+ في PbSO₄، O = 1− في H₂O₂ و2− في H₂O وفي PbSO₄، وH = 1+. (2) S تأكسد، وO في H₂O₂ اختزل. (3) التغير: S = 8+، وكل ذرة O في H₂O₂ = 1−، أي 2− لكل جزيء H₂O₂. (4) لمساواة التغير نضع 4 أمام H₂O₂: PbS + 4H₂O₂ → PbSO₄ + H₂O. (5) بالطريقة التقليدية: ذرات H في اليسار 8 فنضع 4H₂O: PbS + 4H₂O₂ → PbSO₄ + 4H₂O. التحقق من O: 8 = 4 + 4.', '["أعداد التأكسد الصحيحة","تحديد المتأكسد (S) والمختزل (O في H₂O₂)","التغير 8+ و2− لكل H₂O₂","المعامل 4 لـ H₂O₂","إكمال الوزن 4H₂O والتحقق"]'::jsonb, '["S: 2− → 6+ (8+)","O في H₂O₂: 1− → 2− ، والتغير لكل جزيء = 2 × (1−) = 2−","8 = 4 × 2 → 4H₂O₂","H: 8 → 4H₂O","PbS + 4H₂O₂ → PbSO₄ + 4H₂O ، O: 8 = 8"]'::jsonb, '[{"element":"تحديد أعداد التأكسد","marks":1},{"element":"تحديد الذرات المتأكسدة والمختزلة","marks":1},{"element":"حساب التغير","marks":1},{"element":"مساواة التغير بضبط المعاملات","marks":1},{"element":"إكمال الوزن والتحقق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الخطوات الخمس صحيحة والمعادلة النهائية متحقق منها."},{"level":"3–4 درجات","description":"معظم الخطوات صحيحة مع خطأ في حساب التغير لكل جزيء H₂O₂ أو في معامل الماء."},{"level":"1–2 درجة","description":"تحديد أعداد التأكسد فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["اعتبار عدد تأكسد O في H₂O₂ يساوي 2−","حساب التغير لذرة O واحدة دون ضربه في 2","اعتبار الرصاص هو الذي تأكسد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.604Z"}'::jsonb),
('essay', 3, null::int, null, null, 'Mn ينقص من 7+ إلى 2+ (5−)، وCl يزداد من 1− إلى صفر (1+ لكل ذرة، 2+ لكل Cl₂). المضاعف المشترك 10: 2KMnO₄ (10−) و5Cl₂ (10+)، أي 10 ذرات Cl تتأكسد. بالطريقة التقليدية: 2KCl و2MnCl₂ تحتاج 2 + 4 = 6 ذرات Cl إضافية لم يتغير عدد تأكسدها، فمجموع HCl = 10 + 6 = 16، وذرات H الست عشرة تعطي 8H₂O. التحقق من O: 8 = 8. المعادلة: 2KMnO₄ + 16HCl → 2KCl + 2MnCl₂ + 5Cl₂ + 8H₂O. معامل HCl (16) أكبر من عدد ذرات Cl المتأكسدة (10) لأن 6 ذرات Cl تبقى أيونات كلوريد في KCl وMnCl₂ دون تغير في عدد تأكسدها.', '["التغير 5− للمنجنيز و2+ لكل Cl₂","المعاملات 2KMnO₄ و5Cl₂","معامل HCl = 16 بإضافة الكلور غير المتغير","8H₂O والتحقق","تفسير الفرق بين 16 و10"]'::jsonb, '["Mn: 7+ → 2+ (5−) ، Cl: 1− → 0 (1+ لكل ذرة)","المضاعف المشترك 10 → 2KMnO₄ و5Cl₂","Cl غير المتغير: 2 (KCl) + 4 (MnCl₂) = 6","HCl = 10 + 6 = 16 → 8H₂O","2KMnO₄ + 16HCl → 2KCl + 2MnCl₂ + 5Cl₂ + 8H₂O"]'::jsonb, '[{"element":"حساب التغير في أعداد التأكسد","marks":1},{"element":"مساواة التغير (2 و5)","marks":1},{"element":"إكمال معامل HCl بالطريقة التقليدية","marks":1},{"element":"معامل الماء والتحقق","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلة صحيحة كاملة مع تفسير سليم لسبب كبر معامل HCl."},{"level":"3–4 درجات","description":"معادلة صحيحة دون تفسير، أو تفسير صحيح مع خطأ حسابي واحد."},{"level":"1–2 درجة","description":"حساب التغير والمعاملات الأولية فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["الاكتفاء بـ 10HCl ونسيان الكلور في KCl وMnCl₂","حساب تغير الكلور لذرة واحدة ووضع 5HCl","نسيان البوتاسيوم عند التحقق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.604Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
