('mcq', 1, 'عند كتابة تفاعل النحاس مع حمض النيتريك المركز في صورة أيونات:
Cu + 4H⁺ + 4NO₃⁻ → Cu²⁺ + 2NO₃⁻ + 2NO₂ + 2H₂O
أي الجسيمات الآتية تُعد أيونات متفرجة؟', null, '["أيونات الهيدروجين H⁺ لأنها لا تتأكسد ولا تختزل","ذرة النحاس Cu لأنها تبقى نحاسًا في الطرفين","جزيئات NO₂ لأنها غاز يخرج من المحلول","أيونا النترات اللذان يبقيان NO₃⁻ في طرفي المعادلة دون تغير"]'::jsonb, 'فهم', 'تحديد الأيونات المتفرجة', 'سهل', 'الكتاب ص 115 — وزن معادلات الأكسدة والاختزال الأيونية الكلية'),
('mcq', 2, 'ما المقصود بالمعادلة الأيونية الكلية؟', null, '["معادلة تُكتب فيها جميع المركبات الأيونية والجزيئية في صورة أيونات","معادلة أيونية تتضمن الجسيمات المشاركة في التفاعل فقط","معادلة تتضمن الأيونات المتفرجة فقط دون المواد المتأكسدة والمختزلة","معادلة تُحذف منها الشحنات وتُكتب المواد في صورة جزيئات متعادلة"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 113 — مراجعة المفردات: المعادلة الأيونية الكلية'),
('mcq', 3, 'عند كتابة المعادلة Cu + 4HNO₃ → Cu(NO₃)₂ + 2NO₂ + 2H₂O في صورة أيونية، يُكتب HNO₃ على صورة H⁺ وNO₃⁻ بينما يبقى NO₂ وH₂O في صورة جزيئات. لماذا؟', null, '["لأن HNO₃ حمض قوي يتأين كليًّا في المحلول المائي، أما NO₂ وH₂O فمواد جزيئية لا تتفكك إلى أيونات","لأن HNO₃ هو العامل المختزل في التفاعل فيجب كتابته أيونات","لأن جميع المتفاعلات تُكتب أيونات وجميع النواتج تُكتب جزيئات","لأن NO₂ وH₂O أيونات متفرجة يجب أن تبقى دون تغيير"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 115 — وزن معادلات الأكسدة والاختزال الأيونية الكلية'),
('mcq', 4, 'ما المعادلة الأيونية الكلية لتفاعل بروميد البوتاسيوم مع الكلور؟
2KBr(aq) + Cl₂(aq) → 2KCl(aq) + Br₂(aq)', null, '["2K⁺ + 2Br⁻ + Cl₂ → 2K⁺ + 2Cl⁻ + Br₂","2KBr + Cl₂ → 2Cl⁻ + Br₂","2Br⁻ + Cl₂ → 2Cl⁻ + Br₂","Br⁻ + Cl → Cl⁻ + Br"]'::jsonb, 'تطبيق', 'كتابة معادلة أيونية كلية', 'متوسط', 'الكتاب ص 112 و115 — الأيونات المتفرجة'),
('mcq', 5, 'ما المعادلة الأيونية الكلية (التي تتضمن الجسيمات المشاركة في التفاعل فقط) للتفاعل: Zn(s) + 2AgNO₃(aq) → Zn(NO₃)₂(aq) + 2Ag(s)؟', null, '["Zn + 2Ag⁺ + 2NO₃⁻ → Zn²⁺ + 2NO₃⁻ + 2Ag","Zn + Ag⁺ → Zn²⁺ + Ag","Zn²⁺ + 2Ag → Zn + 2Ag⁺","Zn + 2Ag⁺ → Zn²⁺ + 2Ag"]'::jsonb, 'تطبيق', 'كتابة معادلة أيونية كلية', 'متوسط', 'الكتاب ص 115 — وزن معادلات الأكسدة والاختزال الأيونية الكلية'),
('mcq', 6, 'في التفاعل الموزون: 5SO₂ + 2H₂O + 2KMnO₄ → K₂SO₄ + 2H₂SO₄ + 2MnSO₄
أي العبارات الآتية صحيحة بشأن الأيونات المتفرجة التي تُحذف عند كتابة المعادلة الأيونية الكلية؟', null, '["أيون K⁺ وحده متفرج، أما أيونات SO₄²⁻ فناتجة من تأكسد SO₂ فلا تُحذف","أيونات K⁺ وSO₄²⁻ كلاهما متفرج لأنهما يظهران في النواتج على صورة أملاح","أيون Mn²⁺ متفرج لأن المنجنيز يظهر في طرفي المعادلة","لا توجد أيونات متفرجة لأن جميع المواد تشارك في التفاعل"]'::jsonb, 'تحليل', 'تحليل مكونات معادلة', 'صعب', 'الكتاب ص 119 — المثال 5-3'),
('mcq', 7, 'ما المعادلة الأيونية الكلية لتفاعل النحاس مع حمض النيتريك المخفف؟
3Cu(s) + 8HNO₃(aq) → 3Cu(NO₃)₂(aq) + 2NO(g) + 4H₂O(l)', null, '["3Cu + 8H⁺ + 8NO₃⁻ → 3Cu²⁺ + 6NO₃⁻ + 2NO + 4H₂O","3Cu + 8H⁺ + 2NO₃⁻ → 3Cu²⁺ + 2NO + 4H₂O","3Cu + 2H⁺ + 2NO₃⁻ → 3Cu²⁺ + 2NO + 4H₂O","3Cu + 8H⁺ + 6NO₃⁻ → 3Cu²⁺ + 2NO + 4H₂O"]'::jsonb, 'تطبيق', 'كتابة معادلة أيونية كلية', 'صعب', 'الكتاب ص 115 — وزن معادلات الأكسدة والاختزال الأيونية الكلية'),
('essay', 1, 'للتفاعل: Pb(s) + Pd(NO₃)₂(aq) → Pb(NO₃)₂(aq) + Pd(s)
(أ) اكتب المعادلة في صورة أيونية تُظهر جميع الأيونات.
(ب) حدد الأيونات المتفرجة مع التعليل.
(ج) اكتب المعادلة الأيونية الكلية.', null, null, 'تطبيق', 'كتابة معادلة أيونية كلية', 'سهل', 'الكتاب ص 115 — وزن معادلات الأكسدة والاختزال الأيونية الكلية'),
('essay', 2, 'يتفاعل ثاني أكسيد المنجنيز الصلب مع حمض الهيدروكلوريك وفق المعادلة الموزونة:
