select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'من أيونات النترات الأربعة في المتفاعلات تغير اثنان فقط إلى NO₂، وبقي الاثنان الآخران NO₃⁻ في الطرفين دون تغير؛ فهما أيونان متفرجان يُحذفان: Cu + 4H⁺ + 2NO₃⁻ → Cu²⁺ + 2NO₂ + 2H₂O.', '["أيونات H⁺ تشارك في التفاعل فعلًا وتتحول إلى جزيئات ماء، فلا تُحذف.","النحاس يتأكسد من صفر إلى 2+ فهو مشارك أساسي في التفاعل.","NO₂ ناتج من اختزال أيونات النترات، فهو جزء من التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.605Z"}'::jsonb),
('mcq', 2, 1, 'المعادلة الأيونية الكلية هي معادلة أيونية تتضمن الجسيمات المشاركة في التفاعل فقط، بعد حذف الأيونات المتفرجة.', '["كتابة كل المواد في صورة أيونات لا تحذف المتفرجات، وليست كل المواد تتفكك إلى أيونات.","","العكس هو الصحيح: الأيونات المتفرجة هي التي تُحذف من المعادلة الأيونية الكلية.","المعادلة الأيونية الكلية تُظهر الشحنات، ويجب أن تتساوى الشحنة الكلية في طرفيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.605Z"}'::jsonb),
('mcq', 3, 0, 'تحدث التفاعلات في محلول مائي، وHNO₃ حمض قوي يتأين كليًّا إلى H⁺ وNO₃⁻، وCu(NO₃)₂ تتفكك إلى أيونات، أما NO₂ (غاز) وH₂O فتبقى جزيئات؛ لذا تُكتب أيونات فقط المواد المتأينة أو المتفككة.', '["","HNO₃ مصدر العامل المؤكسد (النترات)، وسبب كتابته أيونات هو تأينه الكلي لا دوره في التفاعل.","القاعدة لا تتعلق بموقع المادة؛ فـ Cu(NO₃)₂ من النواتج ويُكتب أيونات، وCu من المتفاعلات ويبقى ذرة.","NO₂ وH₂O ليسا أيونات أصلًا، وهما ناتجان من التفاعل فلا يُعدّان متفرجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.606Z"}'::jsonb),
('mcq', 4, 2, 'يتفكك KBr وKCl إلى أيونات، وK⁺ لا يتغير عدد تأكسده (+1) فهو أيون متفرج يُحذف من الطرفين، فتبقى: 2Br⁻ + Cl₂ → 2Cl⁻ + Br₂، والشحنة 2− في الطرفين.', '["كُتبت المواد في صورة أيونات لكن لم تُحذف أيونات K⁺ المتفرجة.","حُذف البوتاسيوم من النواتج فقط، فلم تعد الذرات ولا الشحنة متساوية في الطرفين.","","الكلور والبروم في صورة جزيئات ثنائية الذرة (Cl₂ وBr₂) وليست ذرات منفردة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.606Z"}'::jsonb),
('mcq', 5, 3, 'يتفكك AgNO₃ وZn(NO₃)₂ إلى أيونات، وأيونات NO₃⁻ لا تتغير فهي متفرجة تُحذف، فتبقى: Zn + 2Ag⁺ → Zn²⁺ + 2Ag، والشحنة 2+ في الطرفين.', '["هذه معادلة أيونية لم تُحذف منها أيونات النترات المتفرجة.","الذرات متوازنة لكن الشحنة غير متساوية (1+ مقابل 2+)؛ لأن ذرة Zn تفقد إلكترونين يكتسبهما أيونا فضة.","عكس اتجاه التفاعل؛ الخارصين هو الذي يتأكسد والفضة هي التي تُختزل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.607Z"}'::jsonb),
('mcq', 6, 0, 'المعادلة الأيونية الكلية هي: 5SO₂ + 2H₂O + 2MnO₄⁻ → 5SO₄²⁻ + 4H⁺ + 2Mn²⁺. أيون K⁺ لم يتغير فهو متفرج ويُعاد في النهاية، بينما SO₄²⁻ ناتج تأكسد SO₂ (S من 4+ إلى 6+)، وMn اختزل من 7+ إلى 2+.', '["","SO₄²⁻ ليس موجودًا في المتفرجات، بل يتكون من تأكسد S في SO₂ من 4+ إلى 6+، فهو مشارك في التفاعل.","المنجنيز يُختزل من 7+ في MnO₄⁻ إلى 2+، فهو مشارك أساسي.","أيون K⁺ يبقى عدد تأكسده 1+ دون تغير، فهو متفرج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.607Z"}'::jsonb),
('mcq', 7, 1, 'نكتب HNO₃ وCu(NO₃)₂ في صورة أيونات: 3Cu + 8H⁺ + 8NO₃⁻ → 3Cu²⁺ + 6NO₃⁻ + 2NO + 4H₂O. ستة أيونات NO₃⁻ تظهر في الطرفين دون تغير فتُحذف، فتبقى: 3Cu + 8H⁺ + 2NO₃⁻ → 3Cu²⁺ + 2NO + 4H₂O، والشحنة 6+ في الطرفين.', '["معادلة أيونية صحيحة الوزن لكن لم تُحذف منها أيونات النترات الستة المتفرجة.","","حذف أيونات H⁺ مع النترات ظنًّا أنها متفرجة، فأصبحت ذرات H غير متساوية (2 مقابل 8).","كتب عدد النترات المتفرجة بدل عدد النترات المتفاعلة؛ فذرات N في اليسار 6 وفي اليمين 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.607Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) Pb + Pd²⁺ + 2NO₃⁻ → Pb²⁺ + 2NO₃⁻ + Pd. (ب) أيونات النترات NO₃⁻ متفرجة لأنها تظهر في الطرفين بالعدد نفسه ولا يتغير عدد تأكسد N فيها. (ج) Pb + Pd²⁺ → Pb²⁺ + Pd.', '["الصورة الأيونية الكاملة","تحديد NO₃⁻ متفرجًا مع التعليل","المعادلة الأيونية الكلية"]'::jsonb, '[]'::jsonb, '[{"element":"الصورة الأيونية الكاملة","marks":1},{"element":"تحديد الأيونات المتفرجة وتعليل ذلك","marks":1},{"element":"المعادلة الأيونية الكلية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة."},{"level":"1–2 درجة","description":"جزء أو جزءان صحيحان."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["كتابة Pd(NO₃)₂ دون تفكيكه إلى أيونات","اعتبار Pb²⁺ أيونًا متفرجًا","كتابة NO₃ دون شحنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.607Z"}'::jsonb),
('essay', 2, null::int, null, null, 'HCl حمض قوي يتأين كليًّا إلى 4H⁺ و4Cl⁻، وMnCl₂ تتفكك إلى Mn²⁺ و2Cl⁻، أما MnO₂ (صلب) وCl₂ (غاز) وH₂O فتبقى كما هي. الصورة الأيونية: MnO₂ + 4H⁺ + 4Cl⁻ → Mn²⁺ + 2Cl⁻ + Cl₂ + 2H₂O. أيونا Cl⁻ يظهران في الطرفين دون تغير فيُحذفان، فتصبح المعادلة الأيونية الكلية: MnO₂ + 4H⁺ + 2Cl⁻ → Mn²⁺ + Cl₂ + 2H₂O. الشحنة: يسار 4+ 2− = 2+، يمين 2+.', '["كتابة HCl وMnCl₂ أيونات مع التعليل","إبقاء MnO₂ وCl₂ وH₂O دون تفكيك","حذف 2Cl⁻ المتفرجين","المعادلة الأيونية الكلية","التحقق من الشحنة"]'::jsonb, '["MnO₂ + 4H⁺ + 4Cl⁻ → Mn²⁺ + 2Cl⁻ + Cl₂ + 2H₂O","حذف 2Cl⁻ من الطرفين","MnO₂ + 4H⁺ + 2Cl⁻ → Mn²⁺ + Cl₂ + 2H₂O","الشحنة: 2+ = 2+"]'::jsonb, '[{"element":"الصورة الأيونية مع التعليل","marks":1},{"element":"تحديد أيونات Cl⁻ المتفرجة وحذفها","marks":1},{"element":"المعادلة الأيونية الكلية الصحيحة","marks":1},{"element":"التحقق من الشحنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"صورة أيونية صحيحة وحذف صحيح ومعادلة نهائية متحقق من شحنتها."},{"level":"2–3 درجات","description":"معادلة نهائية صحيحة دون تعليل أو تحقق."},{"level":"1 درجة","description":"صورة أيونية فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["حذف جميع أيونات Cl⁻ الأربعة مع أن اثنين منها تأكسدا إلى Cl₂","تفكيك MnO₂ الصلب إلى أيونات","كتابة Cl₂ في صورة 2Cl⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.607Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) 2K⁺ + Cr₂O₇²⁻ + 14H⁺ + 14Cl⁻ → 2K⁺ + 2Cl⁻ + 2Cr³⁺ + 6Cl⁻ + 3Cl₂ + 7H₂O. (ب) المتفرجات: 2K⁺، و8Cl⁻ (2 من KCl و6 من CrCl₃) لأنها تبقى أيونات كلوريد دون تغير، بينما تأكسدت 6 أيونات Cl⁻ إلى 3Cl₂. (ج) Cr₂O₇²⁻ + 14H⁺ + 6Cl⁻ → 2Cr³⁺ + 3Cl₂ + 7H₂O. التحقق: Cr 2 = 2، O 7 = 7، H 14 = 14، Cl 6 = 6، والشحنة: 2− + 14 − 6 = 6+، ويمين 2 × 3 = 6+.', '["الصورة الأيونية الكاملة","المتفرجات 2K⁺ و8Cl⁻","تمييز Cl⁻ المتأكسد من المتفرج","المعادلة الأيونية الكلية","التحقق من الذرات والشحنة"]'::jsonb, '["تفكيك K₂Cr₂O₇ وHCl وKCl وCrCl₃","Cl⁻ في النواتج = 2 + 6 = 8 → متفرجة","Cl⁻ المتفاعلة = 14 − 8 = 6","Cr₂O₇²⁻ + 14H⁺ + 6Cl⁻ → 2Cr³⁺ + 3Cl₂ + 7H₂O","الشحنة: 6+ = 6+"]'::jsonb, '[{"element":"الصورة الأيونية الكاملة","marks":1},{"element":"تحديد المتفرجات وعددها","marks":2},{"element":"المعادلة الأيونية الكلية","marks":1},{"element":"التحقق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة مع تحقق كامل."},{"level":"3–4 درجات","description":"معادلة كلية صحيحة مع خطأ في عدد المتفرجات أو نقص في التحقق."},{"level":"1–2 درجة","description":"صورة أيونية كاملة فقط أو تحديد K⁺ متفرجًا فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["حذف جميع أيونات Cl⁻ الأربعة عشر","اعتبار Cr³⁺ متفرجًا","نسيان أن 3Cl₂ تحتاج 6 أيونات Cl⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.608Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
