from (values
('mcq', 1, 0, 'أيونات الهيدروجين H⁺ وجزيئات الماء توجد في المحلول بوفرة، وتستطيع المشاركة في تفاعل الأكسدة والاختزال في صورة متفاعلات أو نواتج؛ لذا تُضاف بالعدد الكافي لوزن الأكسجين والهيدروجين والشحنة.', '["","لا يتغير عدد تأكسد H (1+) ولا O (2−) فيها عادة؛ فهي لا تتأكسد ولا تختزل في هذه التفاعلات.","هي ليست متفرجة؛ إذ تُضاف تحديدًا لوزن ذرات O وH والشحنة.","المطلوب تساوي الشحنة في الطرفين لا أن تساوي صفرًا؛ فقد تتساوى الشحنة في الطرفين دون أن تساوي صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.608Z"}'::jsonb),
('mcq', 2, 3, 'في المتفاعلات 3 ذرات O (في IO₃⁻) ولا أكسجين في النواتج، فنضيف 3H₂O إلى النواتج، ثم نوازن ذرات H الست بإضافة 6H⁺ إلى المتفاعلات: IO₃⁻ + 5I⁻ + 6H⁺ → 3I₂ + 3H₂O. التحقق من الشحنة: 1− 5− 6+ = صفر، والنواتج صفر.', '["عكس الطرفين: ذرات الأكسجين الثلاث موجودة في IO₃⁻ في المتفاعلات، فيجب أن يظهر الماء في النواتج.","3H₂O تحتوي 6 ذرات H، فلا تكفي 3H⁺، والشحنة لا تتساوى (3− مقابل صفر).","هذه إضافة تناسب الوسط القاعدي، والتفاعل هنا في وسط حمضي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.609Z"}'::jsonb),
('mcq', 3, 2, 'المتفاعلات: (2−) + 6 × (2+) + 14 × (1+) = 2− + 12 + 14 = 24+. النواتج: 2 × (3+) + 6 × (3+) = 6 + 18 = 24+، والماء متعادل. فالشحنة الكلية 24+ في كل طرف.', '["أهمل شحنة أيونات H⁺ الأربعة عشر في المتفاعلات (2− + 12 = 10+).","عدّ شحنة أيون الثنائي كرومات موجبة (2+ بدل 2−): 2 + 12 + 14 = 28+، وهذا خطأ في الإشارة.","","حسب شحنة أيونات Fe³⁺ فقط في النواتج (6 × 3) وأهمل أيوني Cr³⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.609Z"}'::jsonb),
('mcq', 4, 1, 'نضيف 2OH⁻ إلى الطرفين (بعدد أيونات H⁺)، فتتحد 2H⁺ + 2OH⁻ مكونة 2H₂O في المتفاعلات، ونحذف جزيء ماء واحدًا من الطرفين: 2MnO₄⁻ + 3SO₃²⁻ + H₂O → 2MnO₂ + 3SO₄²⁻ + 2OH⁻. التحقق: O: 8 + 9 + 1 = 4 + 12 + 2 = 18، H: 2 = 2، الشحنة 8− = 8−.', '["استبدل OH⁻ بـ H⁺ في الموضع نفسه مباشرة، فأصبحت ذرات O غير متساوية (19 مقابل 17) والشحنة كذلك.","","نقل H⁺ إلى الطرف الآخر دون إضافة OH⁻؛ فما زالت المعادلة تحتوي H⁺، والشحنة غير متساوية (8− مقابل 4−).","أضاف عددًا من OH⁻ أكبر من عدد H⁺ (4 بدل 2)، فذرات O غير متساوية (19 مقابل 20)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.609Z"}'::jsonb),
('mcq', 5, 1, 'توجد أيونات H⁺ وجزيئات الماء بوفرة في المحاليل الحمضية، وأيونات OH⁻ وجزيئات الماء في المحاليل القاعدية؛ لذا فنوع الوسط يحدد الجسيمات التي يُسمح بإضافتها لإكمال وزن الذرات والشحنة.', '["المواد المتأكسدة والمختزلة تُحدد من التغير في أعداد التأكسد، لا من نوع الوسط.","","طريقة عدد التأكسد تُستعمل في الوسط الحمضي.","في كل الأوساط يجب أن يتساوى عدد الإلكترونات المفقودة والمكتسبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.609Z"}'::jsonb),
('mcq', 6, 0, 'ذرات O: يسار 1 + 2 = 3، يمين 4. في الوسط الحمضي نضيف H₂O يسارًا و2H⁺ يمينًا، وبإضافة 2OH⁻ للطرفين وتحويل 2H⁺ + 2OH⁻ إلى 2H₂O ثم الاختصار نحصل على: N₂O + 2ClO⁻ + 2OH⁻ → 2NO₂⁻ + 2Cl⁻ + H₂O. التحقق: O 5 = 5، H 2 = 2، الشحنة 4− = 4−.', '["","هذا إكمال صحيح في الوسط الحمضي، لكنه يترك H⁺ في معادلة تفاعل يحدث في وسط قاعدي.","وضعهما في الطرفين المعاكسين؛ فذرات O تصبح 4 في اليسار و6 في اليمين.","ضاعف العدد دون حاجة؛ فذرات O تصبح 7 في اليسار و6 في اليمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.610Z"}'::jsonb),
('mcq', 7, 2, 'عدد الذرات: Cu 1 = 1، H 2 = 2، N 1 = 1، O 3 = 3. لكن الشحنة: يسار 2+ 1− = 1+، ويمين 2+؛ لأن Cu يفقد إلكترونين بينما يكتسب NO₃⁻ واحدًا فقط. فالمعادلة غير موزونة، وصحيحها: Cu + 4H⁺ + 2NO₃⁻ → Cu²⁺ + 2NO₂ + 2H₂O.', '["تساوي الذرات وحده لا يكفي في المعادلات الأيونية؛ يجب أن تتساوى الشحنة الكلية أيضًا.","ذرات O في اليمين 2 (في NO₂) + 1 (في H₂O) = 3، فهي متساوية.","","التفاعل في وسط حمضي، فإضافة H⁺ هي الصحيحة؛ والخلل في الشحنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.610Z"}'::jsonb),
('essay', 1, null::int, null, null, 'S يزداد من 2− إلى صفر (2+)، وN ينقص من 5+ إلى 2+ (3−). المضاعف المشترك 6: 3H₂S + 2NO₃⁻ → 3S + 2NO. ذرات O: يسار 6 ويمين 2، فنضيف 4H₂O إلى النواتج. ذرات H: يسار 6 ويمين 8، فنضيف 2H⁺ إلى المتفاعلات: 3H₂S + 2NO₃⁻ + 2H⁺ → 3S + 2NO + 4H₂O. الشحنة: يسار 2− + 2+ = صفر، ويمين صفر.', '["التغير في أعداد التأكسد والمعاملات 3 و2","إضافة 4H₂O إلى النواتج","إضافة 2H⁺ إلى المتفاعلات","التحقق من الشحنة"]'::jsonb, '["S: 2− → 0 (2+) ، N: 5+ → 2+ (3−)","3H₂S + 2NO₃⁻ → 3S + 2NO","O: 6 مقابل 2 → +4H₂O يمينًا","H: 6 مقابل 8 → +2H⁺ يسارًا","الشحنة: صفر = صفر"]'::jsonb, '[{"element":"التغير في أعداد التأكسد والمعاملات","marks":1},{"element":"وزن الأكسجين بجزيئات الماء","marks":1},{"element":"وزن الهيدروجين بأيونات H⁺","marks":1},{"element":"التحقق من الشحنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة صحيحة كاملة مع التحقق."},{"level":"2–3 درجات","description":"معاملات صحيحة مع خطأ في عدد H⁺ أو H₂O أو غياب التحقق."},{"level":"1 درجة","description":"حساب التغير فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["إضافة 8H⁺ دون احتساب الهيدروجين الموجود في H₂S","وضع الماء في المتفاعلات","إغفال التحقق من الشحنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.610Z"}'::jsonb),
('essay', 2, null::int, null, null, 'Cr يزداد من 3+ إلى 6+ (3+)، وCl ينقص من 1+ إلى 1− (2−). المضاعف المشترك 6: 2Cr(OH)₃ + 3ClO⁻ → 2CrO₄²⁻ + 3Cl⁻. ذرات O: يسار 6 + 3 = 9، يمين 8، فنضيف H₂O إلى النواتج. ذرات H: يسار 6، يمين 2، فنضيف 4H⁺ إلى النواتج: 2Cr(OH)₃ + 3ClO⁻ → 2CrO₄²⁻ + 3Cl⁻ + H₂O + 4H⁺. ولأن الوسط قاعدي نضيف 4OH⁻ إلى الطرفين، فتتحد 4H⁺ + 4OH⁻ مكونة 4H₂O: 2Cr(OH)₃ + 3ClO⁻ + 4OH⁻ → 2CrO₄²⁻ + 3Cl⁻ + 5H₂O. التحقق: Cr 2 = 2، Cl 3 = 3، O 6 + 3 + 4 = 13 = 8 + 5، H 6 + 4 = 10 = 10، الشحنة 3− 4− = 7−، ويمين 4− 3− = 7−.', '["المعاملات 2 و3 من تساوي التغير","وزن O وH","التحويل إلى الوسط القاعدي بإضافة 4OH⁻ إلى الطرفين","المعادلة النهائية","التحقق من الذرات والشحنة"]'::jsonb, '["Cr: 3+ → 6+ (3+) ، Cl: 1+ → 1− (2−)","2Cr(OH)₃ + 3ClO⁻ → 2CrO₄²⁻ + 3Cl⁻","O: 9 مقابل 8 → H₂O يمينًا ، H: 6 مقابل 2 → 4H⁺ يمينًا","+4OH⁻ للطرفين: 4H⁺ + 4OH⁻ → 4H₂O","2Cr(OH)₃ + 3ClO⁻ + 4OH⁻ → 2CrO₄²⁻ + 3Cl⁻ + 5H₂O","الشحنة: 7− = 7−"]'::jsonb, '[{"element":"حساب التغير والمعاملات","marks":1},{"element":"وزن O وH","marks":1},{"element":"التحويل الصحيح إلى الوسط القاعدي","marks":1},{"element":"المعادلة النهائية","marks":1},{"element":"التحقق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح ينتهي بمعادلة دون H⁺ مع تحقق كامل."},{"level":"3–4 درجات","description":"معاملات ووزن صحيحان مع خطأ في التحويل أو التحقق."},{"level":"1–2 درجة","description":"حساب التغير والمعاملات فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["نسيان ذرات الهيدروجين في Cr(OH)₃","ترك H⁺ في المعادلة النهائية","إضافة OH⁻ إلى طرف واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.610Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) I: 6 = 6، Mn: 2 = 2، O: 8 = 4 + 4، H: 8 = 8؛ الشحنة: 6− 2− 8+ = صفر، ويمين صفر؛ فهي موزونة ذريًّا وكهربائيًّا. (ب) لكنها تحتوي أيونات H⁺، وهذه صورة الوسط الحمضي، والتفاعل يحدث في وسط قاعدي تتوافر فيه أيونات OH⁻ وجزيئات الماء لا أيونات H⁺. (ج) نضيف 8OH⁻ إلى الطرفين، فتتحد 8H⁺ + 8OH⁻ مكونة 8H₂O في اليسار، ونحذف 4H₂O من الطرفين: 6I⁻ + 2MnO₄⁻ + 4H₂O → 3I₂ + 2MnO₂ + 8OH⁻. التحقق: O 12 = 12، H 8 = 8، الشحنة 8− = 8−.', '["التحقق من الذرات","التحقق من الشحنة","تعليل رفض الإجابة (H⁺ في وسط قاعدي)","إضافة 8OH⁻ إلى الطرفين والاختصار","المعادلة الصحيحة"]'::jsonb, '["الذرات متساوية والشحنة صفر في الطرفين","إضافة 8OH⁻: 8H⁺ + 8OH⁻ → 8H₂O","حذف 4H₂O من الطرفين","6I⁻ + 2MnO₄⁻ + 4H₂O → 3I₂ + 2MnO₂ + 8OH⁻"]'::jsonb, '[{"element":"التحقق من الذرات والشحنة","marks":1},{"element":"تعليل عدم قبول الإجابة","marks":1},{"element":"التحويل الصحيح بإضافة OH⁻","marks":1},{"element":"المعادلة الصحيحة مع التحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحقق صحيح وتعليل سليم ومعادلة قاعدية صحيحة."},{"level":"2–3 درجات","description":"معادلة قاعدية صحيحة دون تعليل، أو تعليل صحيح مع خطأ في التحويل."},{"level":"1 درجة","description":"التحقق من الذرات والشحنة فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["الحكم بأن المعادلة خاطئة ذريًّا","استبدال OH⁻ بـ H⁺ في الموضع نفسه","عدم اختصار جزيئات الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.610Z"}'::jsonb)
