('mcq', 6, 'أي زوج من أنصاف التفاعلات الآتية يمثل تفاعل الحديد مع الفلور Fe + F₂ → FeF₃ تمثيلًا صحيحًا؟', null, '["الأكسدة: Fe → Fe³⁺ + 3e⁻ ، الاختزال: F + e⁻ → F⁻","الأكسدة: 2F⁻ → F₂ + 2e⁻ ، الاختزال: Fe³⁺ + 3e⁻ → Fe","الأكسدة: Fe → Fe³⁺ + 3e⁻ ، الاختزال: F₂ + 2e⁻ → 2F⁻","الأكسدة: Fe → Fe³⁺ + 3e⁻ ، الاختزال: F₂ → 2F⁻ + 2e⁻"]'::jsonb, 'تحليل', 'تحليل أنصاف تفاعل', 'صعب', 'الكتاب ص 117 — نصف التفاعل والجدول 5-3'),
('mcq', 7, 'في تفاعل KMnO₄ مع SO₂ في وسط حمضي، أي مما يأتي يمثل نصف تفاعل الأكسدة موزونًا ذريًّا وكهربائيًّا؟', null, '["SO₂ + 2H₂O → SO₄²⁻ + 4H⁺","SO₂ + 2H₂O → SO₄²⁻ + 4H⁺ + 2e⁻","SO₂ + 2H₂O + 2e⁻ → SO₄²⁻ + 4H⁺","MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O"]'::jsonb, 'تطبيق', 'كتابة نصف تفاعل موزون', 'صعب', 'الكتاب ص 119 — المثال 5-3'),
('essay', 1, 'عرّف نصف التفاعل، ثم اكتب نصفي تفاعل الأكسدة والاختزال للتفاعل الآتي، محددًا أيهما الأكسدة وأيهما الاختزال:
Pb(s) + Pd(NO₃)₂(aq) → Pb(NO₃)₂(aq) + Pd(s)', null, null, 'فهم', 'تعريف وكتابة أنصاف تفاعل', 'سهل', 'الكتاب ص 120 — الخلاصة وسؤالا التقويم 29 و30'),
('essay', 2, 'يتأكسد الحديد إلى Fe³⁺ في التفاعلات الآتية:
(1) Fe + O₂ → Fe₂O₃ (2) Fe + HBr → H₂ + FeBr₃ (3) Fe + CuSO₄ → Cu + Fe₂(SO₄)₃
اكتب نصف تفاعل الاختزال لكل تفاعل، ثم فسّر لماذا يكون نصف تفاعل الأكسدة واحدًا في التفاعلات الثلاثة.', null, null, 'فهم', 'كتابة أنصاف تفاعل وتفسير', 'متوسط', 'الكتاب ص 117 — نصف التفاعل والجدول 5-3'),
('essay', 3, 'المعادلة الآتية موزونة لتفاعل يحدث في وسط حمضي:
Zn + 2NO₃⁻ + 4H⁺ → Zn²⁺ + 2NO₂ + 2H₂O
افصلها إلى نصفي تفاعل الأكسدة والاختزال موزونين ذريًّا وكهربائيًّا، معللًا تصنيف كل منهما باستعمال أعداد التأكسد، ثم بيّن كيف يعطي جمعهما المعادلة المعطاة.', null, null, 'تحليل', 'تحليل معادلة إلى أنصاف تفاعل', 'صعب', 'الكتاب ص 119 — المثال 5-3')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
