select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'نصف التفاعل هو أحد جزأي تفاعل الأكسدة والاختزال؛ أي تفاعل الأكسدة (فقد الإلكترونات) أو تفاعل الاختزال (كسب الإلكترونات).', '["نصف التفاعل لا يتعلق بكمية المواد المستهلكة، بل بفصل عملية الأكسدة عن عملية الاختزال.","الأيونات المتفرجة لا تظهر في أنصاف التفاعلات أصلًا، ولا تُكتب لها معادلة مستقلة.","","هذا وصف لتفاعل غير مكتمل أو لمادة محددة للتفاعل، وليس تعريف نصف التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.611Z"}'::jsonb),
('mcq', 2, 3, 'تتأكسد كل ذرة حديد بفقد 3 إلكترونات لتصبح Fe³⁺، فنصف تفاعل الأكسدة: Fe → Fe³⁺ + 3e⁻، أما Cl₂ + 2e⁻ → 2Cl⁻ فهو نصف الاختزال.', '["هذا نصف تفاعل الاختزال؛ فالكلور يكتسب الإلكترونات.","وضع الإلكترونات في جهة المتفاعلات؛ ذرة الحديد تفقد الإلكترونات فتظهر في النواتج، والشحنة هنا غير متساوية.","الحديد في FeCl₃ يكون أيون Fe³⁺ لا Fe²⁺.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.611Z"}'::jsonb),
('mcq', 3, 1, 'أيون الفضة Ag⁺ يكتسب إلكترونًا واحدًا فيختزل إلى فلز الفضة: Ag⁺ + e⁻ → Ag، بينما يتأكسد الحديد إلى Fe³⁺.', '["هذا عكس ما يحدث؛ فأيون الفضة يكتسب إلكترونًا ويتحول إلى فلز، لا العكس.","","هذا نصف تفاعل الأكسدة للحديد وليس نصف الاختزال.","أيون النترات متفرج في هذا التفاعل ولا يتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.611Z"}'::jsonb),
('mcq', 4, 0, 'الأكسدة فقد للإلكترونات، فتُكتب الإلكترونات في نواتج نصف التأكسد (مثل Fe → Fe³⁺ + 3e⁻)، والاختزال كسب لها فتُكتب في متفاعلات نصف الاختزال (مثل Cl₂ + 2e⁻ → 2Cl⁻).', '["","عكس الصحيح: الأكسدة فقد للإلكترونات فتظهر ناتجًا، والاختزال كسب لها فتظهر متفاعلًا.","العكس هو الصحيح: الإلكترونات تظهر في أنصاف التفاعلات وتُحذف من المعادلة الكلية بعد الجمع.","لو ظهرت بالعدد نفسه في الطرفين لحُذفت، ولما دل نصف التفاعل على فقد أو كسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.612Z"}'::jsonb),
('mcq', 5, 3, 'عدد تأكسد البلاديوم يقل من 2+ في Pd(NO₃)₂ إلى صفر في Pd، أي يكتسب إلكترونين: Pd²⁺ + 2e⁻ → Pd، وهذا نصف الاختزال.', '["هذا نصف تفاعل الأكسدة؛ فالرصاص يفقد إلكترونين.","عكس اتجاه التغير؛ البلاديوم يتحول من أيون Pd²⁺ إلى فلز Pd لا العكس.","وضع الإلكترونات في جهة النواتج، فالشحنة غير متساوية (2+ مقابل 2−).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-17T11:36:22.612Z"}'::jsonb),
('mcq', 6, 2, 'الحديد يتأكسد من صفر إلى 3+: Fe → Fe³⁺ + 3e⁻، والفلور يختزل من صفر إلى 1−، وجزيء F₂ يكتسب إلكترونين: F₂ + 2e⁻ → 2F⁻.', '["الفلور يوجد في صورة جزيئات ثنائية الذرة F₂، فيجب كتابة نصف الاختزال باستعمال F₂.","عكس الاتجاهين؛ الحديد هو الذي يتأكسد والفلور هو الذي يختزل.","","وضع الإلكترونات في نواتج نصف الاختزال؛ فهذا يعني فقدًا لا كسبًا، والشحنة غير متساوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.612Z"}'::jsonb),
('mcq', 7, 1, 'الكبريت يتأكسد من 4+ في SO₂ إلى 6+ في SO₄²⁻ ففقد إلكترونين. بوزن O بـ 2H₂O وH بـ 4H⁺ نحصل على: SO₂ + 2H₂O → SO₄²⁻ + 4H⁺ + 2e⁻، والشحنة صفر في الطرفين (2− + 4+ 2− = صفر).', '["الذرات متوازنة لكن الشحنة غير متساوية (صفر مقابل 2+)؛ فقد نُسيت الإلكترونات المفقودة.","","وضع الإلكترونات في جهة المتفاعلات، فالشحنة 2− مقابل 2+، ويصبح كأنه اختزال.","هذا نصف تفاعل موزون، لكنه نصف الاختزال لأن المنجنيز يكتسب الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.612Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نصف التفاعل: أحد جزأي تفاعل الأكسدة والاختزال؛ أي تفاعل الأكسدة أو تفاعل الاختزال. نصف الأكسدة: Pb → Pb²⁺ + 2e⁻ (الرصاص يفقد إلكترونين). نصف الاختزال: Pd²⁺ + 2e⁻ → Pd (أيون البلاديوم يكتسب إلكترونين). أيونات النترات متفرجة فلا تظهر.', '["تعريف نصف التفاعل","نصف الأكسدة","نصف الاختزال"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"نصف تفاعل الأكسدة","marks":1},{"element":"نصف تفاعل الاختزال","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف صحيح ونصفا تفاعل صحيحان محددان."},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["تضمين أيونات النترات في أنصاف التفاعل","وضع الإلكترونات في الجهة الخطأ","الخلط بين نصف الأكسدة ونصف الاختزال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-17T11:36:22.612Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) O₂ + 4e⁻ → 2O²⁻. (2) 2H⁺ + 2e⁻ → H₂. (3) Cu²⁺ + 2e⁻ → Cu. نصف الأكسدة واحد في الثلاثة: Fe → Fe³⁺ + 3e⁻، لأن المادة التي تتأكسد واحدة (الحديد) وتتحول إلى الأيون نفسه Fe³⁺، أما العامل المؤكسد فيختلف فيختلف نصف الاختزال.', '["نصف اختزال الأكسجين","نصف اختزال H⁺","نصف اختزال Cu²⁺","التفسير مع كتابة نصف الأكسدة"]'::jsonb, '[]'::jsonb, '[{"element":"O₂ + 4e⁻ → 2O²⁻","marks":1},{"element":"2H⁺ + 2e⁻ → H₂","marks":1},{"element":"Cu²⁺ + 2e⁻ → Cu","marks":1},{"element":"التفسير ونصف الأكسدة المشترك","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ثلاثة أنصاف اختزال صحيحة وتفسير سليم."},{"level":"2–3 درجات","description":"نصفان أو ثلاثة صحيحة دون تفسير كامل."},{"level":"1 درجة","description":"نصف تفاعل واحد صحيح."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["كتابة Br⁻ بدلًا من H⁺ في التفاعل الثاني رغم أن البروميد لا يتغير","كتابة O + 2e⁻ → O²⁻ بذرة أكسجين منفردة","اعتبار SO₄²⁻ هو المختزل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.613Z"}'::jsonb),
('essay', 3, null::int, null, null, 'Zn يزداد عدد تأكسده من صفر إلى 2+ فهو يتأكسد: Zn → Zn²⁺ + 2e⁻. N ينقص من 5+ في NO₃⁻ إلى 4+ في NO₂ فهو يختزل: NO₃⁻ + 2H⁺ + e⁻ → NO₂ + H₂O (O: 3 = 2 + 1، H: 2 = 2، الشحنة: 1− 2+ 1− = صفر). لتساوي الإلكترونات نضرب نصف الاختزال في 2: 2NO₃⁻ + 4H⁺ + 2e⁻ → 2NO₂ + 2H₂O. بالجمع وحذف 2e⁻ نحصل على: Zn + 2NO₃⁻ + 4H⁺ → Zn²⁺ + 2NO₂ + 2H₂O.', '["نصف الأكسدة وتعليله","نصف الاختزال موزونًا بـ H⁺ وH₂O وتعليله","التحقق من شحنة نصف الاختزال","الضرب في 2 والجمع"]'::jsonb, '["Zn: 0 → 2+ ⇒ Zn → Zn²⁺ + 2e⁻","N: 5+ → 4+ ⇒ NO₃⁻ + 2H⁺ + e⁻ → NO₂ + H₂O","نصف الاختزال × 2","الجمع وحذف 2e⁻"]'::jsonb, '[{"element":"نصف الأكسدة مع التعليل","marks":1},{"element":"نصف الاختزال الموزون مع التعليل","marks":2},{"element":"الضرب والجمع للوصول إلى المعادلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نصفان موزونان معللان وجمع صحيح."},{"level":"2–3 درجات","description":"نصفان صحيحان دون تعليل أو دون الجمع."},{"level":"1 درجة","description":"نصف تفاعل الأكسدة فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["كتابة نصف الاختزال NO₃⁻ + e⁻ → NO₂ دون وزن الأكسجين","وضع 2e⁻ في نصف الاختزال بدل e⁻ واحد","نسيان ضرب نصف الاختزال في 2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.613Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
