from (values
('mcq', 1, 'في تفاعل الألومنيوم مع أيونات النحاس II، نصف التأكسد: Al → Al³⁺ + 3e⁻ ونصف الاختزال: Cu²⁺ + 2e⁻ → Cu. ما معاملا الضرب اللذان يساويان بين الإلكترونات المفقودة والمكتسبة؟', null, '["نصف الأكسدة × 2 ونصف الاختزال × 3","نصف الأكسدة × 3 ونصف الاختزال × 2","نصف الأكسدة × 1 ونصف الاختزال × 1","نصف الأكسدة × 6 ونصف الاختزال × 6"]'::jsonb, 'تطبيق', 'مساواة الإلكترونات', 'سهل', 'الكتاب ص 118 — طريقة نصف التفاعل (الجدول 6-3)'),
('mcq', 2, 'ما الخطوة الأخيرة في طريقة نصف التفاعل بعد جمع نصفي التفاعل الموزونين؟', null, '["كتابة معادلة نصف التفاعل لكل مادة من جديد","تحديد أعداد التأكسد لجميع الذرات في المعادلة","ضرب نصفي التفاعل في المضاعف المشترك الأصغر","إعادة الأيونات المتفرجة وحالات المواد"]'::jsonb, 'فهم', 'ترتيب خطوات', 'سهل', 'الكتاب ص 118 — طريقة نصف التفاعل (الجدول 6-3)'),
