from (values
('mcq', 1, 0, 'المضاعف المشترك الأصغر لـ 3 و2 هو 6: نضرب نصف الأكسدة في 2 (6e⁻ مفقودة) ونصف الاختزال في 3 (6e⁻ مكتسبة): 2Al + 3Cu²⁺ → 2Al³⁺ + 3Cu.', '["","عكس المعاملين: يفقد Al ثلاثة إلكترونات فإذا ضُرب في 3 صارت 9 مقابل 4 مكتسبة.","لا تتساوى الإلكترونات (3 مفقودة و2 مكتسبة).","يساوي الإلكترونات (18 لكل طرف) لكنه ليس بالمضاعف المشترك الأصغر، فالمعاملات ليست بأصغر أعداد صحيحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.613Z"}'::jsonb),
('mcq', 2, 3, 'خطوات طريقة نصف التفاعل: كتابة المعادلة الأيونية الكلية، كتابة نصفي التفاعل، وزن الذرات والشحنات، مساواة الإلكترونات، ثم جمع النصفين وتبسيط الناتج وإعادة الأيونات المتفرجة؛ فالأخيرة هي إعادة الأيونات المتفرجة.', '["نصفا التفاعل كُتبا في الخطوة الثانية، ولا حاجة لإعادة كتابتهما.","هذه خطوة من طريقة عدد التأكسد لا من طريقة نصف التفاعل.","هذه الخطوة تسبق الجمع؛ فلا يمكن حذف الإلكترونات قبل تساويها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.614Z"}'::jsonb),
('mcq', 3, 2, '6 هو المضاعف المشترك لـ 6 و2، فيُضرب نصف الأكسدة في 3: 6I⁻ → 3I₂ + 6e⁻. بالجمع وحذف 6e⁻: Cr₂O₇²⁻ + 6I⁻ + 14H⁺ → 2Cr³⁺ + 3I₂ + 7H₂O. الشحنة: 2− 6− 14+ = 6+ ، ويمين 6+.', '["لم يُضرب نصف الأكسدة في 3، فبقيت 6 إلكترونات مكتسبة مقابل 2 مفقودة.","ضرب نصف الاختزال في 3 بدل نصف الأكسدة، فلا تتساوى الذرات.","","غيّر عدد H⁺ دون مبرر؛ فذرات H في اليسار 7 وفي اليمين 14."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.614Z"}'::jsonb),
('mcq', 4, 1, 'المضاعف المشترك الأصغر لـ 2 و3 هو 6: 3Sn²⁺ تعطي 6e⁻، و2Au³⁺ تكتسب 6e⁻: 3Sn²⁺ + 2Au³⁺ → 3Sn⁴⁺ + 2Au.', '["عكس العددين: 2 أيون Sn²⁺ تعطي 4 إلكترونات بينما تحتاج 3 أيونات Au³⁺ إلى 9.","","يفقد Sn²⁺ إلكترونين ويحتاج Au³⁺ إلى ثلاثة؛ فيبقى إلكترون ناقص.","عدد الإلكترونات 12 و18؛ لا تتساوى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.614Z"}'::jsonb),
('mcq', 5, 0, 'نحذف 16H⁺ من الطرفين فتبقى 4H⁺ في النواتج (20 − 16)، ونحذف 8H₂O من الطرفين فتبقى 2H₂O في المتفاعلات (10 − 8). المعادلة: 5SO₂ + 2H₂O + 2MnO₄⁻ → 5SO₄²⁻ + 4H⁺ + 2Mn²⁺.', '["","جمع أيونات H⁺ من الطرفين (20 + 16 = 36) بدل طرحها، ثم نقل المجموع إلى اليسار؛ والصحيح الطرح (20 − 16 = 4).","جمع جزيئات الماء (10 + 8) بدل طرحها؛ فيصبح الماء 18 بدل 2.","جمع 20 + 16 = 36 من H⁺ بدل طرحها (20 − 16 = 4)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.614Z"}'::jsonb),
('mcq', 6, 2, 'المضاعف المشترك الأصغر لـ 1 و5 هو 5، فيُضرب نصف الأكسدة في 5: 5Fe²⁺ → 5Fe³⁺ + 5e⁻. المعادلة: MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O.', '["هو معامل نصف الأكسدة قبل مساواة الإلكترونات.","خلط بمعامل H⁺ في نصف الاختزال.","","ضرب نصف الأكسدة في 10 كما لو كان المضاعف المشترك الأصغر لـ 1 و5 يساوي 10، وهو في الحقيقة 5."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.615Z"}'::jsonb),
('mcq', 7, 0, 'المضاعف المشترك لـ 2 و3 هو 6: Zn × 3 و Cr³⁺ × 2. 3Zn → 3Zn²⁺ + 6e⁻ و 2Cr³⁺ + 6e⁻ → 2Cr، فالمعادلة: 3Zn + 2Cr³⁺ → 3Zn²⁺ + 2Cr. الشحنة: 6+ = 6+.', '["","جمع مباشر لا يحذف الإلكترونات (2 و3)، وهي غير موزونة كهربائيًّا (3+ مقابل 2+).","عكس المعاملين: 2Zn تفقد 4 إلكترونات و3Cr³⁺ تكتسب 9.","إبقاء إلكترون في المعادلة النهائية، والمطلوب أن لا تتبقى إلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.615Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المعادلة الأيونية الكلية: Al + Cu²⁺ → Al³⁺ + Cu (Cl⁻ متفرج). نصف الأكسدة: Al → Al³⁺ + 3e⁻. نصف الاختزال: Cu²⁺ + 2e⁻ → Cu. المضاعف المشترك الأصغر لـ 3 و2 هو 6: 2Al → 2Al³⁺ + 6e⁻ ، 3Cu²⁺ + 6e⁻ → 3Cu. بالجمع: 2Al + 3Cu²⁺ → 2Al³⁺ + 3Cu. نعيد الأيونات المتفرجة (6Cl⁻): 2Al + 3CuCl₂ → 2AlCl₃ + 3Cu.', '["المعادلة الأيونية الكلية","نصفا التفاعل","الضرب في 2 و3","الجمع","إعادة Cl⁻"]'::jsonb, '["Al + Cu²⁺ → Al³⁺ + Cu","Al → Al³⁺ + 3e⁻ ; Cu²⁺ + 2e⁻ → Cu","× 2 و × 3","2Al + 3Cu²⁺ → 2Al³⁺ + 3Cu","2Al + 3CuCl₂ → 2AlCl₃ + 3Cu"]'::jsonb, '[{"element":"المعادلة الأيونية الكلية بحذف المتفرجات","marks":1},{"element":"نصفا تفاعل صحيحان","marks":1},{"element":"مساواة الإلكترونات بالمضاعف المشترك الأصغر","marks":1},{"element":"الجمع وإعادة الأيونات المتفرجة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل الخطوات صحيحة والمعادلة النهائية موزونة."},{"level":"2–3 درجات","description":"خطأ في خطوة واحدة."},{"level":"1 درجة","description":"كتابة نصفي التفاعل فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["عدم إعادة الأيونات المتفرجة","ضرب النصفين في 3 و2 بالعكس","كتابة Cl⁻ في نصف الاختزال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.615Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نصف الأكسدة: Mn²⁺ + 4H₂O → MnO₄⁻ + 8H⁺ + 5e⁻. نصف الاختزال: BiO₃⁻ + 6H⁺ + 2e⁻ → Bi³⁺ + 3H₂O. المضاعف المشترك الأصغر لـ 5 و2 هو 10: الأكسدة × 2 والاختزال × 5: 2Mn²⁺ + 8H₂O → 2MnO₄⁻ + 16H⁺ + 10e⁻ ، 5BiO₃⁻ + 30H⁺ + 10e⁻ → 5Bi³⁺ + 15H₂O. بالجمع والتبسيط: 2Mn²⁺ + 5BiO₃⁻ + 14H⁺ → 2MnO₄⁻ + 5Bi³⁺ + 7H₂O. التحقق: الشحنة يسار 4+ 5− 14+ = 13+ ، يمين 2− 15+ = 13+.', '["نصف الأكسدة موزونًا","نصف الاختزال موزونًا","المضاعف المشترك الأصغر 10","الجمع والتبسيط","التحقق"]'::jsonb, '["Mn²⁺ + 4H₂O → MnO₄⁻ + 8H⁺ + 5e⁻","BiO₃⁻ + 6H⁺ + 2e⁻ → Bi³⁺ + 3H₂O","×2 و ×5","H⁺: 30 − 16 = 14 في المتفاعلات ، H₂O: 15 − 8 = 7 في النواتج","الشحنة 13+ = 13+"]'::jsonb, '[{"element":"نصف الأكسدة موزونًا","marks":1},{"element":"نصف الاختزال موزونًا","marks":1},{"element":"مساواة الإلكترونات","marks":1},{"element":"الجمع والتبسيط","marks":1},{"element":"التحقق من الشحنة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح."},{"level":"3–4 درجات","description":"خطأ في التبسيط أو غياب التحقق."},{"level":"1–2 درجة","description":"نصف تفاعل واحد موزون."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["نسيان وزن الأكسجين بالماء","ضرب النصفين بـ 5 و2 بالعكس","عدم طرح H⁺ و H₂O المتكررة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.615Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المعادلة الأيونية الكلية: MnO₄⁻ + Fe²⁺ + H⁺ → Mn²⁺ + Fe³⁺ + H₂O (K⁺ وSO₄²⁻ متفرجان). الاختزال: MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O. الأكسدة: Fe²⁺ → Fe³⁺ + e⁻. نضرب الأكسدة في 5: 5Fe²⁺ → 5Fe³⁺ + 5e⁻. بالجمع: MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O. ولأن Fe₂(SO₄)₃ تحتوي ذرتي حديد نضرب في 2: 2MnO₄⁻ + 10Fe²⁺ + 16H⁺ → 2Mn²⁺ + 10Fe³⁺ + 8H₂O. نعيد المتفرجات: 2KMnO₄ + 10FeSO₄ + 8H₂SO₄ → K₂SO₄ + 2MnSO₄ + 5Fe₂(SO₄)₃ + 8H₂O. التحقق من SO₄²⁻: 10 + 8 = 18 = 1 + 2 + 15.', '["المعادلة الأيونية الكلية","نصفا التفاعل","الضرب في 5","الضرب في 2 لإعطاء أيونات Fe³⁺ زوجية","إعادة المتفرجات والتحقق"]'::jsonb, '["MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O","Fe²⁺ → Fe³⁺ + e⁻ (×5)","MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O","× 2 لأن Fe₂(SO₄)₃ فيها ذرتا Fe","2KMnO₄ + 10FeSO₄ + 8H₂SO₄ → K₂SO₄ + 2MnSO₄ + 5Fe₂(SO₄)₃ + 8H₂O"]'::jsonb, '[{"element":"المعادلة الأيونية الكلية","marks":1},{"element":"نصفا التفاعل الموزونان","marks":1},{"element":"مساواة الإلكترونات","marks":1},{"element":"ضبط الحديد الزوجي (×2)","marks":1},{"element":"إعادة المتفرجات والتحقق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح."},{"level":"3–4 درجات","description":"معادلة أيونية صحيحة مع خطأ في إعادة المتفرجات."},{"level":"1–2 درجة","description":"نصفا التفاعل فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["إهمال ضرب المعاملات في 2 لأن Fe₂(SO₄)₃ تحتوي ذرتي حديد","وضع 5FeSO₄ و5Fe₂(SO₄)₃","نسيان 8H₂SO₄"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.616Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
