from (values
('mcq', 1, 3, 'يظهر النيتروجين في HNO₃ وCu(NO₃)₂ وNO₂ فيصعب وزن المعادلة بالطريقة التقليدية، لذا تُوزن بطريقة عدد التأكسد بمساواة الزيادة في عدد تأكسد Cu بالنقصان في عدد تأكسد N.', '["العنصر الذي يظهر أكثر من مرة في كل جهة (كالنيتروجين هنا) يصعب وزنه بالطريقة التقليدية.","تتطلب طريقة نصف التفاعل أولًا كتابة المعادلة الأيونية الكلية، ولا تُطبَّق مباشرة على المعادلة الجزيئية.","التفاعل هنا في وسط حمضي (HNO₃)، وليس سبب اختيار الطريقة نوع الوسط القاعدي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.617Z"}'::jsonb),
('mcq', 2, 0, 'المادتان المتأكسدة (Fe) والمختزلة (Cu²⁺) تظهر كل منهما في مادة واحدة، فيسهل فصلها إلى نصفي تفاعل: Fe → Fe³⁺ + 3e⁻ و Cu²⁺ + 2e⁻ → Cu، ثم مساواة الإلكترونات بالمضاعف المشترك 6: 2Fe + 3Cu²⁺ → 2Fe³⁺ + 3Cu.', '["","يمكن وزن هذا التفاعل نفسه بطريقة نصف التفاعل؛ وطريقة عدد التأكسد ليست الوحيدة للمعادلات الأيونية.","لا يكفي عدّ الذرات هنا؛ فالشحنة غير متساوية ولا بد من مساواة الإلكترونات المفقودة والمكتسبة.","المعادلات الأيونية تُوزن بالطريقتين المقررتين، ولا يمنع وجود الأيونات الوزن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.617Z"}'::jsonb),
('mcq', 3, 0, 'تبدأ استراتيجية الحل بتحديد المواد التي تأكسدت والتي اختُزلت (وأيها عوامل مؤكسدة وأيها عوامل مختزلة)، ثم يُختار على أساس ذلك وعلى أساس الوسط وظهور المواد في أكثر من مادة طريقة الوزن المناسبة.', '["","هذه خطوة داخل طريقة عدد التأكسد، تأتي بعد اختيار الطريقة.","هذه خطوة متأخرة تتبع تحديد الطريقة وكتابة أنصاف التفاعل.","هذه آخر خطوة في طريقة نصف التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.617Z"}'::jsonb),
('mcq', 4, 1, 'في المعادلة (ب) يظهر النيتروجين في HNO₃ في المتفاعلات وفي Cu(NO₃)₂ وNO₂ في النواتج، فيصعب وزنها بالطريقة التقليدية وتُوزن بطريقة عدد التأكسد؛ أما في المعادلات الأيونية البسيطة (أ) و(ج) و(د) فيظهر كل عنصر في مادة واحدة في كل جانب، فتناسبها طريقة نصف التفاعل.', '["في (أ) تظهر Fe وCu²⁺ في مادة واحدة في كل جانب، فتناسبها طريقة نصف التفاعل.","","في (ج) تظهر Sn²⁺ وAu³⁺ في مادة واحدة في كل جانب، ويسهل فصلها إلى نصفي تفاعل.","في (د) تظهر Zn وAg⁺ في مادة واحدة في كل جانب، فتناسبها طريقة نصف التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.617Z"}'::jsonb),
('mcq', 5, 1, 'عندما يحدث التفاعل في وسط قاعدي تُضاف أيونات OH⁻ إلى طرفي المعادلة بعدد H⁺ (8OH⁻)، فتتحد 8H⁺ + 8OH⁻ مكونة 8H₂O ثم يُختصر الماء: 6I⁻ + 2MnO₄⁻ + 4H₂O → 3I₂ + 2MnO₂ + 8OH⁻.', '["المعادلة تحتوي H⁺ وهي صورة الوسط الحمضي، ولا تصلح معادلة نهائية في وسط قاعدي.","","زيادة H⁺ تزيد الحمضية ولا تلائم الوسط القاعدي.","حذف H⁺ وحدها يُخل بوزن الهيدروجين والشحنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.618Z"}'::jsonb),
('mcq', 6, 2, 'عدد تأكسد P في P₄ صفر. في HPO₃²⁻: ‎+1 + x + 3(−2) = −2 فـ x = 3+ (تأكسد)، وفي PH₃ يساوي 3− (اختزال). فمادة واحدة تتأكسد وتختزل معًا، وتظهر في أكثر من مادة ناتجة، وهذا ما يُراعى عند اختيار الطريقة.', '["عدد تأكسد P في PH₃ هو 3−، أي أن الفسفور اختُزل فيه.","عدد تأكسد P في HPO₃²⁻ هو 3+، أي أن الفسفور تأكسد فيه.","","P₄ عنصر حر (صفر) تحول إلى 3+ و3−، فالتفاعل أكسدة واختزال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.618Z"}'::jsonb),
('mcq', 7, 3, 'الخطوة الأولى في طريقة نصف التفاعل هي كتابة المعادلة الأيونية الكلية مهملين الأيونات المتفرجة؛ فتصبح: Cr₂O₇²⁻ + Fe²⁺ + H⁺ → Cr³⁺ + Fe³⁺ + H₂O، ثم تُكتب أنصاف التفاعل.', '["هذا هو أسلوب طريقة عدد التأكسد لا طريقة نصف التفاعل.","تُكتب أنصاف التفاعل للمعادلة الأيونية الكلية بعد حذف المتفرجات، لا بالصيغ الجزيئية.","هذه الخطوة الأخيرة في الطريقة، وليست الأولى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.618Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الكلور يظهر في المتفاعل HClO₃ وفي ناتجين (ClO₂ وHClO₄) فيتأكسد ويختزل، والمعادلة جزيئية؛ فالأنسب طريقة عدد التأكسد: Cl من 5+ إلى 4+ (1−) ومن 5+ إلى 7+ (2+)، فنضع 2ClO₂ مقابل 1HClO₄، فتصبح 3HClO₃ → 2ClO₂ + HClO₄ + H₂O. (ب) معادلة أيونية في وسط حمضي، وكل من Cr₂O₇²⁻ وFe²⁺ يظهر في مادة واحدة؛ فالأنسب نصف التفاعل: Fe²⁺ → Fe³⁺ + e⁻ و Cr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O؛ نضرب الأول في 6 فنحصل على: Cr₂O₇²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H₂O.', '["اختيار عدد التأكسد لـ (أ) مع التعليل","اختيار نصف التفاعل لـ (ب) مع التعليل","وزن (أ) صحيحًا","وزن (ب) صحيحًا"]'::jsonb, '["(أ) Cl: 5+ → 4+ (1−) و5+ → 7+ (2+) ⇒ 2ClO₂ : 1HClO₄ ⇒ 3HClO₃","موازنة H وO: 3HClO₃ → 2ClO₂ + HClO₄ + H₂O","(ب) Fe²⁺ → Fe³⁺ + e⁻ ؛ Cr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O","× 6 للحديد ثم الجمع: Cr₂O₇²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H₂O"]'::jsonb, '[{"element":"اختيار طريقة (أ) مع تعليل","marks":1},{"element":"اختيار طريقة (ب) مع تعليل","marks":1},{"element":"وزن (أ)","marks":1},{"element":"وزن (ب)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"اختيار معلل صحيح للمعادلتين ووزن صحيح لهما."},{"level":"3–4 درجات","description":"اختيار صحيح مع خطأ في وزن إحداهما."},{"level":"1–2 درجة","description":"اختيار الطريقة دون وزن، أو وزن دون تعليل."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["اعتبار الكلور في (أ) يتأكسد فقط أو يختزل فقط","استعمال عدد التأكسد دون ضبط H₂O في (أ)","نسيان 14H⁺ في (ب)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.619Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الكلور Cl₂ (صفر) يتأكسد إلى ClO₃⁻ (5+) ويختزل إلى Cl⁻ (1−)؛ فمادة واحدة تؤدي الدورين. (ب) تصلح طريقة نصف التفاعل لأن المعادلة أيونية في وسط قاعدي، فتُكتب أنصاف التفاعل ثم يُكمل الوزن بـ OH⁻ وH₂O؛ وتصلح كذلك طريقة عدد التأكسد، ويُقبل أيهما مع التبرير. (ج) الاختزال: Cl₂ + 2e⁻ → 2Cl⁻. الأكسدة: Cl₂ + 12OH⁻ → 2ClO₃⁻ + 6H₂O + 10e⁻. نضرب الاختزال في 5: 5Cl₂ + 10e⁻ → 10Cl⁻. بالجمع: 6Cl₂ + 12OH⁻ → 10Cl⁻ + 2ClO₃⁻ + 6H₂O، وبالقسمة على 2: 3Cl₂ + 6OH⁻ → 5Cl⁻ + ClO₃⁻ + 3H₂O. التحقق: الشحنة 6− = 5− + 1− = 6−.', '["أعداد التأكسد وتحديد المتأكسد والمختزل","اختيار الطريقة مع التبرير","نصفا التفاعل الموزونان","المعادلة النهائية بأصغر الأعداد","التحقق"]'::jsonb, '["Cl: 0 → 1− و0 → 5+","Cl₂ + 2e⁻ → 2Cl⁻","Cl₂ + 12OH⁻ → 2ClO₃⁻ + 6H₂O + 10e⁻","×5 للاختزال ثم الجمع: 6Cl₂ + 12OH⁻ → 10Cl⁻ + 2ClO₃⁻ + 6H₂O","القسمة على 2: 3Cl₂ + 6OH⁻ → 5Cl⁻ + ClO₃⁻ + 3H₂O"]'::jsonb, '[{"element":"تحليل أعداد التأكسد","marks":1},{"element":"اختيار الطريقة والتبرير","marks":1},{"element":"نصفا التفاعل الموزونان","marks":2},{"element":"المعادلة النهائية بأصغر أعداد","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحليل صحيح، واختيار معلل، ووزن صحيح بأصغر الأعداد."},{"level":"3–4 درجات","description":"تحليل واختيار صحيحان مع خطأ في وزن الأكسجين أو في الاختصار."},{"level":"1–2 درجة","description":"تحليل أعداد التأكسد فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["الاكتفاء بـ 6Cl₂ دون القسمة على 2","استعمال H⁺ في وسط قاعدي","اعتبار Cl₂ يتأكسد فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.619Z"}'::jsonb),
('essay', 3, null::int, null, null, 'كلاهما اختيار مقبول: المعادلة أيونية في وسط حمضي، والمادتان المتأكسدة (Zn) والمختزلة (NO₃⁻) تظهر كل منهما في مادة واحدة في كل جانب، فيناسبها نصف التفاعل لسهولة فصل النصفين وإضافة H⁺ وH₂O؛ وتصلح طريقة عدد التأكسد بمساواة الزيادة (Zn: 2+) بالنقصان (N: من 5+ إلى 3−، أي 8−). الحل بنصف التفاعل: Zn → Zn²⁺ + 2e⁻ ؛ NO₃⁻ + 10H⁺ + 8e⁻ → NH₄⁺ + 3H₂O. المضاعف المشترك 8: الأكسدة × 4: 4Zn → 4Zn²⁺ + 8e⁻. بالجمع: 4Zn + NO₃⁻ + 10H⁺ → 4Zn²⁺ + NH₄⁺ + 3H₂O. التحقق من الشحنة: 1− + 10+ = 9+ ، ويمين 8+ + 1+ = 9+.', '["تقويم الاختيارين وتبريرهما","نصف الأكسدة","نصف الاختزال الموزون","الضرب والجمع","التحقق"]'::jsonb, '["Zn → Zn²⁺ + 2e⁻","NO₃⁻ + 10H⁺ + 8e⁻ → NH₄⁺ + 3H₂O","المضاعف المشترك 8: الأكسدة × 4","4Zn + NO₃⁻ + 10H⁺ → 4Zn²⁺ + NH₄⁺ + 3H₂O","الشحنة 9+ = 9+"]'::jsonb, '[{"element":"تقويم الاختيارين بتبرير سليم","marks":2},{"element":"نصفا التفاعل الموزونان","marks":2},{"element":"الجمع والمعادلة النهائية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم معلل وحل كامل صحيح."},{"level":"3–4 درجات","description":"حل صحيح مع تقويم ناقص أو عكس ذلك."},{"level":"1–2 درجة","description":"نصف تفاعل صحيح أو تبرير فقط."},{"level":"صفر","description":"إجابة غير صحيحة أو لا إجابة."}]'::jsonb, '["اعتبار أن إحدى الطريقتين خاطئة تمامًا","اعتبار تغير N يساوي 2 بدل 8","نسيان H₂O في نصف الاختزال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.619Z"}'::jsonb)
