insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الكيمياء الكهربائية هي دراسة عمليات الأكسدة والاختزال التي تتحول من خلالها الطاقة الكيميائية إلى طاقة كهربائية، وبالعكس؛ فالإجابة: دراسة عمليات الأكسدة والاختزال التي تتحول بها الطاقة الكيميائية إلى كهربائية وبالعكس.', '["هذا وصف لموضوع سرعة التفاعلات الكيميائية، لا للكيمياء الكهربائية التي تدرس تفاعلات الأكسدة والاختزال وتحولات الطاقة الكهربائية.","","هذا وصف للكيمياء الحرارية، أما الكيمياء الكهربائية فتهتم بتحول الطاقة الكيميائية إلى كهربائية وبالعكس.","الكيمياء الكهربائية تقوم على تفاعلات الأكسدة والاختزال، فلا يصح وصفها بأنها دراسة لا يحدث فيها تفاعل كيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.620Z"}'::jsonb),
('mcq', 2, 3, 'الكيمياء الكهربائية دراسة عمليات الأكسدة والاختزال، وهي التفاعلات التي تتضمن انتقال الإلكترونات من المادة التي تتأكسد إلى المادة التي تُختزل؛ فالإجابة: تفاعلات الأكسدة والاختزال.', '["تفاعلات التعادل لا يحدث فيها انتقال للإلكترونات، فلا تقوم عليها الكيمياء الكهربائية.","تفاعلات الترسيب تكوين لمركب صلب من أيونات دون انتقال إلكترونات، فليست موضوع الكيمياء الكهربائية.","تفاعلات الإضافة من تفاعلات الكيمياء العضوية، وليست الأساس الذي تقوم عليه الكيمياء الكهربائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.620Z"}'::jsonb),
('mcq', 3, 0, 'ينص التعريف على أن الكيمياء الكهربائية تدرس تفاعلات الأكسدة والاختزال التي تتحول بها الطاقة الكيميائية إلى طاقة كهربائية وبالعكس، أي تحول الطاقة الكيميائية إلى كهربائية، وتحول الكهربائية إلى كيميائية.', '["","التحول إلى طاقة حرارية ليس ما يميز الكيمياء الكهربائية؛ فتعريفها يتعلق بالطاقة الكهربائية.","تحول الكهرباء إلى ضوء (كما في المصباح) تحول فيزيائي لا يتضمن تفاعل أكسدة واختزال، وليس موضوع التعريف.","هذا يُغفل كلمة «وبالعكس» في التعريف؛ فالكيمياء الكهربائية تشمل أيضًا استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.620Z"}'::jsonb),
('mcq', 4, 2, 'تفاعل الخارصين مع أيونات النحاس تفاعل أكسدة واختزال (يتأكسد Zn وتُختزل Cu²⁺)، واستعماله لتوليد تيار كهربائي تحويل للطاقة الكيميائية إلى كهربائية، وهذا بالضبط موضوع الكيمياء الكهربائية؛ فالإجابة: توليد تيار كهربائي من تفاعل الخارصين مع أيونات Cu²⁺.', '["تفاعل التعادل لا يتضمن انتقال إلكترونات ولا تحولًا إلى طاقة كهربائية.","الذوبان عملية فيزيائية لا يحدث فيها أكسدة واختزال، ولا تتحول فيها طاقة كيميائية إلى كهربائية.","","تفاعل الترسيب لا تتغير فيه أعداد التأكسد، فليس تفاعل أكسدة واختزال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.620Z"}'::jsonb),
('mcq', 5, 0, 'يتأكسد الخارصين: Zn → Zn²⁺ + 2e⁻، وتُختزل أيونات النحاس: Cu²⁺ + 2e⁻ → Cu؛ أي تفقد ذرة Zn إلكترونين وتكتسبهما أيونات Cu²⁺.', '["","هذا عكس ما يحدث؛ فالخارصين يتحول من Zn إلى Zn²⁺ أي يفقد إلكترونين (يتأكسد).","تفاعلات الأكسدة والاختزال تتضمن انتقال الإلكترونات لا البروتونات.","التشارك في الإلكترونات يكوّن رابطة تساهمية، أما هنا فتنتقل الإلكترونات انتقالًا كاملًا من Zn إلى Cu²⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.620Z"}'::jsonb),
('mcq', 6, 3, 'الأكسدة فقدان الذرات للإلكترونات أو الزيادة في عدد التأكسد، وأن الاختزال اكتساب الإلكترونات أو النقص في عدد التأكسد؛ فالإجابة: فقدان الذرات للإلكترونات أو الزيادة في عدد التأكسد.', '["هذا تعريف الاختزال لا الأكسدة.","الأكسدة تتعلق بالإلكترونات وعدد التأكسد، لا بالبروتونات أو العدد الكتلي.","الأكسدة تتضمن دائمًا زيادة في عدد التأكسد، وتعريفها فقد الإلكترونات لا اكتساب الأكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.620Z"}'::jsonb),
('mcq', 7, 2, 'الكيمياء الكهربائية تدرس تفاعلات الأكسدة والاختزال التي تتحول فيها الطاقة الكيميائية إلى كهربائية (كالبطارية) وبالعكس (كالخلية التي يُمرَّر فيها تيار لإحداث تفاعل)، والخلية الكهروكيميائية تشمل الحالتين؛ لذا فكلا الجهازين من مجالها.', '["التعريف يشمل التحول العكسي أيضًا (استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي)، فالجهاز الثاني من مجالها كذلك.","البطارية تحول الطاقة الكيميائية إلى كهربائية بتفاعل أكسدة واختزال، وهذا أصل تعريف الكيمياء الكهربائية.","","في كلا الجهازين يحدث تفاعل أكسدة واختزال؛ ففي الأول يُنتج الكهرباء، وفي الثاني تُحدثه الكهرباء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.621Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكيمياء الكهربائية: دراسة عمليات الأكسدة والاختزال التي تتحول من خلالها الطاقة الكيميائية إلى طاقة كهربائية، وبالعكس. ويُقصد بـ«وبالعكس» أنها تدرس أيضًا استعمال الطاقة الكهربائية لإحداث تفاعل أكسدة واختزال كيميائي، أي تحول الطاقة الكهربائية إلى طاقة كيميائية.', '["دراسة عمليات (تفاعلات) الأكسدة والاختزال","تحول الطاقة الكيميائية إلى طاقة كهربائية","«وبالعكس»: تحول الطاقة الكهربائية إلى كيميائية بإحداث تفاعل كيميائي"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن موضوعها عمليات الأكسدة والاختزال","marks":1},{"element":"ذكر تحول الطاقة الكيميائية إلى كهربائية","marks":1},{"element":"تفسير «وبالعكس» بتحول الكهربائية إلى كيميائية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف كامل مع تفسير صحيح لكلمة «وبالعكس»"},{"level":"درجتان","description":"تعريف صحيح دون تفسير «وبالعكس»، أو تفسير صحيح مع تعريف ناقص"},{"level":"درجة واحدة","description":"ذكر عنصر واحد فقط من التعريف"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["إغفال ذكر الأكسدة والاختزال والاكتفاء بعبارة «دراسة الكهرباء»","حصر التعريف في إنتاج الكهرباء من التفاعلات فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.621Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المادة التي تتأكسد: Zn، ونصف تفاعل الأكسدة: Zn(s) → Zn²⁺(aq) + 2e⁻. المادة التي تُختزل: Cu²⁺، ونصف تفاعل الاختزال: Cu²⁺(aq) + 2e⁻ → Cu(s). عدد الإلكترونات المنتقلة: إلكترونان من كل ذرة Zn إلى كل أيون Cu²⁺. ويندرج ضمن الكيمياء الكهربائية لأنه تفاعل أكسدة واختزال يمكن عند فصل نصفيه وتوصيلهما بسلك وقنطرة ملحية أن تتحول طاقته الكيميائية إلى طاقة كهربائية.', '["Zn تتأكسد وCu²⁺ تُختزل","نصف تفاعل الأكسدة","نصف تفاعل الاختزال","انتقال إلكترونين","الربط بتعريف الكيمياء الكهربائية"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المادة المتأكسدة والمختزلة","marks":1},{"element":"كتابة نصفي التفاعل صحيحين","marks":1},{"element":"عدد الإلكترونات المنتقلة (2)","marks":1},{"element":"الربط بتعريف الكيمياء الكهربائية (أكسدة واختزال وتحول طاقة كيميائية إلى كهربائية)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"3 درجات","description":"خطأ في عنصر واحد"},{"level":"درجتان","description":"تحديد صحيح للمتأكسد والمختزل مع نصفي تفاعل فيهما خطأ"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عكس المتأكسد والمختزل","كتابة الإلكترونات في الجهة الخطأ من نصف التفاعل","عدم ربط التفاعل بتحول الطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.621Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) من موضوعاتها؛ لأن البطارية تحول الطاقة الكيميائية إلى طاقة كهربائية بتفاعل أكسدة واختزال. (ب) ليست منها؛ لأن التعادل لا يتضمن انتقال إلكترونات (ليس أكسدة واختزال) ولا ينتج طاقة كهربائية. (ج) من موضوعاتها؛ لأن الطاقة الكهربائية تُستعمل لإحداث تفاعل أكسدة واختزال، وهو التحول العكسي الذي يشمله التعريف.', '["(أ) من موضوعاتها: كيميائية → كهربائية","(ب) ليست منها: لا أكسدة واختزال","(ج) من موضوعاتها: كهربائية → كيميائية"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (أ) صحيح","marks":1},{"element":"تعليل (أ)","marks":1},{"element":"تصنيف (ب) صحيح","marks":1},{"element":"تعليل (ب)","marks":1},{"element":"تصنيف (ج) صحيح","marks":1},{"element":"تعليل (ج)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف وتعليل صحيحان للعمليات الثلاث"},{"level":"4–5 درجات","description":"تصنيف صحيح للثلاث مع تعليل ناقص لإحداها أو اثنتين"},{"level":"2–3 درجات","description":"تصنيف صحيح لعمليتين أو ثلاث دون تعليل كافٍ"},{"level":"درجة واحدة","description":"تصنيف صحيح لعملية واحدة"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["استبعاد (ج) ظنًّا أن الكيمياء الكهربائية تقتصر على إنتاج الكهرباء","عدّ التعادل من موضوعاتها لأن المحلول موصل للكهرباء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.622Z"}'::jsonb)
