from (values
('mcq', 1, 2, 'الخلية الجلفانية نوع من الخلايا الكهروكيميائية تحول الطاقة الكيميائية إلى طاقة كهربائية بواسطة تفاعل الأكسدة والاختزال التلقائي.', '["هذا وصف لخلية يُستعمل فيها مصدر كهربائي خارجي لإحداث التفاعل، والخلية الجلفانية عكس ذلك: تُنتج الكهرباء من تفاعل تلقائي.","اتجاه تحول الطاقة معكوس، والتفاعل فيها أكسدة واختزال لا تعادل.","","الخلية الجلفانية مصدر طاقتها تفاعل كيميائي (أكسدة واختزال)، لا الطاقة الحرارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.622Z"}'::jsonb),
('mcq', 2, 0, 'تسمى الخلايا الجلفانية أيضًا الخلايا الفولتية نسبة إلى العالم الفيزيائي الإيطالي أليساندرو فولتا (1745–1827م) الذي نُسب إليه اختراعها عام 1800م.', '["","لا تُسمى الخلايا الجلفانية خلايا حرارية؛ فهي تنتج طاقة كهربائية لا حرارية.","خلايا التحليل الكهربائي تستعمل الكهرباء لإحداث تفاعل غير تلقائي، فهي عكس الخلايا الجلفانية.","الخلايا الشمسية تحول الطاقة الضوئية إلى كهربائية دون تفاعل أكسدة واختزال، فليست اسمًا للخلايا الجلفانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.622Z"}'::jsonb),
('mcq', 3, 3, 'التفاعل في الخلية الجلفانية تفاعل أكسدة واختزال تلقائي، فهو الذي يُنتج الطاقة الكهربائية ولا يحتاج إلى مصدر خارجي لها؛ فالإجابة: أنه تلقائي يحدث دون الحاجة إلى مصدر خارجي للطاقة الكهربائية.', '["التفاعل الذي يحتاج إلى مصدر خارجي للتيار هو تفاعل الخلايا التي تستعمل الكهرباء، لا الخلية الجلفانية.","كل تفاعل أكسدة واختزال يتضمن انتقال إلكترونات، وهي التي تتدفق في السلك فتُكوّن التيار.","في الخلية الجلفانية يُفصل نصفا التفاعل في كأسين، وتمنع القنطرة الملحية اختلاط المحلولين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.623Z"}'::jsonb),
('mcq', 4, 1, 'تنطلق الإلكترونات من الأنود حيث تحدث الأكسدة، وتنتقل عبر السلك الخارجي إلى الكاثود حيث يحدث الاختزال، بينما تتحرك الأيونات في القنطرة الملحية؛ فالإجابة: في السلك الخارجي من الأنود إلى الكاثود.', '["الإلكترونات تنتج عند الأنود (حيث الأكسدة) وتُستهلك عند الكاثود (حيث الاختزال)، فاتجاهها من الأنود إلى الكاثود.","","القنطرة الملحية ممر للأيونات لا للإلكترونات؛ فالإلكترونات تتدفق في السلك.","الإلكترونات لا تنتقل خلال المحاليل، بل خلال السلك الموصل بين القطبين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.623Z"}'::jsonb),
('mcq', 5, 1, 'الخلية الجلفانية تحتاج إلى نصفي خلية منفصلين، وسلك لنقل الإلكترونات، وقنطرة ملحية لنقل الأيونات، وتفاعل تلقائي يُنتج طاقة كهربائية (يضيء المصباح)؛ وهذه الشروط تتحقق في شريحتي Zn وCu المتصلتين بسلك وقنطرة ملحية.', '["يحدث هنا تفاعل أكسدة واختزال، لكن الإلكترونات تنتقل مباشرة من Zn إلى Cu²⁺ فلا يتولد تيار في دائرة خارجية.","","بلا قنطرة ملحية تتراكم الأيونات حول القطبين فيتوقف التفاعل، فلا يتدفق تيار مستمر.","هذه خلية تستعمل الطاقة الكهربائية لإحداث تفاعل، أي عكس الخلية الجلفانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.623Z"}'::jsonb),
('mcq', 6, 2, 'تتكون الخلية الجلفانية من جزأين يسمى كل منهما نصف الخلية، ويحتوي كل نصف خلية على قطب ومحلول يشتمل على أيونات، ويُوصل القطبان بسلك والمحلولان بقنطرة ملحية.', '["الخلية الجلفانية تحتاج إلى قطبين منفصلين: أحدهما تحدث عنده الأكسدة والآخر يحدث عنده الاختزال.","يُفصل محلولا نصفي الخلية، ولا يُسمح باختلاطهما؛ وتصلهما قنطرة ملحية.","","الخلية الجلفانية تتكون من نصفي خلية، في كل منهما قطب ومحلول خاص به."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.623Z"}'::jsonb),
('mcq', 7, 0, 'التفاعل تلقائي ويحدث فيه انتقال للإلكترونات، لكن نصفي الأكسدة والاختزال غير منفصلين، فتنتقل الإلكترونات مباشرة من ذرات Zn إلى أيونات Cu²⁺ دون أن تمر في سلك خارجي؛ ولذلك لا تتحول الطاقة الكيميائية إلى تيار كهربائي يمكن استعماله. أما الخلية الجلفانية ففيها يُفصل نصفا التفاعل ويوصلان بسلك وقنطرة ملحية.', '["","ترسب النحاس دليل على أن التفاعل حدث تلقائيًا، فليست المشكلة في التلقائية.","الإلكترونات تنتقل فعلًا من Zn إلى Cu²⁺، فهو تفاعل أكسدة واختزال.","الخلية الجلفانية لا تحتاج إلى مصدر خارجي؛ فهي نفسها مصدر للطاقة الكهربائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.623Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخلية الجلفانية: نوع من الخلايا الكهروكيميائية تحول الطاقة الكيميائية إلى طاقة كهربائية بواسطة تفاعل أكسدة واختزال تلقائي. وتسمى أيضًا الخلايا الفولتية، نسبة إلى العالم الإيطالي أليساندرو فولتا (1745–1827م) الذي نُسب إليه اختراعها عام 1800م.', '["نوع من الخلايا الكهروكيميائية","تحول الطاقة الكيميائية إلى كهربائية","بتفاعل أكسدة واختزال تلقائي","الاسم الآخر: الخلايا الفولتية نسبة إلى فولتا"]'::jsonb, '[]'::jsonb, '[{"element":"تحول الطاقة الكيميائية إلى كهربائية","marks":1},{"element":"تفاعل أكسدة واختزال تلقائي","marks":1},{"element":"الاسم الآخر: الخلايا الفولتية","marks":1},{"element":"سبب التسمية: نسبة إلى فولتا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل مع الاسم الآخر وسببه"},{"level":"3 درجات","description":"تعريف كامل مع الاسم دون السبب، أو العكس"},{"level":"درجتان","description":"تعريف ناقص (إغفال التلقائية أو اتجاه تحول الطاقة) مع الاسم"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["إغفال كلمة «تلقائي» في التعريف","عكس اتجاه تحول الطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.623Z"}'::jsonb),
('essay', 2, null::int, null, null, '1) خلية كهروكيميائية: لأنها جهاز يستعمل تفاعل أكسدة واختزال لإنتاج طاقة كهربائية. 2) تفاعل أكسدة واختزال: يتأكسد الخارصين Zn → Zn²⁺ + 2e⁻، وتُختزل أيونات النحاس Cu²⁺ + 2e⁻ → Cu. 3) التفاعل تلقائي: يحدث بمجرد توصيل السلك والقنطرة دون مصدر خارجي للطاقة. 4) تحول الطاقة الكيميائية إلى كهربائية: الإلكترونات المنتقلة من Zn إلى Cu عبر السلك تُكوّن تيارًا كهربائيًا يضيء المصباح، وتكمل الأيونات في القنطرة الملحية الدائرة.', '["خلية كهروكيميائية","نصفا الأكسدة والاختزال","التلقائية","تحول الطاقة الكيميائية إلى كهربائية عبر تدفق الإلكترونات في السلك"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أنها خلية كهروكيميائية","marks":1},{"element":"كتابة نصفي التفاعل أو تحديد المتأكسد والمختزل","marks":1},{"element":"بيان التلقائية","marks":1},{"element":"بيان تحول الطاقة (الإلكترونات في السلك تضيء المصباح)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ربط صحيح لجميع أجزاء التعريف بالخلية"},{"level":"3 درجات","description":"ثلاثة أجزاء صحيحة"},{"level":"درجتان","description":"جزآن صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن الإلكترونات تمر في القنطرة الملحية","عدّ النحاس هو الذي يتأكسد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.623Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخلية الكهروكيميائية جهاز يستعمل تفاعل الأكسدة والاختزال لإنتاج طاقة كهربائية، أو يستعمل الطاقة الكهربائية لإحداث تفاعل كيميائي. أما الخلية الجلفانية فنوع من الخلايا الكهروكيميائية يحول الطاقة الكيميائية إلى كهربائية بتفاعل أكسدة واختزال تلقائي. فكل خلية جلفانية تحقق تعريف الخلية الكهروكيميائية (إنتاج طاقة كهربائية من تفاعل أكسدة واختزال)، لكن الخلية الكهروكيميائية التي تستعمل الطاقة الكهربائية لإحداث تفاعل كيميائي ليست جلفانية؛ لأن تحول الطاقة فيها معكوس وتفاعلها لا يحدث تلقائيًا.', '["تعريف الخلية الكهروكيميائية بشقيه","تعريف الخلية الجلفانية","الجلفانية حالة خاصة (إنتاج الكهرباء من تفاعل تلقائي)","الخلية التي تستعمل الكهرباء لإحداث تفاعل ليست جلفانية"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الخلية الكهروكيميائية بشقيه","marks":1},{"element":"تعريف الخلية الجلفانية","marks":1},{"element":"تفسير «كل جلفانية كهروكيميائية» ومثال للنوع الآخر","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريفان صحيحان مع تفسير منطقي للعلاقة"},{"level":"درجتان","description":"تعريفان صحيحان دون تفسير العلاقة، أو تفسير صحيح مع تعريف ناقص"},{"level":"درجة واحدة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عدّ المصطلحين مترادفين","حصر الخلية الكهروكيميائية في إنتاج الكهرباء فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.623Z"}'::jsonb)
