insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'في رمز الخلية مثل Zn | Zn²⁺(1M) || Cu²⁺(1M) | Cu يفصل الخط الواحد بين مادتي نصف الخلية، ويفصل الخطان العموديان بين نصف تفاعل الأكسدة ونصف تفاعل الاختزال، ويمثلان القنطرة الملحية.', '["السلك لا يُمثَّل في رمز الخلية بخطين عموديين؛ فالخطان يفصلان بين نصفي الخلية.","الحد بين القطب ومحلوله داخل نصف الخلية يُمثَّل بخط عمودي واحد (|).","مقياس الجهد لا يظهر في رمز الخلية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.624Z"}'::jsonb),
('mcq', 2, 1, 'عند كتابة رمز الخلية يُكتب أولًا نصف تفاعل الأكسدة (الأنود) باستعمال رمز المادة المتفاعلة ثم الناتجة، ثم يُكتب نصف تفاعل الاختزال على اليمين؛ فالذي يُكتب يسارًا نصف خلية الأنود الذي تحدث فيه الأكسدة.', '["نصف تفاعل الاختزال (الكاثود) يُكتب على اليمين بعد الخطين العموديين.","","نصف الخلية ذو جهد الاختزال الأعلى هو الكاثود، ويُكتب على اليمين.","قطب الهيدروجين يُكتب يسارًا إن كان أنودًا ويمينًا إن كان كاثودًا، كما في Zn | Zn²⁺ || H⁺ | H₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.624Z"}'::jsonb),
('mcq', 3, 2, 'يتأكسد Fe إلى Fe²⁺ (الأنود، يسارًا: Fe | Fe²⁺)، وتُختزل Cu²⁺ إلى Cu (الكاثود، يمينًا: Cu²⁺ | Cu)، ويفصل بينهما خطان عموديان؛ فالرمز: Fe | Fe²⁺(1M) || Cu²⁺(1M) | Cu.', '["عُكس الترتيب: Cu²⁺ هي التي تُختزل، فنصف خلية النحاس يُكتب يمينًا لا يسارًا.","كُتبت المادة الناتجة قبل المتفاعلة في كل نصف؛ والقاعدة كتابة المتفاعل ثم الناتج.","","خُلط نصفا الخلية؛ فكل نصف يضم مادتي الزوج نفسه (Fe وFe²⁺ معًا، وCu²⁺ وCu معًا)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T11:36:22.624Z"}'::jsonb),
('mcq', 4, 0, 'يتأكسد Mg (Mg → Mg²⁺) فيُكتب يسارًا: Mg | Mg²⁺، وتُختزل Ag⁺ (Ag⁺ → Ag) فتُكتب يمينًا: Ag⁺ | Ag، دون المعاملات؛ فالرمز Mg | Mg²⁺(1M) || Ag⁺(1M) | Ag.', '["","وُضع نصف خلية الفضة يسارًا مع أنها تُختزل؛ ونصف الاختزال يُكتب يمينًا.","كُتب نصف الكاثود بالناتج قبل المتفاعل؛ والصحيح Ag⁺ | Ag (المتفاعل ثم الناتج).","المعاملات من موازنة المعادلة لا تُكتب في رمز الخلية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.625Z"}'::jsonb),
('mcq', 5, 3, 'من الرمز: نصف الأكسدة Ni → Ni²⁺ + 2e⁻، ونصف الاختزال Ag⁺ + e⁻ → Ag. نضرب نصف الاختزال في 2 لتتساوى الإلكترونات ثم نجمع: Ni + 2Ag⁺ → Ni²⁺ + 2Ag.', '["هذا التفاعل العكسي؛ فالرمز يبين أن Ni (يسارًا) يتأكسد وأن Ag⁺ (يمينًا) تُختزل.","المعادلة غير موزونة إلكترونيًا؛ فـNi يفقد إلكترونين وكل Ag⁺ تكتسب إلكترونًا واحدًا، فيلزم 2Ag⁺.","وُضع المعامل في الجهة الخطأ؛ فالإلكترونات المفقودة (4) لا تساوي المكتسبة (1).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.625Z"}'::jsonb),
('mcq', 6, 1, 'الخارصين يتأكسد (Zn → Zn²⁺) فيُكتب يسارًا بالمتفاعل ثم الناتج، وأيونات الهيدروجين تُختزل (2H⁺ → H₂) فتُكتب يمينًا؛ فالرمز Zn | Zn²⁺(1M) || H⁺(1M) | H₂.', '["هذا يجعل الهيدروجين يتأكسد والخارصين يُختزل، وهو عكس ما يحدث في الخلية.","","نصف الكاثود مكتوب بالناتج قبل المتفاعل؛ فالمتفاعل H⁺ يُكتب أولًا ثم الناتج H₂.","نصف الأنود مكتوب بالناتج قبل المتفاعل؛ والصحيح Zn | Zn²⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.625Z"}'::jsonb),
('mcq', 7, 0, 'في التفاعل يتأكسد Cu (الأنود) وتُختزل Ag⁺ (الكاثود)، فيجب أن يُكتب نصف الأكسدة يسارًا: Cu | Cu²⁺(1M) || Ag⁺(1M) | Ag. والطالب وضع نصف الاختزال يسارًا ونصف الأكسدة يمينًا.', '["","المعاملات لا تُكتب في رمز الخلية، فإغفالها ليس خطأ.","الخطان العموديان هما الصحيح بين نصفي الخلية؛ فهما يمثلان القنطرة الملحية.","قطب الهيدروجين ليس جزءًا من هذه الخلية، فلا يُكتب في رمزها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.625Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نصف الأكسدة (الأنود): Zn → Zn²⁺ + 2e⁻، ونصف الاختزال (الكاثود): Pb²⁺ + 2e⁻ → Pb. الرمز: Zn | Zn²⁺(1M) || Pb²⁺(1M) | Pb؛ نصف خلية الأنود Zn | Zn²⁺ يسارًا، ونصف خلية الكاثود Pb²⁺ | Pb يمينًا، والخطان العموديان يمثلان القنطرة الملحية.', '["تحديد الأنود (Zn) والكاثود (Pb)","Zn | Zn²⁺ يسارًا","Pb²⁺ | Pb يمينًا","|| بين النصفين"]'::jsonb, '["حدد المادة التي تتأكسد (Zn) والتي تُختزل (Pb²⁺).","اكتب نصف الأكسدة يسارًا: المتفاعل ثم الناتج Zn | Zn²⁺(1M).","ضع الخطين العموديين ||.","اكتب نصف الاختزال يمينًا: Pb²⁺(1M) | Pb."]'::jsonb, '[{"element":"تحديد الأنود والكاثود","marks":1},{"element":"كتابة نصف الأنود صحيحًا يسارًا","marks":1},{"element":"كتابة نصف الكاثود صحيحًا يمينًا","marks":1},{"element":"استعمال || بين النصفين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رمز صحيح كامل مع تحديد الأنود والكاثود"},{"level":"3 درجات","description":"رمز صحيح دون تحديد الأنود والكاثود، أو خطأ في ترتيب مادتي أحد النصفين"},{"level":"درجتان","description":"تحديد صحيح للأنود والكاثود مع رمز معكوس"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عكس ترتيب نصفي الخلية","كتابة الناتج قبل المتفاعل في نصف الخلية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T11:36:22.625Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نصف خلية النيكل جهد اختزالها أعلى (−0.257 V > −1.662 V) فهي الكاثود، والألومنيوم هو الأنود. (ب) الأكسدة: Al → Al³⁺ + 3e⁻ (×2)، الاختزال: Ni²⁺ + 2e⁻ → Ni (×3)؛ والتفاعل الكلي: 2Al(s) + 3Ni²⁺(aq) → 2Al³⁺(aq) + 3Ni(s). (ج) الرمز: Al | Al³⁺(1M) || Ni²⁺(1M) | Ni.', '["Ni كاثود وAl أنود","موازنة الإلكترونات (6e⁻)","2Al + 3Ni²⁺ → 2Al³⁺ + 3Ni","Al | Al³⁺(1M) || Ni²⁺(1M) | Ni"]'::jsonb, '["قارن جهدي الاختزال: −0.257 V أعلى من −1.662 V، فالنيكل يُختزل (كاثود) والألومنيوم يتأكسد (أنود).","اعكس نصف تفاعل الألومنيوم: Al → Al³⁺ + 3e⁻.","اضرب نصف الألومنيوم في 2 ونصف النيكل في 3 ليصبح عدد الإلكترونات 6.","اجمع: 2Al + 3Ni²⁺ → 2Al³⁺ + 3Ni.","اكتب الرمز: الأنود يسارًا Al | Al³⁺(1M) ثم || ثم Ni²⁺(1M) | Ni."]'::jsonb, '[{"element":"تحديد الأنود والكاثود مع التعليل","marks":1},{"element":"عكس نصف تفاعل الأكسدة","marks":1},{"element":"موازنة الإلكترونات","marks":1},{"element":"التفاعل الكلي الموزون","marks":1},{"element":"رمز الخلية صحيحًا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"4 درجات","description":"خطأ في الموازنة مع رمز صحيح"},{"level":"2–3 درجات","description":"تحديد صحيح للأنود والكاثود ورمز صحيح دون تفاعل كلي موزون"},{"level":"درجة واحدة","description":"تحديد الأنود والكاثود فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عدّ الألومنيوم كاثودًا لأن القيمة المطلقة لجهده أكبر","كتابة المعاملين 2 و3 في رمز الخلية","جمع نصفي التفاعل دون موازنة الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.625Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الأكسدة: Cd(s) → Cd²⁺(aq) + 2e⁻، الاختزال: Ag⁺(aq) + e⁻ → Ag(s). (ب) Cd(s) + 2Ag⁺(aq) → Cd²⁺(aq) + 2Ag(s). (ج) الأنود قطب الكادميوم Cd (يسار الرمز)، والكاثود قطب الفضة Ag (يمين الرمز). (د) تتدفق الإلكترونات في السلك من قطب الكادميوم (الأنود) إلى قطب الفضة (الكاثود).', '["نصف الأكسدة لـCd","نصف الاختزال لـAg⁺","التفاعل الكلي بمعامل 2 لـAg","Cd أنود وAg كاثود","الإلكترونات من Cd إلى Ag"]'::jsonb, '["الجزء الأيسر من الرمز (Cd | Cd²⁺) نصف الأكسدة: Cd → Cd²⁺ + 2e⁻.","الجزء الأيمن (Ag⁺ | Ag) نصف الاختزال: Ag⁺ + e⁻ → Ag.","اضرب نصف الاختزال في 2 واجمع: Cd + 2Ag⁺ → Cd²⁺ + 2Ag.","الأنود حيث الأكسدة (Cd)، والكاثود حيث الاختزال (Ag)، والإلكترونات من الأنود إلى الكاثود."]'::jsonb, '[{"element":"نصفا التفاعل صحيحان","marks":1},{"element":"التفاعل الكلي موزون","marks":1},{"element":"تحديد الأنود والكاثود","marks":1},{"element":"اتجاه الإلكترونات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3 درجات","description":"خطأ في جزء واحد (غالبًا الموازنة)"},{"level":"درجتان","description":"جزآن صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["قراءة الرمز معكوسًا فيُعد الفضة أنودًا","إغفال المعامل 2 أمام Ag⁺ وAg","جعل اتجاه الإلكترونات من الكاثود إلى الأنود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.626Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
