('mcq', 1, 'ما القنطرة الملحية في الخلية الجلفانية؟', null, '["ممر لتدفق الأيونات من نصف خلية إلى الآخر","ممر لتدفق الإلكترونات بين القطبين","سلك فلزي يصل بين القطبين","غشاء يسمح بخلط محلولي نصفي الخلية"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 135 — القنطرة الملحية'),
('mcq', 2, 'ماذا يحتوي أنبوب القنطرة الملحية؟', null, '["ماء مقطرًا نقيًا لا يحتوي على أيونات","مسحوق فلز النحاس الموصل للإلكترونات","محلولًا إلكتروليتيًا لملح مثل KCl محفوظًا في جل هلامي","محلول سكر مذابًا في الماء داخل جل"]'::jsonb, 'تذكر', 'تعرف', 'سهل', 'الكتاب ص 135 — القنطرة الملحية'),
('mcq', 3, 'في خلية الخارصين–النحاس، ماذا يحدث لو لم تُستعمل القنطرة الملحية مع بقاء السلك موصولًا؟', null, '["تتراكم الإلكترونات داخل محلولي الكأسين فيزداد جهد الخلية","تتراكم أيونات Zn²⁺ الموجبة حول الأنود وأيونات SO₄²⁻ السالبة حول الكاثود فيتوقف التفاعل","يختلط المحلولان فيزداد التيار المار في السلك","يستمر التفاعل لكن تنعكس جهة تدفق الإلكترونات في السلك"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 135 — القنطرة الملحية'),
('mcq', 4, 'في خلية الخارصين–النحاس العاملة، كيف تتحرك الأيونات خلال القنطرة الملحية؟', null, '["الأيونات الموجبة نحو نصف خلية الخارصين، والسالبة نحو نصف خلية النحاس","الأيونات الموجبة والسالبة كلتاهما نحو نصف خلية الخارصين","لا تتحرك أيونات، بل تنتقل الإلكترونات عبر القنطرة نحو النحاس","الأيونات السالبة نحو نصف خلية الخارصين، والموجبة نحو نصف خلية النحاس"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 135 — القنطرة الملحية'),
('mcq', 5, 'لماذا يجب أن تحتوي القنطرة الملحية على محلول إلكتروليتي وليس على ماء مقطر؟', null, '["لأن الماء المقطر يتفاعل مع القطبين ويوقف عملية الأكسدة","لأن المحلول الإلكتروليتي ينقل الإلكترونات من الأنود إلى الكاثود","لأن الماء المقطر لا يوفر أيونات كافية تتحرك لتعادل الشحنات وتكمل الدائرة","لأن المحلول الإلكتروليتي يرفع جهد الاختزال القياسي للكاثود"]'::jsonb, 'تطبيق', 'تعليل', 'متوسط', 'الكتاب ص 135 — القنطرة الملحية'),
('mcq', 6, 'لماذا يُحفظ محلول القنطرة الملحية داخل الأنبوب بجل هلامي أو بغطاء خاص؟', null, '["ليمنع حركة الأيونات تمامًا بين الكأسين","ليسمح بحركة الأيونات مع منع اختلاط محلولي الكأسين","ليسهّل خلط محلولي الكأسين في أثناء التشغيل","ليعزل الإلكترونات ويمنعها من الوصول إلى الكاثود"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 135 — القنطرة الملحية'),
('mcq', 7, 'خلية جلفانية رمزها Cu | Cu²⁺(1M) || Ag⁺(1M) | Ag، وقنطرتها الملحية تحتوي على محلول KNO₃. في أثناء عمل الخلية، كيف تتحرك أيونات القنطرة؟', null, '["تتجه أيونات K⁺ نحو نصف خلية النحاس، وأيونات NO₃⁻ نحو نصف خلية الفضة","تتجه أيونات Cu²⁺ عبر القنطرة إلى نصف خلية الفضة لتُختزل هناك","تتجه أيونات K⁺ وNO₃⁻ كلتاهما نحو نصف خلية الفضة","تتجه أيونات NO₃⁻ نحو نصف خلية النحاس، وأيونات K⁺ نحو نصف خلية الفضة"]'::jsonb, 'تحليل', 'تطبيق في موقف جديد', 'صعب', 'الكتاب ص 135 — القنطرة الملحية'),
('essay', 1, 'اذكر وظيفتين للقنطرة الملحية في الخلية الجلفانية، ووضّح كل وظيفة.', null, null, 'فهم', 'توضيح وظائف', 'متوسط', 'الكتاب ص 135 — القنطرة الملحية'),
('essay', 2, 'خلية خارصين–نحاس تعمل ويضيء مصباحها، ثم رُفعت القنطرة الملحية منها مع بقاء السلك موصولًا. ماذا يحدث للمصباح؟ فسّر إجابتك بما يحدث للأيونات عند كل قطب.', null, null, 'تحليل', 'تنبؤ وتفسير', 'صعب', 'الكتاب ص 135 — القنطرة الملحية'),
('essay', 3, 'قال طالب: «تنقل القنطرة الملحية الإلكترونات من الأنود إلى الكاثود، ولذلك لا تعمل الخلية بدونها». قوّم هذه العبارة، وصحّح ما فيها من خطأ، مبينًا مسار كل من الإلكترونات والأيونات في الخلية.', null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 135 — القنطرة الملحية')
