from (values
('mcq', 1, 0, 'القنطرة الملحية ممر لتدفق الأيونات من جهة إلى أخرى، أي من نصف خلية إلى الآخر.', '["","الإلكترونات تتدفق في السلك الخارجي، أما القنطرة فممر للأيونات.","السلك الفلزي يصل القطبين وينقل الإلكترونات، والقنطرة أنبوب فيه محلول إلكتروليتي.","القنطرة تسمح بحركة الأيونات دون أن يختلط المحلولان في الكأسين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.626Z"}'::jsonb),
('mcq', 2, 2, 'تتكون القنطرة الملحية من أنبوب يحتوي على محلول موصل للتيار الكهربائي (محلول إلكتروليتي) لملح ذائب في الماء مثل KCl، ويُحفظ داخل الأنبوب بجل هلامي أو غطاء يسمح للأيونات بالحركة.', '["الماء المقطر لا يحتوي على أيونات كافية تتحرك لتكمل الدائرة، والقنطرة تحتاج إلى محلول موصل.","القنطرة لا تنقل الإلكترونات، بل الأيونات، فلا تحتوي على فلز.","","السكر مادة غير إلكتروليتية لا تتأين، فلا توفر أيونات متحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.626Z"}'::jsonb),
('mcq', 3, 1, 'تتراكم أيونات الخارصين الموجبة حول قطب الخارصين خلال تأكسده، وتتراكم أيونات الكبريتات السالبة حول قطب النحاس خلال اختزاله، وهذا التراكم يوقف أي استمرار للتفاعل؛ وحل المشكلة هو القنطرة الملحية.', '["الإلكترونات لا تدخل المحاليل، وتراكم الشحنات يوقف التفاعل ولا يزيد الجهد.","","غياب القنطرة لا يؤدي إلى اختلاط المحلولين، بل إلى توقف التيار.","اتجاه التفاعل لا ينعكس؛ وإنما يتوقف بسبب تراكم الأيونات حول القطبين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.626Z"}'::jsonb),
('mcq', 4, 3, 'عند الأنود (Zn) تتكون أيونات Zn²⁺ موجبة، فتتجه إليه الأيونات السالبة من القنطرة، وعند الكاثود (Cu) تُستهلك أيونات Cu²⁺ فتبقى أيونات SO₄²⁻ زائدة، فتتجه إليه الأيونات الموجبة؛ فالسالبة نحو الخارصين والموجبة نحو النحاس.', '["هذا عكس الصحيح؛ فنصف خلية الخارصين تزداد فيها الأيونات الموجبة Zn²⁺ فتحتاج إلى أيونات سالبة لمعادلتها.","لو اتجهت الأيونات كلها إلى جهة واحدة لما عُودلت الشحنات في نصف خلية النحاس.","القنطرة ممر للأيونات لا للإلكترونات؛ فالإلكترونات تنتقل في السلك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.626Z"}'::jsonb),
('mcq', 5, 2, 'وظيفة القنطرة نقل الأيونات بين نصفي الخلية لمنع تراكم الشحنات وإكمال الدائرة، وهذا يتطلب محلولًا موصلًا للتيار (إلكتروليتيًا) فيه أيونات متحركة مثل K⁺ وCl⁻؛ والماء المقطر لا يوفر أيونات كافية.', '["الماء المقطر لا يلامس القطبين داخل القنطرة، والمشكلة أنه لا يوصل التيار لقلة أيوناته.","الإلكتروليت ينقل الأيونات لا الإلكترونات؛ فالإلكترونات تمر في السلك.","","جهد الاختزال القياسي خاصية لنصف الخلية، ولا تغيره القنطرة الملحية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.627Z"}'::jsonb),
('mcq', 6, 1, 'يُحفظ محلول القنطرة بجل هلامي أو أي غطاء يسمح للأيونات بالحركة خلاله، على ألا يختلط المحلولان في الكأسين.', '["لو مُنعت حركة الأيونات لفقدت القنطرة وظيفتها وتوقف التفاعل.","","المطلوب ألا يختلط المحلولان؛ فاختلاطهما يُفقد الخلية فصل نصفي التفاعل.","الإلكترونات تصل إلى الكاثود عبر السلك، ولا علاقة للجل بذلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.627Z"}'::jsonb),
('mcq', 7, 3, 'Cu يتأكسد فهو الأنود، فتتراكم عنده أيونات Cu²⁺ الموجبة وتتجه إليه أيونات NO₃⁻ السالبة؛ وAg⁺ تُختزل عند الكاثود فتقل الأيونات الموجبة هناك وتتجه إليه أيونات K⁺؛ فالإجابة: NO₃⁻ نحو نصف خلية النحاس وK⁺ نحو نصف خلية الفضة.', '["هذا عكس الصحيح؛ فنصف خلية النحاس (الأنود) تتكون فيه أيونات Cu²⁺ موجبة فتحتاج إلى أيونات سالبة.","القنطرة تنقل أيونات محلولها (K⁺ وNO₃⁻) لتعادل الشحنات، والذي يُختزل عند الكاثود أيونات Ag⁺.","اتجاه الأيونات يتحدد بشحنتها؛ فالسالبة نحو الأنود والموجبة نحو الكاثود.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.627Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) تمنع تراكم الشحنات حول القطبين: فهي ممر تتحرك فيه الأيونات السالبة نحو الأنود لتعادل الأيونات الموجبة المتكونة فيه (مثل Zn²⁺)، وتتحرك الأيونات الموجبة نحو الكاثود لتعادل الأيونات السالبة الزائدة (مثل SO₄²⁻)، فيستمر التفاعل. 2) تكمل الدائرة الكهربائية: فالإلكترونات تتدفق في السلك والأيونات تتدفق في القنطرة، فيكتمل مسار التيار دون أن يختلط محلولا نصفي الخلية.', '["منع تراكم الأيونات/الشحنات واستمرار التفاعل","حركة الأيونات السالبة نحو الأنود والموجبة نحو الكاثود","إكمال الدائرة الكهربائية","دون اختلاط المحلولين"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر وظيفة منع تراكم الأيونات","marks":1},{"element":"توضيحها بحركة الأيونات","marks":1},{"element":"ذكر وظيفة إكمال الدائرة","marks":1},{"element":"توضيحها (أيونات في القنطرة وإلكترونات في السلك دون اختلاط المحلولين)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وظيفتان مع توضيح صحيح لكل منهما"},{"level":"3 درجات","description":"وظيفتان مع توضيح إحداهما فقط"},{"level":"درجتان","description":"وظيفتان دون توضيح، أو وظيفة واحدة موضحة"},{"level":"درجة واحدة","description":"ذكر وظيفة واحدة دون توضيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن القنطرة تنقل الإلكترونات","الاكتفاء بعبارة «توصل المحلولين» دون بيان أثرها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.627Z"}'::jsonb),
('essay', 2, null::int, null, null, 'ينطفئ المصباح ويتوقف التفاعل. التفسير: عند الأنود يستمر تأكسد Zn لحظيًا فتتراكم أيونات Zn²⁺ الموجبة في المحلول حوله، وعند الكاثود تُختزل أيونات Cu²⁺ فتبقى أيونات SO₄²⁻ السالبة زائدة حوله. وهذا التراكم للشحنات يوقف استمرار التفاعل؛ لأنه لم يعد هناك ممر للأيونات يعادل الشحنات ويكمل الدائرة، فيتوقف تدفق الإلكترونات في السلك.', '["ينطفئ المصباح/يتوقف التيار","تراكم Zn²⁺ حول الأنود","تراكم SO₄²⁻ حول الكاثود","الدائرة غير مكتملة فيتوقف تدفق الإلكترونات"]'::jsonb, '[]'::jsonb, '[{"element":"التنبؤ بانطفاء المصباح","marks":1},{"element":"تراكم Zn²⁺ حول الأنود","marks":1},{"element":"تراكم SO₄²⁻ حول الكاثود","marks":1},{"element":"الربط بعدم اكتمال الدائرة وتوقف الإلكترونات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تنبؤ صحيح مع تفسير كامل عند القطبين"},{"level":"3 درجات","description":"تنبؤ صحيح مع تفسير عند قطب واحد والربط بالدائرة"},{"level":"درجتان","description":"تنبؤ صحيح مع تفسير ناقص"},{"level":"درجة واحدة","description":"تنبؤ صحيح دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن المصباح يستمر في الإضاءة لأن السلك موجود","القول إن الإلكترونات تتراكم في المحاليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.627Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة جزئيًا: صحيح أن الخلية لا تعمل بدون القنطرة، لكن القنطرة لا تنقل الإلكترونات. التصحيح: تتدفق الإلكترونات في السلك الخارجي من الأنود إلى الكاثود، أما القنطرة الملحية فممر لتدفق الأيونات: تتحرك الأيونات السالبة نحو نصف خلية الأنود، والموجبة نحو نصف خلية الكاثود، فتمنع تراكم الشحنات وتكمل الدائرة. ولذلك لا تعمل الخلية بدونها لأن الأيونات تتراكم فيتوقف التفاعل، لا لأن الإلكترونات تحتاج إليها.', '["الحكم: الخطأ في نقل الإلكترونات","الإلكترونات في السلك من الأنود إلى الكاثود","الأيونات في القنطرة: السالبة نحو الأنود والموجبة نحو الكاثود","السبب الصحيح لضرورة القنطرة: منع تراكم الأيونات وإكمال الدائرة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ في العبارة","marks":1},{"element":"مسار الإلكترونات الصحيح","marks":1},{"element":"مسار الأيونات الصحيح","marks":1},{"element":"التعليل الصحيح لضرورة القنطرة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم وتصحيح كاملان"},{"level":"3 درجات","description":"حكم صحيح مع مسارين صحيحين دون تعليل"},{"level":"درجتان","description":"حكم صحيح مع مسار واحد"},{"level":"درجة واحدة","description":"حكم صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["قبول العبارة كما هي","عكس اتجاه حركة الأيونات في القنطرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.627Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
