insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C4-L1-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'مِمَّ يتكون قطب الهيدروجين القياسي؟', null, '["صفيحة نحاس في محلول Cu²⁺ تركيزه 1M عند 25°C و1 atm","صفيحة بلاتين في محلول H⁺ تركيزه 1M يُضخ فيه غاز H₂ عند 1 atm و25°C","صفيحة بلاتين في ماء مقطر يُضخ فيه غاز O₂ عند 1 atm","صفيحة خارصين في محلول HCl تركيزه 0.1M عند 0°C"]'::jsonb, 'تذكر', 'تعرف', 'سهل', 'الكتاب ص 137 — قطب الهيدروجين القياسي'),
('mcq', 2, 'ما قيمة جهد الاختزال القياسي المعيَّنة لقطب الهيدروجين القياسي؟', null, '["0.000 V","+1.000 V","+0.342 V","−0.762 V"]'::jsonb, 'تذكر', 'تعرف', 'سهل', 'الكتاب ص 137 — قطب الهيدروجين القياسي'),
('mcq', 3, 'لماذا لا يمكن تحديد جهد اختزال قطب ما بصورة مباشرة؟', null, '["لأن أجهزة قياس الجهد لا تقيس إلا شدة التيار المار في السلك","لأن جهد الاختزال يتغير بتغير كتلة القطب المستعمل","لأن نصف تفاعل الاختزال يحدث بسرعة كبيرة يصعب قياسها","لأن نصف تفاعل الاختزال لا يحدث إلا مقترنًا بنصف تفاعل أكسدة"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 137–138 — حساب فرق الجهد وجهود نصف الخلية'),
('mcq', 4, 'لماذا قرر الكيميائيون قياس جهود اختزال جميع الأقطاب مقابل قطب واحد هو قطب الهيدروجين القياسي؟', null, '["لأن قطب الهيدروجين هو القطب الوحيد الذي يحدث عنده اختزال","لأن جهد قطب الهيدروجين الحقيقي يساوي صفرًا تمامًا في الطبيعة","لتُقاس الجهود كلها نسبة إلى مرجع واحد فتصبح قابلة للمقارنة والترتيب في جدول","لأن غاز الهيدروجين لا يتفاعل مع أي نصف خلية آخر"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 137–138 — حساب فرق الجهد وجهود نصف الخلية'),
('mcq', 5, 'ما الدور الذي يؤديه قطب الهيدروجين القياسي عند توصيله بنصف خلية أخرى؟', null, '["يعمل كاثودًا أو أنودًا بحسب نصف الخلية الموصول به","يعمل أنودًا دائمًا مهما كان نصف الخلية الموصول به","يعمل كاثودًا دائمًا مهما كان نصف الخلية الموصول به","لا يحدث عنده تفاعل، وإنما يقيس فرق الجهد فقط"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 137 — قطب الهيدروجين القياسي'),
('mcq', 6, 'عند توصيل نصف خلية النحاس بقطب الهيدروجين القياسي قرأ مقياس الجهد 0.342 V، فعُدّت هذه القراءة جهد الاختزال القياسي للنحاس. ما الذي يسوّغ ذلك؟', null, '["أن قطب الهيدروجين لا يشارك بأي تفاعل عند توصيله بنصف خلية النحاس","أن مقياس الجهد يحذف جهد قطب الهيدروجين تلقائيًا من القراءة","أن جهد نصف خلية النحاس يتضاعف عند توصيله بقطب الهيدروجين","أن جهد قطب الهيدروجين مُعيَّن بصفر، فيُنسب فرق الجهد المقيس كله إلى نصف خلية النحاس"]'::jsonb, 'تطبيق', 'تعليل', 'متوسط', 'الكتاب ص 139 — تحديد جهود اختزال الخلية الكهروكيميائية'),
('mcq', 7, 'لماذا يلزم أن يعمل قطب الهيدروجين المرجعي وأنصاف الخلايا المقيسة تحت الظروف القياسية (1M، 1 atm، 25°C)؟', null, '["لأن قطب البلاتين لا يوصل التيار الكهربائي إلا عند 25°C","لأن الجهد يتغير بتغير التركيز والضغط ودرجة الحرارة، فتلزم ظروف موحدة للمقارنة","لأن غاز الهيدروجين لا يذوب في الماء إلا عند ضغط 1 atm","لأن الظروف القياسية تجعل جهود الأقطاب جميعها صفرًا"]'::jsonb, 'تحليل', 'تعليل', 'صعب', 'الكتاب ص 138 — جهود نصف الخلية'),
('essay', 1, 'فسّر سبب استعمال قطب الهيدروجين القياسي مرجعًا لقياس جهود الأقطاب غير المعلومة، ثم صف مكوناته والظروف التي يعمل عندها وقيمة جهده.', null, null, 'فهم', 'تفسير ووصف', 'متوسط', 'الكتاب ص 137 — قطب الهيدروجين القياسي'),
('essay', 2, 'قال طالب: «بما أن جهد قطب الهيدروجين القياسي يساوي صفرًا، فلا يحدث عنده أي تفاعل كيميائي». قوّم هذه العبارة، مستعينًا بنصفي التفاعل الممكنين عند هذا القطب، وبمثالين.', null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 137 — قطب الهيدروجين القياسي'),
('essay', 3, 'افترض أن العلماء اختاروا نصف خلية النحاس Cu²⁺|Cu قطبًا مرجعيًا بدلًا من قطب الهيدروجين، وعيّنوا جهده صفرًا. علمًا بأن E°(Cu²⁺|Cu) = +0.342 V وE°(Zn²⁺|Zn) = −0.762 V على مقياس الهيدروجين: (أ) احسب جهد الخارصين على المقياس الجديد. (ب) احسب جهد خلية الخارصين–النحاس على المقياسين. (ج) ماذا تستنتج عن سبب كفاية مرجع واحد متفق عليه؟', null, null, 'تحليل', 'تحليل افتراضي', 'صعب', 'الكتاب ص 137–138 — حساب فرق الجهد وجهود نصف الخلية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C4-L1-O05') and x.type = v.type and x.number = v.number);
