select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يتكون قطب الهيدروجين القياسي من شريحة صغيرة من البلاتين مغموسة في محلول حمض الهيدروكلوريك HCl الذي يحتوي على أيونات هيدروجين بتركيز 1M، ويُضخ غاز H₂ في المحلول عند ضغط 1 atm ودرجة حرارة 25°C.', '["هذا وصف نصف خلية النحاس القياسية، لا قطب الهيدروجين.","","قطب الهيدروجين يحتوي على محلول حمضي فيه H⁺ بتركيز 1M ويُضخ فيه غاز H₂ لا O₂.","القطب من البلاتين لا الخارصين، والتركيز 1M، ودرجة الحرارة 25°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.628Z"}'::jsonb),
('mcq', 2, 0, 'عُيِّن جهد الاختزال القياسي لقطب الهيدروجين بالقيمة 0.000 V: 2H⁺(aq) + 2e⁻ ⇌ H₂(g)، E° = 0.000 V.', '["","لم تُعيَّن له القيمة 1 V؛ فقد اختير صفرًا لتُقاس الجهود الأخرى نسبة إليه.","هذه قيمة جهد الاختزال القياسي لنصف خلية النحاس Cu²⁺|Cu.","هذه قيمة جهد الاختزال القياسي لنصف خلية الخارصين Zn²⁺|Zn."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.628Z"}'::jsonb),
('mcq', 3, 3, 'لا يمكن تحديد جهد اختزال القطب بصورة مباشرة؛ لأن نصف تفاعل الاختزال لا بد أن يقترن بنصف تفاعل الأكسدة، والجهد الناتج يساوي فرق الجهد لنصفي التفاعل.', '["مقياس الجهد (الفولتميتر) يقيس فرق الجهد، والمشكلة أن الاختزال لا يحدث منفردًا.","جهد الاختزال لا يعتمد على كتلة القطب، بل على طبيعة نصف التفاعل وظروفه.","السرعة ليست السبب؛ فالسبب أن نصف الاختزال لا بد أن يقترن بنصف أكسدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.628Z"}'::jsonb),
('mcq', 4, 2, 'بما أن جهد القطب لا يُقاس منفردًا، اتفق الكيميائيون على قياس جهود الأقطاب جميعها مقابل قطب مرجعي واحد عُيِّن جهده 0.000 V، فتصبح الجهود منسوبة إلى مرجع واحد يمكن مقارنتها وترتيبها.', '["قطب الهيدروجين قد يحدث عنده اختزال أو أكسدة، وغيره من الأقطاب يحدث عندها اختزال أيضًا.","القيمة صفر قيمة مُعيَّنة باتفاق العلماء، وليست قيمة مطلقة مقيسة.","","قطب الهيدروجين يتفاعل فعلًا (يتأكسد H₂ أو يُختزل H⁺) بحسب نصف الخلية الموصول به."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.629Z"}'::jsonb),
('mcq', 5, 0, 'قطب الهيدروجين القياسي يعمل بوصفه نصف تفاعل اختزال أو نصف تفاعل أكسدة اعتمادًا على نصف الخلية الموصول به؛ فهو كاثود مع الخارصين وأنود مع النحاس.', '["","عند توصيله بنصف خلية الخارصين يُختزل H⁺ عنده فيعمل كاثودًا، فليس أنودًا دائمًا.","عند توصيله بنصف خلية النحاس يتأكسد H₂ عنده فيعمل أنودًا، فليس كاثودًا دائمًا.","يحدث عنده تفاعل فعلي: 2H⁺ + 2e⁻ → H₂ أو H₂ → 2H⁺ + 2e⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.629Z"}'::jsonb),
('mcq', 6, 3, 'فرق الجهد المقيس = E°(النحاس) − E°(الهيدروجين)، وبما أن E°(الهيدروجين) = 0.000 V فإن القراءة تساوي جهد اختزال النحاس نفسه: +0.342 V. فاختيار قطب مرجعي جهده صفر يجعل القراءة جهد القطب الآخر مباشرة.', '["قطب الهيدروجين يشارك فعلًا؛ إذ يتأكسد H₂ عنده إلى H⁺.","مقياس الجهد يقيس فرق الجهد بين القطبين فقط، ولا يحذف شيئًا.","جهد نصف الخلية لا يتغير بنوع القطب الموصول به.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.629Z"}'::jsonb),
('mcq', 7, 1, 'قيم الجهد تعتمد على التركيز والضغط ودرجة الحرارة، فلكي تكون الجهود المقيسة مقابل قطب مرجعي واحد قابلة للمقارنة يجب أن تُقاس جميعها تحت ظروف موحدة هي: تركيز 1M، وضغط 1 atm، و25°C؛ ويشير الصفر في E° إلى ذلك.', '["البلاتين موصل جيد في درجات الحرارة المعتادة كلها؛ والسبب توحيد ظروف القياس.","","الضغط جزء من الظروف الموحدة للقياس، وليس شرطًا لإذابة الغاز.","تحت الظروف القياسية تختلف جهود الأقطاب (مثل +0.342 V للنحاس و−0.762 V للخارصين)، وقطب الهيدروجين وحده جهده صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.629Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السبب: لا يمكن قياس جهد اختزال قطب منفردًا؛ لأن نصف تفاعل الاختزال لا بد أن يقترن بنصف تفاعل أكسدة، فقرر الكيميائيون قياس جهود الأقطاب جميعها مقابل قطب مرجعي واحد عُيِّن جهده صفرًا، فيصبح فرق الجهد المقيس هو جهد القطب المجهول، وتصبح الجهود قابلة للمقارنة. المكونات: شريحة صغيرة من البلاتين مغموسة في محلول HCl يحتوي على أيونات H⁺ بتركيز 1M، ويُضخ فيه غاز H₂ عند ضغط 1 atm ودرجة حرارة 25°C. وجهده 0.000 V، ويعمل كاثودًا أو أنودًا بحسب نصف الخلية الموصول به.', '["تعذر القياس المباشر لاقتران الاختزال بالأكسدة","مرجع واحد يجعل الجهود قابلة للمقارنة","البلاتين وH⁺ بتركيز 1M","H₂ عند 1 atm و25°C","E° = 0.000 V"]'::jsonb, '[]'::jsonb, '[{"element":"تعذر القياس المباشر وسببه","marks":1},{"element":"فائدة المرجع الواحد (المقارنة/نسبة الجهد إلى القطب الآخر)","marks":1},{"element":"المكونات: بلاتين ومحلول H⁺ 1M وغاز H₂","marks":1},{"element":"الظروف: 1 atm و25°C","marks":1},{"element":"القيمة 0.000 V","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير ووصف كاملان"},{"level":"4 درجات","description":"نقص عنصر واحد"},{"level":"3 درجات","description":"تفسير صحيح مع وصف ناقص"},{"level":"1–2 درجة","description":"عناصر متفرقة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن جهد الهيدروجين صفر في الطبيعة لا بالاتفاق","نسيان البلاتين أو تركيز 1M"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.629Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العبارة خاطئة. القيمة صفر قيمة مُعيَّنة اتفاقًا ليُقاس عليها غيره، ولا تعني أن القطب لا يتفاعل. يحدث عنده أحد تفاعلين بحسب نصف الخلية الموصول به: اختزال 2H⁺(aq) + 2e⁻ → H₂(g)، أو أكسدة H₂(g) → 2H⁺(aq) + 2e⁻. مثال 1: عند توصيله بنصف خلية النحاس تتدفق الإلكترونات نحو النحاس، فيتأكسد H₂ عند قطب الهيدروجين (أنود). مثال 2: عند توصيله بنصف خلية الخارصين تتدفق الإلكترونات من الخارصين نحو قطب الهيدروجين، فتُختزل H⁺ عنده (كاثود). ويقبل أي مثال صحيح آخر.', '["الحكم بخطأ العبارة","الصفر قيمة اتفاقية مرجعية","نصف تفاعل الاختزال","نصف تفاعل الأكسدة","مثال النحاس (أنود) ومثال الخارصين (كاثود)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم وتعليله بأن الصفر قيمة مرجعية اتفاقية","marks":1},{"element":"كتابة نصفي التفاعل","marks":1},{"element":"مثال النحاس وما يحدث عند قطب الهيدروجين","marks":1},{"element":"مثال الخارصين وما يحدث عند قطب الهيدروجين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح معلل مع نصفي التفاعل والمثالين"},{"level":"3 درجات","description":"نقص مثال واحد"},{"level":"درجتان","description":"حكم صحيح مع نصفي التفاعل دون أمثلة"},{"level":"درجة واحدة","description":"حكم صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["قبول العبارة","كتابة نصف تفاعل واحد فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.629Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) على المقياس الجديد يُطرح جهد النحاس من كل القيم: −0.762 − (+0.342) = −1.104 V. (ب) على مقياس الهيدروجين: E°cell = +0.342 − (−0.762) = +1.104 V. وعلى المقياس الجديد: E°cell = 0.000 − (−1.104) = +1.104 V. (ج) جهد الخلية (الفرق بين قطبين) لا يتغير بتغير المرجع؛ فاختيار المرجع اتفاق، والمهم أن تُقاس الأقطاب كلها مقابل مرجع واحد تحت الظروف نفسها. واختير قطب الهيدروجين القياسي مرجعًا وعُيِّن جهده 0.000 V.', '["جهد Zn الجديد = −1.104 V","E°cell = +1.104 V على المقياسين","الاستنتاج: الفروق لا تتغير والمرجع اتفاقي"]'::jsonb, '["على المقياس الجديد: E°(Zn) = −0.762 − 0.342 = −1.104 V.","على مقياس الهيدروجين: E°cell = 0.342 − (−0.762) = +1.104 V.","على المقياس الجديد: E°cell = 0.000 − (−1.104) = +1.104 V.","الاستنتاج: فرق الجهد ثابت مهما كان المرجع."]'::jsonb, '[{"element":"حساب جهد الخارصين على المقياس الجديد","marks":1},{"element":"حساب E°cell على مقياس الهيدروجين","marks":1},{"element":"حساب E°cell على المقياس الجديد","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة واستنتاج سليم"},{"level":"3 درجات","description":"حسابات صحيحة دون استنتاج، أو خطأ حسابي واحد مع استنتاج سليم"},{"level":"درجتان","description":"حسابان صحيحان"},{"level":"درجة واحدة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["إضافة 0.342 بدل طرحها عند نقل المرجع","الظن أن جهد الخلية يتغير بتغير المرجع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.630Z"}'::jsonb)
