from (values
('mcq', 1, 2, 'جهد الخلية القياسي يساوي جهد الاختزال القياسي لنصف خلية الاختزال (الكاثود) مطروحًا منه جهد الاختزال القياسي لنصف خلية التأكسد (الأنود): E°cell = E°cathode − E°anode.', '["هذا عكس ترتيب الطرح؛ فهو يعطي القيمة بإشارة معكوسة.","جهد الخلية فرق بين جهدي الاختزال لا مجموعهما.","","لا يُحسب جهد الخلية بضرب الجهدين؛ بل بطرح جهد الأنود من جهد الكاثود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.630Z"}'::jsonb),
('mcq', 2, 3, 'الفضة جهد اختزالها أعلى فهي الكاثود، والماغنسيوم الأنود. E°cell = E°cathode − E°anode = +0.7996 − (−2.372) = +3.172 V.', '["طُرح جهد الكاثود من جهد الأنود (عكس العلاقة)، فظهرت الإشارة سالبة.","جُمع الجهدان (0.7996 + (−2.372)) بدل طرح جهد الأنود من جهد الكاثود.","ضُرب جهد الفضة في 2 بسبب موازنة الإلكترونات، وجهد الاختزال لا يتغير بتغير المعاملات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.631Z"}'::jsonb),
('mcq', 3, 1, 'النحاس جهد اختزاله أعلى فيُختزل (كاثود)، ويتأكسد الألومنيوم: Al → Al³⁺ + 3e⁻. نضرب نصف الأكسدة في 2 ونصف الاختزال (Cu²⁺ + 2e⁻ → Cu) في 3 لتصبح الإلكترونات 6، ثم نجمع: 2Al + 3Cu²⁺ → 2Al³⁺ + 3Cu.', '["هذا التفاعل العكسي؛ فالنحاس جهد اختزاله أعلى فهو الذي يُختزل لا الذي يتأكسد.","","المعادلة غير موزونة إلكترونيًا: Al يفقد 3 إلكترونات وCu²⁺ تكتسب 2.","المعاملان معكوسان: تفقد ذرات Al الثلاث 9 إلكترونات وتكتسب أيونات Cu²⁺ الأيونين 4 فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.631Z"}'::jsonb),
('mcq', 4, 0, 'من الرمز: الأنود Ni (يسارًا) والكاثود Ag (يمينًا). E°cell = +0.7996 − (−0.257) = +1.057 V.', '["","جُمع الجهدان (0.7996 + (−0.257)) بدل الطرح.","عُكست العلاقة فطُرح جهد الكاثود من جهد الأنود.","ضُرب جهد الفضة في 2 تبعًا لمعامل Ag⁺ في المعادلة، وجهد الاختزال لا يُضرب في المعاملات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.631Z"}'::jsonb),
('mcq', 5, 1, 'أكبر جهد خلية ينتج من أعلى جهد اختزال كاثودًا (Ag: +0.7996 V) وأدنى جهد اختزال أنودًا (Zn: −0.762 V): E°cell = +0.7996 − (−0.762) = +1.562 V، وهو أكبر من بقية الأزواج.', '["جهد هذه الخلية +0.7996 − (−0.447) = +1.247 V، وهو أقل من خلية الخارصين–الفضة.","","جهد هذه الخلية +0.342 − (−0.762) = +1.104 V، وهو أقل من خلية الخارصين–الفضة.","جهد هذه الخلية +0.342 − (−0.447) = +0.789 V، وهو الأقل بين الأزواج المذكورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.631Z"}'::jsonb),
('mcq', 6, 0, 'في الرسم: Zn أنود (−0.762 V) وCu كاثود (+0.342 V)، فيُرسم سهم الإلكترونات في السلك الخارجي من Zn إلى Cu، وتتحرك الأيونات السالبة في القنطرة نحو نصف خلية الأنود (Zn) والموجبة نحو نصف خلية الكاثود (Cu).', '["","الإلكترونات تنتقل من الأنود (Zn) إلى الكاثود (Cu)، لا العكس.","الإلكترونات تنتقل في السلك فقط، والأيونات في القنطرة فقط.","الأيونات السالبة تتجه نحو نصف خلية الأنود (Zn)، والموجبة نحو الكاثود (Cu)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.631Z"}'::jsonb),
('mcq', 7, 2, 'مساواة الإلكترونات المفقودة والمكتسبة لا تؤثر في E°. الكاثود Fe (جهد أعلى) والأنود Mn: E°cell = −0.037 − (−1.185) = +1.148 V.', '["هذه إجابة الطالب، وفيها ضرب جهود الاختزال في المعاملات، وموازنة الإلكترونات لا تؤثر في E°.","طُرح جهد الكاثود من جهد الأنود، فانعكست الإشارة.","","جُمع الجهدان (−0.037 + (−1.185)) بدل الطرح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.632Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النحاس جهد اختزاله أعلى فهو الكاثود (يحدث عنده الاختزال)، والخارصين الأنود (تحدث عنده الأكسدة). E°cell = E°cathode − E°anode = +0.342 V − (−0.762 V) = +1.104 V.', '["Cu كاثود وZn أنود","العلاقة E°cell = E°cathode − E°anode","التعويض الصحيح","+1.104 V"]'::jsonb, '["قارن: +0.342 V > −0.762 V، فالنحاس كاثود والخارصين أنود.","اكتب العلاقة: E°cell = E°cathode − E°anode.","عوّض: E°cell = +0.342 − (−0.762).","E°cell = +1.104 V."]'::jsonb, '[{"element":"تحديد الكاثود والأنود","marks":1},{"element":"كتابة العلاقة","marks":1},{"element":"التعويض","marks":1},{"element":"الناتج بالوحدة والإشارة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح"},{"level":"3 درجات","description":"خطأ في الوحدة أو الإشارة فقط"},{"level":"درجتان","description":"تحديد صحيح وعلاقة صحيحة مع خطأ في التعويض"},{"level":"درجة واحدة","description":"تحديد الكاثود والأنود فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["طرح −0.762 على أنها +0.762 مرتين (عكس إشارة الأنود ثم طرحها)","جمع الجهدين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.632Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الكوبلت جهد اختزاله أعلى (−0.28 V > −0.744 V)، فالاختزال: Co²⁺ + 2e⁻ → Co (كاثود)، والأكسدة: Cr → Cr³⁺ + 3e⁻ (أنود). (ب) نضرب نصف الكروم في 2 ونصف الكوبلت في 3: 2Cr(s) + 3Co²⁺(aq) → 2Cr³⁺(aq) + 3Co(s). (ج) E°cell = −0.28 − (−0.744) = +0.46 V. (د) Cr | Cr³⁺(1M) || Co²⁺(1M) | Co.', '["Co كاثود وCr أنود","2Cr + 3Co²⁺ → 2Cr³⁺ + 3Co","E°cell = +0.46 V","Cr | Cr³⁺(1M) || Co²⁺(1M) | Co"]'::jsonb, '["قارن الجهدين: −0.28 V أعلى، فالكوبلت يُختزل.","اعكس نصف تفاعل الكروم: Cr → Cr³⁺ + 3e⁻.","وازن الإلكترونات (6e⁻): ×2 للكروم و×3 للكوبلت، ثم اجمع.","E°cell = E°cathode − E°anode = −0.28 − (−0.744) = +0.464 ≈ +0.46 V (منزلتان عشريتان كأقل القيم دقة).","اكتب الرمز: الأنود يسارًا والكاثود يمينًا."]'::jsonb, '[{"element":"تحديد نصفي الاختزال والأكسدة","marks":1},{"element":"موازنة الإلكترونات","marks":1},{"element":"التفاعل الكلي","marks":1},{"element":"العلاقة والتعويض","marks":1},{"element":"الناتج +0.46 V","marks":1},{"element":"رمز الخلية","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"جميع الأجزاء صحيحة"},{"level":"4–5 درجات","description":"خطأ في جزء واحد أو اثنين (غالبًا الموازنة أو الرمز)"},{"level":"2–3 درجات","description":"تحديد صحيح وحساب صحيح للجهد دون تفاعل موزون ورمز"},{"level":"درجة واحدة","description":"تحديد نصفي التفاعل فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["ضرب E° في المعاملين 2 و3","عدّ الكروم كاثودًا لأن قيمته المطلقة أكبر","كتابة المعاملات في رمز الخلية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.633Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الرسم: كأس فيها قطب Cd مغموس في محلول Cd²⁺ تركيزه 1M، وكأس فيها قطب Cu مغموس في محلول Cu²⁺ تركيزه 1M، ويصل القطبين سلك عليه مقياس جهد، ويصل المحلولين قنطرة ملحية (مثل KCl في جل). Cu جهد اختزاله أعلى فهو الكاثود، وCd الأنود. يُرسم سهم الإلكترونات في السلك من Cd إلى Cu، وتتحرك الأيونات السالبة في القنطرة نحو نصف خلية Cd، والموجبة نحو نصف خلية Cu. نصفا التفاعل: Cd → Cd²⁺ + 2e⁻ (أنود)، Cu²⁺ + 2e⁻ → Cu (كاثود)؛ والتفاعل الكلي: Cd(s) + Cu²⁺(aq) → Cd²⁺(aq) + Cu(s). E°cell = +0.342 − (−0.4030) = +0.745 V. الرمز: Cd | Cd²⁺(1M) || Cu²⁺(1M) | Cu.', '["كأسان بقطبين ومحلولين 1M","Cd أنود وCu كاثود","الإلكترونات في السلك من Cd إلى Cu","السالبة نحو Cd والموجبة نحو Cu في القنطرة","Cd + Cu²⁺ → Cd²⁺ + Cu","E°cell = +0.745 V","Cd | Cd²⁺(1M) || Cu²⁺(1M) | Cu"]'::jsonb, '["ارسم الكأسين بقطبيهما ومحلوليهما، وصلهما بسلك ومقياس جهد وقنطرة ملحية.","حدد الكاثود (الجهد الأعلى: Cu) والأنود (Cd).","ارسم سهم الإلكترونات في السلك من الأنود إلى الكاثود.","حدد حركة الأيونات في القنطرة: السالبة نحو الأنود والموجبة نحو الكاثود.","اكتب التفاعل الكلي واحسب E°cell = 0.342 − (−0.4030) = +0.745 V، ثم اكتب الرمز."]'::jsonb, '[{"element":"مكونات المخطط (كأسان، قطبان، سلك، قنطرة)","marks":1},{"element":"تحديد الأنود والكاثود","marks":1},{"element":"اتجاه الإلكترونات","marks":1},{"element":"اتجاه الأيونات في القنطرة","marks":1},{"element":"التفاعل الكلي","marks":1},{"element":"حساب E°cell","marks":1},{"element":"رمز الخلية","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"مخطط ووصف وحسابات كاملة صحيحة"},{"level":"5–6 درجات","description":"نقص أو خطأ في عنصر أو عنصرين"},{"level":"3–4 درجات","description":"مخطط صحيح مع تحديد الأقطاب والإلكترونات دون حسابات صحيحة"},{"level":"1–2 درجة","description":"عناصر متفرقة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["رسم الإلكترونات وهي تمر في القنطرة الملحية","عكس اتجاه الأيونات في القنطرة","عدّ الأنود القطب الموجب في الخلية الجلفانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة ن