('mcq', 4, 'هل يحدث التفاعل الآتي تلقائيًا تحت الظروف القياسية؟
Pb(s) + Zn²⁺(aq) → Pb²⁺(aq) + Zn(s)
علمًا بأن: E°(Pb²⁺|Pb) = −0.1262 V، وE°(Zn²⁺|Zn) = −0.7618 V.', null, '["E°cell = +0.636 V، والتفاعل تلقائي","E°cell = −0.636 V، والتفاعل غير تلقائي","E°cell = −0.888 V، والتفاعل غير تلقائي","E°cell = +0.888 V، والتفاعل تلقائي"]'::jsonb, 'تطبيق', 'حساب وتنبؤ', 'متوسط', 'الكتاب ص 142 — استعمال جهود الاختزال القياسية'),
('mcq', 5, 'أيّ التفاعلات الآتية يحدث تلقائيًا تحت الظروف القياسية؟ استعن بالجدول.', '{"headers":["نصف التفاعل","E° (V)"],"rows":[["Ag⁺ + e⁻ → Ag","+0.7996"],["Cu²⁺ + 2e⁻ → Cu","+0.3419"],["Ni²⁺ + 2e⁻ → Ni","−0.257"],["Zn²⁺ + 2e⁻ → Zn","−0.7618"]]}'::jsonb, '["Cu + Zn²⁺ → Cu²⁺ + Zn","2Ag + Ni²⁺ → 2Ag⁺ + Ni","Ni + Zn²⁺ → Ni²⁺ + Zn","Cu + 2Ag⁺ → Cu²⁺ + 2Ag"]'::jsonb, 'تحليل', 'حساب ومقارنة', 'صعب', 'الكتاب ص 142 — استعمال جهود الاختزال القياسية'),
('mcq', 6, 'ما تفاعل الأكسدة والاختزال التلقائي الذي يحدث بين الماغنسيوم والنيكل، وما جهده القياسي؟ علمًا بأن: E°(Mg²⁺|Mg) = −2.372 V، وE°(Ni²⁺|Ni) = −0.257 V.', null, '["Ni + Mg²⁺ → Ni²⁺ + Mg، وE° = +2.115 V","Mg + Ni²⁺ → Mg²⁺ + Ni، وE° = +2.629 V","Mg + Ni²⁺ → Mg²⁺ + Ni، وE° = +2.115 V","Ni + Mg²⁺ → Ni²⁺ + Mg، وE° = −2.115 V"]'::jsonb, 'تطبيق', 'تحديد وحساب', 'متوسط', 'الكتاب ص 143 — استراتيجية حل المسألة'),
('mcq', 7, 'حُسب جهد الخلية لتفاعل أكسدة واختزال كما هو مكتوب فكان E°cell = −0.46 V. أيّ الاستنتاجات الآتية صحيح؟', null, '["التفاعل تلقائي؛ لأن القيمة المطلقة للجهد كبيرة نسبيًا","التفاعل غير تلقائي كما كُتب، وعكسه تلقائي وجهده +0.46 V","التفاعل غير تلقائي في الاتجاهين كليهما","التفاعل تلقائي لكنه بطيء جدًا بسبب الإشارة السالبة"]'::jsonb, 'تقويم', 'استنتاج', 'صعب', 'الكتاب ص 142 — استعمال جهود الاختزال القياسية'),
('essay', 1, 'حدّد بالحساب هل يحدث التفاعل الآتي تلقائيًا تحت الظروف القياسية:
Mg(s) + Pb²⁺(aq) → Pb(s) + Mg²⁺(aq)
علمًا بأن: E°(Pb²⁺|Pb) = −0.1262 V، وE°(Mg²⁺|Mg) = −2.372 V.', null, null, 'تطبيق', 'حساب وتنبؤ', 'سهل', 'الكتاب ص 142 — استعمال جهود الاختزال القياسية'),
('essay', 2, 'استعمل جهود الاختزال القياسية: E°(Cl₂|Cl⁻) = +1.358 V، وE°(Br₂|Br⁻) = +1.066 V للتنبؤ بتلقائية كل من التفاعلين تحت الظروف القياسية، مع الحساب:
(أ) Cl₂(g) + 2Br⁻(aq) → 2Cl⁻(aq) + Br₂(l)
(ب) Br₂(l) + 2Cl⁻(aq) → 2Br⁻(aq) + Cl₂(g)', null, null, 'تطبيق', 'حساب وتنبؤ', 'متوسط', 'الكتاب ص 142 — استعمال جهود الاختزال القياسية'),
('essay', 3, 'أراد عامل مختبر حفظ محلول نترات الفضة AgNO₃ في وعاء من النحاس، وحفظ محلول كبريتات النحاس CuSO₄ في وعاء من الفضة. حلّل كلا الاقتراحين باستعمال جهود الاختزال القياسية: E°(Ag⁺|Ag) = +0.7996 V، وE°(Cu²⁺|Cu) = +0.3419 V، وبيّن أيهما مناسب.', null, null, 'تحليل', 'تحليل موقف حياتي', 'صعب', 'الكتاب ص 142 — استعمال جهود الاختزال القياسية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C4-L1-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'إذا كان الجهد المحسوب موجبًا فالتفاعل تلقائي، أما إذا كانت القيمة سالبة فالتفاعل غير تلقائي.', '["الجهد السالب يدل على أن التفاعل غير تلقائي كما هو مكتوب.","القاعدة تربط التلقائية بالجهد الموجب، والصفر لا يدل على تلقائية التفاعل.","التنبؤ بالتلقائية من إشارة الجهد أحد الاستعمالين المهمين لجهود الاختزال.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.633Z"}'::jsonb),
('mcq', 2, 2, 'تتدفق الإلكترونات في الخلية الجلفانية من نصف الخلية ذات جهد الاختزال القياسي الأقل إلى نصف الخلية ذات جهد الاختزال القياسي الأكبر، لتعطي جهدًا موجبًا للخلية.', '["هذا عكس الصحيح؛ فالأكبر جهد اختزال هو الذي يكتسب الإلكترونات (الكاثود).","اتجاه الإلكترونات يحدده جهد الاختزال، لا كتلة القطب.","","تحت الظروف القياسية التراكيز متساوية (1M)، والاتجاه يحدده جهد الاختزال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.634Z"}'::jsonb),
('mcq', 3, 0, 'في التفاعل المكتوب: Cu²⁺ تُختزل (كاثود) وSn يتأكسد (أنود). E°cell = +0.3419 − (−0.1375) = +0.479 V، وبما أن الجهد موجب فالتفاعل تلقائي.', '["","طُرح جهد النحاس من جهد القصدير (عكس العلاقة)؛ والنحاس هو الذي يُختزل في التفاعل المكتوب.","جُمع الجهدان (0.3419 + (−0.1375)) بدل الطرح.","جُمع الجهدان ثم عُكست الإشارة؛ والصحيح طرح جهد الأنود من جهد الكاثود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.634Z"}'::jsonb),
('mcq', 4, 1, 'في التفاعل المكتوب تُختزل Zn²⁺ (كاثود) ويتأكسد Pb (أنود): E°cell = −0.7618 − (−0.1262) = −0.636 V. الجهد سالب، فالتفاعل غير تلقائي كما هو مكتوب.', '["عُدّ الرصاص كاثودًا، مع أن التفاعل المكتوب يجعل Zn²⁺ هي التي تُختزل.","","جُمع الجهدان (−0.7618 + (−0.1262)) بدل الطرح، وإن كان الحكم صحيحًا فالقيمة خاطئة.","جُمع الجهدان ثم عُكست الإشارة؛ والقيمة والحكم كلاهما خطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (65%)"}],"at":"2026-10-17T11:36:22.634Z"}'::jsonb),
('mcq', 5, 3, 'في التفاعل Cu + 2Ag⁺: الكاثود Ag والأنود Cu، E°cell = +0.7996 − 0.3419 = +0.458 V؛ موجب فالتفاعل تلقائي. أما البقية فجهودها سالبة لأن المادة التي تُختزل فيها جهد اختزالها أقل من المادة التي تتأكسد.', '["E°cell = −0.7618 − 0.3419 = −1.104 V؛ سالب فالتفاعل غير تلقائي.","E°cell = −0.257 − 0.7996 = −1.057 V؛ سالب فالتفاعل غير تلقائي.","E°cell = −0.7618 − (−0.257) = −0.505 V؛ سالب فالتفاعل غير تلقائي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.634Z"}'::jsonb),
('mcq', 6, 2, 'النيكل جهد اختزاله أعلى فيُختزل Ni²⁺، ويتأكسد Mg: Mg + Ni²⁺ → Mg²⁺ + Ni، وE°cell = −0.257 − (−2.372) = +2.115 V، وهو موجب فالتفاعل تلقائي.', '["القيمة صحيحة لكن التفاعل معكوس؛ فهذا التفاعل جهده −2.115 V وغير تلقائي.","جُمعت القيمتان المطلقتان (2.372 + 0.257) بدل الطرح.","","الحساب صحيح لهذا الاتجاه، لكن الجهد سالب فالتفاعل غير تلقائي، والمطلوب التفاعل التلقائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.635Z"}'::jsonb),
('mcq', 7, 1, 'الجهد السالب يعني أن التفاعل غير تلقائي كما هو مكتوب، وفي حالة عكس تفاعل غير تلقائي يكون له جهد خلية موجب، أي إن التفاعل العكسي تلقائي وجهده +0.46 V.', '["التلقائية تحددها الإشارة لا القيمة المطلقة؛ والإشارة هنا سالبة.","","عكس التفاعل غير التلقائي يكون له جهد موجب، فهو تلقائي.","الإشارة السالبة تعني أن التفاعل غير تلقائي، ولا تدل على السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.635Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في التفاعل المكتوب: Pb²⁺ تُختزل (كاثود)، وMg يتأكسد (أنود). E°cell = E°cathode − E°anode = −0.1262 − (−2.372) = +2.246 V. الجهد موجب، فالتفاعل تلقائي.', '["تحديد الكاثود والأنود من التفاعل المكتوب","التعويض في العلاقة","E°cell = +2.246 V","الحكم: تلقائي"]'::jsonb, '["اكتب نصفي التفاعل: Pb²⁺ + 2e⁻ → Pb (اختزال)، Mg → Mg²⁺ + 2e⁻ (أكسدة).","E°cell = E°cathode − E°anode = −0.1262 − (−2.372).","E°cell = +2.246 V.","الجهد موجب، إذن التفاعل تلقائي."]'::jsonb, '[{"element":"تحديد نصفي التفاعل من المعادلة","marks":1},{"element":"التعويض الصحيح","marks":1},{"element":"الناتج","marks":1},{"element":"الحكم بالتلقائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل وحكم صحيحان"},{"level":"3 درجات","description":"حساب صحيح دون حكم، أو حكم صحيح مع خطأ حسابي بسيط"},{"level":"درجتان","description":"تحديد صحيح وتعويض صحيح فقط"},{"level":"درجة واحدة","description":"تحديد نصفي التفاعل فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["تحديد الكاثود من الجدول بدل التفاعل المكتوب","الحكم من القيمة المطلقة لا من الإشارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (65%)"}],"at":"2026-10-17T11:36:22.635Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Cl₂ تُختزل (كاثود) وBr⁻ تتأكسد (أنود): E°cell = +1.358 − (+1.066) = +0.292 V؛ موجب، فالتفاعل تلقائي. (ب) Br₂ يُختزل وCl⁻ تتأكسد: E°cell = +1.066 − (+1.358) = −0.292 V؛ سالب، فالتفاعل غير تلقائي، وهو عكس التفاعل (أ).', '["(أ) +0.292 V تلقائي","(ب) −0.292 V غير تلقائي","الربط: التفاعل (ب) عكس (أ)"]'::jsonb, '["(أ) الكاثود Cl₂|Cl⁻ والأنود Br₂|Br⁻: E° = 1.358 − 1.066 = +0.292 V → تلقائي.","(ب) الكاثود Br₂|Br⁻ والأنود Cl₂|Cl⁻: E° = 1.066 − 1.358 = −0.292 V → غير تلقائي."]'::jsonb, '[{"element":"تحديد الكاثود والأنود في (أ)","marks":1},{"element":"حساب (أ) والحكم","marks":1},{"element":"تحديد الكاثود والأنود في (ب)","marks":1},{"element":"حساب (ب) والحكم","marks":1},{"element":"ملاحظة أن (ب) عكس (أ) وجهده بإشارة معاكسة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التفاعلان محسوبان ومحكوم عليهما بصورة صحيحة مع الربط"},{"level":"4 درجات","description":"التفاعلان صحيحان دون الربط"},{"level":"2–3 درجات","description":"تفاعل واحد صحيح كاملًا"},{"level":"درجة واحدة","description":"تحديد صحيح للكاثود والأنود فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["استعمال الجدول لتحديد الكاثود دائمًا بغض النظر عن التفاعل المكتوب، فيخرج التفاعلان تلقائيين","ضرب E° في المعامل 2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.635Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الاقتراح الأول (AgNO₃ في وعاء نحاس): التفاعل المحتمل Cu(s) + 2Ag⁺(aq) → Cu²⁺(aq) + 2Ag(s)، الكاثود Ag والأنود Cu: E°cell = +0.7996 − 0.3419 = +0.458 V؛ موجب، فالتفاعل تلقائي: يتآكل الوعاء (يتأكسد النحاس) وتترسب الفضة، فالاقتراح غير مناسب. الاقتراح الثاني (CuSO₄ في وعاء فضة): التفاعل المحتمل 2Ag(s) + Cu²⁺(aq) → 2Ag⁺(aq) + Cu(s)، الكاثود Cu والأنود Ag: E°cell = +0.3419 − 0.7996 = −0.458 V؛ سالب، فالتفاعل غير تلقائي، والوعاء لا يتفاعل، فالاقتراح مناسب.', '["تفاعل الاقتراح الأول وجهده +0.458 V","الحكم: تلقائي فالوعاء النحاسي يتآكل","تفاعل الاقتراح الثاني وجهده −0.458 V","الحكم: غير تلقائي فالوعاء الفضي مناسب"]'::jsonb, '["الاقتراح الأول: Cu + 2Ag⁺ → Cu²⁺ + 2Ag؛ E° = 0.7996 − 0.3419 = +0.458 V.","موجب ← تلقائي ← لا يصلح.","الاقتراح الثاني: 2Ag + Cu²⁺ → 2Ag⁺ + Cu؛ E° = 0.3419 − 0.7996 = −0.458 V.","سالب ← غير تلقائي ← يصلح."]'::jsonb, '[{"element":"كتابة التفاعل المحتمل في الاقتراح الأول","marks":1},{"element":"حساب جهده","marks":1},{"element":"الحكم على الاقتراح الأول","marks":1},{"element":"كتابة التفاعل المحتمل في الاقتراح الثاني","marks":1},{"element":"حساب جهده","marks":1},{"element":"الحكم على الاقتراح الثاني","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تحليل كامل صحيح للاقتراحين"},{"level":"4–5 درجات","description":"تحليل صحيح لاقتراح واحد كاملًا مع حكم صحيح على الآخر دون حساب كامل"},{"level":"2–3 درجات","description":"تحليل صحيح لاقتراح واحد"},{"level":"درجة واحدة","description":"حكم صحيح دون تبرير"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عدّ الفلز الأعلى جهدًا هو الذي يتأكسد","الحكم على الاقتراحين معًا بالتلقائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.636Z"}'::jsonb)
