('mcq', 4, 0, 'الكاثود (المهبط) هو القطب الذي يحدث عنده تفاعل الاختزال، وإليه تتدفق الإلكترونات من الأنود.', '["","هذا تعريف الأنود (المصعد).","كل من القطبين يحدث عنده نصف تفاعل: أكسدة عند الأنود واختزال عند الكاثود.","المحلول جزء من نصف الخلية، أما الكاثود فهو القطب نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.636Z"}'::jsonb),
('mcq', 5, 3, 'يحدث عند الخارصين تفاعل الأكسدة Zn → Zn²⁺ + 2e⁻، ولذلك فنصف خلية الخارصين هو الأنود وقطبه شريحة Zn؛ أما نصف خلية النحاس فهو الكاثود.', '["النحاس يحدث عنده اختزال Cu²⁺ إلى Cu، فهو الكاثود.","قطب نصف خلية الخارصين شريحة خارصين لا نحاس.","القنطرة ليست نصف خلية ولا قطبًا؛ هي ممر للأيونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.637Z"}'::jsonb),
('mcq', 6, 2, 'اكتساب أيون الفضة لإلكترون اختزال، والقطب الذي يحدث عنده الاختزال يسمى الكاثود (المهبط).', '["الاختزال يحدث عند الكاثود لا الأنود.","التفاعل المكتوب اكتساب إلكترونات (اختزال)، والأنود موقع الأكسدة.","","الكاثود موقع الاختزال، والتفاعل المكتوب اكتساب إلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.637Z"}'::jsonb),
('mcq', 7, 1, 'الخلية الكهروكيميائية جهاز كامل يتكون من نصفي خلية، وفي كل نصف قطب ومحلول أيونات، ويحدث في أحدهما نصف الأكسدة وفي الآخر نصف الاختزال.', '["العلاقة معكوسة؛ نصف الخلية جزء من الخلية.","","نصف الخلية وحده لا ينتج تيارًا؛ إذ لا بد من نصفين معًا.","في نصف الخلية يحدث نصف تفاعل واحد فقط (أكسدة أو اختزال)، أما الخلية فيحدث فيها التفاعلان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.637Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخلية الكهروكيميائية: جهاز يستعمل تفاعل الأكسدة والاختزال لإنتاج طاقة كهربائية، أو يستعمل الطاقة الكهربائية لإحداث تفاعل كيميائي. نصف الخلية: أحد جزأي الخلية، يحتوي على قطب ومحلول أيونات، ويحدث فيه نصف تفاعل أكسدة أو اختزال. الأنود (المصعد): القطب الذي يحدث عنده تفاعل الأكسدة. الكاثود (المهبط): القطب الذي يحدث عنده تفاعل الاختزال.', '["تعريف الخلية الكهروكيميائية","تعريف نصف الخلية","تعريف الأنود","تعريف الكاثود"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الخلية الكهروكيميائية","marks":1},{"element":"تعريف نصف الخلية","marks":1},{"element":"تعريف الأنود","marks":1},{"element":"تعريف الكاثود","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربعة تعريفات صحيحة"},{"level":"3 درجات","description":"ثلاثة تعريفات صحيحة"},{"level":"درجتان","description":"تعريفان صحيحان"},{"level":"درجة واحدة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عكس تعريفي الأنود والكاثود","تعريف الخلية الكهروكيميائية بإنتاج الكهرباء فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.638Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نصف خلية الخارصين: قطب Zn ومحلول يحتوي على أيونات Zn²⁺. نصف خلية النحاس: قطب Cu ومحلول يحتوي على أيونات Cu²⁺. (ب) الأنود: قطب الخارصين، ونصف التفاعل Zn → Zn²⁺ + 2e⁻. الكاثود: قطب النحاس، ونصف التفاعل Cu²⁺ + 2e⁻ → Cu. (ج) سُمي قطب الخارصين أنودًا لأنه القطب الذي تحدث عنده الأكسدة، وسُمي قطب النحاس كاثودًا لأنه القطب الذي يحدث عنده الاختزال.', '["نصفا الخلية وقطباهما ومحلولاهما","الأنود Zn ونصف الأكسدة","الكاثود Cu ونصف الاختزال","التعليل بموقع الأكسدة والاختزال"]'::jsonb, '[]'::jsonb, '[{"element":"نصفا الخلية بقطبيهما ومحلوليهما","marks":1},{"element":"الأنود ونصف تفاعله","marks":1},{"element":"الكاثود ونصف تفاعله","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3 درجات","description":"خطأ في جزء واحد"},{"level":"درجتان","description":"جزآن صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عدّ النحاس أنودًا لأنه ينتج الفلز","كتابة الإلكترونات في الجهة الخطأ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.638Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نصف الخلية (قطب ومحلول أيونات) يحدث فيه نصف تفاعل واحد فقط: إما أكسدة عند الأنود أو اختزال عند الكاثود. وتفاعل الأكسدة لا يحدث دون اختزال؛ لأن الإلكترونات التي تفقدها المادة المتأكسدة يجب أن تكتسبها مادة أخرى. لذلك لا بد من توصيل نصفي خلية: أحدهما أنود تتحرر عنده الإلكترونات، والآخر كاثود تُستهلك عنده، فتتدفق الإلكترونات من الأنود إلى الكاثود مكونة تيارًا كهربائيًا. ومن النصفين معًا تتكون الخلية الكهروكيميائية التي تستعمل تفاعل الأكسدة والاختزال لإنتاج الطاقة الكهربائية.', '["نصف الخلية يحدث فيه نصف تفاعل واحد","الأكسدة لا تحدث دون اختزال","الأنود يطلق الإلكترونات والكاثود يستقبلها","النصفان معًا يكونان الخلية الكهروكيميائية"]'::jsonb, '[]'::jsonb, '[{"element":"نصف الخلية فيه نصف تفاعل واحد","marks":1},{"element":"اقتران الأكسدة بالاختزال (تبادل الإلكترونات)","marks":1},{"element":"دور الأنود والكاثود في تدفق الإلكترونات","marks":1},{"element":"تكوّن الخلية الكهروكيميائية من نصفين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يستعمل المصطلحات الأربعة"},{"level":"3 درجات","description":"تفسير صحيح ينقصه مصطلح أو عنصر"},{"level":"درجتان","description":"تفسير جزئي"},{"level":"درجة واحدة","description":"فكرة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["الظن أن نصف الخلية يعمل منفردًا","الخلط بين الأنود والكاثود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.638Z"}'::jsonb)
