('mcq', 2, 1, 'تُدفع الإلكترونات المتكونة عند الأنود نحو الكاثود بالقوة الدافعة الكهربائية الناشئة عن فرق طاقة الوضع الكهربائية بين القطبين، ويعرف هذا الفرق بجهد الخلية.', '["الانتقال سببه فرق طاقة الوضع الكهربائية بين القطبين لا فرق الحرارة.","","الكتلة لا تتحكم في اتجاه تدفق الإلكترونات.","القنطرة ممر للأيونات ولا تنقل الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.638Z"}'::jsonb),
('mcq', 3, 2, 'جهد الخلية هو القوة الدافعة الكهربائية الناشئة عن فرق طاقة الوضع الكهربائية بين القطبين، وهو إشارة إلى كمية الطاقة المتوفرة لدفع الإلكترونات من الأنود إلى الكاثود.', '["هذه تعريف الشحنة المتدفقة، أما الجهد فهو فرق طاقة الوضع بين القطبين.","جهد الخلية لا يعبر عن كتلة الفلز المتأكسد.","","الجهد لا يقيس سرعة التفاعل، بل يشير إلى الطاقة المتوفرة لدفع الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.639Z"}'::jsonb),
('mcq', 4, 3, 'في التشبيه تتحرك الأفعوانية من القمة نحو القاع بسبب فرق طاقة الوضع الناتج عن اختلاف الارتفاع، وكذلك تتحرك الإلكترونات من الأنود إلى الكاثود بسبب فرق طاقة الوضع الكهربائية بين القطبين.', '["فرق الارتفاع يقابله فرق طاقة الوضع، لا كتلة الإلكترونات.","طول السلك لا يقابل فرق الارتفاع في التشبيه.","حجم المحلول لا يحدد جهد الخلية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-17T11:36:22.639Z"}'::jsonb),
('mcq', 5, 0, 'يتحدد فرق جهد الخلية بمقارنة مدى الفرق في قابلية مواد الأقطاب على اكتساب الإلكترونات؛ فكلما زاد الفرق بين القطبين زاد جهد الخلية.', '["","العلاقة طردية: زيادة الفرق في قابلية اكتساب الإلكترونات تزيد جهد الخلية.","جهد الخلية يتحدد بهذا الفرق، فيتغير بتغيره.","الجهد يصبح صفرًا عند انعدام الفرق بين القطبين، لا عند زيادته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.639Z"}'::jsonb),
('mcq', 6, 1, 'جهد الخلية مقياس لفرق طاقة الوضع الكهربائية بين القطبين؛ والجهد الأكبر (1.10 V) يدل على فرق أكبر ودفع أكبر للإلكترونات.', '["الجهد الأكبر يعني فرق طاقة وضع أكبر، وهو للخلية الأولى.","","وحدة القياس واحدة (V)، والفرق في القيمة يدل على فرق في طاقة الوضع.","اتجاه التدفق في كل خلية جلفانية من الأنود إلى الكاثود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.639Z"}'::jsonb),
('mcq', 7, 2, 'قوة الجاذبية تسحب الغواص نحو وضع منخفض من الطاقة، وأن الإلكترونات تتدفق في الخلية من الأنود إلى الكاثود لوجود فرق طاقة وضع كهربائية؛ فالحركة في الحالتين تلقائية من الطاقة الأعلى إلى الأدنى.', '["التحرك التلقائي يكون نحو طاقة وضع أقل لا أعلى.","طاقة وضع الإلكترونات الكهربائية تنخفض كذلك عند انتقالها من الأنود إلى الكاثود.","","حركة الغواص ناتجة عن الجاذبية الأرضية، وهي تشبيه لجهد الخلية فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.639Z"}'::jsonb),
('essay', 1, null::int, null, null, 'جهد الخلية هو القوة الدافعة الكهربائية الناشئة عن الفرق في طاقة الوضع الكهربائية بين القطبين، وهي التي تدفع الإلكترونات من الأنود إلى الكاثود. ووحدة قياسه الفولت (V).', '["فرق طاقة الوضع الكهربائية بين القطبين","يدفع الإلكترونات من الأنود إلى الكاثود","الوحدة: الفولت"]'::jsonb, '[]'::jsonb, '[{"element":"فرق طاقة الوضع الكهربائية بين القطبين","marks":1},{"element":"دفع الإلكترونات من الأنود إلى الكاثود","marks":1},{"element":"الوحدة: الفولت V","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف ووحدة صحيحان"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عكس اتجاه تدفق الإلكترونات","الخلط بين الفولت والأمبير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T11:36:22.639Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تقف الأفعوانية عند قمة المسار حيث طاقة وضعها عالية، ثم تهبط تلقائيًا نحو القاع حيث طاقة الوضع أقل بسبب فرق الارتفاع (الجاذبية). وبالمثل تتجمع الإلكترونات عند الأنود حيث طاقة وضعها الكهربائية أعلى، وتتحرك عبر السلك إلى الكاثود حيث طاقة الوضع أقل. فقمة المسار تقابل الأنود، وقاع المسار يقابل الكاثود، وفرق الارتفاع يقابل فرق طاقة الوضع الكهربائية بين القطبين وهو جهد الخلية. وكلما زاد فرق الارتفاع كان الدفع أكبر، وكلما زاد الفرق بين القطبين زاد جهد الخلية.', '["القمة تقابل الأنود","القاع يقابل الكاثود","فرق الارتفاع يقابل جهد الخلية","الحركة تلقائية نحو طاقة وضع أقل"]'::jsonb, '[]'::jsonb, '[{"element":"القمة = الأنود","marks":1},{"element":"القاع = الكاثود","marks":1},{"element":"فرق الارتفاع = فرق طاقة الوضع (جهد الخلية)","marks":1},{"element":"الحركة التلقائية وأثر زيادة الفرق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["جعل القمة تقابل الكاثود","عدّ فرق الارتفاع كتلة المادة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-17T11:36:22.640Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تتحدد طاقة الإلكترونات المتدفقة بفرق طاقة الوضع الكهربائية بين القطبين، وهو ناتج عن الفرق في قابلية مادتي القطبين لاكتساب الإلكترونات. في خلية Zn–Cu تكتسب أيونات النحاس عند الكاثود الإلكترونات بسهولة أكبر من الخارصين عند الأنود، فيوجد فرق في طاقة الوضع الكهربائية بين القطبين (جهد الخلية 1.104 V) فتُدفع الإلكترونات من الخارصين إلى النحاس تلقائيًا. أما في قطبي خارصين متماثلين فلا يوجد فرق في قابلية اكتساب الإلكترونات ولا فرق في طاقة الوضع، فيكون الجهد صفرًا ولا تتدفق الإلكترونات.', '["جهد الخلية ناتج عن فرق قابلية اكتساب الإلكترونات","فرق طاقة الوضع في Zn–Cu يدفع الإلكترونات","غياب الفرق في القطبين المتماثلين","الجهد صفر ولا تدفق"]'::jsonb, '[]'::jsonb, '[{"element":"ربط الجهد بالفرق في قابلية اكتساب الإلكترونات","marks":1},{"element":"تفسير تدفق التيار في Zn–Cu","marks":1},{"element":"تفسير عدم التدفق في القطبين المتماثلين","marks":1},{"element":"الاستنتاج: الجهد صفر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["الظن أن وجود قطبين كافٍ لتوليد التيار","عدم ربط الجهد بقابلية اكتساب الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.640Z"}'::jsonb)
