from (values
('mcq', 1, 0, 'جهد الاختزال هو مدى قابلية المادة لاكتساب الإلكترونات (الاختزال هو اكتساب الإلكترونات).', '["","هذا يقابل قابلية التأكسد، وجهد الاختزال يقيس اكتساب الإلكترونات.","هذا مفهوم الحرارة النوعية لا جهد الاختزال.","جهد الاختزال لا يتعلق بعدد إلكترونات التكافؤ، بل بقابلية اكتساب الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.640Z"}'::jsonb),
('mcq', 2, 1, 'الصفر فوق الرمز E° يشير اختصارًا إلى أن القياس تم تحت الظروف القياسية: تركيز 1M، ودرجة حرارة 25°C، وضغط 1 atm.', '["الصفر فوق الرمز لا يدل على درجة الحرارة 0°C، بل على الظروف القياسية (25°C).","","E° جهد اختزال، ولا يدل الصفر على غياب الماء.","الضغط القياسي 1 atm وليس صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.640Z"}'::jsonb),
('mcq', 3, 2, 'يجب أن يُقاس جهد القطب تحت الظروف القياسية، وهي غمس القطب في محلول أيوناته تركيزه 1M عند 25°C و1 atm.', '["القيم المذكورة (0.1M و0°C) غير قياسية؛ القياسية 1M و25°C.","درجة الحرارة 100°C والضغط 2 atm غير قياسيين.","","القطب يُغمس في محلول أيوناته بتركيز 1M لا في الماء المقطر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-10-17T11:36:22.641Z"}'::jsonb),
('mcq', 4, 0, 'جهد الاختزال القياسي: E°(Ag⁺|Ag) = +0.7996 V وE°(Zn²⁺|Zn) = −0.7618 V، فجهد اختزال الفضة أكبر، أي إن أيونات الفضة أقدر على اكتساب الإلكترونات.', '["","القيمة الموجبة أكبر من السالبة، فجهد الفضة أكبر.","الإشارتان معكوستان عن القيمتين الصحيحتين.","القيمتان مختلفتان؛ فلكل نصف خلية جهد اختزال قياسي خاص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.641Z"}'::jsonb),
('mcq', 5, 3, 'لا يمكن تحديد جهد اختزال القطب بصورة مباشرة؛ لأن نصف تفاعل الاختزال لا بد أن يقترن بنصف تفاعل أكسدة، والجهد المقيس هو فرق الجهد بين النصفين.', '["أيونات النحاس Cu²⁺ تكتسب الإلكترونات وتُختزل، ولها جهد اختزال موجب.","جهد الاختزال القياسي يُقاس تحت الظروف القياسية.","مقياس الجهد يقيس فرق الجهد بين قطبين، فيلزم قطبان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.641Z"}'::jsonb),
('mcq', 6, 1, 'الظروف القياسية: غمس القطب في محلول أيوناته (Fe²⁺) بتركيز 1M عند 25°C وضغط 1 atm، وهذا ما يحققه البديل الصحيح.', '["التركيز 0.01M غير قياسي؛ التركيز القياسي 1M.","","درجة الحرارة 60°C غير قياسية؛ القياسية 25°C.","يجب أن يحتوي المحلول على أيونات القطب نفسه (Fe²⁺) لا أيونات فلز آخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.641Z"}'::jsonb),
('mcq', 7, 0, 'جهد الاختزال مقياس لقابلية المادة لاكتساب الإلكترونات، أما جهد الاختزال القياسي E° فهو قيمته عندما يُقاس القطب تحت الظروف القياسية: محلول 1M عند 25°C و1 atm.', '["","كلاهما يقيس قابلية اكتساب الإلكترونات؛ والفرق في ظروف القياس.","جهود الاختزال القياسية تُقاس مقابل قطب الهيدروجين القياسي.","جهد الاختزال القياسي له ظروف محددة هي 1M و25°C و1 atm، وقد تتغير قيمة الجهد بتغيرها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.641Z"}'::jsonb),
('essay', 1, null::int, null, null, 'جهد الاختزال: مدى قابلية المادة لاكتساب الإلكترونات. جهد الاختزال القياسي E°: جهد الاختزال لقطب مقيسًا تحت الظروف القياسية، والصفر فوق الرمز يشير إلى ذلك. الظروف القياسية: غمس القطب في محلول أيوناته تركيزه 1M، ودرجة حرارة 25°C، وضغط 1 atm.', '["جهد الاختزال: قابلية اكتساب الإلكترونات","E°: جهد الاختزال تحت الظروف القياسية","التركيز 1M","25°C و1 atm"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف جهد الاختزال","marks":1},{"element":"تعريف E°","marks":1},{"element":"التركيز 1M","marks":1},{"element":"25°C و1 atm","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["تعريف جهد الاختزال بأنه قابلية فقد الإلكترونات","ذكر 0°C بدل 25°C"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-10-17T11:36:22.641Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الترتيب التصاعدي: Zn²⁺|Zn (−0.7618) < Fe²⁺|Fe (−0.447) < Cu²⁺|Cu (+0.3419) < Ag⁺|Ag (+0.7996). جهد الاختزال مقياس لقابلية اكتساب الإلكترونات، فأقواها اكتسابًا Ag⁺ (أعلى جهد) وأضعفها Zn²⁺ (أقل جهد).', '["الترتيب التصاعدي الصحيح","Ag⁺ الأقوى اكتسابًا","Zn²⁺ الأضعف اكتسابًا","ربط الجهد بقابلية الاكتساب"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح","marks":2},{"element":"تحديد الأقوى","marks":1},{"element":"تحديد الأضعف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب وتحديد صحيحان"},{"level":"3 درجات","description":"ترتيب صحيح مع تحديد أحدهما"},{"level":"درجتان","description":"ترتيب صحيح فقط"},{"level":"درجة واحدة","description":"تحديد الأقوى أو الأضعف فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["الترتيب بالقيمة المطلقة","الخلط بين السالب والموجب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.642Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لأن قيمة جهد القطب تتأثر بظروف القياس (التركيز ودرجة الحرارة والضغط)، فلكي تكون القيم المسجلة قابلة للمقارنة يجب أن تُقاس جميعها تحت ظروف موحدة هي 1M و25°C و1 atm. وفي المثال المذكور تختلف الظروف (تركيز 0.01M ودرجة حرارة 50°C) عن الظروف القياسية، فلا تُعد القيمة المقيسة جهد اختزال قياسيًا، وقد تختلف عن القيمة −0.7618 V؛ فلا تصح مقارنتها مباشرة بالقيم القياسية.', '["توحيد الظروف للمقارنة","تأثر الجهد بالتركيز ودرجة الحرارة","الظروف في المثال غير قياسية","لا تصح المقارنة المباشرة بالجدول"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل التوحيد (تأثر الجهد بالظروف)","marks":1},{"element":"ذكر الظروف القياسية الصحيحة","marks":1},{"element":"تحديد أن ظروف المثال غير قياسية","marks":1},{"element":"النتيجة: لا تصح المقارنة المباشرة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن الجهد لا يتأثر بالظروف","عدّ القيمة المقيسة قيمة E° رغم اختلاف الظروف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.642Z"}'::jsonb)
