('mcq', 2, 'عند توصيل نصف خلية Zn²⁺|Zn بقطب الهيدروجين القياسي، تتدفق الإلكترونات مبتعدة عن الخارصين نحو قطب الهيدروجين، ويكون E° = −0.762 V. ما تفسير الإشارة السالبة؟', null, '["أن أيونات الخارصين تكتسب الإلكترونات أسهل من أيونات الهيدروجين","أن الخارصين لا يمكن أن يتأكسد في أي ظروف","أن أيونات الهيدروجين تكتسب الإلكترونات أسهل من أيونات الخارصين","أن قطب الهيدروجين يفقد الإلكترونات ويتأكسد"]'::jsonb, 'فهم', 'تفسير إشارة', 'متوسط', 'الكتاب ص 139–140 — تحديد جهود اختزال الخلية الكهروكيميائية'),
('mcq', 3, 'ماذا يدل عليه جهد الاختزال القياسي الموجب لقطب ما عند قياسه مقابل قطب الهيدروجين القياسي؟', null, '["أن القطب يفقد الإلكترونات أسهل من قطب الهيدروجين فتحدث عنده أكسدة","أن القطب يكتسب الإلكترونات أسهل من قطب الهيدروجين فيحدث عنده اختزال","أن القطب لا يكتسب الإلكترونات ولا يفقدها","أن القطب يعمل أنودًا عند توصيله بقطب الهيدروجين"]'::jsonb, 'فهم', 'تعميم', 'سهل', 'الكتاب ص 139–140 — تحديد جهود اختزال الخلية الكهروكيميائية'),
('mcq', 4, 'قيس جهد قطب فلز M مقابل قطب الهيدروجين القياسي فكان E° = −0.50 V. ماذا تستنتج من هذه القيمة؟', null, '["أن القطب يكتسب الإلكترونات (يُختزل) عند توصيله بقطب الهيدروجين","أن القطب لا يتأثر بقطب الهيدروجين إطلاقًا","أن قطب الهيدروجين يتأكسد دائمًا مهما كان القطب الموصول به","أن القطب يفقد الإلكترونات (يتأكسد) عند توصيله بقطب الهيدروجين"]'::jsonb, 'فهم', 'تعميم', 'سهل', 'الكتاب ص 139–140 — تحديد جهود اختزال الخلية الكهروكيميائية'),
('mcq', 5, 'وُصل قطب فلز X بقطب الهيدروجين القياسي فتدفقت الإلكترونات من قطب الهيدروجين نحو القطب X. ما إشارة E° لنصف الخلية X؟', null, '["سالبة؛ لأن X يكتسب الإلكترونات أسهل من الهيدروجين","موجبة؛ لأن X يفقد الإلكترونات أسهل من الهيدروجين","موجبة؛ لأن X يكتسب الإلكترونات أسهل من الهيدروجين","سالبة؛ لأن X يفقد الإلكترونات أسهل من الهيدروجين"]'::jsonb, 'تطبيق', 'استنتاج', 'متوسط', 'الكتاب ص 139–140 — تحديد جهود اختزال الخلية الكهروكيميائية'),
('mcq', 6, 'وُصل قطب فلز Y بقطب الهيدروجين القياسي فاتجهت الإلكترونات من Y نحو قطب الهيدروجين. أيّ العبارات الآتية صحيح؟', null, '["جهد الاختزال القياسي لـY سالب، ويعمل قطب الهيدروجين كاثودًا","جهد الاختزال القياسي لـY موجب، ويعمل قطب الهيدروجين كاثودًا","جهد الاختزال القياسي لـY سالب، ويعمل قطب الهيدروجين أنودًا","جهد الاختزال القياسي لـY موجب، ويعمل قطب الهيدروجين أنودًا"]'::jsonb, 'تطبيق', 'استنتاج', 'صعب', 'الكتاب ص 139–140 — تحديد جهود اختزال الخلية الكهروكيميائية'),
('mcq', 7, 'أيّ المقارنات الآتية صحيحة لقطبي النحاس والخارصين عند قياسهما مقابل قطب الهيدروجين القياسي؟', null, '["النحاس: −0.342 V تتدفق الإلكترونات بعيدًا عنه، والخارصين: +0.762 V تتدفق الإلكترونات نحوه","النحاس والخارصين كلاهما موجب، وتتدفق الإلكترونات نحوهما","النحاس والخارصين كلاهما سالب، وتتدفق الإلكترونات بعيدًا عنهما","النحاس: +0.342 V تتدفق الإلكترونات نحوه، والخارصين: −0.762 V تتدفق الإلكترونات بعيدًا عنه"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 139–140 — تحديد جهود اختزال الخلية الكهروكيميائية'),
('essay', 1, 'وُصل نصف خلية Cu²⁺|Cu بقطب الهيدروجين القياسي فتدفقت الإلكترونات نحو النحاس وكان E° = +0.342 V. فسّر ما تدل عليه الإشارة الموجبة، واكتب نصفي التفاعل والتفاعل الكلي.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 139–140 — تحديد جهود اختزال الخلية الكهروكيميائية'),
('essay', 2, 'وُصل نصف خلية Zn²⁺|Zn بقطب الهيدروجين القياسي فتدفقت الإلكترونات مبتعدة عن الخارصين وكان E° = −0.762 V. فسّر الإشارة السالبة، واكتب نصفي التفاعل والتفاعل الكلي، وحدّد القطب الذي يعمل أنودًا.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 139–140 — تحديد جهود اختزال الخلية الكهروكيميائية'),
('essay', 3, 'قارن بين قطبي النحاس والخارصين عند قياس كل منهما مقابل قطب الهيدروجين القياسي من حيث: اتجاه تدفق الإلكترونات، وإشارة E°، وما يحدث عند كل قطب (أكسدة أو اختزال)، ثم استنتج أي القطبين أقوى اكتسابًا للإلكترونات، وكم يبلغ جهد الخلية الجلفانية المكونة منهما.', null, null, 'تحليل', 'مقارنة وحساب', 'صعب', 'الكتاب ص 139–140 — تحديد جهود اختزال الخلية الكهروكيميائية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
