('mcq', 1, 0, 'تدفق الإلكترونات نحو النحاس يعني أن Cu²⁺ تُختزل (تكتسب الإلكترونات) ويتأكسد H₂ عند قطب الهيدروجين، فجهد اختزال النحاس موجب (+0.342 V) أي أعلى من جهد الهيدروجين (0.000 V).', '["","هذا يدل على جهد اختزال سالب للنحاس، وهو عكس ما حدث.","الإلكترونات تتدفق نحو النحاس، أي يحدث عنده اختزال لا أكسدة.","التفاعل يحدث فعلًا وتتدفق إلكترونات، لذلك سُجّل جهد على المقياس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-17T11:36:22.642Z"}'::jsonb),
('mcq', 2, 2, 'تفسَّر الإشارة السالبة بأن أيونات الهيدروجين عند قطب الهيدروجين تكتسب الإلكترونات أسهل من أيونات الخارصين، لذا جهد اختزال أيونات الهيدروجين أعلى من جهد اختزال أيونات الخارصين، ولما كان جهد الهيدروجين 0.00 V فجهد الخارصين سالب.', '["لو كان كذلك لاتجهت الإلكترونات نحو الخارصين ولكان جهده موجبًا.","الخارصين يتأكسد فعلًا في هذه الخلية: Zn → Zn²⁺ + 2e⁻.","","الهيدروجين هنا يُختزل (2H⁺ → H₂)، ويتأكسد الخارصين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T11:36:22.643Z"}'::jsonb),
('mcq', 3, 1, 'الجهد الموجب (كجهد النحاس +0.342 V) يعني أن القطب يكتسب الإلكترونات أسهل من قطب الهيدروجين فتتدفق الإلكترونات نحوه ويحدث عنده اختزال.', '["هذا يدل على جهد اختزال سالب.","","الجهد الموجب دليل على تدفق إلكترونات نحو القطب.","الجهد الموجب يعني أن القطب كاثود يحدث عنده اختزال، والهيدروجين هو الأنود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.643Z"}'::jsonb),
('mcq', 4, 3, 'الجهد السالب (كجهد الخارصين −0.762 V) يدل على أن الإلكترونات تتدفق مبتعدة عن القطب نحو قطب الهيدروجين، أي إن القطب يتأكسد ويُختزل الهيدروجين.', '["هذا يدل على جهد اختزال موجب.","الجهد السالب قيمة مقيسة تدل على حدوث تفاعل أكسدة عند القطب.","اتجاه تفاعل قطب الهيدروجين يعتمد على القطب الموصول به؛ ومع الجهد السالب يُختزل الهيدروجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.643Z"}'::jsonb),
('mcq', 5, 2, 'تدفق الإلكترونات نحو X يعني أنه يُختزل، وأنه يكتسب الإلكترونات أسهل من الهيدروجين؛ فجهد اختزاله أعلى من 0.000 V أي موجب، مثل النحاس.', '["اكتساب X للإلكترونات أسهل من الهيدروجين يعني جهدًا موجبًا لا سالبًا.","الجهد الموجب ناتج من اكتساب الإلكترونات لا فقدها.","","X هنا يكتسب الإلكترونات ولا يفقدها، فالتعليل خاطئ والإشارة خاطئة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-17T11:36:22.643Z"}'::jsonb),
('mcq', 6, 0, 'الإلكترونات تتدفق من Y (الأنود، تأكسد) إلى قطب الهيدروجين (الكاثود، اختزال H⁺)؛ لذا Y جهد اختزاله أقل من الهيدروجين أي سالب، كالخارصين.', '["","تدفق الإلكترونات من Y يعني أن Y يتأكسد وجهده سالب لا موجب.","قطب الهيدروجين يستقبل الإلكترونات فتُختزل H⁺ عنده، فهو كاثود.","الإلكترونات متجهة إلى قطب الهيدروجين فهو كاثود، وجهد Y سالب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-17T11:36:22.643Z"}'::jsonb),
('mcq', 7, 3, 'عند توصيل Cu²⁺|Cu بقطب الهيدروجين تتدفق الإلكترونات نحو النحاس وE° = +0.342 V، وعند توصيل Zn²⁺|Zn تتدفق الإلكترونات مبتعدة عن الخارصين وE° = −0.762 V.', '["الإشارتان واتجاها التدفق معكوسة عن القيم الصحيحة.","الخارصين جهده −0.762 V وتتدفق الإلكترونات بعيدًا عنه.","النحاس جهده +0.342 V وتتدفق الإلكترونات نحوه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.643Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الإشارة الموجبة تدل على أن أيونات Cu²⁺ تكتسب الإلكترونات أسهل من أيونات H⁺، لذلك تتدفق الإلكترونات من قطب الهيدروجين إلى النحاس: يحدث الاختزال عند النحاس (كاثود) والأكسدة عند الهيدروجين (أنود). نصف الأكسدة: H₂(g) → 2H⁺(aq) + 2e⁻، ونصف الاختزال: Cu²⁺(aq) + 2e⁻ → Cu(s)، والتفاعل الكلي: H₂(g) + Cu²⁺(aq) → 2H⁺(aq) + Cu(s).', '["Cu²⁺ تكتسب الإلكترونات أسهل من H⁺","نصف الأكسدة للهيدروجين","نصف الاختزال للنحاس","التفاعل الكلي"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الإشارة الموجبة","marks":1},{"element":"نصف الأكسدة","marks":1},{"element":"نصف الاختزال","marks":1},{"element":"التفاعل الكلي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"خطأ أو نقص في عنصر"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["جعل النحاس هو الذي يتأكسد","عدم موازنة H⁺ في التفاعل الكلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-17T11:36:22.644Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الإشارة السالبة تدل على أن أيونات الهيدروجين تكتسب الإلكترونات أسهل من أيونات الخارصين، أي إن جهد اختزال H⁺ (0.000 V) أعلى من جهد اختزال Zn²⁺، فيجب أن يكون جهد الخارصين سالبًا. تتدفق الإلكترونات من الخارصين إلى قطب الهيدروجين: نصف الأكسدة Zn(s) → Zn²⁺(aq) + 2e⁻، ونصف الاختزال 2H⁺(aq) + 2e⁻ → H₂(g)، والتفاعل الكلي Zn(s) + 2H⁺(aq) → Zn²⁺(aq) + H₂(g). القطب الذي يعمل أنودًا هو قطب الخارصين، ويعمل قطب الهيدروجين كاثودًا.', '["H⁺ تكتسب الإلكترونات أسهل من Zn²⁺","نصف الأكسدة","نصف الاختزال","التفاعل الكلي","Zn أنود وH₂ كاثود"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الإشارة السالبة","marks":1},{"element":"نصف الأكسدة ونصف الاختزال","marks":1},{"element":"التفاعل الكلي","marks":1},{"element":"تحديد الأنود","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"خطأ في عنصر"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن السالب يعني أن الخارصين لا يتفاعل","عدّ قطب الهيدروجين أنودًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-17T11:36:22.644Z"}'::jsonb),
('essay', 3, null::int, null, null, 'النحاس: تتدفق الإلكترونات نحو النحاس، E° = +0.342 V، يحدث عنده اختزال (Cu²⁺ + 2e⁻ → Cu). الخارصين: تتدفق الإلكترونات مبتعدة عنه نحو قطب الهيدروجين، E° = −0.762 V، تحدث عنده أكسدة (Zn → Zn²⁺ + 2e⁻). النحاس أقوى اكتسابًا للإلكترونات لأن جهد اختزاله أعلى (موجب مقابل سالب). جهد خلية Zn–Cu: E°cell = +0.342 − (−0.762) = +1.104 V.', '["اتجاه الإلكترونات لكل قطب","إشارة E° لكل قطب","الاختزال عند النحاس والأكسدة عند الخارصين","النحاس أقوى اكتسابًا","E°cell = +1.104 V"]'::jsonb, '["Cu: الإلكترونات نحوه، E° موجب، اختزال.","Zn: الإلكترونات بعيدًا عنه، E° سالب، أكسدة.","النحاس أعلى جهد اختزال فهو أقوى اكتسابًا.","E°cell = 0.342 − (−0.762) = +1.104 V."]'::jsonb, '[{"element":"اتجاه الإلكترونات","marks":1},{"element":"إشارة E° لكل قطب","marks":1},{"element":"الأكسدة والاختزال عند كل قطب","marks":1},{"element":"استنتاج الأقوى اكتسابًا","marks":1},{"element":"حساب E°cell","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة"},{"level":"4 درجات","description":"نقص عنصر"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["جمع الجهدين بدل الطرح","الظن أن السالب يعني ضعف الجهد المطلق فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.644Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
