('mcq', 1, 'ما المقصود بالبطارية الأولية؟', null, '["بطارية تعتمد على تفاعل أكسدة واختزال عكسي فيمكن إعادة شحنها","خلية تُزوَّد بالوقود باستمرار من مصدر خارجي فلا تنفد","بطارية تنتج طاقة كهربائية من تفاعل أكسدة واختزال لا يحدث عكسيًا بسهولة","بطارية يكون المحلول الموصل فيها محلولًا سائلًا من حمض الكبريتيك"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 146 — البطاريات الأولية والثانوية'),
('mcq', 2, 'أيّ زوج من البطاريات الآتية يتكوّن من بطاريتين ثانويتين؟', null, '["بطارية NiCad وبطارية المركم الرصاصي","البطارية القلوية وبطارية الفضة","بطارية NiCad وخلية الخارصين والكربون","بطارية الفضة وبطارية المركم الرصاصي"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'سهل', 'الكتاب ص 146 — البطاريات الأولية والثانوية'),
('mcq', 3, 'لماذا يمكن إعادة شحن البطاريات الثانوية؟', null, '["لأن أقطابها مصنوعة من مواد لا تشارك في تفاعل الأكسدة والاختزال","لأن تفاعل الأكسدة والاختزال فيها عكسي، فيمكن عكس اتجاهه بطاقة كهربائية من مصدر خارجي","لأن المادة المتأكسدة فيها وقود يُزوَّد باستمرار من مصدر خارجي","لأن تفاعلها في أثناء توليد التيار تفاعل غير تلقائي"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 146 — البطاريات الأولية والثانوية'),
('mcq', 4, 'أيّ الأجهزة الآتية يعمل عادةً ببطارية أولية؟', null, '["حاسوب محمول يُشحن يوميًّا","ساعة يد تعمل ببطارية الفضة","سيارة تعمل ببطارية المركم الرصاصي","آلة حلاقة تعمل ببطارية NiCad"]'::jsonb, 'فهم', 'تطبيق على أمثلة', 'متوسط', 'الكتاب ص 145–146 — بطاريات الفضة؛ البطاريات الأولية والثانوية'),
('mcq', 5, 'لدى طالب بطاريتان: (X) تصبح غير صالحة للاستعمال بعد انتهاء تفاعلها، و(Y) يُعاد تكوين موادها المتفاعلة عند وصلها بمصدر كهربائي. أيّ مما يأتي يصنّفهما ويمثّل لهما تمثيلًا صحيحًا؟', null, '["X أولية مثل البطارية القلوية، وY ثانوية مثل بطارية NiCad","X ثانوية مثل المركم الرصاصي، وY أولية مثل بطارية الفضة","X أولية مثل بطارية NiCad، وY ثانوية مثل البطارية القلوية","X أولية مثل بطارية الفضة، وY ثانوية مثل خلية الخارصين والكربون"]'::jsonb, 'تحليل', 'تصنيف موقف', 'صعب', 'الكتاب ص 146 — البطاريات الأولية والثانوية'),
('mcq', 6, 'ما الاسم الذي يُطلق أحيانًا على البطاريات الثانوية مثل بطارية السيارة وبطارية الحاسوب المحمول؟', null, '["الخلايا الجافة","خلايا الوقود","الخلايا الإلكتروليتية","بطاريات التخزين"]'::jsonb, 'تذكر', 'مصطلح', 'سهل', 'الكتاب ص 146 — البطاريات الأولية والثانوية'),
('mcq', 7, 'أيّ العبارات الآتية تصف تصنيف بطاريات الليثيوم وصفًا صحيحًا؟', null, '["أولية دائمًا لأن الليثيوم أخف فلز معروف","ثانوية دائمًا لأنها تُستعمل في الحواسيب وآلات التصوير","قد تكون أولية أو ثانوية بحسب تفاعل الاختزال المدمج مع أكسدة الليثيوم","ثانوية دائمًا لأن لليثيوم أقل جهد اختزال قياسي"]'::jsonb, 'فهم', 'تمييز', 'صعب', 'الكتاب ص 148 — بطاريات الليثيوم'),
('essay', 1, 'ميّز بين البطاريات الأولية والبطاريات الثانوية من حيث: طبيعة تفاعل الأكسدة والاختزال، وإمكانية إعادة الشحن، ثم أعطِ مثالين على كل نوع.', null, null, 'فهم', 'مقارنة مع أمثلة', 'متوسط', 'الكتاب ص 146 — البطاريات الأولية والثانوية'),
('essay', 2, 'صنّف البطاريات الآتية إلى أولية وثانوية، واذكر الأساس الذي اعتمدت عليه في التصنيف: بطارية الفضة، بطارية NiCad، البطارية القلوية، بطارية المركم الرصاصي، خلية الخارصين والكربون الجافة، بطارية الحاسوب المحمول.', null, null, 'تحليل', 'تصنيف مع تبرير', 'صعب', 'الكتاب ص 144–147 — البطاريات الأولية والثانوية'),
('essay', 3, 'فسّر: يمكن إعادة شحن بطارية NiCad بينما لا يُعاد شحن البطارية القلوية. ثم صف ما يحدث لتفاعل البطارية عند وصل بطارية NiCad بمصدر كهربائي.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 146 — البطاريات الأولية والثانوية؛ بطاريات NiCad')
