from (values
('mcq', 1, 2, 'البطارية الأولية تنتج طاقة كهربائية من تفاعل أكسدة واختزال لا يحدث بشكل عكسي بسهولة، وتصبح غير صالحة للاستعمال بعد انتهاء التفاعل، مثل خلايا الخارصين والكربون والقلوية والفضة.', '["هذا تعريف البطارية الثانوية لا الأولية.","هذا وصف خلية الوقود، وهي لا تُعرَّف بأنها بطارية أولية.","","حمض الكبريتيك محلول بطارية المركم الرصاصي، وهي بطارية ثانوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.645Z"}'::jsonb),
('mcq', 2, 0, 'بطارية NiCad (نيكل – كادميوم) وبطارية المركم الرصاصي (بطارية السيارة) تعتمدان على تفاعل أكسدة واختزال عكسي فيمكن شحنهما؛ لذا فكلتاهما بطارية ثانوية.', '["","كلتاهما بطارية أولية لا يُعاد شحنها.","خلية الخارصين والكربون الجافة بطارية أولية، وإن كانت NiCad ثانوية.","بطارية الفضة أولية، وإن كان المركم الرصاصي ثانويًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.645Z"}'::jsonb),
('mcq', 3, 1, 'تعتمد البطاريات الثانوية على تفاعل أكسدة واختزال عكسي؛ فعند الشحن تُزوَّد بطاقة كهربائية تعكس اتجاه تفاعلها التلقائي فتُستعاد المواد المتفاعلة.', '["القطب غير الفعال (كعمود الكربون) لا علاقة له بإمكانية الشحن، وأقطاب البطاريات الثانوية تشارك في التفاعل.","","هذا ما يميز خلية الوقود، لا البطارية الثانوية التي تُشحن بالكهرباء.","تفاعل البطارية في أثناء توليد التيار تلقائي؛ أما التفاعل غير التلقائي فهو تفاعل الشحن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.645Z"}'::jsonb),
('mcq', 4, 1, 'تُصنَّف بطارية الفضة المستعملة في الساعات وسماعات الأذن بطارية أولية، أما بطاريات الحاسوب المحمول والسيارة وNiCad فثانوية قابلة للشحن.', '["بطارية الحاسوب المحمول مثال على البطاريات الثانوية.","","بطارية المركم الرصاصي ثانوية تُشحن عندما يعمل المحرك.","بطاريات NiCad المستعملة في آلات الحلاقة ثانوية قابلة للشحن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.645Z"}'::jsonb),
('mcq', 5, 0, 'X لا يحدث تفاعلها عكسيًا بسهولة فهي أولية (كالقلوية)، وY تفاعلها عكسي يُعكس بالشحن فهي ثانوية (كـNiCad). لذا فالتصنيف والمثالان الصحيحان: X أولية مثل القلوية، وY ثانوية مثل NiCad.', '["","عكس التصنيف: البطارية التي لا تُشحن أولية، والتي يُعاد تكوين موادها بالشحن ثانوية.","التصنيف صحيح لكن المثالين معكوسان؛ فـNiCad ثانوية والقلوية أولية.","مثال Y خاطئ؛ فخلية الخارصين والكربون الجافة أولية لا تُشحن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.645Z"}'::jsonb),
('mcq', 6, 3, 'بطارية السيارة والحاسوب المحمول مثالان على البطاريات الثانوية التي تُسمّى في بعض الأحيان بطاريات التخزين.', '["الخلية الجافة خلية جلفانية محلولها الموصل عجينة رطبة، ومعظمها أولي.","خلايا الوقود تُزوَّد بالوقود من مصدر خارجي ولا تُشحن، وليست اسمًا للبطاريات الثانوية.","الخلية الإلكتروليتية تستعمل الكهرباء لإحداث تفاعل غير تلقائي، وليست اسمًا للبطاريات الثانوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.646Z"}'::jsonb),
('mcq', 7, 2, 'بطاريات الليثيوم يمكن أن تكون أولية أو ثانوية اعتمادًا على تفاعلات الاختزال التي دُمجت مع تأكسد الليثيوم؛ فالمعيار هو قابلية التفاعل للانعكاس.', '["خفة الليثيوم سبب اختياره لصناعة البطاريات، ولا تحدد كون البطارية أولية أو ثانوية.","مجال الاستعمال لا يحدد التصنيف، وبعض بطاريات الليثيوم أولية.","","جهد الاختزال المنخفض يفسر الجهد العالي لا قابلية الشحن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.646Z"}'::jsonb),
('essay', 1, null::int, null, null, 'البطارية الأولية: تنتج طاقة كهربائية من تفاعل أكسدة واختزال لا يحدث عكسيًا بسهولة، فلا يمكن شحنها وتصبح غير صالحة بعد انتهاء التفاعل؛ مثالاها: خلية الخارصين والكربون الجافة، والبطارية القلوية (ويقبل بطارية الفضة). البطارية الثانوية: تعتمد على تفاعل أكسدة واختزال عكسي، فيمكن شحنها بتزويدها بطاقة كهربائية تعكس التفاعل؛ مثالاها: بطارية المركم الرصاصي (بطارية السيارة)، وبطارية NiCad (ويقبل بطارية الحاسوب المحمول).', '["الأولية: تفاعل لا يحدث عكسيًا بسهولة ولا تُشحن","الثانوية: تفاعل عكسي فيمكن شحنها","مثالان صحيحان على الأولية","مثالان صحيحان على الثانوية"]'::jsonb, '[]'::jsonb, '[{"element":"وصف البطارية الأولية (التفاعل وعدم الشحن)","marks":1},{"element":"وصف البطارية الثانوية (التفاعل العكسي والشحن)","marks":1},{"element":"مثالان صحيحان على البطارية الأولية","marks":1},{"element":"مثالان صحيحان على البطارية الثانوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تمييز صحيح للنوعين مع مثالين صحيحين لكل نوع"},{"level":"3 درجات","description":"تمييز صحيح للنوعين مع خطأ في أحد الأمثلة أو نقص مثال"},{"level":"2 درجتان","description":"تمييز صحيح دون أمثلة، أو أمثلة صحيحة مع تمييز ناقص"},{"level":"1 درجة","description":"وصف أحد النوعين فقط أو أمثلة صحيحة لنوع واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ خلية الخارصين والكربون أو القلوية بطارية ثانوية","الخلط بين البطارية الثانوية وخلية الوقود","الاكتفاء بأن الأولية «تُستعمل مرة واحدة» دون ذكر طبيعة التفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.646Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الأولية: بطارية الفضة، والبطارية القلوية، وخلية الخارصين والكربون الجافة. الثانوية: بطارية NiCad، وبطارية المركم الرصاصي، وبطارية الحاسوب المحمول. أساس التصنيف: هل تفاعل الأكسدة والاختزال في البطارية عكسي يمكن عكسه بالشحن (ثانوية) أم لا يحدث عكسيًا بسهولة فتنتهي صلاحية البطارية بانتهائه (أولية).', '["الفضة والقلوية والخارصين والكربون: أولية","NiCad والمركم الرصاصي والحاسوب المحمول: ثانوية","أساس التصنيف: قابلية تفاعل الأكسدة والاختزال للانعكاس بالشحن"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف البطاريات الست (نصف درجة لكل بطارية)","marks":3},{"element":"ذكر أساس التصنيف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح للبطاريات الست مع ذكر الأساس"},{"level":"3 درجات","description":"تصنيف صحيح للست دون الأساس، أو خطأ في بطاريتين مع الأساس"},{"level":"2 درجتان","description":"تصنيف صحيح لأربع بطاريات"},{"level":"1 درجة","description":"ذكر الأساس فقط أو تصنيف صحيح لبطاريتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف بطارية الفضة ثانوية لصغر حجمها وطول عمرها","جعل أساس التصنيف حجم البطارية أو جهدها","تصنيف القلوية ثانوية لأنها «أكثر كفاءة»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.646Z"}'::jsonb),
('essay', 3, null::int, null, null, 'بطارية NiCad ثانوية تعتمد على تفاعل أكسدة واختزال عكسي، أما القلوية فأولية تفاعلها لا يحدث عكسيًا بسهولة فتصبح غير صالحة بعد انتهاء التفاعل. عند وصل NiCad بمصدر كهربائي يزوّدها بطاقة كهربائية تدفع تفاعل الشحن غير التلقائي للحدوث، فتحدث تفاعلات التفريغ بشكل عكسي: يتحول Cd(OH)₂ إلى Cd، ويتحول Ni(OH)₂ إلى NiO(OH)، فتُستعاد المواد المتفاعلة.', '["NiCad: تفاعل عكسي (ثانوية)","القلوية: تفاعل لا يحدث عكسيًا بسهولة (أولية)","المصدر يزود طاقة كهربائية تدفع تفاعلًا غير تلقائي","انعكاس التفاعلات واستعادة المواد المتفاعلة (Cd وNiO(OH))"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير قابلية شحن NiCad","marks":1},{"element":"تفسير عدم شحن القلوية","marks":1},{"element":"وصف ما يحدث عند الوصل بالمصدر الكهربائي","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير صحيح للبطاريتين مع وصف صحيح لعكس التفاعل عند الشحن"},{"level":"2 درجتان","description":"تفسير صحيح للبطاريتين دون وصف الشحن، أو العكس مع نقص"},{"level":"1 درجة","description":"ذكر أن NiCad ثانوية والقلوية أولية دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الشحن يضيف مواد جديدة إلى البطارية","وصف تفاعل الشحن بأنه تلقائي","تفسير الفرق بنوع المحلول الموصل وحده (كلاهما يستعمل KOH)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.646Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
