from (values
('mcq', 1, 'ممّ يتكوّن كل قطب من قطبي خلية الوقود (الهيدروجين – الأكسجين)؟', null, '["وعاء أجوف جدرانه من كربون مسامي","حافظة من الخارصين تحيط بعجينة رطبة","شبكة من الرصاص مملوءة بأكسيد الرصاص IV","عمود مصمت من الجرافيت لا تنفذ منه الغازات"]'::jsonb, 'تذكر', 'تركيب', 'سهل', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('mcq', 2, 'ما المحلول الموصل الشائع في خلية وقود الهيدروجين – الأكسجين؟', null, '["محلول حمض الكبريتيك H₂SO₄","محلول قلوي من هيدروكسيد البوتاسيوم KOH","عجينة رطبة من NH₄Cl وZnCl₂ وMnO₂","ماء مقطر خالٍ من الأيونات"]'::jsonb, 'تذكر', 'تركيب', 'سهل', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('mcq', 3, 'أيّ المعادلات الآتية تمثل نصف التفاعل الذي يحدث عند أنود خلية الوقود القلوية؟', null, '["O₂ + 2H₂O + 4e⁻ → 4OH⁻","2H₂ + O₂ → 2H₂O","4H₂O + 4e⁻ → 2H₂ + 4OH⁻","2H₂ + 4OH⁻ → 4H₂O + 4e⁻"]'::jsonb, 'فهم', 'تحديد نصف تفاعل', 'متوسط', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('mcq', 4, 'ما الذي يحدث عند كاثود خلية الوقود القلوية؟', null, '["يتأكسد الهيدروجين فتنطلق إلكترونات إلى الدائرة الخارجية","يُختزل الهيدروجين فتتكوّن أيونات الهيدروكسيد","يُختزل الأكسجين بوجود الماء فتتكوّن أيونات الهيدروكسيد","يتأكسد الأكسجين فتتكوّن جزيئات الماء"]'::jsonb, 'فهم', 'وصف آلية', 'متوسط', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('mcq', 5, 'ما أهمية أيونات OH⁻ الناتجة عند كاثود خلية الوقود القلوية في استمرار عمل الخلية؟', null, '["تختزل جزيئات الأكسجين إلى ماء عند الكاثود","تتحد مع أيونات K⁺ فيترسب KOH صلب على الأقطاب","تعوّض أيونات الهيدروكسيد المستهلكة في تفاعل الأنود","تنتقل عبر الدائرة الخارجية من الكاثود إلى الأنود"]'::jsonb, 'تحليل', 'تفسير دور', 'صعب', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('mcq', 6, 'ما وظيفة غشاء تبادل البروتون (PEM) في بعض خلايا الوقود؟', null, '["يُختزل عليه الأكسجين بدلًا من الكاثود","يفصل نصفي التفاعل ويستبعد الحاجة إلى محلول موصل سائل","يسمح بمرور الإلكترونات من الأنود إلى الكاثود","يمنع تكوّن الماء في أثناء تفاعل الخلية"]'::jsonb, 'فهم', 'وظيفة جزء', 'متوسط', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('mcq', 7, 'في خلية الوقود القلوية، إذا استُهلك 4 mol من غاز H₂ عند الأنود، فكم مولًا من الإلكترونات تتدفق عبر الدائرة الخارجية؟', null, '["4 mol","2 mol","16 mol","8 mol"]'::jsonb, 'تطبيق', 'حساب من نصف التفاعل', 'صعب', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('essay', 1, 'صف تركيب خلية وقود الهيدروجين – الأكسجين القلوية، موضحًا: مادة القطبين وشكلهما، والمحلول الموصل، والغاز الذي يُزوَّد به كل من الأنود والكاثود.', null, null, 'تذكر', 'وصف تركيب', 'سهل', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('essay', 2, 'اكتب نصف تفاعل الأكسدة عند الأنود ونصف تفاعل الاختزال عند الكاثود في خلية الوقود القلوية، ثم اجمعهما لتحصل على المعادلة الكلية، موضحًا ما يُحذف من الطرفين.', null, null, 'تطبيق', 'كتابة معادلات', 'متوسط', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
