from (values
('mcq', 1, 0, 'كل قطب في خلية الوقود وعاء أجوف جدرانه من كربون مسامي تسمح بالاتصال بين الحجرة الداخلية (التي فيها الغاز) والمحلول الموصل المحيط بها.', '["","حافظة الخارصين أنود خلية الخارصين والكربون الجافة، لا قطب خلية الوقود.","هذا كاثود بطارية المركم الرصاصي.","قطب خلية الوقود مسامي يسمح بالاتصال بين الحجرة الداخلية والمحلول الموصل، وليس مصمتًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.647Z"}'::jsonb),
('mcq', 2, 1, 'المحلول الموصل الشائع في خلية الوقود محلول قلوي من هيدروكسيد البوتاسيوم KOH، وتستعمل أيونات OH⁻ منه في تفاعل الأنود.', '["حمض الكبريتيك هو المحلول الموصل في بطارية المركم الرصاصي.","","هذه العجينة محلول خلية الخارصين والكربون الجافة.","الماء المقطر موصل رديء لقلة أيوناته، والخلية تحتاج محلولًا موصلًا تنتقل فيه الأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.647Z"}'::jsonb),
('mcq', 3, 3, 'عند الأنود يتأكسد الهيدروجين مستعملًا أيونات الهيدروكسيد في المحلول القلوي ويطلق إلكترونات: 2H₂ + 4OH⁻ → 4H₂O + 4e⁻.', '["هذا نصف تفاعل الاختزال الذي يحدث عند الكاثود.","هذه المعادلة الكلية للخلية، لا نصف تفاعل الأنود.","هذا عكس تفاعل الأنود، وهو اختزال؛ والأنود موقع الأكسدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-17T11:36:22.647Z"}'::jsonb),
('mcq', 4, 2, 'تتدفق الإلكترونات عبر الدائرة الخارجية إلى الكاثود حيث تختزل الأكسجين بوجود الماء: O₂ + 2H₂O + 4e⁻ → 4OH⁻، فتتكوّن أيونات الهيدروكسيد.', '["أكسدة الهيدروجين تحدث عند الأنود لا عند الكاثود.","الهيدروجين هو الوقود الذي يتأكسد، ولا يُختزل في الخلية.","","الأكسجين يكسب إلكترونات عند الكاثود فهو يُختزل لا يتأكسد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-17T11:36:22.647Z"}'::jsonb),
('mcq', 5, 2, 'اختزال الأكسجين ينتج 4 أيونات هيدروكسيد تعمل على تعويض أيونات الهيدروكسيد المستخدمة عند الأنود، فلا يُستهلك المحلول القلوي.', '["الذي يختزل الأكسجين هو الإلكترونات، وأيونات OH⁻ ناتج الاختزال لا عامله.","KOH يبقى ذائبًا في المحلول الموصل، ولا يترسب.","","الدائرة الخارجية تنقل الإلكترونات، أما الأيونات فتنتقل في المحلول الموصل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:36:22.647Z"}'::jsonb),
('mcq', 6, 1, 'تستعمل بعض خلايا الوقود صفيحة بلاستيكية تسمى غشاء تبادل البروتون (PEM) تفصل نصفي التفاعل، مما يستبعد الحاجة إلى محلول موصل سائل.', '["الاختزال يحدث عند الكاثود، والغشاء صفيحة بلاستيكية تفصل نصفي التفاعل.","","الإلكترونات تتدفق في الدائرة الخارجية لا عبر الغشاء.","الماء هو الناتج الجانبي لتفاعل الأكسدة والاختزال في خلية PEM."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.647Z"}'::jsonb),
('mcq', 7, 3, 'من نصف تفاعل الأنود 2H₂ + 4OH⁻ → 4H₂O + 4e⁻: كل 2 mol H₂ تطلق 4 mol e⁻، أي 2 mol e⁻ لكل مول H₂؛ إذن 4 mol H₂ × 2 = 8 mol e⁻.', '["افترض أن كل مول H₂ يطلق مولًا واحدًا من الإلكترونات، بينما يطلق 2 mol.","قلب النسبة المولية: كل 2 mol H₂ تطلق 4 mol إلكترونات لا العكس.","ضرب 4 mol في المعامل 4 للإلكترونات دون القسمة على معامل H₂ وهو 2.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.648Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لخلية الوقود أنود وكاثود، كل منهما وعاء أجوف جدرانه من كربون مسامي تسمح بالاتصال بين الحجرة الداخلية والمحلول الموصل المحيط بها. المحلول الموصل الشائع محلول قلوي من هيدروكسيد البوتاسيوم KOH تنتقل فيه الأيونات بين القطبين. يُزوَّد الأنود بغاز الهيدروجين (الوقود) الذي يتأكسد، ويُزوَّد الكاثود بغاز الأكسجين الذي يُختزل.', '["القطبان وعاءان أجوفان من كربون مسامي","المحلول الموصل KOH (قلوي)","H₂ عند الأنود وO₂ عند الكاثود"]'::jsonb, '[]'::jsonb, '[{"element":"وصف القطبين (أجوفان من كربون مسامي)","marks":1},{"element":"المحلول الموصل KOH","marks":1},{"element":"تحديد غاز كل قطب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"وصف كامل للأقطاب والمحلول وغاز كل قطب"},{"level":"2 درجتان","description":"عنصران صحيحان من الثلاثة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الأكسجين يُزوَّد عند الأنود","ذكر حمض الكبريتيك محلولًا موصلًا لخلية الوقود","وصف الأقطاب بأنها فلزية مصمتة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.648Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الأنود: 2H₂ + 4OH⁻ → 4H₂O + 4e⁻. الكاثود: O₂ + 2H₂O + 4e⁻ → 4OH⁻. بالجمع: 2H₂ + 4OH⁻ + O₂ + 2H₂O + 4e⁻ → 4H₂O + 4e⁻ + 4OH⁻، ثم تُحذف 4e⁻ و4OH⁻ من الطرفين، و2H₂O من الطرفين (فيبقى 2H₂O في النواتج)، فتكون المعادلة الكلية: 2H₂ + O₂ → 2H₂O، وهي معادلة احتراق الهيدروجين في الأكسجين نفسها.', '["نصف تفاعل الأنود صحيحًا موزونًا","نصف تفاعل الكاثود صحيحًا موزونًا","حذف e⁻ وOH⁻ وH₂O المشتركة","المعادلة الكلية 2H₂ + O₂ → 2H₂O"]'::jsonb, '["الأنود (أكسدة): 2H₂ + 4OH⁻ → 4H₂O + 4e⁻","الكاثود (اختزال): O₂ + 2H₂O + 4e⁻ → 4OH⁻","الإلكترونات متساوية في النصفين (4e⁻) فلا حاجة إلى ضرب","الجمع وحذف 4e⁻ و4OH⁻ و2H₂O من الطرفين","المعادلة الكلية: 2H₂ + O₂ → 2H₂O"]'::jsonb, '[{"element":"نصف تفاعل الأنود","marks":1},{"element":"نصف تفاعل الكاثود","marks":1},{"element":"الحذف الصحيح للمواد المشتركة","marks":1},{"element":"المعادلة الكلية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نصفا التفاعل صحيحان والجمع والحذف والمعادلة الكلية صحيحة"},{"level":"3 درجات","description":"نصفا التفاعل والمعادلة الكلية صحيحة دون توضيح الحذف"},{"level":"2 درجتان","description":"نصفا التفاعل صحيحان فقط"},{"level":"1 درجة","description":"نصف تفاعل واحد صحيح أو المعادلة الكلية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الإلكترونات في الطرف الخطأ","تبديل نصفي الأنود والكاثود","إبقاء OH⁻ في المعادلة الكلية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.648Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يتأكسد H₂ عند الأنود مستعملًا أيونات OH⁻ من المحلول فيتكوّن الماء وتنطلق إلكترونات (2H₂ + 4OH⁻ → 4H₂O + 4e⁻). تتدفق الإلكترونات عبر الدائرة الخارجية نحو الكاثود فتشغّل الجهاز المتصل بها. عند الكاثود تختزل الإلكترونات O₂ بوجود الماء فتتكوّن OH⁻ (O₂ + 2H₂O + 4e⁻ → 4OH⁻)، وتنتقل أيونات OH⁻ عبر المحلول الموصل فتعوّض ما استُهلك عند الأنود. أما خلايا PEM فتستعمل صفيحة بلاستيكية (غشاء تبادل البروتون) تفصل نصفي التفاعل وتستبعد الحاجة إلى محلول موصل سائل؛ فيتأكسد H₂ إلى H⁺ وتعبر البروتونات الغشاء إلى الكاثود لتكوّن الماء مع O₂ والإلكترونات.', '["أكسدة H₂ عند الأنود وانطلاق الإلكترونات","تدفق الإلكترونات في الدائرة الخارجية نحو الكاثود","اختزال O₂ وتكوّن OH⁻ عند الكاثود","انتقال OH⁻ في المحلول تعويضًا لما استُهلك","PEM: صفيحة بلاستيكية تفصل نصفي التفاعل وتستبعد المحلول السائل"]'::jsonb, '[]'::jsonb, '[{"element":"أكسدة الهيدروجين عند الأنود","marks":1},{"element":"مسار الإلكترونات في الدائرة الخارجية","marks":1},{"element":"اختزال الأكسجين وحركة OH⁻ في المحلول","marks":1},{"element":"ما يميز خلايا PEM","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تتبع كامل صحيح للإلكترونات والأيونات مع وصف PEM"},{"level":"3 درجات","description":"تتبع صحيح مع نقص في حركة الأيونات أو في وصف PEM"},{"level":"2 درجتان","description":"وصف صحيح لتفاعلي القطبين دون مسار الجسيمات"},{"level":"1 درجة","description":"وصف أحد القطبين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الإلكترونات تعبر المحلول الموصل أو الغشاء","القول إن غشاء PEM يمرر الإلكترونات","إغفال دور أيونات OH⁻ في المحلول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.648Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
