('mcq', 4, 'ما نوع التفاعل الذي يحدث في أثناء تآكل الفلزات في الطبيعة؟', null, '["تفاعل أكسدة واختزال غير تلقائي يحتاج إلى مصدر كهربائي","تفاعل ترسيب لا يتضمن انتقال إلكترونات","تفاعل تحلل حراري للفلز","تفاعل أكسدة واختزال تلقائي"]'::jsonb, 'فهم', 'تصنيف تفاعل', 'متوسط', 'الكتاب ص 150 — التآكل'),
('mcq', 5, 'أيّ الملاحظات الآتية مثال على التآكل؟', null, '["تمدد قضبان السكة الحديدية في أيام الصيف","تكوّن طبقة بنية هشة على سياج حديدي معرّض للمطر","انصهار قطعة من الرصاص عند تسخينها","انجذاب برادة الحديد إلى قطعة مغناطيس"]'::jsonb, 'فهم', 'تمييز أمثلة', 'متوسط', 'الكتاب ص 150 — التآكل'),
('mcq', 6, 'أيّ الظروف الآتية تجعل قطعة الحديد أكثر عرضة للصدأ؟', null, '["توافر الماء والأكسجين معًا على سطحها","توافر الأكسجين وحده في هواء جاف تمامًا","توافر الماء وحده في غياب الهواء","تغطية سطحها بطبقة سليمة من الطلاء"]'::jsonb, 'فهم', 'تفسير ظروف', 'صعب', 'الكتاب ص 150 — التآكل'),
('mcq', 7, 'ماذا يحدث لذرات الفلز في أثناء تآكله؟', null, '["تكسب إلكترونات فتُختزل إلى أيونات سالبة","تفقد إلكترونات فتُختزل إلى ذرات متعادلة","تفقد إلكترونات فتتأكسد إلى أيونات موجبة","تبقى متعادلة وتتحد مع الماء دون تفاعل أكسدة واختزال"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 150 — التآكل'),
('essay', 1, 'عرّف التآكل، واذكر مثالًا عليه من الحياة اليومية، واكتب الصيغة الكيميائية لناتجه في هذا المثال.', null, null, 'تذكر', 'تعريف مع مثال', 'سهل', 'الكتاب ص 150 — التآكل'),
('essay', 2, 'وضّح لماذا يُعدّ التآكل تفاعل أكسدة واختزال، محددًا في صدأ الحديد المادة التي تتأكسد والمادة التي تُختزل، ومكتوبًا المعادلة الكلية لتآكل الحديد.', null, null, 'فهم', 'تفسير مع معادلة', 'متوسط', 'الكتاب ص 150–151 — التآكل'),
('essay', 3, 'يعتقد بعض الناس أن الصدأ مجرد تفاعل بين الحديد والأكسجين. ناقش هذا الاعتقاد في ضوء تعريف التآكل، مستعينًا بالملاحظة الآتية: قطعة حديد في هواء جاف تبقى زمنًا طويلًا دون صدأ يُذكر، بينما تصدأ قطعة مماثلة في هواء رطب، ويصدأ هيكل سفينة في ماء البحر أسرع منهما.', null, null, 'تقويم', 'مناقشة اعتقاد', 'صعب', 'الكتاب ص 150–151 — التآكل')
