('mcq', 1, 3, 'التآكل هو خسارة الفلز الناتجة عن تفاعل أكسدة واختزال بين الفلز والمواد التي في البيئة.', '["هذا وصف الفلزات التي تحمي نفسها كالألومنيوم والكروم، لا تعريف التآكل.","هذا تعريف الجلفنة، وهي طريقة لمنع التآكل.","التآكل تفاعل أكسدة واختزال يتضمن انتقال الإلكترونات، وليس ذوبانًا فيزيائيًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-17T11:36:22.649Z"}'::jsonb),
('mcq', 2, 0, 'تآكل الحديد هو المعروف بالصدأ، وهو مثال على تفاعل أكسدة واختزال تلقائي يحدث في الطبيعة.', '["","الجلفنة تغليف الحديد بالخارصين لحمايته من التآكل.","الاحتراق تفاعل سريع مع الأكسجين ينتج ضوءًا وحرارة، أما تآكل الحديد فعملية بطيئة تحتاج إلى الماء.","التعادل تفاعل حمض مع قاعدة لا يتضمن خسارة الفلز بالأكسدة والاختزال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.649Z"}'::jsonb),
('mcq', 3, 2, 'تتحد أيونات Fe³⁺ بالأكسجين لتكوين صدأ غير ذائب صيغته Fe₂O₃، والمعادلة الكلية: 4Fe + 3O₂ → 2Fe₂O₃.', '["FeO أكسيد الحديد II، أما الصدأ فيتكون من اتحاد أيونات Fe³⁺ بالأكسجين.","Fe(OH)₂ هيدروكسيد الحديد II، وليس صيغة الصدأ.","","FeCl₃ كلوريد الحديد III، ولا يدخل الكلور في معادلة تكوّن الصدأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.649Z"}'::jsonb),
('mcq', 4, 3, 'تفاعلات الأكسدة والاختزال التلقائية تحدث في الخلايا الجلفانية، كما تحدث في الطبيعة بشكل تلقائي، ومن ذلك تآكل الحديد.', '["التآكل يحدث من تلقاء نفسه في الطبيعة دون مصدر كهربائي.","التآكل يتضمن فقد الفلز للإلكترونات، فهو ليس تفاعل ترسيب.","التآكل يحدث في درجات الحرارة العادية ولا يتضمن تحلل الفلز بالحرارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.649Z"}'::jsonb),
('mcq', 5, 1, 'الطبقة البنية على الحديد المعرّض للماء والهواء هي الصدأ Fe₂O₃، وهي خسارة للفلز ناتجة عن تفاعل أكسدة واختزال مع مواد البيئة؛ أما الخيارات الأخرى فتغيرات فيزيائية.', '["التمدد بالحرارة تغير فيزيائي لا يخسر فيه الفلز شيئًا بالأكسدة.","","الانصهار تغير في الحالة الفيزيائية، وليس تفاعل أكسدة واختزال.","الانجذاب المغناطيسي خاصية فيزيائية لا يحدث فيها تفاعل كيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.649Z"}'::jsonb),
('mcq', 6, 0, 'الصدأ يحدث عند توافر كل من الماء والأكسجين، لذا فقطعة الحديد المتروكة معرضة للهواء والرطوبة أكثر عرضة للصدأ.', '["","الصدأ يحدث عند توافر الماء والأكسجين معًا، والهواء الجاف وحده لا يكفي.","دون أكسجين لا يحدث نصف تفاعل الاختزال عند الكاثود.","الطلاء يعزل الماء والهواء عن الحديد، فهو طريقة لمنع التآكل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.649Z"}'::jsonb),
('mcq', 7, 2, 'التآكل خسارة للفلز بتفاعل أكسدة واختزال؛ فذرات الفلز تفقد إلكترونات فتتأكسد، كما في الحديد: Fe → Fe²⁺ + 2e⁻.', '["الفلز في التآكل يفقد الإلكترونات ولا يكسبها، فهو يتأكسد.","فقد الإلكترونات أكسدة لا اختزال، والناتج أيونات موجبة لا ذرات متعادلة.","","التآكل بتعريفه تفاعل أكسدة واختزال، والفلز فيه يفقد إلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.649Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التآكل: خسارة الفلز الناتجة عن تفاعل أكسدة واختزال بين الفلز والمواد التي في البيئة. مثاله: صدأ الحديد (كصدأ سياج أو أنبوب حديدي معرّض للماء والهواء). صيغة الصدأ: Fe₂O₃.', '["خسارة الفلز","ناتجة عن تفاعل أكسدة واختزال مع مواد البيئة","مثال: صدأ الحديد","الصيغة Fe₂O₃"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف كاملًا (خسارة الفلز + أكسدة واختزال مع مواد البيئة)","marks":2},{"element":"مثال صحيح","marks":1},{"element":"الصيغة الكيميائية Fe₂O₃","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل ومثال صحيح وصيغة صحيحة"},{"level":"3 درجات","description":"تعريف كامل ومثال صحيح دون الصيغة"},{"level":"2 درجتان","description":"تعريف ناقص (دون ذكر الأكسدة والاختزال) مع مثال صحيح"},{"level":"1 درجة","description":"مثال صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف التآكل بأنه تفاعل الحديد مع الأكسجين فقط","كتابة صيغة الصدأ FeO أو Fe₃O₄","الخلط بين التآكل والجلفنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.650Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لأن التآكل يتضمن انتقال الإلكترونات: فالحديد يفقد إلكترونات (يتأكسد) إلى Fe²⁺ ثم Fe³⁺، والأكسجين من الهواء يكسب هذه الإلكترونات (يُختزل). المادة المتأكسدة: الحديد Fe، والمادة المختزلة: الأكسجين O₂. المعادلة الكلية: 4Fe + 3O₂ → 2Fe₂O₃.', '["التآكل يتضمن انتقال إلكترونات","الحديد يتأكسد","الأكسجين يُختزل","المعادلة الكلية 4Fe + 3O₂ → 2Fe₂O₃"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير كون التآكل أكسدة واختزال (انتقال الإلكترونات)","marks":1},{"element":"تحديد المادة المتأكسدة","marks":1},{"element":"تحديد المادة المختزلة","marks":1},{"element":"المعادلة الكلية موزونة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح وتحديد صحيح للمادتين ومعادلة موزونة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"تحديد المادتين فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الأكسجين المادة المتأكسدة لأنه «يؤكسد»","عدم وزن المعادلة الكلية","عدّ الماء المادة المختزلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.650Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الاعتقاد غير دقيق: فالصدأ تآكل، أي خسارة للفلز بتفاعل أكسدة واختزال مع مواد البيئة، وهو تفاعل أكثر تعقيدًا من اتحاد الحديد بالأكسجين؛ إذ يحدث عند توافر الماء والأكسجين معًا. في الهواء الجاف لا يوجد ماء فلا يتكوّن محلول تنتقل فيه الأيونات، فيكاد لا يحدث صدأ. في الهواء الرطب يتوافر الماء والأكسجين فيصدأ الحديد ببطء لأن قطرات الماء تحتوي على كمية قليلة من الأيونات فهي محاليل موصلة غير جيدة. أما ماء البحر فيحتوي على كمية كبيرة من الأيونات فيصبح محلولًا موصلًا جيدًا ويحدث التآكل أسرع.', '["الحكم: الاعتقاد غير دقيق/التفاعل أكثر تعقيدًا","الصدأ يحتاج إلى الماء والأكسجين معًا","تفسير بطء الصدأ في الهواء الرطب (قلة الأيونات)","تفسير سرعة التآكل في ماء البحر (محلول موصل جيد)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على الاعتقاد مع ربطه بتعريف التآكل","marks":1},{"element":"تفسير حالة الهواء الجاف","marks":1},{"element":"تفسير حالة الهواء الرطب","marks":1},{"element":"تفسير حالة ماء البحر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مبرر وتفسير صحيح للحالات الثلاث"},{"level":"3 درجات","description":"حكم صحيح وتفسير حالتين"},{"level":"2 درجتان","description":"تفسير حالتين دون حكم مبرر"},{"level":"1 درجة","description":"ذكر أن الصدأ يحتاج إلى الماء فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير سرعة التآكل في ماء البحر بأن الملح يتفاعل مباشرة مع الحديد","إغفال دور الماء بوصفه محلولًا موصلًا","الموافقة على الاعتقاد دون نقد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.650Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
