('mcq', 1, 3, 'يبدأ الصدأ عند وجود شق أو كسر في سطح الحديد، ويصبح هذا الجزء أنود الخلية حيث تفقد ذرات الحديد إلكتروناتها: Fe → Fe²⁺ + 2e⁻.', '["حافة القطرة موقع الكاثود حيث يُختزل الأكسجين.","الهواء مصدر الأكسجين الذي يُختزل، ولا يكون أنودًا.","الصدأ ناتج التآكل وليس موقع أكسدة الحديد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.650Z"}'::jsonb),
('mcq', 2, 1, 'عند الكاثود (حافة قطرة الماء) تختزل الإلكترونات الأكسجين القادم من الهواء: O₂ + 4H⁺ + 4e⁻ → 2H₂O.', '["هذا نصف تفاعل الأكسدة الذي يحدث عند الأنود.","","هذه المعادلة الكلية لتآكل الحديد لا نصف تفاعل الكاثود.","هذه أكسدة لأيونات الحديد II في المحلول، لا اختزال عند الكاثود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.651Z"}'::jsonb),
('mcq', 3, 0, 'أيونات H⁺ تُزوَّد على الأرجح من تكوّن حمض الكربونيك الناتج عن ذوبان CO₂ من الهواء في الماء.', '["","الأكسجين لا يحتوي على هيدروجين، فلا يكون مصدرًا لأيونات H⁺.","أكسدة الحديد تنتج أيونات Fe²⁺ وإلكترونات، لا أيونات H⁺.","الصدأ غير ذائب، ولا يحتوي على هيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.651Z"}'::jsonb),
('mcq', 4, 0, 'تتأكسد ذرات الحديد عند الشق (الأنود)، وتتحرك الإلكترونات الناتجة خلال القطعة الحديدية إلى منطقة الكاثود؛ فتكون القطعة هي الدائرة الخارجية والأنود معًا.', '["","أيونات Fe²⁺ تصبح جزءًا من المحلول المائي، والذي ينتقل خلال الحديد هو الإلكترونات.","اختزال الأكسجين يحدث عند حافة قطرة الماء لا داخل الحديد.","الحديد نفسه يتأكسد عند الأنود، فهو مشارك في التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.651Z"}'::jsonb),
('mcq', 5, 1, 'تتأكسد كتل المغنيسيوم (أو الألومنيوم أو التيتانيوم) أسهل من الحديد فتصبح الأنود في خلية التآكل، ويبقى حديد الهيكل دون تآكل؛ وهذه طريقة الأنود المضحي.', '["المغنيسيوم يتأكسد لا يُختزل؛ فهو أنود مضحٍّ.","","الكتل توصل بالهيكل ولا تغطيه، فعملها ليس عزلًا كالطلاء.","لو كان أصعب تأكسدًا لتأكسد الحديد بدلًا منه ولما حماه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.651Z"}'::jsonb),
('mcq', 6, 3, 'يجب أن يكون الأنود المضحي فلزًا يتأكسد أسهل من الحديد؛ ومثاله المغنيسيوم الذي يُلف حول أنابيب الحديد المدفونة فيتآكل بدلًا منها.', '["النحاس يتأكسد أصعب من الحديد، فيبقى الحديد هو الأنود ولا يُحمى.","الرصاص أقل نشاطًا من الحديد، فلا يتأكسد بدلًا منه.","الفضة فلز قليل النشاط لا يتأكسد بدلًا من الحديد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-17T11:36:22.651Z"}'::jsonb),
('mcq', 7, 2, 'عند تشقق طبقة الخارصين يصبح الخارصين أنود الخلية الجلفانية المتكوّنة (الأنود المضحي)، فيتأكسد غطاء الخارصين بدلًا من الحديد، ويُختزل الأكسجين في الماء عند الكاثود.', '["الخارصين يتأكسد أسهل من الحديد فيصبح هو الأنود لا الكاثود.","الخارصين لا يُختزل، بل يتأكسد ويُختزل الأكسجين في الماء.","","الخارصين يفقد إلكترونات فيتأكسد إلى Zn²⁺، ولا يترسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.651Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الأنود: شق أو كسر في سطح الحديد، تتأكسد عنده ذرات الحديد: Fe → Fe²⁺ + 2e⁻، وتصبح أيونات Fe²⁺ جزءًا من المحلول المائي. تتحرك الإلكترونات خلال قطعة الحديد نفسها إلى منطقة الكاثود (فالقطعة هي الدائرة الخارجية والأنود معًا). الكاثود: حافة قطرة الماء حيث يلتقي الماء والهواء والحديد، ويُختزل عنده الأكسجين: O₂ + 4H⁺ + 4e⁻ → 2H₂O. تتأكسد أيونات Fe²⁺ في المحلول إلى Fe³⁺ بالأكسجين الذائب، وتتحد Fe³⁺ بالأكسجين لتكوين صدأ غير ذائب Fe₂O₃. المعادلة الكلية: 4Fe + 3O₂ → 2Fe₂O₃.', '["الأنود: الشق، Fe → Fe²⁺ + 2e⁻","الإلكترونات تتحرك خلال الحديد إلى الكاثود","الكاثود: حافة القطرة، O₂ + 4H⁺ + 4e⁻ → 2H₂O","تأكسد Fe²⁺ إلى Fe³⁺ وتكوّن Fe₂O₃","المعادلة الكلية 4Fe + 3O₂ → 2Fe₂O₃"]'::jsonb, '[]'::jsonb, '[{"element":"الأنود ونصف تفاعله","marks":1},{"element":"حركة الإلكترونات","marks":1},{"element":"الكاثود ونصف تفاعله","marks":1},{"element":"تكوّن الصدأ","marks":1},{"element":"المعادلة الكلية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف كامل صحيح لجميع العناصر"},{"level":"4 درجات","description":"نقص عنصر واحد"},{"level":"3 درجات","description":"الأنود والكاثود ونصفا التفاعل صحيحة دون بقية العناصر"},{"level":"2 درجتان","description":"تحديد الأنود والكاثود دون معادلات"},{"level":"1 درجة","description":"المعادلة الكلية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الكاثود في وسط القطرة أو في الشق","القول إن الإلكترونات تنتقل خلال الماء","كتابة الصدأ FeO"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.651Z"}'::jsonb),
('essay', 2, null::int, null, null, '1) الطلاء: عمل غطاء من الطلاء يعزل الماء والهواء عن الحديد، ويلزم إعادته لأنه يتلف مع الزمن. 2) الأنود المضحي: توصيل كتل من فلز يتأكسد أسهل من الحديد (مثل المغنيسيوم أو الألومنيوم أو التيتانيوم) بالحديد، فتصبح أنود خلية التآكل وتتأكسد بدلًا منه، كما في هياكل السفن والأنابيب المدفونة. 3) الجلفنة: تغليف الحديد بطبقة من الخارصين (بالغمس في مصهوره أو بالطلاء الكهربائي)؛ فتعزل الطبقة السليمة الماء والهواء، وإذا تشققت يتأكسد الخارصين بوصفه أنودًا بدلًا من الحديد.', '["الطلاء: عزل الماء والهواء","الأنود المضحي: فلز أنشط يتأكسد بدلًا من الحديد","الجلفنة: طبقة خارصين عازلة وأنود عند التشقق"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية الطرائق الثلاث","marks":3},{"element":"توضيح عمل كل طريقة (درجة لكل طريقة)","marks":3}]'::jsonb, '[{"level":"6 درجات","description":"ثلاث طرائق صحيحة مع توضيح عمل كل منها"},{"level":"4 درجات","description":"ثلاث طرائق مع توضيح طريقة واحدة، أو طريقتان مع توضيحهما"},{"level":"2 درجتان","description":"تسمية طريقتين دون توضيح"},{"level":"1 درجة","description":"تسمية طريقة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اقتراح فلز أقل نشاطًا من الحديد (كالنحاس) أنودًا مضحيًا","القول إن الجلفنة تعمل فقط عازلًا","الخلط بين الأنود المضحي والطلاء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.651Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأنود المضحي: كتل أو أسلاك من فلز يتأكسد أسهل من الحديد (Mg أو Al أو Ti) توصل بالحديد فتتأكسد بدلًا منه. الجلفنة: تغطية الحديد كله بطبقة من الخارصين. وجه الشبه: في كلتيهما يتأكسد فلز أنشط من الحديد ويصبح أنود الخلية الجلفانية فيبقى الحديد دون تآكل (الخارصين في الجلفنة المشققة يعمل أنودًا مضحيًا). تحمي الجلفنة بطريقتين: (1) ما دامت طبقة الخارصين سليمة فإنها حاجز يمنع وصول الماء والهواء إلى سطح الحديد، ويتكوّن على سطح الخارصين أكسيد يحميه؛ (2) عند تشقق الطبقة يصبح الخارصين أنود الخلية المتكوّنة فيتأكسد بدلًا من الحديد.', '["وصف الأنود المضحي","وصف الجلفنة","وجه الشبه: فلز أنشط يتأكسد بوصفه أنودًا بدلًا من الحديد","الطريقتان: حاجز عازل ثم أنود مضح عند التشقق"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الطريقتين","marks":1},{"element":"وجه الشبه","marks":1},{"element":"الطريقة الأولى للجلفنة (حاجز)","marks":1},{"element":"الطريقة الثانية للجلفنة (أنود عند التشقق)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة مع وجه الشبه وتفسير الطريقتين"},{"level":"3 درجات","description":"وجه الشبه وتفسير الطريقتين دون وصف كاف للطريقتين"},{"level":"2 درجتان","description":"تفسير إحدى طريقتي الجلفنة مع وجه الشبه"},{"level":"1 درجة","description":"وصف الطريقتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الخارصين أقل نشاطًا من الحديد","إغفال دور طبقة الخارصين السليمة بوصفها حاجزًا","القول إن الحديد يصبح أنودًا عند تشقق طبقة الخارصين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-17T11:36:22.652Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
