from (values
('mcq', 1, 2, 'حافظة الخارصين هي الأنود في الخلية الجافة، ويتأكسد عندها الخارصين: Zn → Zn²⁺ + 2e⁻.', '["عمود الكربون (الجرافيت) يعمل عمل الكاثود غير الفعال.","العجينة هي المحلول الموصل، ويحدث فيها نصف تفاعل الاختزال.","","الفواصل تعمل عمل القنطرة الملحية للسماح بحركة الأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:36:22.652Z"}'::jsonb),
('mcq', 2, 2, 'يتكوّن الكاثود في كل خلية من شبكة من الرصاص مملوءة بأكسيد الرصاص IV (PbO₂)، ويُختزل فيه الرصاص من +4 إلى +2.', '["الرصاص الإسفنجي يملأ شبكات الأنود لا الكاثود.","PbSO₄ ناتج تفاعلي الأكسدة والاختزال، وليس مادة الكاثود.","","حمض الكبريتيك هو المحلول الموصل في البطارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:36:22.652Z"}'::jsonb),
('mcq', 3, 1, 'تستعمل بطارية الفضة أكسيد الفضة Ag₂O في الكاثود بدلًا من أكسيد المنجنيز، ويُختزل وفق: Ag₂O + H₂O + 2e⁻ → 2Ag + 2OH⁻.', '["الخارصين هو أنود بطارية الفضة، كما في البطارية القلوية.","","MnO₂ كاثود البطارية القلوية، وتستعمل بطارية الفضة Ag₂O بدلًا منه.","الفضة Ag ناتج اختزال Ag₂O عند الكاثود، لا مادة الكاثود الأصلية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.652Z"}'::jsonb),
('mcq', 4, 1, 'أنود بطارية NiCad من مسحوق الكادميوم المضغوط، ويتأكسد الكادميوم في وسط قاعدي: Cd + 2OH⁻ → Cd(OH)₂ + 2e⁻.', '["NiO(OH) هو الكاثود الذي يُختزل فيه النيكل من +3 إلى +2.","","هذا أنود البطارية القلوية.","KOH هو المحلول الموصل في بطارية NiCad."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:36:22.652Z"}'::jsonb),
('mcq', 5, 0, 'في البطارية القلوية: الأنود مسحوق الخارصين، والكاثود مخلوط MnO₂ مع KOH، والمحلول الموصل عجينة KOH؛ فالصف (1) صحيح، أما الصفوف الأخرى فقد عُكس فيها القطبان.', '["","القطبان معكوسان: الأنود Pb والكاثود PbO₂.","القطبان معكوسان: الأنود Cd والكاثود NiO(OH).","القطبان معكوسان: الأنود حافظة الخارصين والكاثود عمود الكربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.653Z"}'::jsonb),
('mcq', 6, 0, 'تؤكسد بطاريات الليثيوم الليثيوم على الأنود، وتستعمل بعضها تفاعل الكاثود نفسه في الخلية الجافة: اختزال MnO₂ إلى Mn₂O₃.', '["","الليثيوم يتأكسد إلى Li⁺ فهو الأنود، وتحوّل Li إلى Li⁺ أكسدة لا اختزال.","الليثيوم هو الفلز الذي يتأكسد على الأنود بدلًا من الخارصين.","اختزال PbO₂ هو تفاعل كاثود المركم الرصاصي، لا بطاريات الليثيوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.653Z"}'::jsonb),
('mcq', 7, 3, 'التفاعل أكسدة للكادميوم في وسط قاعدي (فقد إلكترونات)، والكادميوم هو أنود بطارية NiCad؛ إذن القطب هو أنود بطارية NiCad.', '["التفاعل يطلق إلكترونات فهو أكسدة، والأكسدة تحدث عند الأنود لا الكاثود.","أنود القلوية يؤكسد الخارصين لا الكادميوم.","كاثود بطارية الفضة يختزل Ag₂O، ولا يحتوي على كادميوم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-17T11:36:22.654Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الأنود: حافظة الخارصين. الكاثود: عمود الكربون (الجرافيت) في مركز الخلية، ويسمى الكاثود غير الفعال. المحلول الموصل: عجينة رطبة من كلوريد الخارصين ZnCl₂ وأكسيد المنجنيز IV (MnO₂) وكلوريد الأمونيوم NH₄Cl وكمية قليلة من الماء.', '["الأنود: حافظة الخارصين","الكاثود: عمود الكربون","المحلول: عجينة رطبة من ZnCl₂ وMnO₂ وNH₄Cl"]'::jsonb, '[]'::jsonb, '[{"element":"الأنود","marks":1},{"element":"الكاثود","marks":1},{"element":"المحلول الموصل ومكوّناته","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحديد صحيح للثلاثة"},{"level":"2 درجتان","description":"تحديد صحيح لاثنين"},{"level":"1 درجة","description":"تحديد صحيح لواحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل عمود الكربون الأنود","ذكر KOH محلولًا موصلًا للخلية الجافة","نسيان أحد مكونات العجينة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:36:22.654Z"}'::jsonb),
('essay', 2, null::int, null, null, 'القلوية: الأنود مسحوق الخارصين (مع KOH)، والكاثود MnO₂ (مع KOH). الفضة: الأنود الخارصين، والكاثود Ag₂O. NiCad: الأنود الكادميوم Cd، والكاثود NiO(OH). المركم الرصاصي: الأنود الرصاص Pb (شبكات من الرصاص الإسفنجي)، والكاثود أكسيد الرصاص IV (PbO₂).', '["القلوية: Zn / MnO₂","الفضة: Zn / Ag₂O","NiCad: Cd / NiO(OH)","المركم: Pb / PbO₂"]'::jsonb, '[]'::jsonb, '[{"element":"القلوية (نصف درجة لكل قطب)","marks":1},{"element":"الفضة","marks":1},{"element":"NiCad","marks":1},{"element":"المركم الرصاصي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأقطاب الثمانية صحيحة"},{"level":"3 درجات","description":"ستة أقطاب صحيحة"},{"level":"2 درجتان","description":"أربعة أقطاب صحيحة"},{"level":"1 درجة","description":"قطبان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس قطبي المركم الرصاصي","جعل الفضة Ag أنود بطارية الفضة","جعل النيكل أنود بطارية NiCad"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.654Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القطب المشترك هو أنود الخارصين (حافظة الخارصين في الخلية الجافة، ومسحوق الخارصين في القلوية، والخارصين في الفضة). الكاثود: في الخلية الجافة عمود الكربون (كاثود غير فعال) ويحدث الاختزال في عجينة MnO₂؛ في القلوية مخلوط MnO₂ وKOH دون عمود كربون؛ في الفضة أكسيد الفضة Ag₂O بدلًا من MnO₂. يُعدّ الخارصين أنودًا لأنه يتأكسد (يفقد إلكترونات)، والأنود هو القطب الذي تحدث عنده الأكسدة.', '["المشترك: الخارصين أنودًا","كاثود الخلية الجافة: عمود كربون مع اختزال MnO₂ في العجينة","كاثود القلوية: MnO₂ مع KOH","كاثود الفضة: Ag₂O","الخارصين يتأكسد فهو أنود"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد القطب المشترك","marks":1},{"element":"تحديد كاثود البطاريات الثلاث","marks":2},{"element":"تعليل كونه أنودًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد القطب المشترك والكواثيد الثلاثة مع التعليل"},{"level":"3 درجات","description":"نقص كاثود واحد أو التعليل"},{"level":"2 درجتان","description":"تحديد القطب المشترك وكاثود واحد"},{"level":"1 درجة","description":"تحديد القطب المشترك فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الكربون كاثود البطارية القلوية","جعل الفضة أنود بطارية الفضة","تعريف الأنود بأنه القطب الموجب دائمًا دون ذكر الأكسدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.654Z"}'::jsonb)
