('essay', 3, 'يحتوي المحلول الموصل في كل من البطارية القلوية وبطارية NiCad وخلية الوقود الشائعة على هيدروكسيد البوتاسيوم KOH. استعن بنصف تفاعل الأنود في كل منها لتفسير حاجة هذه الخلايا إلى محلول قاعدي.', null, null, 'تحليل', 'تفسير بالمعادلات', 'صعب', 'الكتاب ص 145، 146، 149 — البطاريات القلوية وNiCad وخلية الوقود')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
