from (values
('mcq', 1, 1, 'المحلول الموصل في بطارية المركم الرصاصي محلول حمض الكبريتيك؛ ولذلك تُسمى بطارية الرصاص الحمضية، وهي بطارية غير جافة.', '["KOH محلول البطاريات القلوية وNiCad وخلية الوقود.","","هذه عجينة خلية الخارصين والكربون الجافة.","الماء المقطر موصل رديء، والبطارية تحتاج إلى محلول غني بالأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.655Z"}'::jsonb),
('mcq', 2, 2, 'في البطارية القلوية يُخلط مسحوق الخارصين مع هيدروكسيد البوتاسيوم (قاعدة قوية) على شكل عجينة توضع في علبة من الفولاذ.', '["حمض الكبريتيك محلول المركم الرصاصي.","هذه مكونات عجينة خلية الخارصين والكربون.","","غشاء PEM يُستعمل في بعض خلايا الوقود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.655Z"}'::jsonb),
('mcq', 3, 3, 'المحلول الموصل في الخلية الجافة عجينة رطبة من خليط كلوريد الخارصين وأكسيد المنجنيز IV وكلوريد الأمونيوم وكمية قليلة من الماء داخل حافظة الخارصين.', '["هذه عجينة أنود البطارية القلوية.","حمض الكبريتيك محلول المركم الرصاصي، وPbSO₄ ناتج تفاعله.","Ag₂O والجرافيت مكونات كاثود بطارية الفضة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.655Z"}'::jsonb),
('mcq', 4, 2, 'الخلية الجافة خلية جلفانية محلولها الموصل عجينة رطبة؛ أما المركم الرصاصي فمحلوله الموصل محلول حمض الكبريتيك السائل، لذا فهي بطارية غير جافة.', '["مادة الأقطاب لا تحدد كون الخلية جافة؛ المعيار هو حالة المحلول الموصل.","قابلية الشحن لا تحدد كون الخلية جافة؛ فبطارية NiCad مثلًا ثانوية.","","عدد الخلايا لا علاقة له بتعريف الخلية الجافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.655Z"}'::jsonb),
('mcq', 5, 1, 'تستعمل البطارية القلوية عجينة KOH، وتستعمل بطارية NiCad محلول KOH، فكلتاهما تستعمل محلولًا قاعديًا من هيدروكسيد البوتاسيوم.', '["المركم يستعمل حمض الكبريتيك، أما NiCad فتستعمل KOH.","","الأولى عجينة من NH₄Cl وZnCl₂، والثانية حمض الكبريتيك.","القلوية تستعمل KOH، والمركم يستعمل حمض الكبريتيك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.655Z"}'::jsonb),
('mcq', 6, 3, 'المحلول الموصل في البطارية القلوية عجينة من هيدروكسيد البوتاسيوم KOH، وهي قاعدة قوية، فسُمّيت قلوية نسبةً إلى وسطها القاعدي.', '["أنود البطارية القلوية مسحوق الخارصين، لا الليثيوم.","تفاعل كاثودها ينتج أيونات OH⁻ ولا يستهلكها.","غياب عمود الكربون يسمح بتصغير حجمها، ولا علاقة له بالتسمية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.655Z"}'::jsonb),
('mcq', 7, 0, 'يتطلب عمل الخلية محلولًا موصلًا حتى تستطيع الأيونات الانتقال بين الأقطاب، بينما تنتقل الإلكترونات عبر الدائرة الخارجية.', '["","الإلكترونات تنتقل عبر الدائرة الخارجية لا عبر المحلول.","المحلول لا يمنع الأكسدة، بل قد يشارك فيها كأيونات OH⁻ في القلوية.","التزويد بالوقود من مصدر خارجي صفة خلايا الوقود لا وظيفة المحلول الموصل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.655Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخلية الجافة: عجينة رطبة من ZnCl₂ وMnO₂ وNH₄Cl وقليل من الماء. القلوية: عجينة من هيدروكسيد البوتاسيوم KOH. NiCad: محلول هيدروكسيد البوتاسيوم KOH. المركم الرصاصي: محلول حمض الكبريتيك H₂SO₄.', '["الجافة: عجينة رطبة (ZnCl₂، MnO₂، NH₄Cl)","القلوية: عجينة KOH","NiCad: KOH","المركم: H₂SO₄"]'::jsonb, '[]'::jsonb, '[{"element":"الخلية الجافة","marks":1},{"element":"البطارية القلوية","marks":1},{"element":"NiCad","marks":1},{"element":"المركم الرصاصي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المحاليل الأربعة صحيحة"},{"level":"3 درجات","description":"ثلاثة صحيحة"},{"level":"2 درجتان","description":"اثنان صحيحان"},{"level":"1 درجة","description":"واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر حمض الكبريتيك لبطارية NiCad","ذكر KOH للخلية الجافة","ذكر الماء وحده محلولًا موصلًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T11:36:22.655Z"}'::jsonb),
('essay', 2, null::int, null, null, 'خلية الخارصين والكربون: المحلول الموصل عجينة رطبة من ZnCl₂ وMnO₂ وNH₄Cl مع قليل من الماء؛ لذا تُسمى خلية جافة (الخلية الجافة خلية جلفانية محلولها الموصل عجينة رطبة). المركم الرصاصي: المحلول الموصل محلول سائل من حمض الكبريتيك؛ لذا فهي بطارية غير جافة، وتُسمى بطارية الرصاص الحمضية نسبة إلى هذا الحمض.', '["الجافة: عجينة رطبة ومكوناتها","المركم: محلول سائل من H₂SO₄","التسمية: جافة لأن المحلول عجينة","التسمية: الحمضية لأن المحلول حمض الكبريتيك"]'::jsonb, '[]'::jsonb, '[{"element":"المحلول في الخلية الجافة","marks":1},{"element":"المحلول في المركم الرصاصي","marks":1},{"element":"ربط تسمية الخلية الجافة","marks":1},{"element":"ربط تسمية البطارية الحمضية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة وربط صحيح للتسميتين"},{"level":"3 درجات","description":"مقارنة كاملة وربط تسمية واحدة"},{"level":"2 درجتان","description":"تحديد المحلولين دون ربط بالتسمية"},{"level":"1 درجة","description":"تحديد محلول واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الخلية الجافة لا تحتوي على أي ماء","ربط تسمية «الحمضية» بالرصاص","وصف محلول المركم بأنه عجينة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T11:36:22.656Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نصف تفاعل الأنود في كل منها يستهلك أيونات الهيدروكسيد OH⁻: القلوية: Zn + 2OH⁻ → ZnO + H₂O + 2e⁻. NiCad: Cd + 2OH⁻ → Cd(OH)₂ + 2e⁻. خلية الوقود: 2H₂ + 4OH⁻ → 4H₂O + 4e⁻. لذا يلزم وسط قاعدي يوفر أيونات OH⁻ اللازمة لأكسدة الأنود، ويوفرها KOH وهو قاعدة قوية، فضلًا عن أن المحلول ينقل الأيونات بين القطبين.', '["أنود القلوية يستهلك OH⁻","أنود NiCad يستهلك OH⁻","أنود خلية الوقود يستهلك OH⁻","الاستنتاج: KOH يوفر OH⁻ اللازمة"]'::jsonb, '[]'::jsonb, '[{"element":"نصف تفاعل أنود القلوية","marks":1},{"element":"نصف تفاعل أنود NiCad","marks":1},{"element":"نصف تفاعل أنود خلية الوقود","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أنصاف التفاعلات الثلاثة صحيحة مع استنتاج سليم"},{"level":"3 درجات","description":"نصفا تفاعل صحيحان مع الاستنتاج"},{"level":"2 درجتان","description":"أنصاف تفاعلات صحيحة دون استنتاج"},{"level":"1 درجة","description":"الاستنتاج فقط أو نصف تفاعل واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة أنصاف تفاعلات الكاثود بدلًا من الأنود","القول إن KOH يتأكسد عند الأنود","إغفال ربط OH⁻ بتفاعل الأنود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.656Z"}'::jsonb)
