('mcq', 5, 'صُنعت بطاريتان بالحجم نفسه: أنود الأولى حافظة من الخارصين، وأنود الثانية مسحوق خارصين في عجينة KOH. أيّهما يُتوقع أن تكون أكثر كفاءة، ولماذا؟', null, '["الأولى؛ لأن حافظة الخارصين تعمل أنودًا وغلافًا معًا","الأولى؛ لأن عمود الكربون فيها يوصل الإلكترونات","الثانية؛ لأن الخارصين فيها لا يتأكسد","الثانية؛ لأن مسحوق الخارصين يوفر مساحة سطح أكبر للتفاعل"]'::jsonb, 'تحليل', 'تطبيق على موقف', 'صعب', 'الكتاب ص 145 — البطاريات القلوية'),
('mcq', 6, 'يُكتب تفاعل الكاثود في خلية الخارصين والكربون: 2NH₄⁺ + 2MnO₂ + 2e⁻ → Mn₂O₃ + 2NH₃ + H₂O، وفي البطارية القلوية: MnO₂ + 2H₂O + 2e⁻ → Mn(OH)₂ + 2OH⁻. ما الميزة التي تظهرها المقارنة للبطارية القلوية؟', null, '["يستهلك تفاعل كاثودها أيونات NH₄⁺ بدلًا من الماء","لا يُختزل فيها MnO₂ عند الكاثود","لا ينتج عن تفاعل كاثودها الأمونيا التي يخفض انطلاقها غازًا جهد الخلية","يحدث تفاعل كاثودها على عمود كربون غير فعال"]'::jsonb, 'تحليل', 'مقارنة معادلات', 'صعب', 'الكتاب ص 144–145 — الخلايا الجافة؛ البطاريات القلوية'),
('mcq', 7, 'لماذا حلّت الخلية القلوية محل خلية الخارصين والكربون الجافة في كثير من التطبيقات؟', null, '["لأنها أكثر كفاءة","لأنها قابلة للشحن","لأنها أكبر حجمًا","لأن أنودها من الكربون"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 145 — البطاريات القلوية'),
('essay', 1, 'علّل: تُفضَّل البطارية القلوية على خلية الخارصين والكربون الجافة. اذكر ثلاثة أسباب مستندة إلى تركيب البطاريتين.', null, null, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 145 — البطاريات القلوية'),
('essay', 2, 'قارن بين خلية الخارصين والكربون الجافة والبطارية القلوية من حيث: هيئة الخارصين في الأنود، والكاثود، والمحلول الموصل، وإمكانية تصنيعها بأحجام صغيرة.', null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 144–145 — الخلايا الجافة؛ البطاريات القلوية'),
('essay', 3, 'تريد شركة اختيار بطارية لجهاز تحكم صغير الحجم يُستعمل مدة طويلة، وعُرض عليها نوعان: خلية الخارصين والكربون الجافة، والبطارية القلوية. أيّهما توصي به؟ قوّم الخيارين مقدمًا ثلاث حجج علمية.', null, null, 'تقويم', 'اتخاذ قرار مع تبرير', 'صعب', 'الكتاب ص 144–145 — الخلايا الجافة؛ البطاريات القلوية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
