select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'يوجد الخارصين في الخلية القلوية على هيئة مسحوق يُخلط مع هيدروكسيد البوتاسيوم على شكل عجينة توضع في علبة من الفولاذ.', '["حافظة الخارصين هيئة الأنود في خلية الخارصين والكربون.","العمود في مركز الخلية الجافة من الكربون، والقلوية لا تحتاج إليه.","","لا يوجد محلول حمضي في البطارية القلوية؛ محلولها عجينة KOH القاعدية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.656Z"}'::jsonb),
('mcq', 2, 0, 'وجود الخارصين على هيئة مسحوق يوفر مساحة سطح أكبر للتفاعل، وهذا من أسباب كفاءة البطارية القلوية.', '["","الخارصين في القلوية يتأكسد عند الأنود فعلًا، والمسحوق يسرّع ذلك.","الذي يسمح بحركة الأيونات هو المحلول الموصل والفواصل، لا مسحوق الأنود.","MnO₂ مع KOH يقوم مقام الكاثود، والخارصين هو الأنود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.656Z"}'::jsonb),
('mcq', 3, 3, 'لا تحتاج البطاريات القلوية إلى عمود الكربون بوصفه كاثودًا (يقوم مخلوط MnO₂ وKOH مقامه)؛ لذا يمكن تصنيعها بأحجام صغيرة، ولها استعمالات متعددة في الأجهزة الصغيرة.', '["محلول القلوية عجينة KOH، وحمض الكبريتيك محلول المركم الرصاصي.","الخارصين في القلوية مسحوق، لا حافظة.","القلوية بطارية أولية، وقابلية الشحن لا تحدد الحجم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.657Z"}'::jsonb),
('mcq', 4, 1, 'يقوم مخلوط من ثاني أكسيد المنجنيز وهيدروكسيد البوتاسيوم مقام الكاثود في البطارية القلوية، ويُختزل MnO₂ وفق: MnO₂ + 2H₂O + 2e⁻ → Mn(OH)₂ + 2OH⁻.', '["لا تحتاج القلوية إلى عمود الكربون، وهذا سبب إمكانية تصغيرها.","","علبة الفولاذ وعاء للعجينة، وليست مادة تُختزل.","مسحوق الخارصين هو الأنود الذي يتأكسد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.657Z"}'::jsonb),
('mcq', 5, 3, 'البطارية الثانية قلوية، والأولى خلية خارصين وكربون. القلوية أكثر كفاءة لأن الخارصين فيها مسحوق يوفر مساحة سطح أكبر للتفاعل.', '["عمل الحافظة غلافًا لا يزيد الكفاءة، والقلوية أكثر كفاءة.","عمود الكربون كاثود غير فعال، ووجوده يزيد الحجم ولا يزيد الكفاءة.","الخارصين في القلوية يتأكسد عند الأنود؛ وإلا لما أنتجت تيارًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.657Z"}'::jsonb),
('mcq', 6, 2, 'تنتج الخلية الجافة الأمونيا NH₃، وعندما يبدأ انطلاقها غازًا ينخفض الجهد إلى مستوى يجعل البطارية غير نافعة؛ أما كاثود القلوية فينتج Mn(OH)₂ وOH⁻ دون أمونيا.', '["العكس: كاثود القلوية يستهلك الماء، أما NH₄⁺ فتستهلك في الخلية الجافة.","MnO₂ يُختزل في البطاريتين كما تبين المعادلتان.","","القلوية لا تحتاج إلى عمود كربون؛ العمود في الخلية الجافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.657Z"}'::jsonb),
('mcq', 7, 0, 'الخلية القلوية الجافة الأكثر كفاءة حلت محل خلية الخارصين والكربون الجافة في الكثير من التطبيقات.', '["","القلوية بطارية أولية لا يُعاد شحنها.","القلوية يمكن تصنيعها بأحجام أصغر، وهذه من مزاياها.","لا تحتوي القلوية على عمود كربون، وأنودها الخارصين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.657Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) الخارصين في القلوية مسحوق يوفر مساحة سطح أكبر للتفاعل، فهي أكثر كفاءة. 2) لا تحتاج القلوية إلى عمود كربون بوصفه كاثودًا، فيمكن تصنيعها بأحجام صغيرة تناسب الأجهزة الصغيرة. 3) خلية الخارصين والكربون تنتج 1.5 V حتى يبدأ انطلاق الأمونيا الناتجة عن تفاعل الاختزال غازًا، فينخفض جهدها إلى مستوى يجعلها غير نافعة، والقلوية لا ينتج عن كاثودها أمونيا.', '["مسحوق الخارصين: مساحة سطح أكبر وكفاءة أعلى","لا عمود كربون: أحجام صغيرة","انخفاض جهد الخلية الجافة عند انطلاق الأمونيا"]'::jsonb, '[]'::jsonb, '[{"element":"السبب الأول","marks":1},{"element":"السبب الثاني","marks":1},{"element":"السبب الثالث","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة أسباب صحيحة مرتبطة بالتركيب"},{"level":"2 درجتان","description":"سببان صحيحان"},{"level":"1 درجة","description":"سبب واحد أو ذكر «أكثر كفاءة» دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القلوية قابلة للشحن","القول إن القلوية لا تحتوي على خارصين","ذكر «أرخص» سببًا دون أساس علمي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.657Z"}'::jsonb),
('essay', 2, null::int, null, null, 'هيئة الخارصين: حافظة في الخلية الجافة، ومسحوق في القلوية. الكاثود: عمود كربون (كاثود غير فعال) مع اختزال MnO₂ في العجينة في الجافة، ومخلوط MnO₂ وKOH في القلوية. المحلول الموصل: عجينة رطبة من ZnCl₂ وMnO₂ وNH₄Cl في الجافة، وعجينة KOH في القلوية. الحجم: الجافة تحتاج إلى عمود الكربون، أما القلوية فلا تحتاج إليه فيمكن تصنيعها بأحجام صغيرة.', '["هيئة الخارصين","الكاثود","المحلول الموصل","الحجم وعمود الكربون"]'::jsonb, '[]'::jsonb, '[{"element":"هيئة الخارصين","marks":1},{"element":"الكاثود","marks":1},{"element":"المحلول الموصل","marks":1},{"element":"إمكانية التصغير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الجوانب الأربعة"},{"level":"3 درجات","description":"ثلاثة جوانب صحيحة"},{"level":"2 درجتان","description":"جانبان صحيحان"},{"level":"1 درجة","description":"جانب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل عمود الكربون جزءًا من القلوية","عكس المحلولين الموصلين","القول إن الخلية الجافة أصغر حجمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.658Z"}'::jsonb),
('essay', 3, null::int, null, null, 'أوصي بالبطارية القلوية. الحجج: 1) أكثر كفاءة؛ لأن الخارصين فيها مسحوق يوفر مساحة سطح أكبر للتفاعل. 2) لا تحتاج إلى عمود كربون كاثودًا فيمكن تصنيعها بأحجام صغيرة تناسب الأجهزة الصغيرة. 3) خلية الخارصين والكربون ينخفض جهدها (1.5 V) إلى مستوى غير نافع عندما يبدأ انطلاق غاز الأمونيا الناتج عن تفاعل الاختزال، فلا تناسب الاستعمال الطويل. ويقبل أي حجة علمية صحيحة.', '["التوصية بالقلوية","حجة الكفاءة ومساحة السطح","حجة الحجم الصغير (لا عمود كربون)","حجة انخفاض جهد الخلية الجافة بالأمونيا"]'::jsonb, '[]'::jsonb, '[{"element":"التوصية الصحيحة","marks":1},{"element":"الحجة الأولى","marks":1},{"element":"الحجة الثانية","marks":1},{"element":"الحجة الثالثة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توصية صحيحة بثلاث حجج علمية صحيحة"},{"level":"3 درجات","description":"توصية صحيحة بحجتين"},{"level":"2 درجتان","description":"توصية صحيحة بحجة واحدة"},{"level":"1 درجة","description":"توصية صحيحة دون حجج"},{"level":"صفر","description":"توصية خاطئة أو لا إجابة"}]'::jsonb, '["التوصية بالقلوية لأنها «قابلة للشحن»","الاستناد إلى السعر بدل الخواص العلمية","إغفال ربط الحجم الصغير بغياب عمود الكربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.658Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
