from (values
('mcq', 1, 'بماذا تختلف خلايا الوقود عن البطاريات الأخرى؟', null, '["يُعاد شحنها بمصدر كهربائي خارجي","تُزوَّد بالوقود باستمرار من مصدر خارجي","لا تحتوي على أنود وكاثود","لا تعتمد على تفاعل أكسدة واختزال"]'::jsonb, 'تذكر', 'تمييز', 'سهل', 'الكتاب ص 148 — خلايا الوقود'),
('mcq', 2, 'إلى متى تستمر خلية الوقود في إنتاج الكهرباء؟', null, '["ما دام الوقود متوافرًا","حتى يُستهلك أنود الخلية كله","حتى يتحول المحلول الموصل إلى ماء","حتى ينطلق غاز الأمونيا"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('mcq', 3, 'ما المادة التي تتأكسد في خلية وقود الهيدروجين – الأكسجين؟', null, '["أقطاب الكربون المسامية","غاز الأكسجين المزوَّد عند الكاثود","غاز الهيدروجين المزوَّد من الخارج","أيونات K⁺ في المحلول الموصل"]'::jsonb, 'فهم', 'تحديد', 'متوسط', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('mcq', 4, 'لماذا تنفد البطارية القلوية بينما لا تنفد خلية الوقود؟', null, '["لأن مواد القلوية المتفاعلة مخزونة فيها وتُستهلك، أما وقود الخلية فيُعوَّض من الخارج","لأن القلوية تحتوي على أنود وكاثود وخلية الوقود لا تحتوي عليهما","لأن تفاعل القلوية غير تلقائي وتفاعل خلية الوقود تلقائي","لأن خلية الوقود بطارية ثانوية تعيد شحن نفسها ذاتيًا"]'::jsonb, 'تحليل', 'مقارنة وتعليل', 'صعب', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('mcq', 5, 'توقفت خلية وقود هيدروجين – أكسجين في مركبة فضائية عن إنتاج التيار. ما السبب الأرجح لذلك؟', null, '["تآكل قطبي الكربون بعد أكسدتهما","نفاد أيونات OH⁻ من المحلول الموصل","تحوّل تفاعلها إلى تفاعل غير تلقائي","انقطاع تزويدها بغاز الهيدروجين"]'::jsonb, 'تطبيق', 'تفسير موقف', 'متوسط', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('mcq', 6, 'أيّ مما يأتي يلزم تزويد خلية وقود الهيدروجين به باستمرار لتستمر في العمل؟', null, '["محلول جديد من KOH","أقطاب كربون جديدة","طاقة كهربائية خارجية","غازا الهيدروجين والأكسجين"]'::jsonb, 'فهم', 'استنتاج', 'سهل', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('mcq', 7, 'لماذا تُعدّ خلايا وقود الهيدروجين مناسبة لتزويد سفن الفضاء بالطاقة في الرحلات الطويلة؟', null, '["لأنها تعيد شحن نفسها دون الحاجة إلى وقود","لأنها تنتج الكهرباء ما دام الوقود متوافرًا، وناتجها الماء الذي يحتاج إليه الرواد","لأن ناتجها ثاني أكسيد الكربون الذي يستفيد منه الرواد","لأنها بطاريات أولية خفيفة تُستعمل مرة واحدة ثم تُرمى"]'::jsonb, 'تحليل', 'تطبيق في سياق', 'صعب', 'الكتاب ص 148–149 — خلايا الوقود'),
('essay', 1, 'علّل: لا تنفد خلية الوقود مثل سائر البطاريات.', null, null, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 149 — كيف تعمل خلية الوقود'),
('essay', 2, 'قارن بين بطارية NiCad وخلية وقود الهيدروجين من حيث الطريقة التي يستمر بها كل منهما في تزويد الأجهزة بالطاقة الكهربائية على المدى الطويل.', null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 146، 149 — بطاريات NiCad؛ خلايا الوقود'),
('essay', 3, 'استند إلى نصفي تفاعل خلية الوقود القلوية والمعادلة الكلية لتفسير أن أقطاب الخلية ومحلولها الموصل لا تُستهلك، ثم بيّن ما يحدث للخلية إذا استمر تزويدها بالوقود والأكسجين، وما الناتج الإضافي إذا استُعمل الميثان وقودًا بدل الهيدروجين.', null, null, 'تحليل', 'تفسير بالمعادلات', 'صعب', 'الكتاب ص 149 — كيف تعمل خلية الوقود')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
