from (values
('mcq', 1, 1, 'خلايا الوقود تختلف عن البطاريات الأخرى لأنها تزود بالوقود باستمرار من مصدر خارجي.', '["إعادة الشحن صفة البطاريات الثانوية، أما خلية الوقود فتُزوَّد بالوقود.","","لخلية الوقود أنود وكاثود كسائر الخلايا الجلفانية.","خلية الوقود خلية جلفانية تنتج الكهرباء من أكسدة الوقود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.658Z"}'::jsonb),
('mcq', 2, 0, 'لما كانت خلية الوقود تُزوَّد بالوقود من مصدر خارجي فإنها لا تنفد مثل سائر البطاريات، وتستمر في إنتاج الكهرباء ما دام الوقود متوافرًا.', '["","قطب الكربون المسامي لا يُستهلك في التفاعل، والذي يتأكسد هو الوقود.","أيونات OH⁻ المستهلكة عند الأنود تُعوَّض عند الكاثود، فلا ينفد المحلول.","انطلاق الأمونيا سبب انخفاض جهد خلية الخارصين والكربون، لا خلية الوقود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.658Z"}'::jsonb),
('mcq', 3, 2, 'الهيدروجين هو الوقود الذي يتأكسد عند الأنود (2H₂ + 4OH⁻ → 4H₂O + 4e⁻)، ويُزوَّد من مصدر خارجي، فلا تنفد مادة متأكسدة مخزونة داخل الخلية.', '["الأقطاب أوعية يحدث عليها التفاعل ولا تُستهلك، ولذا لا تنفد الخلية.","الأكسجين يكسب إلكترونات عند الكاثود فهو يُختزل.","","أيونات K⁺ لا تشارك في نصفي التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.658Z"}'::jsonb),
('mcq', 4, 0, 'الخارصين وMnO₂ في القلوية كمية محدودة داخل البطارية تُستهلك فتنفد، بينما تُزوَّد خلية الوقود بالمادة المتأكسدة (الوقود) باستمرار من مصدر خارجي فلا تنفد.', '["","لخلية الوقود أنود وكاثود أيضًا.","التفاعل في البطاريتين تلقائي لأنهما خليتان جلفانيتان.","خلية الوقود لا تُشحن، بل تُزوَّد بالوقود من مصدر خارجي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.659Z"}'::jsonb),
('mcq', 5, 3, 'تستمر خلية الوقود في إنتاج الكهرباء ما دام الوقود متوافرًا؛ فإذا توقفت فالسبب الأرجح انقطاع الوقود (الهيدروجين) القادم من المصدر الخارجي.', '["قطبا الكربون لا يتأكسدان في تفاعل الخلية.","أيونات OH⁻ المستهلكة عند الأنود تُعوَّض بما ينتج عند الكاثود.","تفاعل H₂ مع O₂ تلقائي ما دامت المواد المتفاعلة متوافرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.659Z"}'::jsonb),
('mcq', 6, 3, 'المواد المتفاعلة في التفاعل الكلي 2H₂ + O₂ → 2H₂O هي الهيدروجين والأكسجين، فيلزم تزويدهما باستمرار، أما الأقطاب والمحلول فلا تُستهلك.', '["المحلول الموصل لا يُستهلك؛ فأيونات OH⁻ تُعوَّض عند الكاثود.","الأقطاب لا تُستهلك في التفاعل.","خلية الوقود تنتج الكهرباء ولا تحتاج إلى مصدر كهربائي كالبطارية الثانوية عند شحنها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.659Z"}'::jsonb),
('mcq', 7, 1, 'يحتاج رواد الفضاء إلى الماء ومصدر كهربائي موثوق، وخلية وقود الهيدروجين تزود السفينة بالكهرباء ما دام الوقود متوافرًا وتنتج الماء دون مواد جانبية يجب التخلص منها.', '["خلية الوقود لا تعمل دون وقود، ولا تُشحن.","","ناتج خلية الهيدروجين الماء فقط، ولا ينتج CO₂.","خلية الوقود لا تُصنَّف بطارية أولية، وهي لا تنفد ما دام الوقود متوافرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.659Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لأن خلية الوقود تُزوَّد بالوقود (المادة التي تتأكسد مثل الهيدروجين) باستمرار من مصدر خارجي، فلا تعتمد على كمية محدودة من المواد المخزونة داخلها؛ لذا تستمر في إنتاج الكهرباء ما دام الوقود متوافرًا.', '["التزويد المستمر بالوقود من مصدر خارجي","تستمر في إنتاج الكهرباء ما دام الوقود متوافرًا"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر التزويد المستمر بالوقود من مصدر خارجي","marks":1},{"element":"ربط ذلك باستمرار إنتاج الكهرباء ما دام الوقود متوافرًا","marks":1}]'::jsonb, '[{"level":"2 درجتان","description":"تعليل كامل يذكر المصدر الخارجي واستمرار الإنتاج"},{"level":"1 درجة","description":"ذكر أحد العنصرين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن خلية الوقود تعيد شحن نفسها","القول إن تفاعلها عكسي","القول إن أقطابها لا تتفاعل دون ذكر الوقود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (2 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.659Z"}'::jsonb),
('essay', 2, null::int, null, null, 'بطارية NiCad: بطارية ثانوية تحتوي على كمية محدودة من المواد المتفاعلة (Cd وNiO(OH)) تُستهلك في أثناء توليد التيار فتنفد شحنتها، ثم يُعاد شحنها بوصلها بمصدر كهربائي يزودها بطاقة تعكس التفاعل فتُستعاد المواد المتفاعلة. خلية الوقود: لا تُشحن، بل تُزوَّد بالوقود (H₂) والأكسجين باستمرار من مصدر خارجي، فلا تنفد وتستمر في إنتاج الكهرباء ما دام الوقود متوافرًا.', '["NiCad: مواد محدودة تُستهلك","NiCad: إعادة الشحن تعكس التفاعل","خلية الوقود: تزويد مستمر بالوقود من الخارج","خلية الوقود: لا تنفد ما دام الوقود متوافرًا"]'::jsonb, '[]'::jsonb, '[{"element":"وصف NiCad (استهلاك المواد)","marks":1},{"element":"وصف إعادة شحن NiCad","marks":1},{"element":"وصف تزويد خلية الوقود","marks":1},{"element":"استمرار خلية الوقود ما دام الوقود متوافرًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة صحيحة"},{"level":"3 درجات","description":"مقارنة صحيحة مع نقص عنصر"},{"level":"2 درجتان","description":"وصف صحيح لإحداهما فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن خلية الوقود تُشحن كبطارية NiCad","القول إن NiCad لا تنفد","الخلط بين الشحن والتزويد بالوقود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.659Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأنود: 2H₂ + 4OH⁻ → 4H₂O + 4e⁻، والكاثود: O₂ + 2H₂O + 4e⁻ → 4OH⁻، والمعادلة الكلية: 2H₂ + O₂ → 2H₂O. لا يظهر الكربون (مادة الأقطاب) في أي معادلة فهو لا يُستهلك، وأيونات OH⁻ التي تُستهلك عند الأنود تُعوَّض بالأيونات الناتجة عند الكاثود فلا تظهر في المعادلة الكلية، فالمحلول لا ينفد. المواد المستهلكة هي H₂ وO₂ فقط، وهي تُزوَّد من مصدر خارجي، لذا تستمر الخلية في إنتاج الكهرباء ما دام الوقود متوافرًا. إذا استُعمل الميثان بدل الهيدروجين فقد يؤدي إلى إنتاج ثاني أكسيد الكربون، وهو من غازات الدفيئة.', '["الكربون لا يظهر في المعادلات فلا يُستهلك","OH⁻ تُستهلك عند الأنود وتُعوَّض عند الكاثود","المستهلك H₂ وO₂ يُزوَّدان من الخارج فتستمر الخلية","الميثان ينتج CO₂"]'::jsonb, '[]'::jsonb, '[{"element":"عدم استهلاك الأقطاب","marks":1},{"element":"تعويض OH⁻ وعدم استهلاك المحلول","marks":1},{"element":"استمرار الخلية ما دام الوقود متوافرًا","marks":1},{"element":"ناتج الميثان CO₂","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مستند إلى المعادلات مع ذكر CO₂"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن KOH يُستهلك ويجب تجديده","إغفال دور الكاثود في تعويض OH⁻","القول إن الميثان لا ينتج إلا الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.659Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
