('mcq', 2, 'ما المقصود بالخلية الجافة؟', null, '["خلية جلفانية لا تحتوي على أي ماء إطلاقًا","خلية جلفانية يكون المحلول الموصل فيها عجينة رطبة","بطارية ثانوية محلولها الموصل حمض الكبريتيك","خلية جلفانية قطباها من الفلز نفسه"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 144 — الخلايا الجافة'),
('mcq', 3, 'تتكون معظم بطاريات السيارات من 6 خلايا داخل غلاف واحد. لماذا يصح تسميتها بطارية واحدة؟', null, '["لأن الخلايا الست تشترك في أنود واحد من الخارصين","لأن الخلايا الست خلايا جافة محلولها عجينة رطبة","لأن البطارية خلية جلفانية أو أكثر في عبوة واحدة","لأن البطارية لا تتكون إلا من خلية جلفانية واحدة"]'::jsonb, 'فهم', 'تطبيق التعريف', 'متوسط', 'الكتاب ص 144، 146 — الخلايا الجافة؛ المركم الرصاصي'),
('mcq', 4, 'ما الذي يجعل خلية الخارصين والكربون خلية جافة رغم احتوائها على قليل من الماء؟', null, '["أن محلولها الموصل عجينة رطبة لا محلول سائل","أن أنودها حافظة صلبة من الخارصين","أن تفاعلها لا يحدث عكسيًا بسهولة","أن الماء فيها لا يشارك في أي تفاعل"]'::jsonb, 'فهم', 'تفسير التعريف', 'متوسط', 'الكتاب ص 144 — الخلايا الجافة'),
('mcq', 5, 'ما نوع الخلية التي تتكوّن منها البطاريات؟', null, '["خلية إلكتروليتية تحدث فيها تفاعلات غير تلقائية","خلية تحدث فيها تفاعلات تعادل بين حمض وقاعدة","خلية جلفانية تحدث فيها تفاعلات أكسدة واختزال تلقائية","خلية تحوّل الطاقة الضوئية إلى طاقة كهربائية"]'::jsonb, 'تذكر', 'تصنيف', 'سهل', 'الكتاب ص 144 — الخلايا الجافة'),
('mcq', 6, 'اعتمادًا على الجدول الآتي، أيّ الخلايا ينطبق عليها تعريف الخلية الجافة؟', '{"headers":["الخلية","القطبان","المحلول الموصل"],"rows":[["(1)","Zn وCu","محلولا ZnSO₄ وCuSO₄ في كأسين بينهما قنطرة ملحية"],["(2)","حافظة Zn وعمود كربون","عجينة رطبة من ZnCl₂ وMnO₂ وNH₄Cl"],["(3)","Pb وPbO₂","محلول حمض الكبريتيك"],["(4)","وعاءان من كربون مسامي","محلول KOH"]]}'::jsonb, '["الخلية (1)","الخلية (3)","الخلية (4)","الخلية (2)"]'::jsonb, 'تحليل', 'تطبيق التعريف على بيانات', 'صعب', 'الكتاب ص 144 — الخلايا الجافة'),
('mcq', 7, 'أيّ العبارات الآتية صحيحة؟', null, '["كل خلية جافة خلية جلفانية، وليست كل خلية جلفانية خلية جافة","كل خلية جلفانية خلية جافة، وليست كل خلية جافة جلفانية","الخلية الجافة خلية إلكتروليتية لأنها تحتوي على عجينة","البطارية تتكوّن دائمًا من خلية جلفانية واحدة فقط"]'::jsonb, 'تحليل', 'علاقة بين مفهومين', 'صعب', 'الكتاب ص 144 — الخلايا الجافة'),
('essay', 1, 'عرّف كلًّا من: البطارية، والخلية الجافة، وأعطِ مثالًا على خلية جافة.', null, null, 'تذكر', 'تعريف', 'متوسط', 'الكتاب ص 144 — الخلايا الجافة'),
('essay', 2, 'تتكوّن بطارية سيارة من 6 خلايا جلفانية في غلاف واحد، تولد كل خلية 2 V، والمحلول الموصل فيها محلول حمض الكبريتيك. احسب جهد البطارية، ووضّح كيف ينطبق عليها تعريف البطارية، ولماذا لا تُعدّ خلية جافة.', null, null, 'فهم', 'تطبيق التعريف', 'متوسط', 'الكتاب ص 144، 146 — الخلايا الجافة؛ المركم الرصاصي'),
('essay', 3, 'حدّد أيّ مما يأتي خلية جافة وأيّها ليس كذلك، مع التعليل بالاستناد إلى التعريف: خلية الخارصين والكربون، والبطارية القلوية، وبطارية المركم الرصاصي، وخلية الوقود القلوية.', null, null, 'تحليل', 'تصنيف مع تبرير', 'صعب', 'الكتاب ص 144–149 — الخلايا الجافة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
