('mcq', 1, 1, 'البطارية خلية جلفانية أو أكثر في عبوة واحدة تنتج التيار الكهربائي.', '["البطارية خلية جلفانية تنتج الكهرباء من تفاعل تلقائي، لا خلية إلكتروليتية.","","هذا تعريف الخلية الجافة، وهي نوع من البطاريات.","هذا وصف خلية الوقود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.660Z"}'::jsonb),
('mcq', 2, 1, 'الخلية الجافة خلية جلفانية يكون المحلول الموصل فيها عجينة رطبة، ومثالها خلية الخارصين والكربون.', '["عجينة الخلية الجافة رطبة تحتوي على كمية قليلة من الماء.","","هذا وصف المركم الرصاصي، وهو بطارية غير جافة.","تعريف الخلية الجافة يتعلق بالمحلول الموصل لا بمادة القطبين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.660Z"}'::jsonb),
('mcq', 3, 2, 'بحسب التعريف، البطارية خلية جلفانية أو أكثر في عبوة واحدة تنتج التيار الكهربائي؛ والخلايا الست في عبوة واحدة فهي بطارية واحدة.', '["أنود كل خلية في المركم من الرصاص، ولا يشترط التعريف أنودًا مشتركًا.","محلول المركم حمض الكبريتيك السائل، فهي ليست جافة.","","التعريف يشمل خلية واحدة أو أكثر في عبوة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.660Z"}'::jsonb),
('mcq', 4, 0, 'الخلية الجافة خلية جلفانية يكون المحلول الموصل فيها عجينة رطبة؛ وعجينة الخارصين والكربون رطبة تحتوي على قليل من الماء، فهي جافة لأن المحلول ليس سائلًا.', '["","مادة الأنود لا تحدد تعريف الخلية الجافة.","هذا يجعلها بطارية أولية، لا خلية جافة.","الماء من نواتج نصف تفاعل الاختزال فيها، والمعيار هو هيئة المحلول الموصل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.660Z"}'::jsonb),
('mcq', 5, 2, 'الفكرة الرئيسة للدرس: البطاريات خلايا جلفانية تستعمل التفاعلات التلقائية (أكسدة واختزال) لإنتاج الطاقة لأغراض متعددة.', '["الخلية الإلكتروليتية تستهلك الكهرباء، والبطارية تنتجها.","إنتاج الكهرباء في البطارية يعتمد على انتقال الإلكترونات في الأكسدة والاختزال.","","هذه الخلية الشمسية، والبطارية تحول الطاقة الكيميائية إلى كهربائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.661Z"}'::jsonb),
('mcq', 6, 3, 'الخلية الجافة خلية جلفانية محلولها الموصل عجينة رطبة، ولا ينطبق ذلك إلا على الخلية (2) ذات العجينة الرطبة داخل حافظة الخارصين.', '["محلولاها مائيان سائلان في كأسين، فهي خلية جلفانية غير جافة.","محلولها الموصل محلول سائل من حمض الكبريتيك.","محلولها الموصل محلول سائل من KOH.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.661Z"}'::jsonb),
('mcq', 7, 0, 'الخلية الجافة خلية جلفانية محلولها عجينة رطبة؛ فهي نوع من الخلايا الجلفانية، ومن الخلايا الجلفانية ما محلوله سائل كالمركم الرصاصي.', '["","عُكست العلاقة؛ فالخلية الجافة نوع خاص من الخلايا الجلفانية.","الخلية الجافة جلفانية تنتج التيار من تفاعل تلقائي.","البطارية خلية جلفانية واحدة أو أكثر في عبوة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-17T11:36:22.661Z"}'::jsonb),
('essay', 1, null::int, null, null, 'البطارية: خلية جلفانية أو أكثر في عبوة واحدة تنتج التيار الكهربائي. الخلية الجافة: خلية جلفانية يكون المحلول الموصل فيها عجينة رطبة. مثال: خلية الخارصين والكربون الجافة (ويقبل البطارية القلوية).', '["تعريف البطارية","تعريف الخلية الجافة","مثال صحيح على خلية جافة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف البطارية","marks":2},{"element":"تعريف الخلية الجافة","marks":1},{"element":"مثال صحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريفان صحيحان كاملان مع مثال صحيح"},{"level":"3 درجات","description":"التعريفان صحيحان دون مثال، أو نقص في أحدهما مع المثال"},{"level":"2 درجتان","description":"تعريف واحد صحيح"},{"level":"1 درجة","description":"مثال صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف البطارية بأنها خلية إلكتروليتية","تعريف الخلية الجافة بأنها لا تحتوي على ماء","ذكر المركم الرصاصي مثالًا على الخلية الجافة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.661Z"}'::jsonb),
('essay', 2, null::int, null, null, 'جهد البطارية = 6 × 2 V = 12 V. ينطبق عليها تعريف البطارية لأنها أكثر من خلية جلفانية في عبوة واحدة تنتج التيار الكهربائي. لا تُعدّ خلية جافة لأن الخلية الجافة محلولها الموصل عجينة رطبة، أما هذه فمحلولها الموصل محلول سائل من حمض الكبريتيك.', '["الجهد 12 V","أكثر من خلية جلفانية في عبوة واحدة","المحلول سائل لا عجينة رطبة"]'::jsonb, '["جهد البطارية = عدد الخلايا × جهد الخلية","= 6 × 2 V = 12 V"]'::jsonb, '[{"element":"حساب الجهد","marks":1},{"element":"تطبيق تعريف البطارية","marks":1},{"element":"تعليل عدم كونها جافة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حساب صحيح وتطبيق التعريفين تطبيقًا صحيحًا"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل جهد البطارية 2 V لأنها «بطارية واحدة»","القول إنها ليست بطارية لأنها تتكون من عدة خلايا","تعليل عدم جفافها بقابليتها للشحن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.661Z"}'::jsonb),
('essay', 3, null::int, null, null, 'خلية الخارصين والكربون: جافة، لأن محلولها الموصل عجينة رطبة من ZnCl₂ وMnO₂ وNH₄Cl. البطارية القلوية: جافة، لأن محلولها الموصل عجينة من KOH. المركم الرصاصي: ليست جافة، لأن محلولها الموصل محلول سائل من حمض الكبريتيك. خلية الوقود القلوية: ليست جافة، لأن محلولها الموصل محلول قلوي من KOH (أو غشاء PEM)، لا عجينة رطبة.', '["الخارصين والكربون: جافة (عجينة)","القلوية: جافة (عجينة KOH)","المركم: غير جافة (محلول H₂SO₄)","خلية الوقود: غير جافة (محلول KOH)"]'::jsonb, '[]'::jsonb, '[{"element":"خلية الخارصين والكربون مع التعليل","marks":1},{"element":"البطارية القلوية مع التعليل","marks":1},{"element":"المركم الرصاصي مع التعليل","marks":1},{"element":"خلية الوقود مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد وتعليل صحيحان للأربع"},{"level":"3 درجات","description":"ثلاث صحيحة مع التعليل"},{"level":"2 درجتان","description":"تحديد صحيح للأربع دون تعليل، أو اثنتان مع التعليل"},{"level":"1 درجة","description":"واحدة صحيحة مع التعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف القلوية غير جافة لأن KOH «محلول»","التعليل بقابلية الشحن بدل حالة المحلول الموصل","تصنيف خلية الوقود جافة لأن مدخلاتها غازات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.661Z"}'::jsonb)
