from (values
('mcq', 1, 'أيّ المعادلات الآتية تمثل نصف تفاعل الأنود في خلية الخارصين والكربون الجافة؟', null, '["Zn²⁺(aq) + 2e⁻ → Zn(s)","Zn(s) → Zn²⁺(aq) + 2e⁻","2NH₄⁺ + 2MnO₂ + 2e⁻ → Mn₂O₃ + 2NH₃ + H₂O","Zn + 2OH⁻ → ZnO + H₂O + 2e⁻"]'::jsonb, 'تذكر', 'كتابة نصف تفاعل', 'سهل', 'الكتاب ص 144 — خلية الخارصين والكربون الجافة'),
('mcq', 2, 'أيّ المعادلات الآتية تمثل نصف تفاعل الكاثود في البطارية القلوية؟', null, '["MnO₂ + 2H₂O → Mn(OH)₂ + 2OH⁻ + 2e⁻","Zn + 2OH⁻ → ZnO + H₂O + 2e⁻","Ag₂O + H₂O + 2e⁻ → 2Ag + 2OH⁻","MnO₂ + 2H₂O + 2e⁻ → Mn(OH)₂ + 2OH⁻"]'::jsonb, 'تذكر', 'كتابة نصف تفاعل', 'سهل', 'الكتاب ص 145 — البطاريات القلوية وبطاريات الفضة'),
('mcq', 3, 'أيّ المعادلات الآتية تمثل نصف تفاعل الكاثود في بطارية الفضة؟', null, '["Ag₂O + H₂O → 2Ag + 2OH⁻ + 2e⁻","2Ag + 2OH⁻ → Ag₂O + H₂O + 2e⁻","MnO₂ + 2H₂O + 2e⁻ → Mn(OH)₂ + 2OH⁻","Ag₂O + H₂O + 2e⁻ → 2Ag + 2OH⁻"]'::jsonb, 'تطبيق', 'كتابة نصف تفاعل', 'متوسط', 'الكتاب ص 145 — البطاريات القلوية وبطاريات الفضة'),
('mcq', 4, 'أيّ المعادلات الآتية تمثل نصف تفاعل الأنود في بطارية NiCad عند توليد التيار؟', null, '["Cd(OH)₂ + 2e⁻ → Cd + 2OH⁻","NiO(OH) + H₂O + e⁻ → Ni(OH)₂ + OH⁻","Cd + 2OH⁻ → Cd(OH)₂ + 2e⁻","Cd → Cd²⁺ + 2e⁻"]'::jsonb, 'تطبيق', 'كتابة نصف تفاعل', 'متوسط', 'الكتاب ص 146 — بطاريات NiCad والمركم الرصاصي'),
('mcq', 5, 'عند الكاثود في بطارية NiCad يُختزل النيكل من +3 إلى +2. أيّ المعادلات الآتية تمثل هذا التفاعل موزونًا؟', null, '["NiO(OH) + H₂O + e⁻ → Ni(OH)₂ + OH⁻","NiO(OH) + H₂O → Ni(OH)₂ + OH⁻ + e⁻","NiO(OH) + H₂O + 2e⁻ → Ni(OH)₂ + OH⁻","Ni(OH)₂ + OH⁻ → NiO(OH) + H₂O + e⁻"]'::jsonb, 'تحليل', 'كتابة موزونة', 'صعب', 'الكتاب ص 146 — بطاريات NiCad والمركم الرصاصي'),
('mcq', 6, 'أيّ المعادلات الآتية تمثل نصف تفاعل الكاثود في بطارية المركم الرصاصي؟', null, '["Pb + SO₄²⁻ → PbSO₄ + 2e⁻","PbO₂ + 4H⁺ + SO₄²⁻ + 2e⁻ → PbSO₄ + 2H₂O","PbO₂ + 4H⁺ + SO₄²⁻ → PbSO₄ + 2H₂O + 2e⁻","PbO₂ + 2H⁺ + SO₄²⁻ + 2e⁻ → PbSO₄ + H₂O"]'::jsonb, 'تطبيق', 'كتابة نصف تفاعل', 'متوسط', 'الكتاب ص 146 — بطاريات NiCad والمركم الرصاصي'),
('mcq', 7, 'جمع نصفا التفاعل في المركم الرصاصي، فأيّ مما يأتي هو المعادلة الكلية الصحيحة؟', null, '["Pb + PbO₂ + 2H⁺ + SO₄²⁻ → 2PbSO₄ + H₂O","Pb + PbO₂ + 4H⁺ + 2SO₄²⁻ + 4e⁻ → 2PbSO₄ + 2H₂O","Pb + PbO₂ + 4H⁺ + 2SO₄²⁻ → 2PbSO₄ + 2H₂O","2PbSO₄ + 2H₂O → Pb + PbO₂ + 4H⁺ + 2SO₄²⁻"]'::jsonb, 'تطبيق', 'جمع نصفي التفاعل', 'صعب', 'الكتاب ص 146 — بطاريات NiCad والمركم الرصاصي'),
('essay', 1, 'اكتب نصفي تفاعل الأنود والكاثود في خلية الخارصين والكربون الجافة، موضحًا أيهما أكسدة وأيهما اختزال.', null, null, 'تطبيق', 'كتابة أنصاف تفاعل', 'متوسط', 'الكتاب ص 144 — خلية الخارصين والكربون الجافة'),
('essay', 2, 'اكتب نصفي تفاعل الأنود والكاثود في كل من: البطارية القلوية، وبطارية الفضة.', null, null, 'تطبيق', 'كتابة أنصاف تفاعل', 'متوسط', 'الكتاب ص 145 — البطاريات القلوية وبطاريات الفضة'),
('essay', 3, 'اكتب نصفي تفاعل الأنود والكاثود في كل من بطارية NiCad وبطارية المركم الرصاصي عند توليد التيار، ثم اكتب المعادلة الكلية للمركم الرصاصي موضحًا خطوة الجمع.', null, null, 'تطبيق', 'كتابة معادلات وجمعها', 'صعب', 'الكتاب ص 146 — بطاريات NiCad والمركم الرصاصي')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C4-L2-O10') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يتأكسد الخارصين عند أنود الخلية الجافة (حافظة الخارصين): Zn(s) → Zn²⁺(aq) + 2e⁻.', '["هذه معادلة اختزال، أما الأنود فموقع الأكسدة.","","هذا نصف تفاعل الاختزال عند الكاثود.","هذا أنود البطارية القلوية التي محلولها قاعدي، لا الخلية الجافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T11:36:22.662Z"}'::jsonb),
('mcq', 2, 3, 'يُختزل MnO₂ عند كاثود القلوية فيكسب إلكترونين: MnO₂(s) + 2H₂O(l) + 2e⁻ → Mn(OH)₂(s) + 2OH⁻(aq).', '["الإلكترونات في الطرف الخطأ؛ فالكاثود اختزال يكسب إلكترونات.","هذا نصف تفاعل الأنود في القلوية.","هذا كاثود بطارية الفضة لا القلوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-17T11:36:22.662Z"}'::jsonb),
('mcq', 3, 3, 'يُختزل أكسيد الفضة عند الكاثود: Ag₂O(s) + H₂O(l) + 2e⁻ → 2Ag(s) + 2OH⁻(aq)، وتستعمل بطارية الفضة تفاعل الأنود نفسه في القلوية.', '["الإلكترونات في الطرف الخطأ؛ الاختزال يكسب إلكترونات.","هذا عكس تفاعل الكاثود، أي أكسدة للفضة.","هذا كاثود القلوية، وتستعمل الفضة Ag₂O بدلًا من MnO₂.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-10-17T11:36:22.662Z"}'::jsonb),
('mcq', 4, 2, 'يتأكسد الكادميوم في وسط قاعدي عند أنود NiCad: Cd(s) + 2OH⁻(aq) → Cd(OH)₂(s) + 2e⁻.', '["هذا اختزال لـ Cd(OH)₂، وهو الاتجاه العكسي الذي يحدث عند الشحن.","هذا نصف تفاعل الكاثود الذي يُختزل فيه النيكل.","","الوسط قاعدي والناتج Cd(OH)₂ الصلب، وليس أيون Cd²⁺ في المحلول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-17T11:36:22.662Z"}'::jsonb),
('mcq', 5, 0, 'ينخفض عدد تأكسد النيكل من +3 إلى +2 فيكسب إلكترونًا واحدًا: NiO(OH) + H₂O + e⁻ → Ni(OH)₂ + OH⁻، والشحنة متساوية في الطرفين (−1).', '["","الإلكترون في طرف النواتج يعني أكسدة، بينما النيكل يُختزل.","غير موزونة شحنيًا؛ فاختزال +3 إلى +2 يحتاج إلكترونًا واحدًا لا اثنين.","هذا تفاعل الشحن (أكسدة النيكل)، وليس تفاعل الكاثود عند التفريغ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T11:36:22.662Z"}'::jsonb),
('mcq', 6, 1, 'يُختزل الرصاص من +4 إلى +2 عند الكاثود: PbO₂(s) + 4H⁺ + SO₄²⁻(aq) + 2e⁻ → PbSO₄(s) + 2H₂O(l).', '["هذا نصف تفاعل الأنود (أكسدة الرصاص).","","الإلكترونان في طرف النواتج؛ والكاثود اختزال يكسب إلكترونات.","غير موزونة؛ فتحتاج الأكسجين إلى 4H⁺ وتنتج 2H₂O."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-10-17T11:36:22.662Z"}'::jsonb),
('mcq', 7, 2, 'بجمع Pb + SO₄²⁻ → PbSO₄ + 2e⁻ مع PbO₂ + 4H⁺ + SO₄²⁻ + 2e⁻ → PbSO₄ + 2H₂O وحذف 2e⁻ تنتج: Pb + PbO₂ + 4H⁺ + 2SO₄²⁻ → 2PbSO₄ + 2H₂O.', '["غير موزونة: يجب أن يكون 4H⁺ و2SO₄²⁻ ونواتج 2H₂O.","الإلكترونات تُحذف عند الجمع لأن النصفين يتبادلان 2e⁻ بالعدد نفسه.","","هذا تفاعل الشحن (العكس)، لا تفاعل توليد التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.662Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الأنود (أكسدة): Zn(s) → Zn²⁺(aq) + 2e⁻. الكاثود (اختزال): 2NH₄⁺(aq) + 2MnO₂(s) + 2e⁻ → Mn₂O₃(s) + 2NH₃(aq) + H₂O(l).', '["نصف تفاعل الأنود صحيحًا","نصف تفاعل الكاثود صحيحًا","تحديد الأكسدة والاختزال"]'::jsonb, '[]'::jsonb, '[{"element":"نصف تفاعل الأنود","marks":1},{"element":"نصف تفاعل الكاثود موزونًا","marks":1},{"element":"تحديد الأكسدة عند الأنود والاختزال عند الكاثود","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"نصفا التفاعل صحيحان مع تحديد النوع"},{"level":"2 درجتان","description":"نصفا التفاعل صحيحان دون تحديد النوع، أو نصف واحد مع تحديد"},{"level":"1 درجة","description":"نصف تفاعل واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الإلكترونات في الطرف الخطأ","نسيان NH₃ وH₂O في ناتج الكاثود","تبديل الأنود والكاثود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.663Z"}'::jsonb),
('essay', 2, null::int, null, null, 'القلوية: الأنود Zn(s) + 2OH⁻(aq) → ZnO(s) + H₂O(l) + 2e⁻؛ الكاثود MnO₂(s) + 2H₂O(l) + 2e⁻ → Mn(OH)₂(s) + 2OH⁻(aq). الفضة: الأنود هو نفسه تفاعل أنود القلوية Zn + 2OH⁻ → ZnO + H₂O + 2e⁻؛ الكاثود Ag₂O(s) + H₂O(l) + 2e⁻ → 2Ag(s) + 2OH⁻(aq).', '["أنود القلوية","كاثود القلوية","أنود الفضة","كاثود الفضة"]'::jsonb, '[]'::jsonb, '[{"element":"أنود القلوية","marks":1},{"element":"كاثود القلوية","marks":1},{"element":"أنود الفضة","marks":1},{"element":"كاثود الفضة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأنصاف الأربعة صحيحة موزونة"},{"level":"3 درجات","description":"ثلاثة صحيحة"},{"level":"2 درجتان","description":"اثنان صحيحان"},{"level":"1 درجة","description":"واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال Zn²⁺ بدل ZnO في الوسط القاعدي","عكس موضع الإلكترونات","وضع MnO₂ في بطارية الفضة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.663Z"}'::jsonb),
('essay', 3, null::int, null, null, 'NiCad: الأنود Cd + 2OH⁻ → Cd(OH)₂ + 2e⁻؛ الكاثود NiO(OH) + H₂O + e⁻ → Ni(OH)₂ + OH⁻. المركم الرصاصي: الأنود Pb + SO₄²⁻ → PbSO₄ + 2e⁻؛ الكاثود PbO₂ + 4H⁺ + SO₄²⁻ + 2e⁻ → PbSO₄ + 2H₂O. الجمع: يتساوى عدد الإلكترونات (2e⁻) في النصفين فتُحذف، وتُجمع المتفاعلات والنواتج: Pb + PbO₂ + 4H⁺ + 2SO₄²⁻ → 2PbSO₄ + 2H₂O.', '["أنود NiCad وكاثودها","أنود المركم وكاثوده","حذف 2e⁻ عند الجمع","المعادلة الكلية موزونة"]'::jsonb, '["الأنود: Pb + SO₄²⁻ → PbSO₄ + 2e⁻","الكاثود: PbO₂ + 4H⁺ + SO₄²⁻ + 2e⁻ → PbSO₄ + 2H₂O","الإلكترونات متساوية (2e⁻) فتُحذف","الكلية: Pb + PbO₂ + 4H⁺ + 2SO₄²⁻ → 2PbSO₄ + 2H₂O"]'::jsonb, '[{"element":"نصفا تفاعل NiCad","marks":2},{"element":"نصفا تفاعل المركم","marks":2},{"element":"المعادلة الكلية مع توضيح الجمع","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"جميع الأنصاف صحيحة والمعادلة الكلية موزونة مع توضيح الجمع"},{"level":"4 درجات","description":"الأنصاف الأربعة صحيحة دون المعادلة الكلية"},{"level":"2 درجتان","description":"نصفان صحيحان"},{"level":"1 درجة","description":"نصف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم وزن H⁺ وH₂O في كاثود المركم","إبقاء الإلكترونات في المعادلة الكلية","كتابة Cd²⁺ بدل Cd(OH)₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.663Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C4-L2-O10') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C4-L2-O11'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا يسمى عمود الكربون في الخلية الجافة الكاثود غير الفعال؟', null, '["لأنه لا يوصل الإلكترونات إلى الدائرة الخارجية","لأنه مصنوع من مادة لا تسهم في تفاعل الأكسدة والاختزال","لأنه يتأكسد ببطء أكثر من الخارصين","لأنه يُختزل داخل العجينة بدلًا من الخارصين"]'::jsonb, 'تذكر', 'تعليل مصطلح', 'سهل', 'الكتاب ص 144 — خلية الخارصين والكربون الجافة'),
('mcq', 2, 'ما الدور الذي يؤديه عمود الكربون في الخلية الجافة؟', null, '["يوصل الإلكترونات إلى العجينة حيث يحدث الاختزال","يتأكسد ليزود الخلية بالإلكترونات","يختزل أيونات الأمونيوم مباشرة على سطحه","يفصل العجينة عن أنود الخارصين"]'::jsonb, 'فهم', 'دور مكوّن', 'متوسط', 'الكتاب ص 144 — خلية الخارصين والكربون الجافة'),
('mcq', 3, 'ما دور الفواصل المسامية في خلية الخارصين والكربون الجافة؟', null, '["تعمل عمل القنطرة الملحية فتسمح بحركة الأيونات","تمنع انتقال الأيونات حفاظًا على نقاء الأنود","توصل الإلكترونات من الأنود إلى الكاثود","تختزل MnO₂ داخل العجينة"]'::jsonb, 'فهم', 'دور مكوّن', 'متوسط', 'الكتاب ص 145 — الفواصل المسامية'),
('mcq', 4, 'أيّ مما يأتي يسبب انخفاض جهد خلية الخارصين والكربون عند نفادها؟', null, '["تحول عمود الكربون إلى مادة متأكسدة","ترسب كلوريد الخارصين على الفواصل","بدء إنتاج الأمونيا غازًا بوصفها ناتج تفاعل الاختزال","زيادة أيونات NH₄⁺ في العجينة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 145 — خلية الخارصين والكربون الجافة'),
('mcq', 5, 'ما جهد خلية الخارصين والكربون الجافة الجديدة؟', null, '["3 V","2 V","12 V","1.5 V"]'::jsonb, 'تذكر', 'قيمة', 'سهل', 'الكتاب ص 145 — خلية الخارصين والكربون الجافة'),
('mcq', 6, 'لو صُنع القطب الأوسط في الخلية الجافة من فلز يتأكسد بدلًا من الكربون، فأيّ نتيجة متوقعة؟', null, '["سيتوقف توصيل الإلكترونات إلى العجينة","سيصبح الخارصين كاثودًا للخلية","سيشارك القطب في تفاعل الأكسدة والاختزال ولن يبقى غير فعال","ستنتج الخلية جهدًا أعلى من 1.5 V دائمًا"]'::jsonb, 'تحليل', 'تنبؤ', 'صعب', 'الكتاب ص 144 — خلية الخارصين والكربون الجافة'),
('mcq', 7, 'في خلية الخارصين والكربون أضعفت الفواصل المسامية (لم تعد تسمح بحركة الأيونات). ما الأثر المتوقع؟', null, '["ستنتج جهدًا أعلى لأن الإلكترونات ستتحرك أسرع","ستتأكسد حافظة الخارصين وحدها بسرعة أكبر","ستتحول إلى خلية إلكتروليتية","ستتوقف الخلية عن إنتاج التيار لعدم اكتمال الدائرة بالأيونات"]'::jsonb, 'تحليل', 'تنبؤ', 'صعب', 'الكتاب ص 145 — الفواصل المسامية'),
('essay', 1, 'وضّح دور عمود الكربون في خلية الخارصين والكربون الجافة، ولماذا يسمى الكاثود غير الفعال؟', null, null, 'فهم', 'توضيح دور', 'سهل', 'الكتاب ص 144 — خلية الخارصين والكربون الجافة'),
('essay', 2, 'وضّح دور الفواصل المسامية في خلية الخارصين والكربون الجافة، ثم فسّر سبب انخفاض جهد الخلية عند نفادها.', null, null, 'فهم', 'توضيح دور وتفسير', 'متوسط', 'الكتاب ص 145 — خلية الخارصين والكربون الجافة'),
('essay', 3, 'تشبه الخلية الجافة الخلية الجلفانية التي درستها في القسم 4-1. طابق بين مكوّنات الخلية الجافة (حافظة الخارصين، عمود الكربون، العجينة الرطبة، الفواصل المسامية) وما يقابلها في الخلية الجلفانية، ثم وضّح ما يحدث في كل مكوّن، وأين يختلف تركيبها عن الخلية الجلفانية ذات الكأسين.', null, null, 'تحليل', 'مطابقة ومقارنة', 'صعب', 'الكتاب ص 144–145 — الخلية الجافة والقنطرة الملحية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C4-L2-O11') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يتكون عمود الكربون من مادة لا تسهم في تفاعل الأكسدة والاختزال، إلا أن له غرضًا مهمًا في توصيل الإلكترونات؛ ولذا يسمى الكاثود غير الفعال.', '["للقطب غير الفعال غرض مهم هو توصيل الإلكترونات.","","عمود الكربون لا يتأكسد ولا يُختزل أصلًا.","الذي يُختزل في العجينة هو MnO₂ مع NH₄⁺، لا الكربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-17T11:36:22.663Z"}'::jsonb),
('mcq', 2, 0, 'يوصل عمود الكربون الإلكترونات القادمة من الدائرة الخارجية إلى العجينة، حيث يحدث تفاعل الاختزال لنصف الخلية.', '["","الذي يتأكسد هو الخارصين عند الأنود لا الكربون.","الكربون لا يشارك في التفاعل؛ يحدث الاختزال داخل العجينة.","الفواصل المسامية هي التي تفصل العجينة عن الأنود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.663Z"}'::jsonb),
('mcq', 3, 0, 'الفواصل رقيقة من مادة مسامية تحتوي على عجينة رطبة تفصلها عن أنود الخارصين، وتعمل عمل القنطرة الملحية للسماح بحركة الأيونات.', '["","الفواصل تسمح بتحرك الأيونات، ولا تمنعها.","الإلكترونات تنتقل عبر الدائرة الخارجية لا عبر الفواصل.","الاختزال تفاعل كيميائي، والفواصل مادة مساميّة لا تشارك فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T11:36:22.664Z"}'::jsonb),
('mcq', 4, 2, 'تنتج الخلية 1.5 V حتى يبدأ إنتاج الأمونيا NH₃ غازًا ناتجًا من تفاعل الاختزال عن محلولها المائي، وعندها ينخفض الجهد إلى مستوى يجعل البطارية غير نافعة.', '["الكربون لا يتأكسد في الخلية.","هذا ليس سبب انخفاض الجهد.","","أيونات NH₄⁺ تُستهلك في تفاعل الكاثود ولا تزيد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-17T11:36:22.664Z"}'::jsonb),
('mcq', 5, 3, 'تنتج خلية الخارصين والكربون الجافة 1.5 V حتى يبدأ إنتاج الأمونيا غازًا فينخفض الجهد.', '["هذا جهد بطاريات الليثيوم.","هذا جهد الخلية الواحدة في المركم الرصاصي.","هذا جهد بطارية السيارة المكونة من 6 خلايا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T11:36:22.664Z"}'::jsonb),
('mcq', 6, 2, 'القطب غير الفعال من مادة لا تسهم في الأكسدة والاختزال، فاستبدال فلز يتأكسد به يجعله مشاركًا في التفاعل لا غير فعال.', '["الفلز موصل جيد، فلن يتوقف التوصيل.","حافظة الخارصين تبقى أنودًا لأنها تتأكسد.","","لا يمكن الجزم بزيادة الجهد؛ والمقصود أن القطب فقد صفة عدم المشاركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.664Z"}'::jsonb),
('mcq', 7, 3, 'تعمل الفواصل عمل القنطرة الملحية؛ فإذا لم تسمح بحركة الأيونات لم تكتمل الدائرة وتوقف التفاعل وإنتاج التيار.', '["من دون حركة الأيونات تتراكم الشحنة ويتوقف التفاعل.","الأكسدة تتوقف أيضًا لتراكم الشحنات الموجبة عند الأنود.","فقدان الفواصل لا يغير طبيعة الخلية إلى إلكتروليتية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.664Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يتكون عمود الكربون (الجرافيت) في مركز الخلية من مادة لا تسهم في تفاعل الأكسدة والاختزال، لذا يسمى الكاثود غير الفعال. دوره توصيل الإلكترونات؛ إذ تصل إليه الإلكترونات من الدائرة الخارجية فينقلها إلى العجينة، حيث يحدث تفاعل اختزال نصف الخلية (2NH₄⁺ + 2MnO₂ + 2e⁻ → Mn₂O₃ + 2NH₃ + H₂O).', '["مادة لا تسهم في الأكسدة والاختزال","توصيل الإلكترونات","الاختزال يحدث في العجينة"]'::jsonb, '[]'::jsonb, '[{"element":"سبب تسميته غير فعال","marks":1},{"element":"دوره في توصيل الإلكترونات","marks":1},{"element":"موضع الاختزال (العجينة)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الإجابة كاملة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عمود الكربون يتأكسد","القول إن الاختزال يحدث على الكربون نفسه","نسيان دور التوصيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-17T11:36:22.664Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الفواصل رقيقة من مادة مسامية تحتوي على عجينة رطبة تفصلها عن أنود الخارصين، وتعمل عمل القنطرة الملحية فتسمح بحركة الأيونات بين نصفي الخلية. تنتج الخلية 1.5 V حتى يبدأ إنتاج الأمونيا NH₃ غازًا بوصفه ناتج تفاعل الاختزال عن محلولها المائي، وعندها ينخفض الجهد إلى مستوى يجعل البطارية غير نافعة.', '["الفواصل تفصل العجينة عن الأنود","تعمل عمل القنطرة الملحية للسماح بحركة الأيونات","الجهد 1.5 V حتى بدء إنتاج الأمونيا غازًا","انخفاض الجهد يجعل البطارية غير نافعة"]'::jsonb, '[]'::jsonb, '[{"element":"وظيفة الفواصل (قنطرة ملحية)","marks":1},{"element":"الجهد الأولي 1.5 V","marks":1},{"element":"سبب الانخفاض (انطلاق الأمونيا)","marks":1},{"element":"النتيجة (بطارية غير نافعة)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة صحيحة"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الفواصل توصل الإلكترونات","القول إن الخارصين ينفد فيخفض الجهد دون ذكر الأمونيا","القول إن الجهد ينخفض لتحلل الكربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T11:36:22.665Z"}'::jsonb),
('essay', 3, null::int, null, null, 'حافظة الخارصين تقابل قطب الأنود (تتأكسد: Zn → Zn²⁺ + 2e⁻). عمود الكربون يقابل قطب الكاثود، لكنه كاثود غير فعال لا يسهم في التفاعل ويوصل الإلكترونات. العجينة الرطبة (ZnCl₂ وMnO₂ وNH₄Cl) تقابل المحلول الموصل ويحدث فيها الاختزال. الفواصل المسامية تقابل القنطرة الملحية وتسمح بحركة الأيونات. الاختلاف: الخلية الجافة داخل عبوة واحدة بعجينة رطبة بدل محلولين في كأسين، وكاثودها غير فعال، وتحدث فيها أكسدة الأنود واختزال العجينة في عبوة واحدة.', '["حافظة الخارصين = أنود","عمود الكربون = كاثود غير فعال يوصل الإلكترونات","العجينة = المحلول الموصل ويحدث فيها الاختزال","الفواصل = قنطرة ملحية","الاختلاف عن الخلية ذات الكأسين"]'::jsonb, '[]'::jsonb, '[{"element":"الأنود","marks":1},{"element":"الكاثود غير الفعال","marks":1},{"element":"العجينة","marks":1},{"element":"الفواصل","marks":1},{"element":"وجه الاختلاف","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مطابقة صحيحة لأربعة مكوّنات مع وجه الاختلاف"},{"level":"4 درجات","description":"نقص عنصر"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مطابقة العجينة مع الأنود","القول إن عمود الكربون يتفاعل","إغفال دور الفواصل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.665Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C4-L2-O11') and x.type = v.type and x.number = v.number
