from (values
('mcq', 1, 'أيّ مادة في بطارية المركم الرصاصي تفقد إلكترونات في أثناء توليد التيار؟', null, '["الرصاص Pb عند الأنود","أكسيد الرصاص IV عند الكاثود","كبريتات الرصاص II","أيونات الهيدروجين H⁺"]'::jsonb, 'تذكر', 'تحديد المتأكسد', 'سهل', 'الكتاب ص 146 — بطاريات تخزين المركم الرصاصي الحمضية'),
('mcq', 2, 'أيّ مادة في بطارية المركم الرصاصي تكسب إلكترونات في أثناء توليدها التيار؟', null, '["أكسيد الرصاص IV PbO₂","الرصاص Pb","حمض الكبريتيك كاملًا","كبريتات الرصاص II"]'::jsonb, 'تذكر', 'تحديد المختزل', 'سهل', 'الكتاب ص 146 — بطاريات تخزين المركم الرصاصي الحمضية'),
('mcq', 3, 'ماذا يحدث لتركيز حمض الكبريتيك في أثناء توليد البطارية للتيار؟', null, '["يزداد لأن الماء يُستهلك في التفاعل","يبقى ثابتًا لأنه محلول موصل فقط","يزداد لأن PbSO₄ يتفكك إلى حمض","يقل لأن الحمض يُستهلك في التفاعل"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 147 — بطاريات تخزين المركم الرصاصي الحمضية'),
('mcq', 4, 'ما الذي يحدث لتفاعل البطارية عند إعادة شحنها؟', null, '["يتوقف التفاعل ويتجمد PbSO₄","يتكرر التفاعل نفسه بسرعة أكبر","ينعكس التفاعل فينتج Pb وPbO₂ وحمض الكبريتيك","يتحول PbSO₄ إلى PbO فقط"]'::jsonb, 'فهم', 'وصف', 'متوسط', 'الكتاب ص 147 — بطاريات تخزين المركم الرصاصي الحمضية'),
('mcq', 5, 'ما المادة التي تتأكسد عند شحن بطارية المركم الرصاصي؟', null, '["كبريتات الرصاص II عند القطب السالب لتتحول إلى Pb","الرصاص Pb عند القطب السالب","أكسيد الرصاص IV عند القطب الموجب","كبريتات الرصاص II عند القطب الموجب لتتحول إلى PbO₂"]'::jsonb, 'تحليل', 'تحديد مع الاستدلال', 'صعب', 'الكتاب ص 147 — بطاريات تخزين المركم الرصاصي الحمضية'),
('mcq', 6, 'أيّ الجدولين الآتيين يصف أعداد تأكسد الرصاص صحيحًا في بطارية المركم الرصاصي عند توليد التيار؟', null, '["Pb: من +2 إلى 0، وفي PbO₂: من +2 إلى +4","Pb: من 0 إلى +2، وفي PbO₂: من +4 إلى +2","Pb: من 0 إلى +4، وفي PbO₂: من +4 إلى 0","Pb: من 0 إلى +2، وفي PbO₂: من +2 إلى +4"]'::jsonb, 'تطبيق', 'أعداد التأكسد', 'متوسط', 'الكتاب ص 146 — بطاريات تخزين المركم الرصاصي الحمضية'),
('mcq', 7, 'لماذا تبقى المواد المتفاعلة في أماكنها المطلوبة سواء كانت البطارية في حالة استعمال أم شحن؟', null, '["لأن حمض الكبريتيك يثبّتها على الأقطاب","لأن Pb وPbO₂ وPbSO₄ جميعها مواد صلبة تبقى في مكان تكوّنها","لأن الفواصل تمنع وصول الأيونات إليها","لأن البطارية مغلقة تمامًا فلا يتغير شيء"]'::jsonb, 'فهم', 'تعليل', 'صعب', 'الكتاب ص 147 — بطاريات تخزين المركم الرصاصي الحمضية'),
('essay', 1, 'صف ما يحدث في بطارية المركم الرصاصي عند توليد التيار، محددًا المادة التي تتأكسد والمادة التي تُختزل، مع كتابة نصفي التفاعل والمعادلة الكلية.', null, null, 'فهم', 'وصف مع معادلات', 'متوسط', 'الكتاب ص 146 — بطاريات تخزين المركم الرصاصي الحمضية'),
('essay', 2, 'صف ما يحدث في بطارية المركم الرصاصي عند إعادة شحنها: ما اتجاه التفاعل، وما المواد التي تتأكسد والتي تُختزل، وما المواد الناتجة، وما الذي يحدث لتركيز حمض الكبريتيك؟', null, null, 'فهم', 'وصف مع تحديد', 'متوسط', 'الكتاب ص 147 — بطاريات تخزين المركم الرصاصي الحمضية'),
('essay', 3, 'قارن بين ما يحدث في المركم الرصاصي عند توليد التيار وعند إعادة الشحن، في جدول أو فقرة، من حيث: المادة المتأكسدة والمختزلة، والتغير في تركيز حمض الكبريتيك، ثم فسّر سبب بقاء المواد المتفاعلة في أماكنها في الحالتين.', null, null, 'تحليل', 'مقارنة مع تفسير', 'صعب', 'الكتاب ص 146–147 — بطارية المركم الرصاصي')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C4-L2-O12') and x.type = v.type and x.number = v.number);
