from (values
('mcq', 1, 0, 'يتأكسد الرصاص عند الأنود من حالة تأكسد 0 إلى +2 في PbSO₄: Pb + SO₄²⁻ → PbSO₄ + 2e⁻.', '["","PbO₂ يُختزل (من +4 إلى +2) عند الكاثود.","PbSO₄ ناتج التفاعل، وليست مادة متأكسدة عند توليد التيار.","أيونات H⁺ تتحد مع أكسجين PbO₂ لتكوين الماء ولا تتأكسد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-10-17T11:36:22.665Z"}'::jsonb),
('mcq', 2, 0, 'يُختزل الرصاص في PbO₂ من +4 إلى +2 عند الكاثود: PbO₂ + 4H⁺ + SO₄²⁻ + 2e⁻ → PbSO₄ + 2H₂O.', '["","الرصاص يتأكسد عند الأنود.","الذي يتغير عدد تأكسده هو رصاص PbO₂ لا الكبريت.","PbSO₄ ناتج وليست متفاعلة عند التوليد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-10-17T11:36:22.665Z"}'::jsonb),
('mcq', 3, 3, 'تظهر المعادلة الكلية استهلاك 4H⁺ و2SO₄²⁻ (حمض الكبريتيك) وتكوّن الماء؛ لذا يقل تركيز الحمض ويصبح المحلول الموصل أقل كثافة.', '["الماء يتكوّن في التفاعل الكلي ولا يُستهلك، فيقل تركيز الحمض.","الحمض يُستهلك في أثناء توليد التيار كما توضح المعادلة الكلية.","PbSO₄ صلب يتكوّن ويبقى مكانه ولا يتفكك عند توليد التيار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.666Z"}'::jsonb),
('mcq', 4, 2, 'عند إعادة الشحن يصبح التفاعل عكسيًا: 2PbSO₄ + 2H₂O → Pb + PbO₂ + 4H⁺ + 2SO₄²⁻، فينتج الرصاص وأكسيد الرصاص IV وحمض الكبريتيك.', '["الشحن يعكس التفاعل فيُحوَّل PbSO₄ إلى مواد البطارية الأصلية.","الشحن يعكس اتجاه التفاعل ولا يكرره.","","الشحن ينتج Pb وPbO₂ وحمض الكبريتيك، لا PbO."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.666Z"}'::jsonb),
('mcq', 5, 3, 'عند الشحن ينعكس التفاعل: PbSO₄ عند القطب الموجب يتأكسد من +2 إلى +4 مكوّنًا PbO₂، وPbSO₄ عند القطب السالب يُختزل من +2 إلى 0 مكوّنًا Pb.', '["تحول PbSO₄ إلى Pb اختزال (من +2 إلى 0) وليس أكسدة.","Pb ناتج الشحن عند القطب السالب ولا يتأكسد فيه.","PbO₂ ناتج الشحن عند القطب الموجب، ولا يتأكسد فيه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.666Z"}'::jsonb),
('mcq', 6, 1, 'يتأكسد Pb من 0 إلى +2 في PbSO₄، ويُختزل Pb في PbO₂ من +4 إلى +2 في PbSO₄ أيضًا.', '["عُكست التغيرات؛ وهذا ما يحدث عند الشحن لا التوليد.","","ناتج الأنود والكاثود هو PbSO₄ (+2) لا +4 أو 0.","PbO₂ يُختزل من +4 إلى +2 ولا يتأكسد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.666Z"}'::jsonb),
('mcq', 7, 1, 'كلٌّ من PbO₂ وPb وPbSO₄ مادة صلبة، لذا تبقى في مكان تكوّنها نفسه، فتكون المواد المتفاعلة في الأماكن المطلوبة في الاستعمال والشحن.', '["ثبات المواد سببه كونها صلبة لا الحمض.","","الأيونات ضرورية للتفاعل؛ والفواصل لا تمنعها.","التفاعل يحدث فعلًا؛ والعلة صلابة المواد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.666Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عند توليد التيار: يتأكسد الرصاص Pb عند الأنود من 0 إلى +2: Pb + SO₄²⁻ → PbSO₄ + 2e⁻. ويُختزل PbO₂ عند الكاثود من +4 إلى +2: PbO₂ + 4H⁺ + SO₄²⁻ + 2e⁻ → PbSO₄ + 2H₂O. المعادلة الكلية: Pb + PbO₂ + 4H⁺ + 2SO₄²⁻ → 2PbSO₄ + 2H₂O، ويُستهلك حمض الكبريتيك ويتكون PbSO₄ الصلب.', '["Pb يتأكسد (0 إلى +2)","PbO₂ يُختزل (+4 إلى +2)","نصفا التفاعل","المعادلة الكلية واستهلاك الحمض"]'::jsonb, '[]'::jsonb, '[{"element":"المادة المتأكسدة","marks":1},{"element":"المادة المختزلة","marks":1},{"element":"نصفا التفاعل","marks":1},{"element":"المعادلة الكلية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف كامل صحيح"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"2 درجتان","description":"تحديد المتأكسد والمختزل دون معادلات"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل الأنود والكاثود","نسيان H⁺ وH₂O في نصف تفاعل الكاثود","القول إن حمض الكبريتيك لا يُستهلك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.666Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عند الشحن يزوَّد التفاعل بطاقة كهربائية فينعكس: 2PbSO₄ + 2H₂O → Pb + PbO₂ + 4H⁺ + 2SO₄²⁻. تتأكسد PbSO₄ (من +2 إلى +4) فتتحول إلى PbO₂، وتُختزل PbSO₄ (من +2 إلى 0) فتتحول إلى Pb. المواد الناتجة: Pb وPbO₂ وحمض الكبريتيك. يزداد تركيز حمض الكبريتيك لأنه يتكوّن من جديد.', '["التفاعل ينعكس","PbSO₄ يتأكسد إلى PbO₂","PbSO₄ يُختزل إلى Pb","الناتج Pb وPbO₂ وH₂SO₄","تركيز الحمض يزداد"]'::jsonb, '[]'::jsonb, '[{"element":"انعكاس التفاعل","marks":1},{"element":"المادة المتأكسدة","marks":1},{"element":"المادة المختزلة","marks":1},{"element":"المواد الناتجة","marks":1},{"element":"تركيز الحمض","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف كامل صحيح"},{"level":"4 درجات","description":"نقص عنصر"},{"level":"3 درجات","description":"ثلاثة عناصر"},{"level":"2 درجتان","description":"عنصران"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الرصاص يتأكسد عند الشحن","نسيان أن PbSO₄ هي المتفاعلة عند الشحن","القول إن الحمض يقل عند الشحن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-17T11:36:22.666Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التوليد: يتأكسد Pb (0 إلى +2) ويُختزل PbO₂ (+4 إلى +2)، ويُستهلك حمض الكبريتيك فيقل تركيزه، ويتكوّن PbSO₄. الشحن: يتأكسد PbSO₄ إلى PbO₂ ويُختزل PbSO₄ إلى Pb، ويتكوّن حمض الكبريتيك فيزداد تركيزه. تبقى المواد في أماكنها لأن PbO₂ وPb وPbSO₄ جميعها مواد صلبة تبقى في مكان تكوّنها نفسه، فتكون المواد المتفاعلة في الأماكن المطلوبة سواء كانت البطارية في حالة استعمال أم شحن.', '["المتأكسد والمختزل في التوليد","المتأكسد والمختزل في الشحن","تركيز الحمض في الحالتين","سبب بقاء المواد: كلها صلبة"]'::jsonb, '[]'::jsonb, '[{"element":"التوليد","marks":1},{"element":"الشحن","marks":1},{"element":"تركيز الحمض","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة صحيحة"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"2 درجتان","description":"عنصران"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المواد تبقى لأن الحمض يثبتها","عكس تفاعلي التوليد والشحن","القول إن الحمض لا يتغير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.667Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
