('mcq', 1, 'ما السببان اللذان ركّز المهندسون من أجلهما على الليثيوم في صناعة البطاريات؟', null, '["أنه أخف فلز معروف وله أقل جهد اختزال قياسي بين الفلزات","أنه أثقل فلز معروف وله أعلى جهد اختزال قياسي","أنه أخف فلز معروف وله أعلى جهد اختزال قياسي","أنه فلز لا يتأكسد وله أعلى جهد اختزال قياسي"]'::jsonb, 'تذكر', 'تذكر أسباب', 'سهل', 'الكتاب ص 147 — بطاريات الليثيوم'),
('mcq', 2, 'كم يبلغ جهد الليثيوم القياسي E° لنصف تفاعل Li⁺|Li؟', null, '["+3.04 V","−0.762 V","−3.04 V","−2.28 V"]'::jsonb, 'تذكر', 'قيمة', 'سهل', 'الكتاب ص 148 — بطاريات الليثيوم'),
('mcq', 3, 'ما الجهد الذي تنتجه معظم بطاريات الليثيوم مقارنة بخلية الخارصين والكربون؟', null, '["3 V مقابل 1.5 V","1.5 V مقابل 3 V","12 V مقابل 1.5 V","2 V مقابل 1.5 V"]'::jsonb, 'تذكر', 'قيمة', 'سهل', 'الكتاب ص 148 — بطاريات الليثيوم'),
('mcq', 4, 'لماذا تولد البطارية التي تؤكسد الليثيوم جهدًا أكبر من التي تؤكسد الخارصين؟', null, '["لأن كتلة الليثيوم الذرية أكبر من كتلة الخارصين","لأن جهد اختزال الليثيوم أعلى من جهد اختزال الخارصين","لأن الليثيوم يفقد إلكترونين بينما يفقد الخارصين إلكترونًا","لأن جهد اختزال الليثيوم أقل بكثير فتأكسده أسهل ويزداد فرق الجهد"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 148 — بطاريات الليثيوم'),
('mcq', 5, 'أيّ مما يأتي ليس من مزايا بطاريات الليثيوم؟', null, '["خفة وزنها وصغر كتلتها","سرعة نفادها بعد استعمال قصير","ارتفاع جهدها إلى نحو 3 V","استمرارها فترة أطول من أنواع البطاريات الأخرى"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 148 — بطاريات الليثيوم'),
('mcq', 6, 'بطارية أنودها الليثيوم وبطارية أنودها الخارصين، وكاثود كل منهما المادة نفسها. إذا علمت أن E°(Li⁺|Li) = −3.04 V وE°(Zn²⁺|Zn) = −0.762 V، فأيّ مقارنة بين جهدي البطاريتين صحيحة؟', null, '["جهد بطارية الخارصين أكبر بنحو 2.28 V","جهد بطارية الليثيوم أكبر بنحو 2.28 V","جهد بطارية الليثيوم أكبر بنحو 3.80 V","جهدا البطاريتين متساويان لأن الكاثود واحد"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 148 — بطاريات الليثيوم'),
('mcq', 7, 'تحتاج سيارة كهربائية إلى كمية كبيرة من الطاقة. لماذا لا تُعدّ بطاريات المركم الرصاصي عملية لها بينما تُناسبها بطاريات الليثيوم؟', null, '["لأن المركم لا يعطي طاقة عالية في بداية التشغيل","لأن المركم الرصاصي بطارية أولية لا يعاد شحنها","لأن المركم ثقيل جدًّا، أما الليثيوم فخفيف ويخزن طاقة كبيرة","لأن الليثيوم أثقل من الرصاص فيخزن طاقة أكبر منه"]'::jsonb, 'تحليل', 'تفسير في سياق', 'صعب', 'الكتاب ص 147 — بطاريات الليثيوم'),
('essay', 1, 'اذكر ثلاث مزايا لبطاريات الليثيوم.', null, null, 'تذكر', 'تعداد', 'سهل', 'الكتاب ص 148 — بطاريات الليثيوم'),
('essay', 2, 'علّل: اختار المهندسون الليثيوم لصناعة بطاريات ذات وزن خفيف وجهد عالٍ. استعمل في إجابتك جهدي الاختزال القياسيين E°(Li⁺|Li) = −3.04 V وE°(Zn²⁺|Zn) = −0.762 V لحساب الفرق بين جهد بطارية تؤكسد الليثيوم وأخرى تؤكسد الخارصين.', null, null, 'تطبيق', 'تعليل مع حساب', 'متوسط', 'الكتاب ص 148 — بطاريات الليثيوم'),
('essay', 3, 'تحتاج شركة إلى بطارية لسيارة كهربائية تقطع مسافات طويلة. قوّم صلاحية بطارية المركم الرصاصي وبطارية الليثيوم لهذا الاستعمال، مبينًا مزايا بطاريات الليثيوم، وهل يمكن أن تكون بطاريات الليثيوم أولية وثانوية معًا؟', null, null, 'تقويم', 'اتخاذ قرار مع تبرير', 'صعب', 'الكتاب ص 147 — بطاريات الليثيوم')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
