('mcq', 4, 3, 'E°(Zn²⁺|Zn) − E°(Li⁺|Li) = −0.762 − (−3.04) = +2.28 V؛ فالبطارية التي تؤكسد الليثيوم تولد جهدًا أكبر بنحو 2.3 V من التي تؤكسد الخارصين.', '["الليثيوم أخف الفلزات، والجهد مرتبط بجهد الاختزال لا بالكتلة.","جهد اختزال Li (−3.04 V) أقل من Zn (−0.762 V).","الليثيوم يفقد إلكترونًا واحدًا بينما يفقد الخارصين إلكترونين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.668Z"}'::jsonb),
('mcq', 5, 1, 'من مزايا بطاريات الليثيوم: خفة الوزن، والجهد العالي، وطول العمر؛ أما سرعة النفاد فليست ميزة بل عكسها صحيح.', '["الليثيوم أخف فلز معروف، وهذه ميزة.","","جهدها 3 V مقابل 1.5 V لخلية الخارصين والكربون، وهذه ميزة.","من مزاياها أنها تستمر فترة أطول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.668Z"}'::jsonb),
('mcq', 6, 1, 'الفرق = −0.762 − (−3.04) = 2.278 ≈ 2.28 V؛ فجهد بطارية الليثيوم أكبر بنحو 2.28 V.', '["الليثيوم أقل جهد اختزال فيولد جهدًا أكبر لا أصغر.","","3.80 V ناتج جمع القيمتين بدل طرحهما.","الأنود مختلف، وفرق الجهد بين الليثيوم والخارصين مقداره 2.28 V."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.668Z"}'::jsonb),
('mcq', 7, 2, 'المركم الرصاصي ثقيل جدًّا فلا يكون عمليًا في السيارات الكهربائية، وأن الحل كان بطارية خفيفة الوزن تخزن كميات كبيرة من الطاقة بالنسبة إلى حجمها، فركّز المهندسون على الليثيوم.', '["المركم يزود المحرك بطاقة ابتدائية عالية جدًّا.","المركم الرصاصي بطارية ثانوية قابلة للشحن.","","الليثيوم أخف فلز معروف، والرصاص ثقيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.668Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) خفة الوزن (الليثيوم أخف فلز معروف). 2) الجهد العالي (3 V مقارنة بـ 1.5 V لخلية الخارصين والكربون). 3) تستمر فترة أطول من أنواع البطاريات الأخرى (طول العمر).', '["خفة الوزن","الجهد العالي 3 V","طول العمر"]'::jsonb, '[]'::jsonb, '[{"element":"الميزة الأولى","marks":1},{"element":"الميزة الثانية","marks":1},{"element":"الميزة الثالثة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاث مزايا صحيحة"},{"level":"2 درجتان","description":"ميزتان صحيحتان"},{"level":"1 درجة","description":"ميزة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر قابلية الشحن ميزة عامة لجميع بطاريات الليثيوم","ذكر الرخص","ذكر ارتفاع الكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.668Z"}'::jsonb),
('essay', 2, null::int, null, null, 'السببان: الليثيوم أخف فلز معروف فتكون البطارية خفيفة الوزن وتخزن طاقة كبيرة بالنسبة إلى حجمها، ولليثيوم أقل جهد اختزال قياسي بين الفلزات (−3.04 V) فيتأكسد بسهولة ويولد البطارية جهدًا عاليًا. الحساب: الفرق = E°(Zn²⁺|Zn) − E°(Li⁺|Li) = −0.762 − (−3.04) = +2.28 V، فتولد البطارية التي تؤكسد الليثيوم جهدًا أكبر بنحو 2.3 V من التي تؤكسد الخارصين.', '["أخف فلز معروف","أقل جهد اختزال قياسي","الحساب 2.28 V","الاستنتاج: جهد أكبر"]'::jsonb, '["الفرق = E°(Zn²⁺|Zn) − E°(Li⁺|Li)","= −0.762 − (−3.04)","= +2.28 V"]'::jsonb, '[{"element":"خفة الوزن","marks":1},{"element":"أقل جهد اختزال قياسي","marks":1},{"element":"الحساب الصحيح 2.28 V","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل وحساب صحيح"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"2 درجتان","description":"السببان دون حساب، أو الحساب فقط"},{"level":"1 درجة","description":"سبب واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع القيمتين بدل طرحهما (3.80 V)","القول إن الليثيوم أعلى جهد اختزال","نسيان خفة الوزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.668Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المركم الرصاصي موثوق ومناسب لتشغيل السيارات التقليدية لأنه يزود المحرك بطاقة ابتدائية عالية جدًّا، لكنه ثقيل جدًّا فلا يكون عمليًا للسيارات الكهربائية التي تحتاج كميات كبيرة من الطاقة. أما بطاريات الليثيوم فأنسب: لأن الليثيوم أخف فلز معروف فتخزن طاقة كبيرة بالنسبة إلى حجمها، وجهدها عالٍ (3 V مقابل 1.5 V)، وتستمر فترة أطول. وبطاريات الليثيوم يمكن أن تكون أولية أو ثانوية بحسب تفاعل الاختزال المدمج مع تأكسد الليثيوم؛ لذا تناسب السيارة الكهربائية منها الثانوية القابلة للشحن.', '["المركم: ثقيل جدًّا فغير عملي للسيارات الكهربائية","الليثيوم: خفة الوزن","الجهد العالي وطول العمر","قد تكون أولية أو ثانوية","الحكم: الليثيوم أنسب"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم المركم الرصاصي","marks":1},{"element":"خفة الوزن","marks":1},{"element":"الجهد العالي وطول العمر","marks":1},{"element":"أولية أو ثانوية","marks":1},{"element":"الحكم النهائي المبرر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم كامل صحيح ومبرر"},{"level":"4 درجات","description":"نقص عنصر"},{"level":"3 درجات","description":"ثلاثة عناصر"},{"level":"2 درجتان","description":"عنصران"},{"level":"1 درجة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المركم الرصاصي غير قابل للشحن","القول إن بطاريات الليثيوم أولية فقط","إغفال مشكلة وزن المركم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.669Z"}'::jsonb)
