from (values
('mcq', 1, 'توقفت خلية جلفانية من الخارصين والنحاس عن العمل بعد استهلاك قطعة الخارصين تقريبًا. كيف يمكن تجديد هذه الخلية؟', null, '["بإضافة قنطرة ملحية جديدة بين نصفي الخلية","بتسخين الخلية حتى يصبح التفاعل العكسي تلقائيًا","بتبديل موضعي القطبين دون توصيل أي مصدر للطاقة","بتزويدها بتيار في الاتجاه المعاكس من مصدر طاقة خارجي"]'::jsonb, 'فهم', 'وصف عملية', 'سهل', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('mcq', 2, 'لماذا يلزم مصدر طاقة خارجي لعكس تفاعل الأكسدة والاختزال في خلية جلفانية مستهلكة؟', null, '["لأن التفاعل العكسي تلقائي لكنه بطيء جدًا","لأن التفاعل في الاتجاه العكسي غير تلقائي","لأن الإلكترونات لا تنتقل في الأسلاك الفلزية","لأن القنطرة الملحية تمنع حركة الأيونات"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('mcq', 3, 'التفاعل التلقائي في خلية الخارصين والنحاس الجلفانية هو: Zn + Cu²⁺ → Zn²⁺ + Cu. ما التفاعل الذي يحدث عند عكس هذه الخلية بمصدر طاقة خارجي؟', null, '["Zn + Cu²⁺ → Zn²⁺ + Cu","Zn²⁺ + Cu²⁺ → Zn + Cu","Zn + Cu → Zn²⁺ + Cu²⁺","Cu + Zn²⁺ → Cu²⁺ + Zn"]'::jsonb, 'تطبيق', 'كتابة معادلة', 'متوسط', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('mcq', 4, 'عند تحويل خلية الخارصين والنحاس إلى خلية تحليل كهربائي بمصدر جهد خارجي، أيّ الفلزين يتأكسد، وأيهما تُختزل أيوناته؟', null, '["يتأكسد الخارصين، وتُختزل أيونات النحاس","يتأكسد الخارصين والنحاس كلاهما معًا","يتأكسد النحاس، وتُختزل أيونات الخارصين","تُختزل أيونات الخارصين والنحاس معًا"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('mcq', 5, 'ماذا يحدث لاتجاه تدفق الإلكترونات في الدائرة الخارجية عندما تُزوَّد خلية جلفانية مستهلكة بطاقة من مصدر خارجي لعكس تفاعلها؟', null, '["يبقى اتجاه تدفقها كما كان في الخلية الجلفانية","ينعكس اتجاه تدفقها عما كان عليه في الخلية الجلفانية","يتوقف تدفقها في الدائرة الخارجية توقفًا تامًا","تنتقل الإلكترونات عبر المحلول بدلًا من السلك"]'::jsonb, 'فهم', 'وصف', 'سهل', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('mcq', 6, 'يمكن تشبيه الهبوط بالدراجة إلى أسفل التل والصعود إلى أعلاه بتفاعلات الأكسدة والاختزال. أيّ الربطين الآتيين صحيح؟', null, '["الصعود يشبه التحليل الكهربائي؛ لأنه يحتاج إلى طاقة خارجية","الهبوط يشبه التحليل الكهربائي؛ لأنه لا يحتاج إلى جهد","الصعود يشبه الخلية الجلفانية؛ لأنه يولد طاقة كهربائية","الهبوط والصعود كلاهما يمثلان تفاعلات غير تلقائية"]'::jsonb, 'تحليل', 'تشبيه وربط', 'صعب', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('mcq', 7, 'باستعمال جهود الاختزال القياسية: E°(Zn²⁺/Zn) = −0.7618 V و E°(Cu²⁺/Cu) = +0.3419 V، ما الجهد القياسي للتفاعل المعكوس Cu + Zn²⁺ → Cu²⁺ + Zn، وماذا يعني؟', null, '["+1.104 V؛ تفاعل تلقائي لا يحتاج إلى مصدر طاقة","−0.420 V؛ تفاعل غير تلقائي يحتاج إلى مصدر طاقة","−1.104 V؛ تفاعل غير تلقائي يحتاج إلى مصدر طاقة","+1.104 V؛ تفاعل غير تلقائي يحتاج إلى مصدر طاقة"]'::jsonb, 'تحليل', 'حساب وتفسير', 'صعب', 'الكتاب ص 138 و154 — جهود الاختزال القياسية وعكس التفاعلات'),
('essay', 1, 'صِف كيف يمكن تجديد خلية جلفانية من الخارصين والنحاس توقف تفاعلها، موضحًا سبب الحاجة إلى مصدر طاقة خارجي، وما الذي يحدث لاتجاه تدفق الإلكترونات.', null, null, 'فهم', 'وصف وتعليل', 'متوسط', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('essay', 2, 'في خلية مكوّنة من قطب خارصين في محلول Zn²⁺ وقطب نحاس في محلول Cu²⁺: (أ) اكتب نصفي التفاعل والتفاعل الكلي عندما تعمل خلية جلفانية. (ب) اكتب نصفي التفاعل والتفاعل الكلي عندما توصل بمصدر جهد خارجي فتعمل خلية تحليل كهربائي، محددًا القطب الذي يحدث عنده التأكسد في كل حالة.', null, null, 'تطبيق', 'كتابة معادلات', 'صعب', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('essay', 3, 'تُعاد شحن البطاريات الثانوية بتمرير تيار كهربائي من خلالها. حلّل ما يحدث في البطارية في أثناء تفريغها (تشغيل جهاز) وفي أثناء شحنها من حيث: تلقائية التفاعل، وتحول الطاقة، ونوع الخلية التي تعمل بها البطارية في كل حالة.', null, null, 'تحليل', 'مقارنة وتحليل', 'صعب', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C4-L3-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'يمكن تجديد الخلية إذا زُوّدت بتيار في الاتجاه المعاكس باستعمال مصدر طاقة خارجي؛ لأن التفاعل في الاتجاه العكسي غير تلقائي، فإذا زُوّدت بالطاقة مدة كافية عادت إلى قوتها الأصلية تقريبًا.', '["القنطرة الملحية تكمل الدائرة فقط ولا تزود الخلية بالطاقة اللازمة لعكس التفاعل.","التفاعل العكسي غير تلقائي ويُحدثه مصدر طاقة كهربائي خارجي لا التسخين.","تبديل القطبين دون مصدر طاقة لا يُحدث تفاعلًا غير تلقائي؛ فالتفاعل العكسي يحتاج إلى طاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.669Z"}'::jsonb),
('mcq', 2, 1, 'التفاعل التلقائي في الخلية الجلفانية يحدث من تلقاء نفسه، أما التفاعل في الاتجاه المعاكس فغير تلقائي، لذا لا يحدث إلا بتزويد الخلية بطاقة كهربائية من مصدر خارجي.', '["لو كان التفاعل العكسي تلقائيًا لحدث دون مصدر طاقة؛ فهو غير تلقائي.","","الإلكترونات تنتقل في الدائرة الخارجية في الخلايا كلها؛ وليس هذا سبب الحاجة إلى الطاقة.","القنطرة الملحية تسمح بحركة الأيونات ولا تمنعها، ولا علاقة لها بالحاجة إلى مصدر طاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.669Z"}'::jsonb),
('mcq', 3, 3, 'عكس التفاعل يعني أن النواتج تصبح متفاعلات: يتأكسد النحاس إلى Cu²⁺ وتُختزل أيونات Zn²⁺ إلى Zn، فيكون التفاعل Cu + Zn²⁺ → Cu²⁺ + Zn، وهو غير تلقائي يحدث بالطاقة الخارجية.', '["هذا هو التفاعل التلقائي نفسه في الخلية الجلفانية، لا التفاعل المعكوس.","هذا اختزال لكلا الأيونين دون أكسدة، ولا يمكن حدوث اختزال دون أكسدة مرافقة.","هذه أكسدة للفلزين معًا دون اختزال؛ فلا تمثل تفاعل أكسدة واختزال.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.670Z"}'::jsonb),
('mcq', 4, 2, 'في خلية التحليل ينعكس التفاعل التلقائي، فيتأكسد النحاس (Cu → Cu²⁺ + 2e⁻) وتُختزل أيونات الخارصين (Zn²⁺ + 2e⁻ → Zn)، وهو عكس ما يحدث في الخلية الجلفانية.', '["هذا ما يحدث في الخلية الجلفانية (التفاعل التلقائي) لا في خلية التحليل.","لا بد أن يرافق الأكسدة اختزال؛ ولا يتأكسد الفلزان معًا.","","لا يحدث اختزال دون أكسدة؛ ويتأكسد في خلية التحليل قطب النحاس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.670Z"}'::jsonb),
('mcq', 5, 1, 'عند تزويد الخلية بطاقة خارجية ينعكس تدفق الإلكترونات ويحدث التفاعل غير التلقائي الذي يستعيد الوضع الأصلي للخلية.', '["لو بقي الاتجاه نفسه لاستمر التفاعل التلقائي، والمطلوب حدوث التفاعل المعاكس.","","مصدر الطاقة يدفع الإلكترونات في الدائرة، فلا يتوقف تدفقها.","الإلكترونات تنتقل في السلك؛ والمحلول تنتقل فيه الأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.671Z"}'::jsonb),
('mcq', 6, 0, 'الهبوط بفعل الجاذبية دون جهد يشبه التفاعل التلقائي، أما الصعود فيتطلب بذل طاقة كبيرة، كما يتطلب التفاعل غير التلقائي في التحليل الكهربائي مصدر طاقة خارجيًا.', '["","الهبوط دون جهد يشبه التفاعل التلقائي في الخلية الجلفانية، لا التحليل الكهربائي.","الصعود يستهلك طاقة ولا يولدها، والخلية الجلفانية تفاعلها تلقائي كالهبوط.","الهبوط يحدث بفعل الجاذبية دون بذل جهد، فهو يمثل التفاعل التلقائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.671Z"}'::jsonb),
('mcq', 7, 2, 'في التفاعل المعكوس يُختزل Zn²⁺ (الكاثود) ويتأكسد Cu (الأنود): E°الخلية = E°الكاثود − E°الأنود = −0.7618 − 0.3419 = −1.104 V. الإشارة السالبة تعني أن التفاعل غير تلقائي، فيحتاج إلى مصدر طاقة خارجي.', '["هذا جهد الخلية الجلفانية للتفاعل التلقائي؛ إذ عُدّ النحاس كاثودًا رغم أنه يتأكسد في التفاعل المعكوس.","نتجت هذه القيمة من جمع الجهدين بدل طرح جهد الأنود من جهد الكاثود.","","الإشارة الموجبة تدل على تفاعل تلقائي، فلا تتفق مع وصفه بأنه غير تلقائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.671Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يتوقف التفاعل التلقائي عندما تُستهلك قطعة الخارصين أو تنفد أيونات النحاس. ويمكن تجديد الخلية بتزويدها بتيار كهربائي في الاتجاه المعاكس من مصدر طاقة خارجي، وهذا المصدر مطلوب لأن التفاعل في الاتجاه العكسي غير تلقائي. عند ذلك ينعكس اتجاه تدفق الإلكترونات ويحدث التفاعل غير التلقائي الذي يستعيد الوضع الأصلي للخلية، وإذا زُوّدت بالطاقة مدة كافية عادت إلى قوتها الأصلية تقريبًا. وتسمى الخلية عندئذ خلية تحليل كهربائي.', '["سبب توقف الخلية: استهلاك الخارصين أو نفاد أيونات النحاس","تزويد الخلية بتيار في الاتجاه المعاكس من مصدر طاقة خارجي","التفاعل العكسي غير تلقائي","انعكاس اتجاه تدفق الإلكترونات واستعادة الوضع الأصلي"]'::jsonb, '[]'::jsonb, '[{"element":"سبب توقف التفاعل","marks":1},{"element":"طريقة التجديد بمصدر طاقة خارجي وتيار معاكس","marks":1},{"element":"التعليل: التفاعل العكسي غير تلقائي","marks":1},{"element":"انعكاس تدفق الإلكترونات واستعادة الوضع الأصلي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف كامل لسبب التوقف وطريقة التجديد وتعليلها وانعكاس تدفق الإلكترونات"},{"level":"3 درجات","description":"وصف طريقة التجديد وتعليلها مع إغفال عنصر واحد"},{"level":"2 درجتان","description":"ذكر الحاجة إلى مصدر طاقة خارجي دون تعليل صحيح"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التفاعل العكسي تلقائي","الاعتقاد بأن إضافة قنطرة ملحية تجدد الخلية","القول إن اتجاه الإلكترونات لا يتغير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.671Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الخلية الجلفانية: عند الخارصين (الأنود) Zn → Zn²⁺ + 2e⁻، وعند النحاس (الكاثود) Cu²⁺ + 2e⁻ → Cu، والكلي Zn + Cu²⁺ → Zn²⁺ + Cu (تلقائي). (ب) خلية التحليل: يتأكسد النحاس Cu → Cu²⁺ + 2e⁻ فيصبح قطب النحاس أنودًا، وتُختزل أيونات الخارصين Zn²⁺ + 2e⁻ → Zn فيصبح قطب الخارصين كاثودًا، والكلي Cu + Zn²⁺ → Cu²⁺ + Zn (غير تلقائي يحدث بالطاقة الخارجية).', '["نصفا التفاعل في الخلية الجلفانية","التفاعل الكلي التلقائي","نصفا التفاعل في خلية التحليل","التفاعل الكلي المعكوس","تحديد قطب التأكسد في كل حالة"]'::jsonb, '[]'::jsonb, '[{"element":"نصفا تفاعل الخلية الجلفانية وتفاعلها الكلي","marks":2},{"element":"نصفا تفاعل خلية التحليل وتفاعلها الكلي","marks":2},{"element":"تحديد قطب التأكسد في الحالتين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلات صحيحة موزونة للحالتين مع تحديد قطب التأكسد في كل منهما"},{"level":"3 درجات","description":"معادلات إحدى الحالتين صحيحة كاملة مع أخطاء في الأخرى"},{"level":"2 درجتان","description":"التفاعلان الكليان صحيحان دون أنصاف التفاعل"},{"level":"1 درجة","description":"تحديد قطب التأكسد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة التفاعل نفسه للحالتين","عدّ الخارصين أنودًا في خلية التحليل","عدم موازنة الشحنات بالإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.671Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في أثناء التفريغ يحدث تفاعل أكسدة واختزال تلقائي يحول الطاقة الكيميائية إلى طاقة كهربائية، فتعمل البطارية خلية جلفانية. وفي أثناء الشحن يمرر مصدر خارجي تيارًا في الاتجاه المعاكس فيحدث التفاعل العكسي غير التلقائي، وتتحول الطاقة الكهربائية إلى طاقة كيميائية مخزنة، فتعمل البطارية خلية تحليل كهربائي، وتعود إلى قوتها الأصلية تقريبًا إذا شُحنت مدة كافية.', '["التفريغ: تفاعل تلقائي","التفريغ: طاقة كيميائية → كهربائية، خلية جلفانية","الشحن: تفاعل عكسي غير تلقائي بمصدر خارجي","الشحن: طاقة كهربائية → كيميائية، خلية تحليل كهربائي"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل حالة التفريغ (التلقائية وتحول الطاقة ونوع الخلية)","marks":2},{"element":"تحليل حالة الشحن (التلقائية وتحول الطاقة ونوع الخلية)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تحليل صحيح للحالتين بالمعايير الثلاثة"},{"level":"3 درجات","description":"تحليل صحيح للحالتين مع خطأ في معيار واحد"},{"level":"2 درجتان","description":"تحليل صحيح لحالة واحدة فقط"},{"level":"1 درجة","description":"ذكر نوع الخلية في الحالتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين اتجاهي تحول الطاقة","القول إن البطارية في أثناء الشحن خلية جلفانية","عدّ تفاعل الشحن تلقائيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.672Z"}'::jsonb)
