from (values
('mcq', 1, 0, 'عند كاثود خلية داون تُختزل أيونات الصوديوم إلى فلز الصوديوم: Na⁺ + e⁻ → Na.', '["","الهيدروجين ينتج عند الكاثود في التحليل الكهربائي لماء البحر، ولا يوجد ماء في المصهور.","الكلور ينتج عند الأنود بتأكسد أيونات الكلوريد، لا عند الكاثود.","هيدروكسيد الصوديوم ناتج التحليل الكهربائي لماء البحر، لا المصهور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:36:22.672Z"}'::jsonb),
('mcq', 2, 2, 'عند أنود خلية ماء البحر تتأكسد أيونات الكلوريد إلى غاز الكلور: 2Cl⁻ → Cl₂ + 2e⁻؛ لأن تأكسدها أسهل حدوثًا من تأكسد الماء.', '["هذا تفاعل محتمل عند الأنود، لكنه لا يحدث لأن تأكسد أيونات الكلوريد أسهل حدوثًا.","هذا اختزال، والاختزال يحدث عند الكاثود، ثم إنه لا يحدث في ماء البحر أصلًا.","","هذا اختزال الماء الذي يحدث عند الكاثود لا عند الأنود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.673Z"}'::jsonb),
('mcq', 3, 3, 'في المصهور لا يوجد إلا Na⁺ ليُختزل فيتكون فلز الصوديوم، أما في ماء البحر فيُختزل الماء تفضيليًا: 2H₂O + 2e⁻ → H₂ + 2OH⁻، فيتكون غاز الهيدروجين.', '["عُكست المقارنة؛ فالمصهور لا ماء فيه فيُختزل Na⁺، وفي ماء البحر يُختزل الماء.","في ماء البحر لا يُختزل Na⁺ لأن الماء أسهل اختزالًا، فلا يتكون الصوديوم.","الكلور ينتج عند الأنود في الخليتين، لا عند الكاثود.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.673Z"}'::jsonb),
('mcq', 4, 1, 'في الخليتين يحدث عند الأنود التفاعل نفسه: 2Cl⁻ → Cl₂ + 2e⁻، فغاز الكلور ناتج مشترك، ويختلف الناتج عند الكاثود (Na في المصهور، H₂ في ماء البحر).', '["اختزال Na⁺ يحدث في المصهور فقط؛ ففي ماء البحر يُختزل الماء بدلًا منه.","","NaOH يتكون في خلية ماء البحر فقط، ولا ماء في المصهور ليعطي OH⁻.","اختزال الماء يحدث في ماء البحر فقط، ولا يوجد ماء في خلية داون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.673Z"}'::jsonb),
('mcq', 5, 0, 'باختزال الماء عند الكاثود (H₂ وOH⁻) وتأكسد Cl⁻ عند الأنود (Cl₂) يكون التفاعل الكلي: 2H₂O + 2NaCl → H₂ + Cl₂ + 2NaOH.', '["","هذه المعادلة الكلية لخلية داون (مصهور NaCl) لا لماء البحر.","هذه معادلة التحليل الكهربائي للماء النقي، ولا يتكون O₂ في ماء البحر لأن تأكسد Cl⁻ أسهل.","المعادلة موزونة لكنها تفترض تكوّن Na وO₂، وكلاهما لا يتكون في ماء البحر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.673Z"}'::jsonb),
('mcq', 6, 3, 'يتكون NaOH في خلية ماء البحر فقط؛ لأن الماء يُختزل عند الكاثود: 2H₂O + 2e⁻ → H₂ + 2OH⁻، فتبقى أيونات OH⁻ مع أيونات Na⁺ في المحلول.', '["تفاعل الصوديوم مع الكلور يعطي NaCl لا NaOH، ولا يوجد مصدر لـ OH⁻ في المصهور.","تأكسد الماء لا يحدث في ماء البحر، ولو حدث لأعطى H⁺ لا OH⁻.","وجود Na⁺ لا يكفي؛ فالمصهور لا يحتوي على ماء يعطي أيونات OH⁻.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.673Z"}'::jsonb),
('mcq', 7, 2, 'قول الطالب خطأ: في المصهور 2Na⁺ + 2Cl⁻ → 2Na + Cl₂، وفي ماء البحر يُختزل الماء بدل Na⁺ فيكون 2H₂O + 2NaCl → H₂ + Cl₂ + 2NaOH.', '["وجود الماء في ماء البحر يغيّر التفاعل عند الكاثود، فتختلف النواتج.","عُكست النواتج؛ فالصوديوم ينتج من المصهور والهيدروجين من ماء البحر.","","الأكسجين لا ينتج في أيٍّ من الخليتين؛ فالناتج عند الأنود فيهما هو الكلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.673Z"}'::jsonb),
('essay', 1, null::int, null, null, 'مصهور NaCl: الأنود 2Cl⁻ → Cl₂ + 2e⁻، الكاثود Na⁺ + e⁻ → Na، الكلي 2Na⁺ + 2Cl⁻ → 2Na + Cl₂، والنواتج فلز الصوديوم وغاز الكلور. ماء البحر: الأنود 2Cl⁻ → Cl₂ + 2e⁻، الكاثود 2H₂O + 2e⁻ → H₂ + 2OH⁻، الكلي 2H₂O + 2NaCl → H₂ + Cl₂ + 2NaOH، والنواتج غاز الهيدروجين وغاز الكلور وهيدروكسيد الصوديوم. أوجه الشبه: تأكسد Cl⁻ إلى Cl₂ عند الأنود في الخليتين. أوجه الاختلاف: يُختزل Na⁺ في المصهور، ويُختزل الماء تفضيليًا في ماء البحر.', '["تفاعل الأنود في الخليتين (متماثل)","تفاعل الكاثود في المصهور","تفاعل الكاثود في ماء البحر","التفاعلان الكليان","نواتج كل خلية"]'::jsonb, '[]'::jsonb, '[{"element":"تفاعل الأنود في الخليتين","marks":1},{"element":"تفاعلا الكاثود","marks":2},{"element":"التفاعلان الكليان الموزونان","marks":2},{"element":"النواتج في كل خلية","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة بالمعادلات الصحيحة الموزونة والنواتج للخليتين"},{"level":"4 درجات","description":"معادلات صحيحة مع خطأ في أحد التفاعلين الكليين أو النواتج"},{"level":"2 درجتان","description":"ذكر النواتج صحيحة دون معادلات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Na ناتجًا عند كاثود ماء البحر","كتابة O₂ ناتجًا عند أنود ماء البحر","عدم موازنة معادلة ماء البحر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:36:22.674Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الكاثود: Na⁺ + e⁻ → Na أو 2H₂O + 2e⁻ → H₂ + 2OH⁻، ويحدث اختزال الماء لأن اختزال الهيدروجين في الماء أسهل حدوثًا (اختزال تفضيلي). الأنود: 2Cl⁻ → Cl₂ + 2e⁻ أو 2H₂O → O₂ + 4H⁺ + 4e⁻، ويحدث تأكسد أيونات الكلوريد لأنه أسهل حدوثًا. أما مصهور NaCl فلا يحتوي على ماء، فلا يوجد إلا Na⁺ ليُختزل عند الكاثود وCl⁻ ليتأكسد عند الأنود، فينتج Na وCl₂.', '["التفاعلان المحتملان عند الكاثود","التفاعلان المحتملان عند الأنود","تحديد اختزال الماء عند الكاثود وتعليله","تحديد تأكسد Cl⁻ عند الأنود وتعليله","غياب الماء في المصهور"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة التفاعلات الأربعة المحتملة","marks":2},{"element":"تحديد التفاعل الفعلي عند الكاثود مع التعليل","marks":1},{"element":"تحديد التفاعل الفعلي عند الأنود مع التعليل","marks":1},{"element":"تفسير حالة المصهور","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"كتابة الاحتمالات الأربعة وتحديد الفعلي منها عند كل قطب بتعليل صحيح وتفسير حالة المصهور"},{"level":"3 درجات","description":"تحديد صحيح للتفاعلين الفعليين مع نقص في الاحتمالات أو التعليل"},{"level":"1 درجة","description":"تحديد ناتج واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار Na⁺ للاختزال لأنه أيون موجب","اختيار تأكسد الماء عند الأنود","إهمال أن المصهور خالٍ من الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.674Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) لإنتاج الصوديوم يُختار التحليل الكهربائي لمصهور NaCl في خلية داون؛ لأن المصهور خالٍ من الماء فتُختزل أيونات Na⁺ إلى فلز الصوديوم: 2Na⁺ + 2Cl⁻ → 2Na + Cl₂، أما ماء البحر فلا ينتج الصوديوم لأن الماء يُختزل تفضيليًا. (ب) لإنتاج هيدروكسيد الصوديوم يُختار التحليل الكهربائي لماء البحر: 2H₂O + 2NaCl → H₂ + Cl₂ + 2NaOH، إذ تنتج أيونات OH⁻ من اختزال الماء، ولا ينتج NaOH من المصهور. الناتج المشترك بين العمليتين هو غاز الكلور.', '["اختيار المصهور لإنتاج الصوديوم مع التبرير","المعادلة الكلية لخلية داون","اختيار ماء البحر لإنتاج NaOH مع التبرير","المعادلة الكلية لماء البحر","الكلور ناتج مشترك"]'::jsonb, '[]'::jsonb, '[{"element":"الاختيار والتبرير لإنتاج الصوديوم","marks":2},{"element":"الاختيار والتبرير لإنتاج NaOH","marks":2},{"element":"الناتج المشترك","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"اختيار صحيح للحالتين بتبرير ومعادلات صحيحة وذكر الناتج المشترك"},{"level":"3 درجات","description":"اختيار صحيح للحالتين مع تبرير ناقص أو معادلة خاطئة"},{"level":"1 درجة","description":"اختيار صحيح لحالة واحدة دون تبرير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار ماء البحر لإنتاج الصوديوم لتوافره","عدّ الهيدروجين ناتجًا مشتركًا","عدم ربط NaOH باختزال الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.674Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
