('mcq', 1, 2, 'تقوم الخلايا الجلفانية بتحويل الطاقة الكيميائية إلى طاقة كهربائية نتيجة تفاعل أكسدة واختزال تلقائي.', '["هذا تحول الطاقة في خلية التحليل الكهربائي لا في الخلية الجلفانية.","الخلية الجلفانية لا تعتمد على الحرارة، بل على تفاعل أكسدة واختزال تلقائي.","","هذا وصف لعمل مدفأة كهربائية لا لخلية كهروكيميائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.675Z"}'::jsonb),
('mcq', 2, 3, 'تعتمد الخلية الجلفانية على تفاعل أكسدة واختزال تلقائي، بينما تستعمل خلية التحليل الكهربائي الطاقة الكهربائية لإحداث تفاعل أكسدة واختزال غير تلقائي.', '["عُكست المقارنة؛ فالخلية الجلفانية تعمل بتفاعل تلقائي، وخلية التحليل تحتاج إلى طاقة لتفاعل غير تلقائي.","لو كان تفاعل خلية التحليل تلقائيًا لما احتاجت إلى مصدر طاقة خارجي.","الخلية الجلفانية تولد تيارًا من تلقاء نفسها، فتفاعلها تلقائي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.675Z"}'::jsonb),
('mcq', 3, 0, 'في الخلية الجلفانية يوفر التفاعل التلقائي نفسه الطاقة الكهربائية، أما خلية التحليل فتحتاج إلى مصدر جهد خارجي يدفع التفاعل غير التلقائي.', '["","عُكس المصدران؛ فخلية التحليل هي التي تحتاج إلى مصدر جهد خارجي.","الخلية الجلفانية تولد الطاقة الكهربائية بنفسها ولا تحتاج إلى مصدر خارجي.","تفاعل خلية التحليل غير تلقائي فلا يمكن أن يكون مصدرًا للطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.675Z"}'::jsonb),
('mcq', 4, 1, 'في الخلية الجلفانية يتأكسد الخارصين فتتدفق الإلكترونات منه إلى النحاس، وفي خلية التحليل يعكس مصدر الجهد التدفق فتتجه الإلكترونات نحو الخارصين حيث تُختزل أيوناته.', '["عُكس الاتجاهان؛ ففي الخلية الجلفانية يتأكسد الخارصين فتخرج منه الإلكترونات.","","مصدر الجهد في خلية التحليل يعكس تدفق الإلكترونات، فلا يبقى الاتجاه نفسه.","في الخلية الجلفانية تتدفق الإلكترونات تلقائيًا من الخارصين لأنه يتأكسد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.675Z"}'::jsonb),
('mcq', 5, 0, 'في خلية داون يوفر مصدر الطاقة الإلكترونات لاختزال Na⁺، وينتزعها من أيونات Cl⁻ عند الأنود، فهو يُحدث تفاعلًا غير تلقائي، وهذه صفة خلية التحليل الكهربائي.', '["","هذا وصف الخلية الجلفانية؛ وتفاعل تفكك NaCl غير تلقائي.","نوع مادة الأقطاب لا يحدد نوع الخلية، بل تلقائية التفاعل ومصدر الطاقة.","وجود المصهور ليس معيار التصنيف؛ فمعياره حاجة التفاعل إلى طاقة خارجية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.675Z"}'::jsonb),
('mcq', 6, 3, 'التفاعل التلقائي في الخلية الجلفانية جهده موجب (+1.104 V)، أما تفاعل خلية داون فغير تلقائي: E° = −2.71 − (+1.358) = −4.07 V، والإشارة السالبة تؤكد حاجته إلى مصدر خارجي.', '["عُكست الإشارتان؛ فالتفاعل التلقائي جهده موجب، وغير التلقائي جهده سالب.","الجهد الموجب يدل على تفاعل تلقائي، وتفاعل خلية داون غير تلقائي.","تفاعل الخلية الجلفانية تلقائي، فجهدها يجب أن يكون موجبًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.676Z"}'::jsonb),
('mcq', 7, 1, 'البطارية الثانوية في أثناء شحنها تعمل خلية تحليل كهربائي، فتستهلك الطاقة الكهربائية وتخزنها في صورة طاقة كيميائية؛ أما بقية الأمثلة فخلايا جلفانية.', '["البطارية في أثناء التشغيل خلية جلفانية تحول الطاقة الكيميائية إلى كهربائية.","","هذه خلية جلفانية تعمل بتفاعل تلقائي يولد طاقة كهربائية.","خلية الوقود تنتج الطاقة الكهربائية من احتراق الهيدروجين، فهي خلية جلفانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.676Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخلية الجلفانية: تحول الطاقة الكيميائية إلى طاقة كهربائية، تفاعلها تلقائي، ومصدر طاقتها التفاعل الكيميائي نفسه؛ مثالها خلية الخارصين والنحاس التي تضيء مصباحًا. خلية التحليل الكهربائي: تحول الطاقة الكهربائية إلى طاقة كيميائية، تفاعلها غير تلقائي، ومصدر طاقتها مصدر جهد (طاقة) خارجي؛ مثالها خلية داون أو البطارية الثانوية في أثناء شحنها. ويقبل أي مثال صحيح.', '["تحول الطاقة في كل خلية","تلقائية التفاعل في كل خلية","مصدر الطاقة في كل خلية","مثال صحيح لكل خلية"]'::jsonb, '[]'::jsonb, '[{"element":"تحول الطاقة","marks":2},{"element":"التلقائية","marks":2},{"element":"مصدر الطاقة","marks":2},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"مقارنة صحيحة كاملة في المعايير الثلاثة مع مثالين صحيحين"},{"level":"5 درجات","description":"مقارنة صحيحة في معيارين مع مثالين، أو في ثلاثة دون أمثلة"},{"level":"3 درجات","description":"مقارنة صحيحة في معيار واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس اتجاه تحول الطاقة","عدّ خلية الوقود خلية تحليل كهربائي","ذكر القنطرة الملحية مصدرًا للطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.676Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في الخلية الجلفانية يحدث تفاعل تلقائي: يتأكسد الخارصين (Zn → Zn²⁺ + 2e⁻) وتُختزل أيونات النحاس عند قطب النحاس (Cu²⁺ + 2e⁻ → Cu)، وتتدفق الإلكترونات من الخارصين إلى النحاس عبر المصباح فيضيء؛ فالمصباح يستهلك الطاقة الناتجة. وعند استبدال المصباح بمصدر جهد خارجي ينعكس تدفق الإلكترونات ويحدث التفاعل غير التلقائي: يتأكسد النحاس (Cu → Cu²⁺ + 2e⁻) وتُختزل أيونات الخارصين عند قطب الخارصين (Zn²⁺ + 2e⁻ → Zn)؛ فمصدر الجهد يزود الخلية بالطاقة اللازمة ويستعيد الوضع الأصلي لها. إذن ما يحدد نوع الخلية هو تلقائية التفاعل واتجاه تحول الطاقة لا مادة الأقطاب.', '["الجلفانية: تأكسد Zn واختزال Cu²⁺","المصباح يستهلك الطاقة الناتجة من التفاعل التلقائي","التحليل: تأكسد Cu واختزال Zn²⁺","مصدر الجهد يزود الطاقة ويعكس تدفق الإلكترونات","الاستنتاج: نوع الخلية تحدده التلقائية لا الأقطاب"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة الجلفانية (القطبان ودور المصباح)","marks":2},{"element":"حالة التحليل (القطبان ودور مصدر الجهد)","marks":2},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير صحيح للحالتين بالأقطاب والدور مع الاستنتاج"},{"level":"3 درجات","description":"تفسير صحيح لحالة واحدة مع جزء من الأخرى"},{"level":"1 درجة","description":"تحديد صحيح للقطب المتأكسد في حالة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الخارصين يتأكسد في الحالتين","القول إن المصباح يزود الخلية بالطاقة","الاعتقاد بأن نوع الخلية تحدده مادة الأقطاب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.676Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في خلية داون يحدث الاختزال عند الكاثود (Na⁺ + e⁻ → Na) والأكسدة عند الأنود (2Cl⁻ → Cl₂ + 2e⁻). E°الخلية = E°الكاثود − E°الأنود = −2.71 − (+1.358) = −4.07 V. يجب أن يكون الجهد سالبًا؛ لأن التفاعل غير تلقائي ولا يحدث إلا بمصدر طاقة خارجي، فخلية داون خلية تحليل كهربائي. أما خلية الخارصين والنحاس فجهدها موجب (+1.104 V) لأن تفاعلها تلقائي يولد طاقة كهربائية بنفسه دون مصدر خارجي.', '["تحديد تفاعلي الكاثود والأنود","التعويض في E°الخلية = E°الكاثود − E°الأنود","النتيجة −4.07 V","تفسير الإشارة السالبة: غير تلقائي يحتاج إلى مصدر خارجي","المقارنة مع الخلية الجلفانية"]'::jsonb, '["الكاثود: Na⁺ + e⁻ → Na ؛ E° = −2.71 V","الأنود: 2Cl⁻ → Cl₂ + 2e⁻ ؛ E° = +1.358 V","E°الخلية = −2.71 − 1.358 = −4.07 V","الإشارة سالبة ← التفاعل غير تلقائي"]'::jsonb, '[{"element":"تحديد الكاثود والأنود","marks":1},{"element":"الحساب والنتيجة الصحيحة بالوحدة","marks":2},{"element":"تفسير الإشارة","marks":1},{"element":"المقارنة بالخلية الجلفانية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح بالإشارة والوحدة مع تفسير ومقارنة صحيحين"},{"level":"3 درجات","description":"حساب صحيح مع نقص في التفسير أو المقارنة"},{"level":"1 درجة","description":"تحديد القطبين صحيحًا مع خطأ في الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع الجهدين بدل الطرح","عكس الكاثود والأنود فيكون الناتج +4.07 V","عدّ الجهد السالب خطأً حسابيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.676Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
