('mcq', 4, 'باستعمال جهود الاختزال: E°(Na⁺/Na) = −2.71 V و E°(2H₂O/H₂) = −0.83 V، أيّ المادتين تُختزل عند كاثود خلية ماء البحر، ولماذا؟', null, '["أيونات Na⁺؛ لأن جهد اختزالها أكثر سالبية","الماء؛ لأن جهد اختزاله أقل سالبية (أكبر)","أيونات Na⁺؛ لأنها أيونات موجبة تنجذب إلى الكاثود","الماء؛ لأن جهد اختزاله أكثر سالبية (أصغر)"]'::jsonb, 'تطبيق', 'تفسير بيانات', 'متوسط', 'الكتاب ص 138 و156 — جهود الاختزال والتحليل الكهربائي لماء البحر'),
('mcq', 5, 'إذا أردنا الحصول على فلز الصوديوم بالتحليل الكهربائي لكلوريد الصوديوم، فما الذي يجب فعله؟', null, '["زيادة تركيز NaCl في ماء البحر قبل تحليله","استعمال أقطاب من الصوديوم في ماء البحر","تحليل مصهور NaCl الخالي من الماء كما في خلية داون","تبريد ماء البحر قبل تحليله كهربائيًا"]'::jsonb, 'تطبيق', 'حل مشكلة', 'متوسط', 'الكتاب ص 155 — التحليل الكهربائي لمصهور NaCl (خلية داون)'),
('mcq', 6, 'قال طالب: «بما أن أيونات Na⁺ موجودة في ماء البحر، فلا بد أن تُختزل إلى صوديوم عند الكاثود». أيّ الردود الآتية أدق؟', null, '["قوله صحيح؛ فكل أيون موجب يُختزل عند الكاثود","وجود Na⁺ لا يكفي؛ فالماء أسهل اختزالًا فيُختزل هو","قوله خطأ؛ لأن Na⁺ يتأكسد عند الأنود إلى Na","قوله خطأ؛ لأن Na⁺ يتحد مع Cl⁻ عند الكاثود"]'::jsonb, 'تحليل', 'تقويم ادعاء', 'صعب', 'الكتاب ص 156 — التحليل الكهربائي لماء البحر'),
('mcq', 7, 'أيّ الملاحظات الآتية عند الكاثود في أثناء التحليل الكهربائي لماء البحر تؤيد أن الماء هو الذي يُختزل لا أيونات Na⁺؟', null, '["تصاعد غاز الهيدروجين وتكوّن محلول قاعدي حول الكاثود","ترسب طبقة فلزية لامعة على سطح الكاثود","تصاعد غاز أخضر مصفر حول الكاثود","تكوّن محلول حمضي حول الكاثود"]'::jsonb, 'تحليل', 'ربط ملاحظة بتفسير', 'صعب', 'الكتاب ص 156 — التحليل الكهربائي لماء البحر'),
('essay', 1, 'علّل عدم إنتاج الصوديوم من التحليل الكهربائي لماء البحر، مستعينًا بكتابة التفاعلين المحتملين عند الكاثود، وموضحًا أيهما يحدث فعلًا.', null, null, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 156 — التحليل الكهربائي لماء البحر'),
('essay', 2, 'استعمل البيانات الآتية: E°(Na⁺/Na) = −2.71 V و E°(2H₂O + 2e⁻ → H₂ + 2OH⁻) = −0.8277 V لتبرير عدم تكوّن الصوديوم عند كاثود خلية ماء البحر، ثم فسّر لماذا يصبح المحلول المحيط بالكاثود قاعديًا، واكتب التفاعل الكلي للخلية.', null, null, 'تطبيق', 'تفسير بيانات', 'متوسط', 'الكتاب ص 138 و156 — جهود الاختزال والتحليل الكهربائي لماء البحر'),
('essay', 3, 'يُنتج الصوديوم في خلية داون من كلوريد الصوديوم، ولا يُنتج من ماء البحر رغم أنه يحتوي على كلوريد الصوديوم أيضًا. حلّل سبب هذا الاختلاف، مبينًا دور وجود الماء أو غيابه في تحديد التفاعل عند الكاثود في كل خلية.', null, null, 'تحليل', 'تحليل مقارن', 'صعب', 'الكتاب ص 155–156 — خلية داون والتحليل الكهربائي لماء البحر')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C4-L3-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'لا يحدث اختزال Na⁺ في ماء البحر لأن اختزال الهيدروجين في جزيئات الماء أسهل حدوثًا، فجزيئات الماء لديها ميل للاختزال أكثر من الصوديوم.', '["","Na⁺ أيون موجب لا يتأكسد في الخلية؛ والذي يتأكسد عند الأنود هو Cl⁻.","ماء البحر محلول مائي لـ NaCl يحتوي على أيونات Na⁺ حرة الحركة.","أيونات الكلوريد تتأكسد عند الأنود ولا تُختزل عند الكاثود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.677Z"}'::jsonb),
('mcq', 2, 3, 'عند الكاثود يُختزل الماء: 2H₂O + 2e⁻ → H₂ + 2OH⁻، فيتكون غاز الهيدروجين وأيونات الهيدروكسيد بدلًا من الصوديوم.', '["هذه نواتج تأكسد الماء، وهي تفاعل أنود لا يحدث أصلًا في ماء البحر.","الكلور يتكون عند الأنود، وأيونات الصوديوم تبقى في المحلول دون تغير.","لا يتكون هيدريد الصوديوم، ولا يتكون الكلور عند الكاثود.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.677Z"}'::jsonb),
('mcq', 3, 2, 'اختزال الهيدروجين في الماء أسهل حدوثًا، ومن ثمّ يتم الاختزال التفضيلي للماء بدل أيونات الصوديوم.', '["ما يحدث للماء عند الكاثود اختزال (اكتساب إلكترونات) لا أكسدة.","التحلل المائي تفاعل أيون مع الماء ولا يصف اختيار المادة التي تُختزل عند الكاثود.","","التعادل تفاعل حمض مع قاعدة، ولا علاقة له بالاختزال عند الكاثود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.677Z"}'::jsonb),
('mcq', 4, 1, 'يُختزل في الكاثود النوع ذو جهد الاختزال الأكبر (الأقل سالبية): −0.83 V للماء أكبر من −2.71 V لأيونات Na⁺، فيُختزل الماء تفضيليًا ولا يتكون الصوديوم.', '["الجهد الأكثر سالبية يعني ميلًا أقل للاختزال، فـ Na⁺ أصعب اختزالًا.","","الانجذاب إلى الكاثود لا يكفي؛ فالذي يُختزل هو صاحب الميل الأكبر للاختزال.","النتيجة صحيحة والتعليل خاطئ؛ فـ −0.83 V أقل سالبية من −2.71 V."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.678Z"}'::jsonb),
('mcq', 5, 2, 'بما أن الماء يُختزل تفضيليًا في المحاليل المائية، فلا بد من غياب الماء، أي تحليل مصهور NaCl في خلية داون، حيث تُختزل Na⁺ إلى Na.', '["زيادة التركيز لا تمنع الماء من الاختزال التفضيلي، فيبقى الناتج H₂ لا Na.","مادة القطب لا تغير حقيقة أن الماء أسهل اختزالًا من Na⁺ في المحلول المائي.","","التبريد لا يزيل الماء، فيظل الماء يُختزل بدل أيونات الصوديوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.678Z"}'::jsonb),
('mcq', 6, 1, 'وجود الأيون في المحلول لا يعني اختزاله؛ ففي ماء البحر يتنافس Na⁺ والماء على الاختزال، والماء أسهل اختزالًا فيُختزل تفضيليًا ولا يتكون الصوديوم.', '["ليس كل أيون موجب يُختزل؛ إذ يُختزل النوع الأسهل اختزالًا، وهو الماء هنا.","","التأكسد لا يحول Na⁺ إلى Na؛ فهذا اختزال، ولا يحدث عند الأنود.","لا يتكون NaCl عند الكاثود، بل يُختزل الماء إلى H₂ وOH⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.678Z"}'::jsonb),
('mcq', 7, 0, 'اختزال الماء عند الكاثود: 2H₂O + 2e⁻ → H₂ + 2OH⁻ يعطي غاز الهيدروجين وأيونات OH⁻ التي تجعل المحلول قاعديًا (NaOH)، وهذا دليل على أن الماء هو الذي اختُزل.', '["","ترسب فلز لامع يعني اختزال Na⁺ إلى صوديوم، وهذا لا يحدث في ماء البحر.","الغاز الأخضر المصفر هو الكلور، ويتصاعد عند الأنود لا الكاثود.","اختزال الماء يعطي OH⁻ فيصبح المحلول قاعديًا لا حمضيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.678Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عند الكاثود يحتمل حدوث تفاعلين: اختزال أيونات الصوديوم Na⁺ + e⁻ → Na، أو اختزال الهيدروجين في جزيئات الماء 2H₂O + 2e⁻ → H₂ + 2OH⁻. لا يحدث اختزال Na⁺ لأن اختزال الماء أسهل حدوثًا، فجزيئات الماء لديها ميل للاختزال أكثر من الصوديوم، فيحدث الاختزال التفضيلي للماء وينتج غاز الهيدروجين وأيونات الهيدروكسيد بدل الصوديوم.', '["التفاعل المحتمل الأول: اختزال Na⁺","التفاعل المحتمل الثاني: اختزال الماء","التعليل: الماء أكثر ميلًا للاختزال (اختزال تفضيلي)","النواتج الفعلية: H₂ وOH⁻"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة التفاعلين المحتملين","marks":2},{"element":"التعليل","marks":1},{"element":"تحديد النواتج الفعلية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كتابة التفاعلين صحيحين مع تعليل واضح وتحديد النواتج"},{"level":"3 درجات","description":"تعليل صحيح مع خطأ في إحدى المعادلتين"},{"level":"2 درجتان","description":"تعليل صحيح دون معادلات"},{"level":"1 درجة","description":"ذكر أن الماء يُختزل دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الصوديوم يتكون ثم يختفي دون تفسير","كتابة اختزال الماء دون موازنة","الخلط بين تفاعلي الأنود والكاثود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-17T11:36:22.678Z"}'::jsonb),
('essay', 2, null::int, null, null, 'النوع ذو جهد الاختزال الأكبر (الأقل سالبية) هو الأسهل اختزالًا. جهد اختزال الماء (−0.8277 V) أكبر من جهد اختزال Na⁺ (−2.71 V)، لذا يُختزل الماء تفضيليًا ولا يتكون الصوديوم: 2H₂O + 2e⁻ → H₂ + 2OH⁻. تتراكم أيونات OH⁻ الناتجة حول الكاثود مع أيونات Na⁺ فيصبح المحلول قاعديًا (هيدروكسيد الصوديوم). التفاعل الكلي: 2H₂O + 2NaCl → H₂ + Cl₂ + 2NaOH.', '["مقارنة الجهدين: −0.8277 > −2.71","استنتاج اختزال الماء تفضيليًا","تكوّن OH⁻ يجعل المحلول قاعديًا","التفاعل الكلي الموزون"]'::jsonb, '["مقارنة جهدي الاختزال: −0.8277 V أكبر من −2.71 V","الأكبر جهدًا يُختزل: الماء","2H₂O + 2e⁻ → H₂ + 2OH⁻ ← تكوّن OH⁻ (وسط قاعدي)","2H₂O + 2NaCl → H₂ + Cl₂ + 2NaOH"]'::jsonb, '[{"element":"المقارنة الصحيحة للجهدين والاستنتاج","marks":2},{"element":"تفسير القاعدية","marks":1},{"element":"التفاعل الكلي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة وتبرير صحيحان مع تفسير القاعدية والمعادلة الكلية الموزونة"},{"level":"3 درجات","description":"تبرير صحيح وتفسير القاعدية دون المعادلة الكلية أو بخطأ فيها"},{"level":"2 درجتان","description":"تبرير صحيح بالجهود فقط"},{"level":"1 درجة","description":"استنتاج صحيح دون استعمال الجهود"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ −2.71 أكبر من −0.8277","القول إن المحلول يصبح حمضيًا","إدخال O₂ في المعادلة الكلية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.679Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في خلية داون يكون NaCl مصهورًا خاليًا من الماء، فالأيونات حرة الحركة ولا يوجد عند الكاثود إلا أيونات Na⁺ لتُختزل: Na⁺ + e⁻ → Na، فينتج الصوديوم. أما ماء البحر فمحلول مائي، فيوجد عند الكاثود نوعان قابلان للاختزال: Na⁺ والماء، وجزيئات الماء أكثر ميلًا للاختزال فيحدث الاختزال التفضيلي للماء: 2H₂O + 2e⁻ → H₂ + 2OH⁻، فينتج H₂ لا Na. إذن غياب الماء في المصهور هو الذي يسمح بإنتاج الصوديوم، ووجوده في ماء البحر يمنعه.', '["المصهور خالٍ من الماء، فلا يُختزل إلا Na⁺","معادلة اختزال Na⁺ في خلية داون","في ماء البحر يتنافس Na⁺ والماء على الاختزال","الماء أسهل اختزالًا فيُختزل تفضيليًا","الاستنتاج: وجود الماء هو العامل الحاسم"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل حالة المصهور","marks":2},{"element":"تحليل حالة ماء البحر","marks":2},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحليل صحيح للحالتين بالمعادلات مع الاستنتاج"},{"level":"3 درجات","description":"تحليل صحيح لحالة واحدة كاملة وجزئي للأخرى"},{"level":"1 درجة","description":"ذكر أن الماء هو السبب دون تحليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن تركيز NaCl في ماء البحر منخفض هو السبب","إغفال أن المصهور لا ماء فيه","القول إن الصوديوم يتكون في ماء البحر عند الأنود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.679Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C4-L3-O04') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C4-L3-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا يجب أن يكون كلوريد الصوديوم مصهورًا في خلية داون؟', null, '["لأن NaCl الصلب يتفكك إلى ذرات Na وCl عند تسخينه","لأن الإلكترونات تتحرك بحرية في NaCl المصهور","لأن الصوديوم لا يتكون إلا عند درجات حرارة منخفضة","لتصبح أيوناته حرة الحركة دون وجود ماء يُختزل بدل Na⁺"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 155 — التحليل الكهربائي لمصهور NaCl (خلية داون)'),
('mcq', 2, 'متى يمكن للمركبات الأيونية مثل كلوريد الصوديوم توصيل التيار الكهربائي؟', null, '["عند ذوبانها في الماء أو انصهارها","في حالتها الصلبة عند درجة حرارة الغرفة فقط","عند طحنها إلى مسحوق ناعم جدًا","عند تبريدها إلى درجات حرارة منخفضة جدًا"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 155 — التحليل الكهربائي لمصهور NaCl (خلية داون)'),
('mcq', 3, 'لماذا لا يوصل كلوريد الصوديوم الصلب التيار الكهربائي؟', null, '["لأنه لا يحتوي على أيونات، بل على جزيئات متعادلة","لأن إلكتروناته الحرة قليلة مقارنة بالفلزات","لأن أيوناته مقيدة في مواقع ثابتة ولا تتحرك بحرية","لأن أيوناته تحمل شحنات متساوية فيلغي بعضها بعضًا"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 155 — التحليل الكهربائي لمصهور NaCl (خلية داون)'),
('mcq', 4, 'ما حاملات الشحنة التي تنقل التيار الكهربائي داخل مصهور كلوريد الصوديوم؟', null, '["الإلكترونات الحرة كما في الفلزات","أيونات Na⁺ وCl⁻ المتحركة","جزيئات NaCl المتعادلة","ذرات الصوديوم والكلور المتعادلة"]'::jsonb, 'فهم', 'تحديد', 'متوسط', 'الكتاب ص 155 — التحليل الكهربائي لمصهور NaCl (خلية داون)'),
('mcq', 5, 'يوضح الجدول عينات من كلوريد الصوديوم في حالات مختلفة. أيّ العينات توصل التيار الكهربائي؟', '{"headers":["العينة","الحالة"],"rows":[["1","بلورات NaCl صلبة عند 25°C"],["2","NaCl منصهر"],["3","NaCl مذاب في الماء"]]}'::jsonb, '["العينة 1 فقط","العينات 1 و2 و3","العينتان 2 و3 فقط","العينة 3 فقط"]'::jsonb, 'تطبيق', 'تفسير بيانات', 'متوسط', 'الكتاب ص 155 — التحليل الكهربائي لمصهور NaCl (خلية داون)'),
('mcq', 6, 'في أثناء التحليل الكهربائي لمصهور NaCl، كيف تتحرك أيوناته داخل المصهور؟', null, '["Na⁺ نحو الأنود، و Cl⁻ نحو الكاثود","Na⁺ نحو الكاثود، و Cl⁻ نحو الأنود","الأيونان كلاهما نحو الكاثود","لا تتحرك الأيونات، بل تتحرك الإلكترونات خلال المصهور"]'::jsonb, 'فهم', 'وصف', 'متوسط', 'الكتاب ص 155 — التحليل الكهربائي لمصهور NaCl (خلية داون)'),
('mcq', 7, 'سُخنت بلورات NaCl في بوتقة موصولة بدائرة كهربائية فيها مصباح، فلم يضئ المصباح في البداية ثم أضاء بعد انصهار الملح. ما التفسير الأدق؟', null, '["التسخين حوّل الأيونات إلى ذرات متعادلة توصل التيار","الانصهار أنتج إلكترونات حرة تتحرك داخل المصهور","الحرارة وحدها تكفي لإضاءة المصباح دون مرور تيار","الانصهار حرّر الأيونات من مواقعها فأصبحت حرة الحركة تنقل الشحنة"]'::jsonb, 'تحليل', 'تفسير ملاحظة', 'صعب', 'الكتاب ص 155 — التحليل الكهربائي لمصهور NaCl (خلية داون)'),
('essay', 1, 'علّل: يوصل محلول ملح الطعام ومصهوره التيار الكهربائي، بينما لا توصله بلوراته الصلبة.', null, null, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 155 — التحليل الكهربائي لمصهور NaCl (خلية داون)'),
('essay', 2, 'فسّر لماذا يجب أن يكون كلوريد الصوديوم مصهورًا في خلية داون، ثم بيّن ما الذي سيتغير في الناتج عند الكاثود لو استُعمل محلول مائي من NaCl بدلًا من المصهور.', null, null, 'فهم', 'تفسير وتنبؤ', 'متوسط', 'الكتاب ص 155–156 — خلية داون والتحليل الكهربائي لماء البحر'),
('essay', 3, 'صِف كيف ينتقل التيار الكهربائي في دائرة خلية داون كاملة: في الأسلاك الخارجية، وداخل مصهور NaCl، وعند سطحي القطبين، مع كتابة نصف التفاعل عند كل قطب.', null, null, 'تحليل', 'وصف وتحليل', 'صعب', 'الكتاب ص 155 — التحليل الكهربائي لمصهور NaCl (خلية داون)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C4-L3-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'المركبات الأيونية لا توصل التيار الكهربائي إلا عندما تكون أيوناتها حرة الحركة، وذلك عند ذوبانها في الماء أو انصهارها؛ ولأن المطلوب إنتاج الصوديوم فلا بد من غياب الماء، لذا يُصهر NaCl.', '["الانصهار لا يفكك NaCl إلى ذرات، بل يحرر أيوناته Na⁺ وCl⁻ من مواقعها.","التيار في المصهور تحمله الأيونات المتحركة لا الإلكترونات الحرة.","المصهور ساخن جدًا، وسبب الانصهار حرية حركة الأيونات لا درجة الحرارة المناسبة للصوديوم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T11:36:22.679Z"}'::jsonb),
('mcq', 2, 0, 'المركبات الأيونية لا يمكنها توصيل التيار إلا عندما تكون أيوناتها حرة الحركة، وذلك عند ذوبانها في الماء أو انصهارها.', '["","في الحالة الصلبة تكون الأيونات مقيدة في مواقعها فلا توصل التيار.","الطحن لا يحرر الأيونات من الشبكة البلورية، فيبقى المسحوق صلبًا غير موصل.","التبريد يُبقي المركب صلبًا وأيوناته غير حرة الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.679Z"}'::jsonb),
('mcq', 3, 2, 'الأيونات موجودة في NaCl الصلب لكنها غير حرة الحركة، والمركبات الأيونية لا توصل التيار إلا عندما تكون أيوناتها حرة الحركة (بالانصهار أو الذوبان).', '["كلوريد الصوديوم مركب أيوني يتكون من أيونات Na⁺ وCl⁻ في الحالات كلها.","توصيل المركبات الأيونية يعتمد على حركة الأيونات لا على الإلكترونات الحرة.","","تعادل الشحنة الكلية لا يمنع التوصيل؛ فالمصهور متعادل أيضًا ويوصل التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.680Z"}'::jsonb),
('mcq', 4, 1, 'عند الانصهار تتحرر أيونات Na⁺ وCl⁻ وتصبح حرة الحركة، فتنقل الشحنة داخل المصهور، بينما تنقل الإلكترونات الشحنة في الأسلاك.', '["المصهور الأيوني ليس فلزًا؛ والإلكترونات تنتقل في الأسلاك الخارجية فقط.","","الجسيمات المتعادلة لا تحمل شحنة فلا تنقل التيار، ثم إن NaCl مركب أيوني.","الذرات المتعادلة لا تحمل شحنة، والمصهور يتكون من أيونات لا ذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.680Z"}'::jsonb),
('mcq', 5, 2, 'يوصل NaCl التيار عندما تكون أيوناته حرة الحركة: في المحلول المائي (العينة 3) وفي المصهور (العينة 2)، أما الصلب (العينة 1) فلا يوصله.', '["NaCl الصلب أيوناته مقيدة فلا يوصل التيار.","العينة الصلبة (1) لا توصل التيار لأن أيوناتها غير حرة الحركة.","","المصهور (2) يوصل التيار أيضًا لأن أيوناته حرة الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.680Z"}'::jsonb),
('mcq', 6, 1, 'الأيونات حرة الحركة في المصهور: تتجه Na⁺ إلى الكاثود فتُختزل (Na⁺ + e⁻ → Na)، وتتجه Cl⁻ إلى الأنود فتتأكسد (2Cl⁻ → Cl₂ + 2e⁻).', '["عُكس الاتجاهان؛ فـ Na⁺ يُختزل عند الكاثود وCl⁻ يتأكسد عند الأنود.","","أيونات Cl⁻ تتجه إلى الأنود حيث تتأكسد إلى Cl₂.","حركة الأيونات في المصهور هي التي تنقل التيار؛ والإلكترونات تتحرك في الأسلاك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.680Z"}'::jsonb),
('mcq', 7, 3, 'في الحالة الصلبة تكون الأيونات مقيدة فلا يمر تيار، وعند الانصهار تصبح الأيونات حرة الحركة فينتقل التيار خلال المصهور ويضيء المصباح.', '["الذرات المتعادلة لا تنقل الشحنة، ثم إن الانصهار لا يحول الأيونات إلى ذرات.","التيار في المصهور تحمله الأيونات المتحركة لا الإلكترونات الحرة.","المصباح لا يضيء إلا بمرور تيار في الدائرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.680Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ملح الطعام (NaCl) مركب أيوني، والمركبات الأيونية لا يمكنها توصيل التيار الكهربائي إلا عندما تكون أيوناتها حرة الحركة. في البلورات الصلبة تكون أيونات Na⁺ وCl⁻ مقيدة في مواقعها فلا توصل التيار. وعند ذوبان الملح في الماء أو انصهاره تتحرر الأيونات وتصبح حرة الحركة، فتنقل الشحنة الكهربائية ويوصل المحلول والمصهور التيار.', '["NaCl مركب أيوني","التوصيل يتطلب أيونات حرة الحركة","في الصلب الأيونات مقيدة","الذوبان أو الانصهار يحرر الأيونات"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن التوصيل يتطلب أيونات حرة الحركة","marks":1},{"element":"تفسير عدم توصيل الصلب","marks":1},{"element":"تفسير توصيل المحلول والمصهور","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل للحالات الثلاث"},{"level":"2 درجتان","description":"تعليل صحيح لتوصيل المحلول والمصهور دون تفسير حالة الصلب"},{"level":"1 درجة","description":"ذكر أن السبب الأيونات دون توضيح حرية الحركة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة التوصيل إلى الإلكترونات الحرة","القول إن الصلب لا يحتوي على أيونات","القول إن الماء وحده هو الذي يوصل التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.680Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يجب أن يكون NaCl في خلية داون في حالة سائلة لتكون أيوناته حرة الحركة فيوصل التيار ويحدث التحليل؛ والانصهار يحقق ذلك دون وجود ماء. ولو استُعمل محلول مائي لوصل التيار أيضًا، لكن الماء أكثر ميلًا للاختزال من Na⁺، فيُختزل الماء عند الكاثود (2H₂O + 2e⁻ → H₂ + 2OH⁻) وينتج غاز الهيدروجين بدل فلز الصوديوم، وهو ليس المطلوب من خلية داون.', '["الانصهار يجعل الأيونات حرة الحركة","الانصهار يحقق ذلك دون ماء","في المحلول المائي يُختزل الماء بدل Na⁺","الناتج يصبح H₂ بدل Na"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير ضرورة الانصهار (حرية حركة الأيونات)","marks":2},{"element":"التغير في الناتج عند استعمال المحلول مع التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح لضرورة الانصهار وللتغير في الناتج مع التعليل"},{"level":"3 درجات","description":"تفسير صحيح لأحد الجزأين وجزئي للآخر"},{"level":"2 درجتان","description":"تفسير صحيح لجزء واحد فقط"},{"level":"1 درجة","description":"ذكر حرية حركة الأيونات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحلول المائي لا يوصل التيار","القول إن الناتج سيبقى صوديومًا","عدّ الانصهار ضروريًا لتكوين الأيونات أصلًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T11:36:22.681Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في الأسلاك الخارجية ينتقل التيار بحركة الإلكترونات: يدفع مصدر الطاقة الإلكترونات نحو الكاثود (الحديد) ويسحبها من الأنود (الكربون). داخل المصهور ينتقل التيار بحركة الأيونات الحرة: تتجه أيونات Na⁺ نحو الكاثود وأيونات Cl⁻ نحو الأنود. وعند سطحي القطبين تكتمل الدائرة بتفاعلي الأكسدة والاختزال: عند الكاثود تكتسب أيونات الصوديوم الإلكترونات Na⁺ + e⁻ → Na، وعند الأنود تفقد أيونات الكلوريد الإلكترونات 2Cl⁻ → Cl₂ + 2e⁻ فتعود إلى الدائرة الخارجية.', '["الإلكترونات تنقل التيار في الأسلاك","الأيونات الحرة تنقل التيار في المصهور واتجاه كل منها","تفاعل الكاثود","تفاعل الأنود","التفاعلات عند القطبين تكمل الدائرة"]'::jsonb, '[]'::jsonb, '[{"element":"انتقال التيار في الأسلاك","marks":1},{"element":"انتقال التيار في المصهور واتجاه الأيونات","marks":2},{"element":"نصفا التفاعل عند القطبين","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"وصف صحيح للمناطق الثلاث مع نصفي التفاعل الصحيحين"},{"level":"3 درجات","description":"وصف صحيح لحركة الأيونات ونصفي التفاعل مع إغفال الأسلاك أو خطأ فيها"},{"level":"1 درجة","description":"نصف تفاعل واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الإلكترونات تعبر المصهور","عكس اتجاه حركة الأيونات","كتابة 2Cl⁻ → Cl₂ دون إلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.681Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
